/// New paged stores default to 1 GiB page-file extents (PostgreSQL-style
/// segment files). Override with `BICDB_PAGED_EXTENT_BYTES` (0 = monolithic).
pub const DEFAULT_PAGED_EXTENT_BYTES: u64 = 1024 * 1024 * 1024;
/// Maximum UTF-8 byte length of one full-text lexeme. This stays below the
/// page-store key ceiling after the index namespace and string encoding are
/// added.
pub const MAX_FULL_TEXT_TERM_BYTES: usize = 2_046;
const MAX_FULL_TEXT_OVERSIZE_WARNINGS: u64 = 4;
static FULL_TEXT_OVERSIZED_TERMS_SKIPPED: AtomicU64 = AtomicU64::new(0);

fn test_fts_build_abort_matches(index: &str, phase: &str) -> bool {
    std::env::var("BICDB_TEST_FTS_BUILD_ABORT_PHASE")
        .ok()
        .is_some_and(|value| {
            value
                .strip_prefix(index)
                .and_then(|suffix| suffix.strip_prefix(':'))
                == Some(phase)
        })
}

/// Process-wide count of pathological full-text terms skipped before they can
/// enter an index key. The counter is intentionally monotonic and lock-free so
/// callers can export it through their existing metrics system.
pub fn full_text_oversized_terms_skipped() -> u64 {
    FULL_TEXT_OVERSIZED_TERMS_SKIPPED.load(AtomicOrdering::Relaxed)
}

/// Apply BicDB's shared full-text storage boundary. Oversized terms are
/// deliberately skipped rather than truncated: truncation aliases unrelated
/// terms, while hashing breaks prefix semantics. Warnings are bounded and
/// never include term contents, which may contain sensitive document data.
pub fn full_text_term_is_indexable(term: &str) -> bool {
    let bytes = term.len();
    if bytes <= MAX_FULL_TEXT_TERM_BYTES {
        return true;
    }
    let observed = FULL_TEXT_OVERSIZED_TERMS_SKIPPED.fetch_add(1, AtomicOrdering::Relaxed) + 1;
    if observed <= MAX_FULL_TEXT_OVERSIZE_WARNINGS {
        eprintln!(
            "[bicdb][fts] skipped oversized term: bytes={bytes} max_bytes={MAX_FULL_TEXT_TERM_BYTES} skipped_total={observed}"
        );
    } else if observed == MAX_FULL_TEXT_OVERSIZE_WARNINGS + 1 {
        eprintln!(
            "[bicdb][fts] further oversized-term warnings suppressed; skipped_total={observed}"
        );
    }
    false
}

#[derive(Clone, Debug)]
pub struct DbConfig {
    pub fsync: bool,
    pub read_mode: SegmentReadMode,
    pub compression: CompressionConfig,
    pub audit_events: bool,
    /// Sign exported mesh envelopes with this node's ed25519 key (generated
    /// on first signing open, stored in `mesh_signing_key.json`). Receivers
    /// with this node's key pinned verify origin authenticity through any
    /// relay chain.
    /// Opt-in zstd compression for paged record values (write-new-read-both;
    /// reads always understand both forms, so flipping this never requires a
    /// rebuild). Biggest ratio win on JSON-heavy metadata.
    pub paged_value_compression: bool,
    pub mesh_signing: bool,
    /// Refuse imported events that are unsigned or whose origin has no
    /// pinned key. Enabled by default; legacy unsigned imports require an
    /// explicit opt-out.
    pub require_signed_imports: bool,
    /// Compatibility escape hatch for pre-v2 meshes that auto-created and
    /// synchronized every unprotected collection. Unsafe for SQL RLS/schema
    /// tenancy; false by default.
    pub allow_unsafe_legacy_mesh_collections: bool,
    /// Whether to maintain the change-data-capture (CDC) sync outbox — the
    /// `pending_sync_ops()` / `mark_synced()` poll API. It has NO internal
    /// consumer (mesh replication uses the event stream), so a deployment that
    /// does not poll it pays a per-write `Uuid` + content-hash (SHA-256) + JSON
    /// append for nothing, and the never-drained outbox grows unbounded (the
    /// dominant restart cost on large datasets). Default on for compatibility;
    /// set `BICDB_SYNC_OUTBOX=off` (or `with_sync_outbox(false)`) to disable.
    pub sync_outbox: bool,
    /// Whether the binary startup snapshot ("true checkpoint") is active. A derived
    /// cache written at compaction that lets the next open rebuild the heap from
    /// compact binary records instead of reparsing JSON segments. OFF by default; on
    /// any mismatch (missing/torn/version-skew) the open transparently falls back to
    /// the JSON segment path, so it is a pure accelerator. Enable per-instance with
    /// `with_snapshot(true)` or globally with `BICDB_SNAPSHOT=1`. See [`crate::snapshot`].
    pub snapshot: bool,
    /// Native ordered commit-stream replication. Disabled by default; enabled
    /// configs are validated so remote replication requires TLS/mTLS.
    pub replication: ReplicationConfig,
    /// Raft-style cluster consensus. Disabled by default. When enabled, writes
    /// should be admitted only through a leader that can replicate to quorum.
    pub consensus: ConsensusConfig,
    /// Fail closed when a write reaches the local commit path before a
    /// cluster range-quorum authority has been installed. Distributed server
    /// opens enable this automatically; standalone/embedded databases leave
    /// it disabled.
    pub require_commit_admission: bool,
    /// Which storage engine to open the database with. Durable per-database
    /// metadata, not a free-form runtime toggle: opening an existing database
    /// under a mode other than its recorded one is refused rather than converted
    /// (see [`crate::format::ensure_requested_mode_matches`]). Only
    /// [`StorageMode::EmbeddedMemory`] is implemented today.
    pub storage_mode: StorageMode,
    /// Fixed physical page size for a newly created server-paged store. An
    /// existing store rejects a mismatch; this never silently rewrites pages.
    pub paged_page_size: u32,
    /// Hard resident-byte ceiling for the server-paged buffer pool.
    pub paged_buffer_pool_bytes: u64,
    /// Build the in-memory primary-key/row-id registry for durable secondary
    /// indexes while opening a paged database. Disable only for a read-serving
    /// handle that uses direct primary-key reads and generation-backed FTS;
    /// row-id-addressed secondary-index hydration is unavailable on that
    /// handle. Keeping this enabled preserves the general SQL contract.
    pub paged_rowid_registry: bool,
    /// Load secondary and vector indexes while opening the database. Disable
    /// this only for bounded primary-record operations such as a collection
    /// export: those operations read the page store directly and must not pay
    /// corpus-sized index reconstruction costs before emitting their first
    /// row. The catalog remains durable and is loaded normally on the next
    /// ordinary open.
    pub load_secondary_indexes: bool,
    /// Document-range partitions a single ranked full-text query is split
    /// across. This is intra-QUERY parallelism: one query using many cores,
    /// rather than many queries each using one — the difference between a
    /// search bounded by a single core and one bounded by the machine.
    ///
    /// The output is identical at every setting; only the scheduling changes.
    /// Raising it trades total CPU for latency, because partitioning weakens
    /// WAND pruning (each partition establishes its own top-k threshold), so
    /// the right value depends on how many queries run concurrently. A
    /// read-serving deployment with few concurrent queries wants this near
    /// the core count; a high-concurrency OLTP mix wants it low.
    pub fts_query_partitions: usize,
    /// Write new full-text generations as packed immutable segments
    /// (physical-format v2) instead of millions of keyed rows. Existing
    /// generations keep whichever format they were built with and stay
    /// readable either way; the flag only affects NEW builds.
    pub fts_packed_segments: bool,
    /// Hard metadata ceiling for deduplicated server-paged read-ahead hints.
    /// Zero disables speculative queueing without changing foreground reads.
    pub paged_read_ahead_queue_pages: usize,
    /// Checkpoint trigger for the server-paged WAL. A single transaction or a
    /// transaction blocking the freeze watermark may temporarily exceed it.
    pub paged_wal_max_bytes: u64,
    /// Bytes at which the active WAL seals and rotates to an immutable
    /// `store.wal.<seq>` segment (distinct from the checkpoint trigger).
    /// Online backups are robust to rotation regardless of this value.
    pub paged_wal_segment_bytes: u64,
    /// Accept and transform a paged meta page written by an engine predating
    /// durable abort exceptions. Opt-in (`BICDB_ACCEPT_LEGACY_META=1`):
    /// on a store that already uses the current layout the same validation
    /// failure means real corruption and must keep failing the open.
    pub paged_accept_legacy_meta: bool,
    /// Bytes per page-file extent for NEWLY created paged stores. `0` keeps
    /// one monolithic `store.pages`; the default segments new stores into
    /// 1 GiB files so file-level tooling (rsync deltas, parallel uploads,
    /// per-file checksums, incremental backup) scales. Existing stores keep
    /// their recorded layout regardless of this setting.
    pub paged_extent_bytes: u64,
    /// Hard working-set budget for the in-process portion of a bulk full-text
    /// index build. Posting runs spill to disk when this many bytes have been
    /// accumulated. One exceptionally large document may temporarily exceed
    /// the limit by that document's encoded term data.
    pub fts_build_memory_bytes: usize,
    /// Maximum CPU parallelism used while generating and merging full-text
    /// posting runs. The global memory budget above is divided among workers.
    pub fts_build_workers: usize,
    /// Maximum encoded row bytes decoded by one paged B-tree build tick.
    pub btree_build_batch_bytes: usize,
    /// Maximum rows decoded and indexed by one paged B-tree build tick.
    pub btree_build_batch_rows: usize,
    /// Hard resident-byte ceiling for decoded hot FTS posting blocks. Zero
    /// disables the cache.
    pub fts_block_cache_bytes: usize,
    /// Progressive full-text builds: publish searchable sub-segments while
    /// the build runs, flipping visibility at the FIRST sub. Partial results
    /// are DELIBERATELY visible mid-build — the inverse of the default
    /// "aborted builds leave nothing visible" contract, which is why it is
    /// opt-in. The final merge swaps in the ordinary single segment and
    /// deletes the subs.
    pub fts_progressive: bool,
    /// Documents per progressive sub-segment.
    pub fts_progressive_interval_docs: u64,
    /// Number of upcoming posting blocks decoded concurrently per active term
    /// cursor. Zero disables look-ahead.
    pub fts_prefetch_blocks: usize,
    /// Hard per-operator memory budget used by spillable SQL execution. An
    /// individual value larger than the budget is rejected instead of silently
    /// making the query unbounded.
    pub query_work_memory_bytes: usize,
    /// Hard temporary-disk quota for one spillable SQL operator, including
    /// intermediate merge generations.
    pub query_temp_space_bytes: u64,
    /// Hard aggregate temporary-disk quota shared by spillable SQL operators
    /// using the same spill root. This prevents concurrent individually valid
    /// queries from exhausting the server filesystem together.
    pub query_server_temp_space_bytes: u64,
    /// Maximum number of sorted runs opened by one merge pass. Keeping this
    /// bounded makes file descriptors and merge memory independent of input
    /// size.
    pub query_merge_fan_in: usize,
}

