/// Durable lifecycle state for one large full-text index build.
///
/// This is intentionally derived from BicDB's own checkpoint and published
/// generation, rather than from an operator-owned marker. It is therefore the
/// authoritative answer after a process crash or machine restart.
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum FullTextBuildLifecycleState {
    NotFound,
    Idle,
    AwaitingInput,
    Tokenizing,
    Finalizing,
    Publishing,
    Published,
    Blocked,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum FullTextBuildRecommendedAction {
    None,
    AppendDocuments,
    Reconcile,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct FullTextBuildLifecycleStatus {
    pub schema_version: u32,
    pub logical_index: String,
    pub state: FullTextBuildLifecycleState,
    /// Stable machine-readable reason. Human-facing callers may localize it.
    pub reason_code: String,
    pub recommended_action: FullTextBuildRecommendedAction,
    pub serving: bool,
    pub resumable: bool,
    pub checkpoint_updated_unix_ms: Option<u64>,
    pub staged_physical_index: Option<String>,
    pub progressive_documents_staged: u64,
    pub progress: Option<crate::fts_build::FullTextBuildStatus>,
    pub published: Option<FullTextPublishedGeneration>,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
