#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct SignedClusterSchemaBundle {
    pub format_version: u32,
    pub bundle: ClusterSchemaBundle,
    pub signer_key_id: String,
    pub signature_ed25519_hex: String,
}

impl SignedClusterSchemaBundle {
    pub fn verify(&self, trusted_keys: &BTreeMap<String, [u8; 32]>) -> Result<()> {
        if self.format_version != SIGNED_CLUSTER_SCHEMA_BUNDLE_FORMAT_VERSION
            || self.signer_key_id.is_empty()
            || self.signer_key_id.len() > MAX_CLUSTER_SCHEMA_SIGNER_KEY_ID_BYTES
            || !self
                .signer_key_id
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
        {
            return Err(BicDbError::Cluster(
                "signed cluster schema bundle format or signer key id is invalid".to_string(),
            ));
        }
        self.bundle.verify()?;
        let public_key = trusted_keys.get(&self.signer_key_id).ok_or_else(|| {
            BicDbError::Cluster(format!(
                "cluster schema signer `{}` is not trusted",
                self.signer_key_id
            ))
        })?;
        let verifying_key = VerifyingKey::from_bytes(public_key).map_err(|_| {
            BicDbError::Cluster("cluster schema signer public key is invalid".to_string())
        })?;
        let signature_bytes = hex::decode(&self.signature_ed25519_hex).map_err(|_| {
            BicDbError::Cluster("cluster schema signature is not valid hex".to_string())
        })?;
        let signature = Signature::from_slice(&signature_bytes).map_err(|_| {
            BicDbError::Cluster("cluster schema signature must be exactly 64 bytes".to_string())
        })?;
        verifying_key
            .verify_strict(&self.bundle.signing_message()?, &signature)
            .map_err(|_| BicDbError::Cluster("cluster schema signature is invalid".to_string()))
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct ClusterSchemaStageLimits {
    pub max_state_bytes: u64,
    pub max_changes: usize,
}

impl Default for ClusterSchemaStageLimits {
    fn default() -> Self {
        Self {
            max_state_bytes: 72 * 1024 * 1024,
            max_changes: MAX_CLUSTER_SCHEMA_BUNDLE_RECORDS,
        }
    }
}

impl ClusterSchemaStageLimits {
    pub fn validate(self) -> Result<()> {
        if !(MAX_CLUSTER_SCHEMA_BUNDLE_BYTES as u64..=256 * 1024 * 1024)
            .contains(&self.max_state_bytes)
            || !(1..=MAX_CLUSTER_SCHEMA_BUNDLE_RECORDS).contains(&self.max_changes)
        {
            return Err(BicDbError::Cluster(
                "cluster schema staging limits are invalid".to_string(),
            ));
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct ClusterSchemaOnlinePlan {
    pub base_fingerprint_sha256: String,
    pub target_fingerprint_sha256: String,
    pub collection_additions: usize,
    pub index_additions: usize,
    pub structural_record_additions: usize,
}

impl ClusterSchemaOnlinePlan {
    pub fn total_changes(&self) -> usize {
        self.collection_additions
            .saturating_add(self.index_additions)
            .saturating_add(self.structural_record_additions)
    }
}

