/// What one [`BicDb::pack_spatial_index`] produced: the published packed
/// generation and its tree shape.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct SpatialPackReport {
    pub index_name: String,
    pub collection: String,
    pub strategy: SpatialPackStrategy,
    pub generation: u64,
    pub entry_count: u64,
    pub node_count: u64,
    pub height: u32,
    /// Whether this pack continued a checkpointed build (crash-interrupted
    /// scan or pack phase) instead of starting fresh.
    #[serde(default)]
    pub resumed: bool,
}

/// Nodes per committed transaction while writing a packed generation:
/// bounded WAL per commit no matter the corpus size.
const SPATIAL_PACK_NODES_PER_TXN: usize = 2_048;

fn hex_bytes(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push_str(&format!("{byte:02x}"));
    }
    out
}

