#[derive(Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct CompactionOptions {
    pub reclaim_threshold_percent: u8,
    pub schedule: Option<String>,
    pub max_io_bytes_per_sec: Option<u64>,
    pub max_pause_ms: Option<u64>,
    pub force: bool,
    /// Run as an online WAL checkpoint: materialize the committed in-memory
    /// snapshot to segments and truncate the WAL even while transactions are
    /// in-flight. Safe because compaction takes `&mut self` (exclusive: no commit
    /// is mid-apply), the records map is therefore a consistent committed
    /// snapshot, and in-flight transactions have written no committed WAL frames
    /// yet — their later commit appends to the fresh log with a monotonic
    /// commit_seq, so recovery stays gap-free. Used by the server's WAL-size
    /// auto-checkpointer to bound log growth under sustained write load.
    pub allow_pending: bool,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct IncrementalCompactionLimits {
    pub max_collections: usize,
    pub max_state_bytes: u64,
}

impl Default for IncrementalCompactionLimits {
    fn default() -> Self {
        Self {
            max_collections: 1_000_000,
            max_state_bytes: 64 * 1024 * 1024,
        }
    }
}

impl IncrementalCompactionLimits {
    pub fn validate(self) -> Result<()> {
        if !(1..=1_000_000).contains(&self.max_collections)
            || !(64 * 1024..=256 * 1024 * 1024).contains(&self.max_state_bytes)
        {
            return Err(BicDbError::Compaction(
                "incremental compaction collection/state limits are invalid".to_string(),
            ));
        }
        Ok(())
    }
}

