pub enum PagedBTreeBuildAdvance {
    Progress(PagedBTreeBuildState),
    Complete(PagedBTreeBuildState),
}

impl PagedBTreeBuildState {
    fn calculate_checksum(&self) -> Result<String> {
        let mut value = self.clone();
        value.checksum_sha256.clear();
        Ok(hex::encode(sha2::Sha256::digest(serde_json::to_vec(
            &value,
        )?)))
    }

    fn refresh_checksum(&mut self) -> Result<()> {
        self.checksum_sha256 = self.calculate_checksum()?;
        Ok(())
    }

    pub fn validate(&self) -> Result<()> {
        self.limits.validate()?;
        if self.format_version != PAGED_BTREE_BUILD_FORMAT_VERSION
            || self.run_id.is_nil()
            || self.definition.kind != IndexKind::BTree
            || self.definition.name.is_empty()
            || self.physical_name.is_empty()
            || self.created_at_ms > self.updated_at_ms
            || self.checksum_sha256.len() != 64
            || self.calculate_checksum()? != self.checksum_sha256
            || serde_json::to_vec(self)?.len() as u64 > self.limits.max_state_bytes
            || self.count_after_key_hex.is_some() != self.count_after_pk.is_some()
        {
            return Err(BicDbError::Index(
                "paged B-tree build state identity, checksum, cursor, or bound is invalid"
                    .to_string(),
            ));
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum IncrementalCompactionAdvance {
    Progress {
        phase: IncrementalCompactionPhase,
        completed_collections: usize,
        total_collections: usize,
    },
    Complete(CompactionReport),
}

impl IncrementalCompactionState {
    pub fn validate(&self) -> Result<()> {
        self.limits.validate()?;
        if self.format_version != INCREMENTAL_COMPACTION_FORMAT_VERSION
            || self.run_id.is_nil()
            || self.collections.len() > self.limits.max_collections
            || self.next_collection > self.collections.len()
            || self.report.collections.len() != self.next_collection
            || self.created_at_ms > self.updated_at_ms
            || self
                .options
                .schedule
                .as_ref()
                .is_some_and(|schedule| schedule.len() > 1_024)
            || self.options.reclaim_threshold_percent > 100
            || self.options.allow_pending
        {
            return Err(BicDbError::Compaction(
                "incremental compaction identity, cursor, options, or bounds are invalid"
                    .to_string(),
            ));
        }
        if self.collections.windows(2).any(|pair| pair[0] >= pair[1])
            || self
                .collections
                .iter()
                .any(|collection| collection.is_empty() || collection.len() > 1_024)
            || self
                .report
                .collections
                .iter()
                .zip(&self.collections)
                .any(|(report, collection)| &report.collection != collection)
        {
            return Err(BicDbError::Compaction(
                "incremental compaction collection order is not canonical".to_string(),
            ));
        }
        if self.phase != IncrementalCompactionPhase::RewritingCollections
            && self.next_collection != self.collections.len()
        {
            return Err(BicDbError::Compaction(
                "incremental compaction phase advanced before every collection".to_string(),
            ));
        }
        if self.report.checkpoint_id.as_deref() != Some(self.run_id.to_string().as_str()) {
            return Err(BicDbError::Compaction(
                "incremental compaction report belongs to another run".to_string(),
            ));
        }
        if self.checksum_sha256.len() != 64
            || !self
                .checksum_sha256
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
            || self.calculate_checksum()? != self.checksum_sha256
            || serde_json::to_vec(self)?.len() as u64 > self.limits.max_state_bytes
        {
            return Err(BicDbError::Compaction(
                "incremental compaction state checksum or byte bound is invalid".to_string(),
            ));
        }
        Ok(())
    }

    fn refresh_checksum(&mut self) -> Result<()> {
        self.checksum_sha256 = self.calculate_checksum()?;
        Ok(())
    }

    fn calculate_checksum(&self) -> Result<String> {
        #[derive(Serialize)]
        struct Payload<'a> {
            format_version: u32,
            run_id: Uuid,
            phase: IncrementalCompactionPhase,
            options: &'a CompactionOptions,
            limits: IncrementalCompactionLimits,
            collections: &'a [String],
            next_collection: usize,
            starting_commit_seq: u64,
            created_at_ms: u64,
            updated_at_ms: u64,
            report: &'a CompactionReport,
        }
        Ok(hex::encode(sha2::Sha256::digest(serde_json::to_vec(
            &Payload {
                format_version: self.format_version,
                run_id: self.run_id,
                phase: self.phase,
                options: &self.options,
                limits: self.limits,
                collections: &self.collections,
                next_collection: self.next_collection,
                starting_commit_seq: self.starting_commit_seq,
                created_at_ms: self.created_at_ms,
                updated_at_ms: self.updated_at_ms,
                report: &self.report,
            },
        )?)))
    }
}

