#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
enum RecordFrame {
    Upsert {
        record: Record,
    },
    Delete {
        id: String,
    },
    TxUpsert {
        tx_id: TransactionId,
        record: Record,
    },
    TxDelete {
        tx_id: TransactionId,
        id: String,
    },
}

/// Serialize-only twin of [`RecordFrame`] that borrows the resident
/// [`StoredRecord`] instead of materializing a [`Record`]: `to_record()` parses
/// the metadata `RawValue` into a full `Value` tree only for it to be
/// re-serialized verbatim, which is the dominant cost of checkpoint phase 1.
/// `StoredRecord`'s serde form is byte-identical to `Record` (see its docs), so
/// the emitted frame is unchanged on disk. Internal tagging is safe here: the
/// `Content`-buffer/`RawValue` hazard the deserializers below work around only
/// exists on the deserialize path.
#[derive(Serialize)]
#[serde(tag = "op", rename_all = "snake_case")]
enum RecordFrameRef<'a> {
    Upsert { record: &'a StoredRecord },
    Delete { id: &'a str },
}

/// Twin of [`RecordFrame`] that holds the record in the compact [`StoredRecord`]
/// form (metadata as raw JSON). Constructed manually by [`decode_stored_record_frame`]
/// — NOT via `#[serde(tag)]`, because an internally-tagged enum buffers through
/// serde's `Content` type, which cannot reproduce a `RawValue` (it would corrupt the
/// metadata). The two-step decode below avoids that buffer entirely.
enum StoredRecordFrame {
    Upsert(StoredRecord),
    Delete(String),
    TxUpsert(TransactionId, StoredRecord),
    TxDelete(TransactionId, String),
}

/// Op discriminant for a record frame; a plain externally-tagged enum (just a
/// string match) so no `Content` buffering occurs.
#[derive(Deserialize)]
#[serde(rename_all = "snake_case")]
enum RecordFrameOp {
    Upsert,
    Delete,
    TxUpsert,
    TxDelete,
}

/// Native-deserializer view of a record frame: the `record` sub-object is captured
/// as raw JSON (`RawValue`) without parsing, so the heavy metadata `Value` is never
/// built. Deserialized with `from_slice` (the real serde_json deserializer), so the
/// `RawValue` capture is valid.
#[derive(Deserialize)]
struct RecordFrameWire {
    op: RecordFrameOp,
    #[serde(default)]
    record: Option<Box<RawValue>>,
    #[serde(default)]
    id: Option<String>,
    #[serde(default)]
    tx_id: Option<TransactionId>,
}

/// A segment record frame after the worker has parsed AND compacted it into the
/// in-memory [`StoredRecord`] form (Arc-shared). Produced by the parallel decode
/// on the open path so the sequential apply only does map/version bookkeeping.
enum LoadedRecordFrame {
    Upsert(Arc<StoredRecord>),
    Delete(String),
    TxUpsert(TransactionId, Arc<StoredRecord>),
    TxDelete(TransactionId, String),
}

#[derive(
    Clone, Copy, Debug, Default, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord, Hash,
)]
pub struct TransactionId(pub u64);

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum TxState {
    Pending,
    Committed,
    Aborted,
}

/// Captured at [`BicDb::checkpoint_begin`] and consumed by
/// [`BicDb::checkpoint_write_segments`]: the WAL truncation boundary plus, per
/// collection, the set of record ids modified since the last checkpoint (moved
/// out of each collection's dirty locator/key sets). The incremental checkpoint
/// appends only these records as delta frames.
#[derive(Debug, Default)]
pub struct CheckpointPlan {
    keep_from: u64,
    dirty: FxHashMap<String, Vec<CheckpointDirtyShard>>,
}

#[derive(Debug)]
struct CheckpointDirtyShard {
    index: usize,
    resident: FxHashSet<RowId>,
    unresolved: FxHashSet<String>,
}

impl CheckpointPlan {
    /// The WAL byte offset below which frames may be dropped by phase 2.
    pub fn keep_from(&self) -> u64 {
        self.keep_from
    }

    /// Captured dirty locators across all collections. This is an upper bound
    /// on delta frames: deleted resident locators and duplicate unresolved keys
    /// are filtered during phase 1, outside the exclusive database lock.
    pub fn dirty_count(&self) -> usize {
        self.dirty
            .values()
            .flatten()
            .map(|shard| shard.resident.len() + shard.unresolved.len())
            .sum()
    }
}

/// Periodic-sampling view of the in-memory structures that can grow with write
/// volume. Used by leak profiling; see [`BicDb::mvcc_debug_stats`].
#[derive(Debug, Clone, Default)]
pub struct MvccDebugStats {
    /// Live entries in the `tx_states` map (one per transaction, ever).
    pub tx_states: usize,
    /// Distinct registered active read snapshots.
    pub active_snapshots: usize,
    /// Oldest registered snapshot (the GC watermark floor), 0 if none.
    pub min_active_snapshot: u64,
    /// MVCC visibility watermark (commit_seq units).
    pub last_committed_seq: u64,
    /// Highest assigned commit_seq.
    pub commit_seq: u64,
    /// Sum of version-chain lengths across all collections.
    pub total_versions: usize,
    /// Longest single version chain.
    pub max_chain: usize,
    /// Total live records across all collections.
    pub total_records: usize,
    /// On-disk (here: tmpfs) transaction-log size in bytes.
    pub wal_bytes: u64,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct VersionedRecord {
    // NOTE: the record id is intentionally NOT stored here. A `VersionedRecord` only
    // ever lives inside `VersionMap` (`FxHashMap<String, Vec<VersionedRecord>>`) keyed
    // by record id, and the id is also carried by `record: Arc<StoredRecord>` (`.id`),
    // so a per-version `record_id: String` was pure duplication — one redundant heap
    // String per version (~15M+ under a large write workload). Removing it shrinks the hot, read-walked
    // version struct ~37% (denser chains => less cache/bandwidth pressure).
    /// commit_seq of the transaction that created this version. Named `*_tx` for
    /// historical reasons but holds a gap-free **commit_seq** (the durable commit
    /// order), NOT the begin-order transaction id. Snapshots are commit_seq
    /// watermarks, so visibility is consistent even when commits apply
    /// concurrently and out of begin order.
    pub created_tx: TransactionId,
    /// commit_seq of the transaction that deleted/superseded this version.
    pub deleted_tx: Option<TransactionId>,
    pub timestamp: i64,
    pub record: Arc<StoredRecord>,
}

#[derive(Clone, Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub(crate) enum TxFrame {
    #[serde(rename = "tx_begin")]
    Begin {
        tx_id: TransactionId,
        timestamp: i64,
    },
    #[serde(rename = "tx_write")]
    Write {
        tx_id: TransactionId,
        write: Box<TxWrite>,
    },
    /// Compact stored-form UPDATE. `before` and `after` contain only the
    /// top-level metadata keys changed by the statement. Recovery compares
    /// both sides before applying, making the frame idempotent across a
    /// checkpoint/WAL overlap without carrying the complete row image.
    #[serde(rename = "tx_patch")]
    Patch {
        tx_id: TransactionId,
        patch: Box<TxPatch>,
    },
    #[serde(rename = "tx_truncate")]
    Truncate { tx_id: TransactionId, len: usize },
    #[serde(rename = "tx_broker_publish")]
    BrokerPublish {
        tx_id: TransactionId,
        publish: crate::broker::PendingBrokerPublish,
    },
    /// Record-audit outbox entry.  It is committed by the same WAL decision
    /// as the row mutation, then copied idempotently into the event segment
    /// only after that decision is durable.  Keeping this in the transaction
    /// log closes both crash windows: an audit event can neither outlive an
    /// uncommitted row nor disappear after a committed row is recovered.
    #[serde(rename = "tx_record_audit")]
    RecordAudit { tx_id: TransactionId, event: Event },
    /// Durable acknowledgement that every audit event carried by this
    /// transaction has reached the event segment. Recovery skips acknowledged
    /// outboxes, which also prevents a later retention rewrite from being
    /// undone by stale transaction WAL.
    #[serde(rename = "tx_record_audit_published")]
    RecordAuditPublished { tx_id: TransactionId },
    #[serde(rename = "tx_commit")]
    Commit {
        tx_id: TransactionId,
        timestamp: i64,
        // Defaults to 0 for transaction logs written before commit sequencing.
        #[serde(default)]
        commit_seq: u64,
    },
    #[serde(rename = "tx_commit_materialized")]
    CommitMaterialized {
        tx_id: TransactionId,
        timestamp: i64,
        // Defaults to 0 for frames written before paged mode used markers.
        #[serde(default)]
        commit_seq: u64,
    },
    #[serde(rename = "tx_abort")]
    Abort {
        tx_id: TransactionId,
        timestamp: i64,
    },
}

#[derive(Deserialize)]
#[serde(rename_all = "snake_case")]
enum TxFrameKind {
    TxBegin,
    TxWrite,
    TxPatch,
    TxTruncate,
    TxBrokerPublish,
    TxRecordAudit,
    TxRecordAuditPublished,
    TxCommit,
    TxCommitMaterialized,
    TxAbort,
}

#[derive(Deserialize)]
struct TxFrameWire {
    #[serde(rename = "type")]
    kind: TxFrameKind,
    tx_id: TransactionId,
    #[serde(default)]
    timestamp: Option<i64>,
    #[serde(default)]
    write: Option<Box<RawValue>>,
    #[serde(default)]
    patch: Option<Box<RawValue>>,
    #[serde(default)]
    publish: Option<Box<RawValue>>,
    #[serde(default)]
    event: Option<Box<RawValue>>,
    #[serde(default)]
    len: Option<usize>,
    #[serde(default)]
    commit_seq: u64,
}

fn decode_tx_frame(payload: &[u8]) -> Result<TxFrame> {
    let wire: TxFrameWire = serde_json::from_slice(payload)?;
    let missing = |field: &str| BicDbError::Corruption {
        path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
        message: format!("transaction frame missing {field}"),
    };
    Ok(match wire.kind {
        TxFrameKind::TxBegin => TxFrame::Begin {
            tx_id: wire.tx_id,
            timestamp: wire.timestamp.ok_or_else(|| missing("timestamp"))?,
        },
        TxFrameKind::TxWrite => TxFrame::Write {
            tx_id: wire.tx_id,
            write: Box::new(serde_json::from_str(
                wire.write.ok_or_else(|| missing("write"))?.get(),
            )?),
        },
        TxFrameKind::TxPatch => TxFrame::Patch {
            tx_id: wire.tx_id,
            patch: Box::new(serde_json::from_str(
                wire.patch.ok_or_else(|| missing("patch"))?.get(),
            )?),
        },
        TxFrameKind::TxTruncate => TxFrame::Truncate {
            tx_id: wire.tx_id,
            len: wire.len.ok_or_else(|| missing("len"))?,
        },
        TxFrameKind::TxBrokerPublish => TxFrame::BrokerPublish {
            tx_id: wire.tx_id,
            publish: serde_json::from_str(wire.publish.ok_or_else(|| missing("publish"))?.get())?,
        },
        TxFrameKind::TxRecordAudit => TxFrame::RecordAudit {
            tx_id: wire.tx_id,
            event: serde_json::from_str(wire.event.ok_or_else(|| missing("event"))?.get())?,
        },
        TxFrameKind::TxRecordAuditPublished => TxFrame::RecordAuditPublished { tx_id: wire.tx_id },
        TxFrameKind::TxCommit => TxFrame::Commit {
            tx_id: wire.tx_id,
            timestamp: wire.timestamp.ok_or_else(|| missing("timestamp"))?,
            commit_seq: wire.commit_seq,
        },
        TxFrameKind::TxCommitMaterialized => TxFrame::CommitMaterialized {
            tx_id: wire.tx_id,
            timestamp: wire.timestamp.ok_or_else(|| missing("timestamp"))?,
            // `wire.commit_seq` already defaults to 0 for frames written
            // before paged mode used materialized markers.
            commit_seq: wire.commit_seq,
        },
        TxFrameKind::TxAbort => TxFrame::Abort {
            tx_id: wire.tx_id,
            timestamp: wire.timestamp.ok_or_else(|| missing("timestamp"))?,
        },
    })
}

#[derive(Clone, Debug)]
pub(crate) struct TxWrite {
    pub(crate) collection: String,
    pub(crate) op: TxWriteOp,
    pub(crate) record_id: String,
    /// The parsed record: set at buffering for record-based writes; for a
    /// write that arrives as a prepared `StoredRecord` (`stored`) it is parsed
    /// on first use through [`TxWrite::record`]. Consumers that only need the
    /// stored form (WAL frame, resident row, index keys) never fill it.
    pub(crate) record: OnceLock<Option<Arc<Record>>>,
    pub(crate) timestamp: i64,
    pub(crate) statement_snapshot: u64,
    /// Commit-time conflict repair (in-memory only; never serialized to the
    /// WAL — the repaired absolute record is what gets encoded at commit).
    pub(crate) repair: Option<Arc<RepairPlan>>,
    /// The resident (`StoredRecord`) form of `record`, compacted once by
    /// `prepare_wal_payloads` off the commit critical section: the same raw
    /// JSON serves the WAL Write frame and becomes the resident record, so the
    /// row is serialized once per commit instead of twice. In-memory only.
    pub(crate) stored: Option<Arc<StoredRecord>>,
    /// The pre-image this transaction read for the row (`get_visible_unchecked`)
    /// as the exact resident `StoredRecord` it was parsed from plus the parsed
    /// `Record`. Commit uses the parsed form for the index diff when the
    /// resident row is still that very `StoredRecord` (pointer identity), and
    /// re-parses otherwise. In-memory only.
    pub(crate) previous: Option<(Arc<StoredRecord>, Arc<Record>)>,
    /// Compact pre-image supplied by stored-form UPDATE execution. Unlike
    /// `previous`, this does not force the row through a serde `Value` tree;
    /// compact WAL can project the changed columns directly from these bytes.
    /// In-memory only.
    pub(crate) previous_stored: Option<Arc<StoredRecord>>,
    /// The top-level keys whose values may differ between this write's
    /// pre-image and its row, when the writer knows them exactly (a stored-form
    /// UPDATE splices precisely its assignment columns). Commit skips every
    /// index whose fields are outside this set — no key derivation, no cell
    /// scan of the new row. `None` means unknown: every index is diffed.
    /// In-memory only.
    pub(crate) changed: Option<Arc<[Box<str>]>>,
}

impl TxWrite {
    /// The write's parsed record, parsed from `stored` on first use when the
    /// write was buffered in its stored form. `None` for deletes.
    pub(crate) fn record(&self) -> Result<Option<&Arc<Record>>> {
        if let Some(record) = self.record.get() {
            return Ok(record.as_ref());
        }
        let parsed = match self.stored.as_deref() {
            Some(stored) => Some(Arc::new(stored.to_record()?)),
            None => None,
        };
        let _ = self.record.set(parsed);
        Ok(self.record.get().and_then(Option::as_ref))
    }

    /// [`Self::record`] for call sites that cannot report a parse failure
    /// (a corrupt stored form reads as absent there).
    pub(crate) fn record_opt(&self) -> Option<&Arc<Record>> {
        self.record().ok().flatten()
    }

    /// This pending upsert as the row a reader in the same transaction sees:
    /// the stored form when the write carries one, the parsed record
    /// otherwise. `None` for deletes.
    pub(crate) fn pending_visible_row(&self) -> Option<VisibleRow> {
        match self.op {
            TxWriteOp::Delete => None,
            TxWriteOp::Upsert => match &self.stored {
                Some(stored) => Some(VisibleRow::Stored(Arc::clone(stored))),
                None => self.record_opt().cloned().map(VisibleRow::Pending),
            },
        }
    }
}

/// The WAL / wire form of a write: `TxWrite` without its in-memory fields.
/// Decode metadata directly into its compact form. Expanding every retained
/// WAL row into a JSON value tree makes recovery much larger than live data.
#[derive(Serialize, Deserialize)]
struct TxWriteWire {
    collection: String,
    op: TxWriteOp,
    record_id: String,
    record: Option<Arc<StoredRecord>>,
    timestamp: i64,
    #[serde(default)]
    statement_snapshot: u64,
}

/// WAL representation of a stored-form UPDATE. Both JSON objects contain the
/// same small set of changed top-level metadata keys. Keeping the before-side
/// makes replay idempotent when a crash leaves checkpointed rows and their WAL
/// suffix temporarily overlapping.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub(crate) struct TxPatch {
    collection: String,
    record_id: String,
    before: Box<RawValue>,
    after: Box<RawValue>,
    timestamp: i64,
    #[serde(default)]
    statement_snapshot: u64,
}

fn compact_update_wal_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("BICDB_COMPACT_UPDATE_WAL")
            .map(|value| matches!(value.as_str(), "1" | "on" | "true" | "yes"))
            .unwrap_or(false)
    })
}

fn single_buffer_wal_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("BICDB_WAL_SINGLE_BUFFER")
            .map(|value| matches!(value.as_str(), "1" | "on" | "true" | "yes"))
            .unwrap_or(false)
    })
}

#[derive(Debug)]
pub(crate) enum PreparedWal {
    Payloads(Vec<Vec<u8>>),
    PlainFrames { count: usize, bytes: Vec<u8> },
}

impl Default for PreparedWal {
    fn default() -> Self {
        Self::Payloads(Vec::new())
    }
}

impl PreparedWal {
    fn len(&self) -> usize {
        match self {
            Self::Payloads(payloads) => payloads.len(),
            Self::PlainFrames { count, .. } => *count,
        }
    }
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    fn clear(&mut self) {
        *self = Self::default();
    }
    fn push<T: Serialize>(&mut self, frame: &T, capacity: usize) -> Result<()> {
        match self {
            Self::Payloads(payloads) => {
                let mut bytes = Vec::with_capacity(capacity);
                serde_json::to_writer(&mut bytes, frame)?;
                payloads.push(bytes);
            }
            Self::PlainFrames { count, bytes } => {
                storage::append_plain_json_frame(bytes, FrameKind::Transaction, frame)?;
                *count += 1;
            }
        }
        Ok(())
    }
    #[cfg(test)]
    fn first_payload(&self) -> &[u8] {
        match self {
            Self::Payloads(payloads) => &payloads[0],
            Self::PlainFrames { bytes, .. } => storage::first_plain_frame_payload(bytes),
        }
    }
}

fn compact_wal_patch(write: &TxWrite) -> Option<(Box<RawValue>, Box<RawValue>)> {
    if write.op != TxWriteOp::Upsert || write.repair.is_some() {
        return None;
    }
    let before = write.previous_stored.as_deref()?;
    let after = write.stored.as_deref()?;
    let changed = write.changed.as_deref()?;
    // A metadata patch is only a complete representation when every other
    // record field is unchanged and both rows really are resident bytes.
    if before.evicted.is_some()
        || after.evicted.is_some()
        || before.id != after.id
        || before.vector != after.vector
        || before.geometry != after.geometry
        || before.timestamp != after.timestamp
        || before.payload != after.payload
    {
        return None;
    }
    let before = crate::record::project_json_object_text(before.metadata.get(), changed)?;
    let after = crate::record::project_json_object_text(after.metadata.get(), changed)?;
    // A patch carries both sides for idempotent replay. Decline wide updates
    // (notably TPC-C bad-credit c_data rewrites) when those two projections are
    // no smaller than the complete metadata object they would replace.
    if before.len().saturating_add(after.len()) >= write.stored.as_ref()?.metadata.get().len() {
        return None;
    }
    Some((
        RawValue::from_string(before).ok()?,
        RawValue::from_string(after).ok()?,
    ))
}

impl Serialize for TxWrite {
    fn serialize<S: serde::Serializer>(
        &self,
        serializer: S,
    ) -> std::result::Result<S::Ok, S::Error> {
        #[derive(Serialize)]
        struct Wire<'a> {
            collection: &'a str,
            op: TxWriteOp,
            record_id: &'a str,
            record: Option<&'a Arc<Record>>,
            timestamp: i64,
            statement_snapshot: u64,
        }
        let record = self.record().map_err(serde::ser::Error::custom)?;
        Wire {
            collection: &self.collection,
            op: self.op,
            record_id: &self.record_id,
            record,
            timestamp: self.timestamp,
            statement_snapshot: self.statement_snapshot,
        }
        .serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for TxWrite {
    fn deserialize<D: serde::Deserializer<'de>>(
        deserializer: D,
    ) -> std::result::Result<Self, D::Error> {
        let wire = TxWriteWire::deserialize(deserializer)?;
        Ok(Self {
            collection: wire.collection,
            op: wire.op,
            record_id: wire.record_id,
            record: OnceLock::new(),
            timestamp: wire.timestamp,
            statement_snapshot: wire.statement_snapshot,
            repair: None,
            stored: wire.record,
            previous: None,
            previous_stored: None,
            changed: None,
        })
    }
}

/// Commit-time conflict repair for an "increment-shaped" update: the new value
/// of each repaired column is the old value plus a row-independent numeric
/// delta (`SET col = col + expr` where `expr` reads no column of the target
/// row). Instead of taking the row's write lock for the statement-to-commit
/// window, the writer buffers the absolute record it computed plus these
/// deltas; if the row turns out to have changed by commit time, the record is
/// rebuilt as `latest + deltas` — the same outcome PostgreSQL's READ COMMITTED
/// EvalPlanQual recheck produces — under a lock held only for the microseconds
/// of the commit section.
#[derive(Clone, Debug)]
pub struct RepairPlan {
    /// (top-level metadata key, numeric delta) per repaired column.
    pub deltas: Vec<(String, RepairDelta)>,
}

#[derive(Clone, Copy, Debug)]
pub enum RepairDelta {
    Int(i64),
    Float(f64),
    /// Exact fixed-point decimal (`units * 10^-scale`) — NUMERIC columns are
    /// stored as canonical decimal text, and their deltas arrive the same way.
    Decimal {
        units: i128,
        scale: u32,
    },
}

/// Parse canonical decimal text ("123", "-4.50") into fixed-point
/// (units, scale). `None` for exotic forms (exponents, NaN, > 27 digits).
pub fn parse_repair_decimal(text: &str) -> Option<(i128, u32)> {
    let text = text.trim();
    let (negative, digits) = match text.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => (false, text.strip_prefix('+').unwrap_or(text)),
    };
    if digits.is_empty() || digits.len() > 28 {
        return None;
    }
    let (int_part, frac_part) = match digits.split_once('.') {
        Some((int_part, frac_part)) => (int_part, frac_part),
        None => (digits, ""),
    };
    if !int_part.bytes().all(|b| b.is_ascii_digit())
        || !frac_part.bytes().all(|b| b.is_ascii_digit())
        || (int_part.is_empty() && frac_part.is_empty())
        || frac_part.len() > 18
    {
        return None;
    }
    let mut units: i128 = 0;
    for b in int_part.bytes().chain(frac_part.bytes()) {
        units = units.checked_mul(10)?.checked_add((b - b'0') as i128)?;
    }
    if negative {
        units = -units;
    }
    Some((units, frac_part.len() as u32))
}

fn format_repair_decimal(units: i128, scale: u32) -> String {
    if scale == 0 {
        return units.to_string();
    }
    let negative = units < 0;
    let magnitude = units.unsigned_abs();
    let divisor = 10u128.pow(scale);
    let int_part = magnitude / divisor;
    let frac_part = magnitude % divisor;
    format!(
        "{}{}.{:0width$}",
        if negative { "-" } else { "" },
        int_part,
        frac_part,
        width = scale as usize
    )
}

fn typed_numeric_repair_decimal(value: &Value) -> Option<(i128, u32)> {
    let envelope = value.get("$bicdb_typed")?;
    if envelope.get("version")?.as_u64()? != 1 || envelope.get("pg_type")?.as_str()? != "numeric" {
        return None;
    }
    if let Some(text) = envelope.get("text").and_then(Value::as_str) {
        return parse_repair_decimal(text);
    }
    let numeric = envelope.get("value")?;
    if numeric.get("kind")?.as_str()? != "finite" {
        return None;
    }
    let coefficient = numeric.get("coefficient")?.as_str()?;
    let scale = u32::try_from(numeric.get("display_scale")?.as_i64()?).ok()?;
    let mut units = coefficient.parse::<i128>().ok()?;
    if numeric.get("negative")?.as_bool()? {
        units = units.checked_neg()?;
    }
    Some((units, scale))
}

fn set_typed_numeric_repair_decimal(value: &mut Value, units: i128, scale: u32) -> Option<()> {
    let envelope = value.get_mut("$bicdb_typed")?.as_object_mut()?;
    let text = format_repair_decimal(units, scale);
    let index_key = crate::numeric_index_key_from_canonical_text(&text)?;
    envelope.insert(
        "index_key".to_string(),
        Value::String(hex::encode(index_key)),
    );
    if envelope.get("text").is_some_and(Value::is_string) {
        envelope.insert("text".to_string(), Value::String(text));
        return Some(());
    }
    let numeric = envelope.get_mut("value")?.as_object_mut()?;
    numeric.insert(
        "coefficient".to_string(),
        Value::String(units.unsigned_abs().to_string()),
    );
    numeric.insert("display_scale".to_string(), Value::from(scale));
    numeric.insert("negative".to_string(), Value::Bool(units < 0));
    Some(())
}

fn align_decimal_scale(units: i128, scale: u32, target: u32) -> Option<i128> {
    debug_assert!(target >= scale);
    units.checked_mul(10i128.checked_pow(target - scale)?)
}

/// Borrowed, serialize-only mirror of the [`TxFrame`] variants written on the
/// commit hot path. It serializes byte-for-byte identically to the owned
/// `TxFrame` (verified by `tx_frame_ref_matches_owned_serialization`), letting
/// commit append the WAL without cloning each write into an owned frame.
#[derive(Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum TxFrameRef<'a> {
    #[serde(rename = "tx_write")]
    Write {
        tx_id: TransactionId,
        write: &'a TxWrite,
    },
    /// `Write` with the record in its resident (`StoredRecord`) form. The two
    /// serialize byte-identically (`StoredRecord` is `Record` with the metadata
    /// kept as raw JSON), so `prepare_wal_payloads` can compact the record once
    /// and use that one serialization for the frame and the resident row.
    #[serde(rename = "tx_write")]
    WriteStored {
        tx_id: TransactionId,
        write: TxWriteStoredRef<'a>,
    },
    #[serde(rename = "tx_patch")]
    Patch {
        tx_id: TransactionId,
        patch: TxPatchRef<'a>,
    },
    #[serde(rename = "tx_broker_publish")]
    BrokerPublish {
        tx_id: TransactionId,
        publish: &'a crate::broker::PendingBrokerPublish,
    },
    #[serde(rename = "tx_record_audit")]
    RecordAudit {
        tx_id: TransactionId,
        event: &'a Event,
    },
    #[serde(rename = "tx_commit")]
    Commit {
        tx_id: TransactionId,
        timestamp: i64,
        commit_seq: u64,
    },
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub(crate) enum TxWriteOp {
    Upsert,
    Delete,
}

/// `TxWrite` by reference with the record as a `StoredRecord`; must keep the
/// exact field set and order of `TxWrite`'s serialized form.
#[derive(Serialize)]
struct TxWriteStoredRef<'a> {
    collection: &'a str,
    op: TxWriteOp,
    record_id: &'a str,
    record: Option<&'a StoredRecord>,
    timestamp: i64,
    statement_snapshot: u64,
}

#[derive(Serialize)]
struct TxPatchRef<'a> {
    collection: &'a str,
    record_id: &'a str,
    before: &'a RawValue,
    after: &'a RawValue,
    timestamp: i64,
    statement_snapshot: u64,
}

/// A snapshot-visible row in the cheapest form available without parsing its
/// JSON: see [`Transaction::get_stored`].
#[derive(Clone, Debug)]
pub enum VisibleRow {
    /// A committed row, as resident.
    Stored(Arc<StoredRecord>),
    /// A row this transaction has written (or a lazily paged row fetched from
    /// the page store): already a full `Record`.
    Pending(Arc<Record>),
}

impl VisibleRow {
    pub fn id(&self) -> &str {
        match self {
            Self::Stored(stored) => &stored.id,
            Self::Pending(record) => &record.id,
        }
    }

    /// The full `Record` form (parses a stored row's JSON).
    pub fn to_record(&self) -> Result<Arc<Record>> {
        match self {
            Self::Stored(stored) => stored.to_record().map(Arc::new),
            Self::Pending(record) => Ok(Arc::clone(record)),
        }
    }
}

/// See `Transaction::read_images`.
#[derive(Debug, Default)]
struct ReadImages {
    rows: FxHashMap<String, FxHashMap<String, (Arc<StoredRecord>, Arc<Record>)>>,
    len: usize,
}

const READ_IMAGE_CAP: usize = 4096;

impl ReadImages {
    fn remember(
        &mut self,
        collection: &str,
        id: &str,
        stored: Arc<StoredRecord>,
        record: Arc<Record>,
    ) {
        match self.rows.get_mut(collection) {
            Some(rows) => match rows.get_mut(id) {
                Some(slot) => *slot = (stored, record),
                None => {
                    if self.len >= READ_IMAGE_CAP {
                        return;
                    }
                    rows.insert(id.to_string(), (stored, record));
                    self.len += 1;
                }
            },
            None => {
                if self.len >= READ_IMAGE_CAP {
                    return;
                }
                let mut rows = FxHashMap::default();
                rows.insert(id.to_string(), (stored, record));
                self.rows.insert(collection.to_string(), rows);
                self.len += 1;
            }
        }
    }

    fn get(&self, collection: &str, id: &str) -> Option<(Arc<StoredRecord>, Arc<Record>)> {
        self.rows.get(collection)?.get(id).cloned()
    }
}

struct PreparedMemoryIndexJob {
    job_id: Uuid,
    action: PreparedMemoryIndexJobAction,
}

enum PreparedMemoryIndexJobAction {
    Index {
        collection: String,
        record: Record,
    },
    Stale {
        collection: String,
        record: Record,
    },
    Failed {
        status: MemoryJobStatus,
        error: String,
    },
}

fn tx_writes_by_collection(writes: &[TxWrite]) -> BTreeMap<&str, Vec<&TxWrite>> {
    let mut writes_by_collection = BTreeMap::<&str, Vec<&TxWrite>>::new();
    for write in writes {
        writes_by_collection
            .entry(write.collection.as_str())
            .or_default()
            .push(write);
    }
    writes_by_collection
}

fn tx_writes_are_unique(writes: &[TxWrite]) -> bool {
    let mut seen = FxHashSet::default();
    seen.reserve(writes.len());
    writes
        .iter()
        .all(|write| seen.insert((write.collection.as_str(), write.record_id.as_str())))
}

fn resulting_records_for_relation(
    db: &BicDb,
    tx: &Transaction,
    relation: &str,
) -> Result<Vec<Record>> {
    let mut records = db
        .scan_collection_unchecked(relation)?
        .into_iter()
        .map(|record| (record.id.clone(), record))
        .collect::<BTreeMap<_, _>>();
    for write in tx
        .writes
        .iter()
        .filter(|write| write.collection == relation)
    {
        match write.op {
            TxWriteOp::Upsert => {
                if let Some(record) = write.record()?.map(Arc::as_ref) {
                    records.insert(write.record_id.clone(), record.clone());
                }
            }
            TxWriteOp::Delete => {
                records.remove(&write.record_id);
            }
        }
    }
    Ok(records.into_values().collect())
}

fn json_number(value: Option<&Value>) -> Option<f64> {
    match value? {
        Value::Number(number) => number.as_f64(),
        Value::String(number) => number.parse().ok(),
        _ => None,
    }
}

fn record_invariant_field(record: &Record, field: &str) -> Value {
    match field {
        "id" => Value::String(record.id.clone()),
        "timestamp" => record.timestamp.map(Value::from).unwrap_or(Value::Null),
        "geometry" => record
            .geometry
            .as_ref()
            .map(|geometry| Value::String(geometry.to_wkt()))
            .unwrap_or(Value::Null),
        field => record.metadata.get(field).cloned().unwrap_or(Value::Null),
    }
}

fn invariant_index_type(value_type: NativeInvariantValueType) -> IndexPredicateValueType {
    match value_type {
        NativeInvariantValueType::Bool => IndexPredicateValueType::Bool,
        NativeInvariantValueType::Int64 => IndexPredicateValueType::Int64,
        NativeInvariantValueType::Float64 => IndexPredicateValueType::Float64,
        NativeInvariantValueType::Decimal => IndexPredicateValueType::Decimal,
        NativeInvariantValueType::String => IndexPredicateValueType::String,
        NativeInvariantValueType::Uuid => IndexPredicateValueType::Uuid,
        NativeInvariantValueType::Timestamp => IndexPredicateValueType::Timestamp,
        NativeInvariantValueType::Date => IndexPredicateValueType::Date,
        NativeInvariantValueType::Json => IndexPredicateValueType::Json,
    }
}

fn invariant_numeric_binary(
    operator: NativeInvariantBinaryOperator,
    left: &Value,
    right: &Value,
    value_type: NativeInvariantValueType,
) -> Result<Value> {
    match value_type {
        NativeInvariantValueType::Int64 => {
            let left = left.as_i64().ok_or_else(|| {
                BicDbError::CommitValidation("invariant integer operand is invalid".to_string())
            })?;
            let right = right.as_i64().ok_or_else(|| {
                BicDbError::CommitValidation("invariant integer operand is invalid".to_string())
            })?;
            let value = match operator {
                NativeInvariantBinaryOperator::Add => left.checked_add(right),
                NativeInvariantBinaryOperator::Subtract => left.checked_sub(right),
                NativeInvariantBinaryOperator::Multiply => left.checked_mul(right),
                NativeInvariantBinaryOperator::Divide if right != 0 => left.checked_div(right),
                _ => None,
            }
            .ok_or_else(|| {
                BicDbError::CommitValidation(
                    "invariant integer arithmetic overflowed or divided by zero".to_string(),
                )
            })?;
            Ok(Value::from(value))
        }
        NativeInvariantValueType::Float64 => {
            let left = left.as_f64().ok_or_else(|| {
                BicDbError::CommitValidation("invariant float operand is invalid".to_string())
            })?;
            let right = right.as_f64().ok_or_else(|| {
                BicDbError::CommitValidation("invariant float operand is invalid".to_string())
            })?;
            let value = match operator {
                NativeInvariantBinaryOperator::Add => left + right,
                NativeInvariantBinaryOperator::Subtract => left - right,
                NativeInvariantBinaryOperator::Multiply => left * right,
                NativeInvariantBinaryOperator::Divide => left / right,
                _ => unreachable!("numeric operator validated by caller"),
            };
            serde_json::Number::from_f64(value)
                .map(Value::Number)
                .ok_or_else(|| {
                    BicDbError::CommitValidation(
                        "invariant float arithmetic produced a non-finite value".to_string(),
                    )
                })
        }
        NativeInvariantValueType::Decimal => {
            let parse = |value: &Value| {
                value
                    .as_str()
                    .map(str::to_string)
                    .or_else(|| value.as_number().map(ToString::to_string))
                    .and_then(|value| Decimal::from_str(&value).ok())
                    .ok_or_else(|| {
                        BicDbError::CommitValidation(
                            "invariant decimal operand is invalid".to_string(),
                        )
                    })
            };
            let left = parse(left)?;
            let right = parse(right)?;
            let value = match operator {
                NativeInvariantBinaryOperator::Add => left.checked_add(right),
                NativeInvariantBinaryOperator::Subtract => left.checked_sub(right),
                NativeInvariantBinaryOperator::Multiply => left.checked_mul(right),
                NativeInvariantBinaryOperator::Divide => left.checked_div(right),
                _ => None,
            }
            .ok_or_else(|| {
                BicDbError::CommitValidation(
                    "invariant decimal arithmetic overflowed or divided by zero".to_string(),
                )
            })?;
            Ok(Value::String(value.to_string()))
        }
        _ => Err(BicDbError::CommitValidation(
            "invariant arithmetic requires a numeric type".to_string(),
        )),
    }
}

fn evaluate_native_invariant_expression(
    db: &BicDb,
    tx: &Transaction,
    subject_relation: &str,
    subject: &Record,
    bindings: &BTreeMap<String, Record>,
    expression: &NativeInvariantExpression,
) -> Result<Value> {
    Ok(match expression {
        NativeInvariantExpression::SubjectField { field } => record_invariant_field(subject, field),
        NativeInvariantExpression::BindingField { binding, field } => bindings
            .get(binding)
            .map(|record| record_invariant_field(record, field))
            .ok_or_else(|| {
                BicDbError::CommitValidation(format!(
                    "invariant binding `{binding}` is unavailable"
                ))
            })?,
        NativeInvariantExpression::Literal { value } => value.clone(),
        NativeInvariantExpression::Unary {
            operator,
            value,
            value_type,
        } => {
            let value = evaluate_native_invariant_expression(
                db,
                tx,
                subject_relation,
                subject,
                bindings,
                value,
            )?;
            match operator {
                NativeInvariantUnaryOperator::Not => {
                    Value::Bool(!value.as_bool().ok_or_else(|| {
                        BicDbError::CommitValidation(
                            "invariant `not` operand is not boolean".to_string(),
                        )
                    })?)
                }
                NativeInvariantUnaryOperator::Negate => invariant_numeric_binary(
                    NativeInvariantBinaryOperator::Subtract,
                    &match value_type {
                        NativeInvariantValueType::Decimal => Value::String("0".to_string()),
                        NativeInvariantValueType::Float64 => Value::from(0.0),
                        _ => Value::from(0),
                    },
                    &value,
                    *value_type,
                )?,
            }
        }
        NativeInvariantExpression::Binary {
            operator,
            left,
            right,
            value_type,
        } => {
            let left = evaluate_native_invariant_expression(
                db,
                tx,
                subject_relation,
                subject,
                bindings,
                left,
            )?;
            let right = evaluate_native_invariant_expression(
                db,
                tx,
                subject_relation,
                subject,
                bindings,
                right,
            )?;
            match operator {
                NativeInvariantBinaryOperator::Add
                | NativeInvariantBinaryOperator::Subtract
                | NativeInvariantBinaryOperator::Multiply
                | NativeInvariantBinaryOperator::Divide => {
                    invariant_numeric_binary(*operator, &left, &right, *value_type)?
                }
                NativeInvariantBinaryOperator::And => {
                    Value::Bool(left.as_bool() == Some(true) && right.as_bool() == Some(true))
                }
                NativeInvariantBinaryOperator::Or => {
                    Value::Bool(left.as_bool() == Some(true) || right.as_bool() == Some(true))
                }
                NativeInvariantBinaryOperator::Implies => {
                    Value::Bool(left.as_bool() == Some(false) || right.as_bool() == Some(true))
                }
                NativeInvariantBinaryOperator::Contains => Value::Bool(match (&left, &right) {
                    (Value::String(left), Value::String(right)) => left.contains(right),
                    (Value::Array(left), right) => left.contains(right),
                    _ => false,
                }),
                NativeInvariantBinaryOperator::Equal => Value::Bool(
                    left == right
                        || compare_predicate_values(
                            &left,
                            &right,
                            invariant_index_type(*value_type),
                        ) == Some(Ordering::Equal),
                ),
                NativeInvariantBinaryOperator::NotEqual => Value::Bool(
                    left != right
                        && compare_predicate_values(
                            &left,
                            &right,
                            invariant_index_type(*value_type),
                        ) != Some(Ordering::Equal),
                ),
                NativeInvariantBinaryOperator::Greater => Value::Bool(
                    compare_predicate_values(&left, &right, invariant_index_type(*value_type))
                        .is_some_and(Ordering::is_gt),
                ),
                NativeInvariantBinaryOperator::GreaterEqual => Value::Bool(
                    compare_predicate_values(&left, &right, invariant_index_type(*value_type))
                        .is_some_and(|ordering| !ordering.is_lt()),
                ),
                NativeInvariantBinaryOperator::Less => Value::Bool(
                    compare_predicate_values(&left, &right, invariant_index_type(*value_type))
                        .is_some_and(Ordering::is_lt),
                ),
                NativeInvariantBinaryOperator::LessEqual => Value::Bool(
                    compare_predicate_values(&left, &right, invariant_index_type(*value_type))
                        .is_some_and(|ordering| !ordering.is_gt()),
                ),
            }
        }
        NativeInvariantExpression::Overlaps { values, value_type } => {
            if values.len() != 4 {
                return Err(BicDbError::CommitValidation(
                    "invariant overlaps requires four values".to_string(),
                ));
            }
            let values = values
                .iter()
                .map(|value| {
                    evaluate_native_invariant_expression(
                        db,
                        tx,
                        subject_relation,
                        subject,
                        bindings,
                        value,
                    )
                })
                .collect::<Result<Vec<_>>>()?;
            let value_type = invariant_index_type(*value_type);
            Value::Bool(
                compare_predicate_values(&values[0], &values[3], value_type)
                    .is_some_and(Ordering::is_lt)
                    && compare_predicate_values(&values[2], &values[1], value_type)
                        .is_some_and(Ordering::is_lt),
            )
        }
        NativeInvariantExpression::Exists {
            binding,
            relation,
            condition,
        } => {
            let records = resulting_records_for_relation(db, tx, relation)?;
            let mut found = false;
            for record in records {
                if relation == subject_relation && record.id == subject.id {
                    continue;
                }
                let mut nested = bindings.clone();
                nested.insert(binding.clone(), record);
                if evaluate_native_invariant_expression(
                    db,
                    tx,
                    subject_relation,
                    subject,
                    &nested,
                    condition,
                )?
                .as_bool()
                    == Some(true)
                {
                    found = true;
                    break;
                }
            }
            Value::Bool(found)
        }
        NativeInvariantExpression::Aggregate {
            function,
            binding,
            relation,
            condition,
            field,
            value_type,
        } => {
            let records = resulting_records_for_relation(db, tx, relation)?;
            let mut count = 0i64;
            let mut sum = match value_type {
                NativeInvariantValueType::Decimal => Value::String("0".to_string()),
                NativeInvariantValueType::Float64 => Value::from(0.0),
                _ => Value::from(0),
            };
            for record in records {
                let mut nested = bindings.clone();
                nested.insert(binding.clone(), record.clone());
                if evaluate_native_invariant_expression(
                    db,
                    tx,
                    subject_relation,
                    subject,
                    &nested,
                    condition,
                )?
                .as_bool()
                    != Some(true)
                {
                    continue;
                }
                count = count.checked_add(1).ok_or_else(|| {
                    BicDbError::CommitValidation("invariant count overflowed".to_string())
                })?;
                if *function == NativeInvariantAggregateFunction::Sum {
                    let value = record_invariant_field(
                        &record,
                        field.as_deref().ok_or_else(|| {
                            BicDbError::CommitValidation("invariant sum lacks a field".to_string())
                        })?,
                    );
                    sum = invariant_numeric_binary(
                        NativeInvariantBinaryOperator::Add,
                        &sum,
                        &value,
                        *value_type,
                    )?;
                }
            }
            match function {
                NativeInvariantAggregateFunction::Count => Value::from(count),
                NativeInvariantAggregateFunction::Sum => sum,
            }
        }
    })
}

fn validate_carrier_invariant(
    db: &BicDb,
    tx: &Transaction,
    definition: &NativeInvariantDefinition,
) -> Result<()> {
    if !tx.writes.is_empty()
        && !tx
            .writes
            .iter()
            .any(|write| definition.dependency_relations.contains(&write.collection))
    {
        return Ok(());
    }
    let subjects = resulting_records_for_relation(db, tx, &definition.subject_relation)?;
    for subject in subjects {
        let value = evaluate_native_invariant_expression(
            db,
            tx,
            &definition.subject_relation,
            &subject,
            &BTreeMap::new(),
            &definition.expression,
        )?;
        let predicate = value.as_bool().ok_or_else(|| {
            BicDbError::CommitValidation(format!(
                "invariant `{}` did not return Bool",
                definition.name
            ))
        })?;
        let valid = match definition.kind {
            NativeInvariantKind::MustAlways => predicate,
            NativeInvariantKind::MustNever => !predicate,
        };
        if !valid {
            return Err(BicDbError::CommitValidation(format!(
                "invariant `{}` violated on `{}`/`{}`: {}",
                definition.name, definition.subject_relation, subject.id, definition.source
            )));
        }
    }
    Ok(())
}

#[derive(Clone, Debug)]
struct RetainedReplicationCommit {
    commit_seq: u64,
    tx_id: u64,
    timestamp: i64,
    writes: Vec<ReplicationWrite>,
}

fn tx_write_to_replication_write(
    collection_meta: Option<CollectionMeta>,
    write: &TxWrite,
) -> Result<ReplicationWrite> {
    let operation = match write.op {
        TxWriteOp::Upsert => ReplicationOperationType::Upsert,
        TxWriteOp::Delete => ReplicationOperationType::Delete,
    };
    let payload = match write.record()? {
        Some(record) => serde_json::to_vec(record.as_ref())?,
        None => Vec::new(),
    };
    Ok(ReplicationWrite {
        collection: write.collection.clone(),
        record_id: write.record_id.clone(),
        operation,
        payload,
        schema_version: 0,
        collection_meta,
    })
}

fn replication_writes_to_tx_writes(frame: &CommitFrame) -> Result<Vec<TxWrite>> {
    let mut writes = Vec::with_capacity(frame.writes.len());
    for write in &frame.writes {
        let op = match write.operation {
            ReplicationOperationType::Insert | ReplicationOperationType::Upsert => {
                TxWriteOp::Upsert
            }
            ReplicationOperationType::Delete => TxWriteOp::Delete,
        };
        let record = match write.operation {
            ReplicationOperationType::Insert | ReplicationOperationType::Upsert => {
                let record: Record = serde_json::from_slice(&write.payload)?;
                if record.id != write.record_id {
                    return Err(replication_error(format!(
                        "replication record id mismatch: frame has {}, payload has {}",
                        write.record_id, record.id
                    )));
                }
                Some(Arc::new(record))
            }
            ReplicationOperationType::Delete => None,
        };
        writes.push(TxWrite {
            collection: write.collection.clone(),
            op,
            record_id: write.record_id.clone(),
            record: OnceLock::from(record),
            timestamp: frame.timestamp,
            statement_snapshot: frame.previous_commit_seq,
            repair: None,
            stored: None,
            previous: None,
            previous_stored: None,
            changed: None,
        });
    }
    Ok(writes)
}

fn validate_replication_collection_meta(write: &ReplicationWrite) -> Result<()> {
    if let Some(meta) = write.collection_meta.as_ref() {
        if meta.name != write.collection {
            return Err(replication_error(format!(
                "replication collection metadata mismatch: write targets {}, metadata names {}",
                write.collection, meta.name
            )));
        }
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum TransactionIsolation {
    #[default]
    ReadCommitted,
    RepeatableRead,
    Serializable,
}

/// One logical row mutation presented to the distributed commit authority.
/// The payload is the exact post-validation record that the local commit path
/// will apply; deletes carry no record.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct CommitAdmissionMutation {
    pub collection: String,
    pub record_id: String,
    pub record: Option<Record>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct CommitAdmissionIntent {
    pub transaction_id: u64,
    pub mutations: Vec<CommitAdmissionMutation>,
}

/// Opaque durable decision returned by a commit authority. BicDB gives it
/// back only after the local transaction has applied, allowing the authority
/// to checkpoint crash recovery without exposing forgeable state to callers.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct CommitAdmissionTicket {
    pub authority: String,
    pub command_id: String,
}

/// Capability installed by the trusted cluster host. `admit` must not return
/// success until the intent has a durable quorum decision. Implementations
/// must be idempotent because transport ambiguity and process recovery can
/// repeat both calls.
pub trait CommitAdmission: std::fmt::Debug + Send + Sync {
    fn admit(&self, intent: &CommitAdmissionIntent) -> Result<CommitAdmissionTicket>;
    /// Record the exact durable local sequence for an admitted decision.
    /// This callback runs only after the transaction WAL is durable. Keeping
    /// the sequence in this trusted callback lets Cell writer fencing advance
    /// its external anti-rollback watermark without trusting SQL or a caller.
    fn local_applied(&self, ticket: &CommitAdmissionTicket, commit_seq: u64) -> Result<()>;

    /// Irreversibly reject future admissions for this installed authority.
    /// Implementations which cannot be fenced locally must refuse explicitly.
    fn fence(&self) -> Result<()> {
        Err(BicDbError::HighAvailability(
            "installed commit authority does not support local fencing".to_string(),
        ))
    }
}

/// A rollback boundary for one transaction's writes, locks and deferred effects.
/// Keep new transaction-local effect queues in this marker so every SQL
/// savepoint and procedural exception restores the same logical state.
#[derive(Clone, Copy, Debug)]
pub struct TransactionRollbackMark {
    transaction_id: TransactionId,
    write_len: usize,
    lock_len: usize,
    broker_publish_len: usize,
    deferred_hook_len: usize,
}

impl TransactionRollbackMark {
    pub fn write_len(&self) -> usize {
        self.write_len
    }
}

#[derive(Debug)]
pub struct Transaction {
    db: NonNull<BicDb>,
    id: TransactionId,
    snapshot_tx: TransactionId,
    // Un-floored contiguous applied watermark at begin; see
    // `begin_transaction_after`. Always <= snapshot_tx.
    applied_snapshot: u64,
    // Exact mutation version observed by point reads. This is separate from
    // `snapshot_tx`: that snapshot may be raised for read-your-writes while a
    // lower commit sequence is still applying. Carrying the row observation
    // into a later write prevents the raised snapshot from masking that change.
    observed_record_versions: Mutex<FxHashMap<String, FxHashMap<String, u64>>>,
    state: TxState,
    writes: Vec<TxWrite>,
    // Index over `writes`: collection -> record id -> position of the LAST
    // buffered write for that key. Read-your-writes overlays used to scan the
    // whole write log with two string compares per entry on every point read
    // (O(reads x writes) per transaction); this makes each overlay one hash
    // probe. Maintained by `push_writes`/`rebuild_write_index`; every mutation
    // of `writes` must go through them.
    write_index: FxHashMap<String, FxHashMap<String, usize>>,
    enqueue_memory_jobs_on_commit: bool,
    // Pre-serialized WAL Write-frame payloads, built before the commit acquires
    // the database write lock so the (CPU-heavy) serde serialization runs off the
    // serial commit critical section. Empty until `prepare_wal_payloads` is
    // called; the commit path falls back to serializing inline if so.
    prepared_wal: PreparedWal,
    // Pre-images handed out by point reads: collection -> id -> (the exact
    // resident StoredRecord, its parsed Record). A later write to the row
    // carries the pair (`TxWrite::previous`) so commit can diff index keys
    // without parsing the resident JSON again. Bounded: a transaction that
    // reads more rows than `READ_IMAGE_CAP` simply stops remembering.
    read_images: Mutex<ReadImages>,
    // Own handle to the shared record-lock map so an abandoned transaction can
    // release its locks on drop without dereferencing `db` (which would be
    // unsound if another thread holds the database write lock).
    write_locks: Arc<row_lock_waiters::RowLockTable>,
    // Every successfully acquired row lock, including locks taken before a
    // statement has produced a buffered write. UPDATE rechecks deliberately
    // lock before assignment/type validation; tracking only `writes` therefore
    // leaked those locks when validation failed and poisoned the row until
    // restart. The list is acquisition ordered and duplicate-free so a
    // savepoint can release exactly its suffix.
    /// Keys this transaction holds write locks on, released at commit or
    /// rollback. A SET, not a Vec: the membership check runs once per written
    /// record, and as a `Vec::contains` it made a transaction's own locking
    /// O(rows^2) — 100 -> 195 -> 813 us/row across 50k/100k/200k in a single
    /// bulk load, with no indexes, no audit and no projections involved.
    locked_keys: Mutex<LockedKeys>,
    // Own handle to the active-snapshot registry so drop can deregister this
    // transaction's snapshot (unblocking version-chain GC) without touching `db`.
    active_snapshots: Arc<ActiveSnapshots>,
    // Own handle to the transaction-state map so drop can remove this txn's
    // Pending entry when it is abandoned/conflict-dropped (committed/aborted txns
    // remove their own entry in the commit/rollback paths), keeping `tx_states`
    // bounded to in-flight transactions instead of leaking one entry per begin.
    tx_states: Arc<ShardedMutexMap<u64, TxState>>,
    // Broker publishes deferred to commit (`buffer_broker_publish`): flushed
    // by `commit_transaction` after the commit applies, dropped with the
    // transaction on rollback/abandonment. Interior mutability because SQL
    // engines hold `&Transaction` while evaluating expressions.
    pending_broker_publishes: Mutex<Vec<crate::broker::PendingBrokerPublish>>,
    // Audit events produced by this commit. Their exact bytes also ride the
    // transaction WAL; this in-memory copy is published to the event segment
    // only after `write_durable` succeeds.
    pending_record_audit_events: Vec<Event>,
    // Trusted application-runtime authority. Ordinary SQL, pgwire, direct API,
    // replication, and WASM data cannot manufacture these grants.
    mutation_actor: Option<MutationActor>,
    // Deferred trigger invocations (DEFERRABLE INITIALLY DEFERRED constraint
    // triggers) queued by the SQL layer, opaque to core. They ride the
    // transaction — not any session — because in server mode each statement
    // runs in its own short-lived session while the transaction travels the
    // whole BEGIN..COMMIT span. Fired by the SQL layer immediately before
    // commit; dropped with the transaction on rollback, which is exactly the
    // semantics deferral requires.
    deferred_hooks: Vec<serde_json::Value>,
    mutation_grants: BTreeMap<MutationGrantId, MutationGrant>,
    next_mutation_grant: u64,
    commit_validators: Vec<NativeCommitValidator>,
    isolation: TransactionIsolation,
    serializable_generation_snapshot: HashMap<String, u64>,
    serializable_reads: BTreeSet<String>,
    /// Used only by authenticated range-log replay. It is private to the core
    /// crate and therefore cannot be selected by SQL, pgwire, or extensions.
    bypass_commit_admission: bool,
    commit_admission_ticket: Option<(Arc<dyn CommitAdmission>, CommitAdmissionTicket)>,
    committed_seq: Option<u64>,
    // Paged mode: the page-store snapshot captured when this transaction began,
    // used to read rows a lazy collection has never touched this session (they
    // have no shard entry to consult). Capturing at begin rather than at each
    // read is what keeps those reads stable across the transaction's life —
    // and correct after a deleted row's chain is GC'd out of the shards, since
    // GC only runs once every snapshot entitled to the old value is gone.
    paged_snapshot: Option<bicdb_page::Snapshot>,
    _not_send: PhantomData<*mut BicDb>,
}

// A transaction may move between pgwire worker threads while it remains owned by
// a single connection. Its mutable operations still require `&mut self`, and the
// database pointer is dereferenced only by commit/rollback paths that the pgwire
// layer runs under the server's database lock.
unsafe impl Send for Transaction {}

impl DbSnapshot {
    pub fn transaction_id(&self) -> TransactionId {
        self.tx_id
    }

    pub fn get(&self, collection: &str, id: &str) -> Option<&Record> {
        self.records.get(collection)?.get(id)
    }

    pub fn scan(&self, collection: &str) -> Vec<Record> {
        self.records
            .get(collection)
            .map(|records| records.values().cloned().collect())
            .unwrap_or_default()
    }

    pub fn collection(&self, collection: &str) -> Option<&BTreeMap<String, Record>> {
        self.records.get(collection)
    }

    pub fn record_count(&self) -> usize {
        self.records.values().map(BTreeMap::len).sum()
    }
}

#[derive(Debug, Serialize, Deserialize)]
struct CollectionCatalog {
    collections: Vec<CollectionMeta>,
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct IndexCatalog {
    #[serde(default)]
    indexes: Vec<IndexDefinition>,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct FtsGenerationCatalog {
    #[serde(default)]
    indexes: BTreeMap<String, String>,
}

#[derive(Clone, Debug)]
struct PreparedMutation {
    record: Record,
    op_type: OpType,
}

/// A mutation's pre-image, parsed only if a consumer needs the full `Record`.
///
/// Commit index maintenance used to `to_record()` (JSON text -> `Value` tree)
/// the resident row of EVERY write just to diff its index keys. The B-tree
/// consumers now read the keys straight from the resident row's cells
/// (`stored_index_key`) and only the consumers that need a `Value` (predicate
/// indexes, full-text, spatial, exclusion, delete events) trigger the parse —
/// once, memoized here.
#[derive(Clone, Debug, Default)]
pub(crate) struct OldImage {
    stored: Option<Arc<StoredRecord>>,
    parsed: Arc<std::sync::OnceLock<Option<Arc<Record>>>>,
    /// The stored row's cells, scanned once per image as offsets into its own
    /// text (see `ImageCells`): every index of the collection asks this image
    /// for its key at commit, and each ask used to re-scan the row's JSON.
    cells: Arc<std::sync::OnceLock<Option<ImageCells>>>,
    /// Keys already built for this image, by the identity of the index's
    /// field list: unique claims, validation and apply each ask for the same
    /// (image, index) key, and building it copied every string each time.
    /// Field lists live in the index catalog, which a commit holds shared, so
    /// their address names an index for the image's lifetime.
    keys: Arc<std::sync::Mutex<Vec<ImageKeyMemo>>>,
}

/// One memoized (image, index field list) key: the values, and the encoded
/// bytes once any phase asked for them — claim, validate and apply each
/// re-encoded the same values into a fresh `Vec<u8>` before this.
#[derive(Debug)]
struct ImageKeyMemo {
    fields_ptr: usize,
    fields_len: usize,
    values: Option<Arc<Vec<IndexValue>>>,
    encoded: Option<Arc<[u8]>>,
}

/// One top-level cell of a stored row for index-key building, with every
/// text kept as a span of the row's metadata (only strings the scan had to
/// unescape are copied). `OwnedCellRow` copied every key and every value —
/// two allocations per column, for rows that then contribute one or two
/// index keys.
#[derive(Debug)]
struct ImageCells {
    cells: Vec<(ImageSpan, ImageCell)>,
    unescaped: Vec<String>,
}

#[derive(Clone, Copy, Debug)]
enum ImageSpan {
    Text(u32, u32),
    Unescaped(u32),
}

#[derive(Clone, Copy, Debug)]
enum ImageCell {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(ImageSpan),
    Envelope {
        index_key: Option<ImageSpan>,
        raw: ImageSpan,
    },
    Raw,
}

#[cfg(test)]
thread_local! {
    /// Rows scanned into `ImageCells` on this thread (commit-time key
    /// derivation); tests assert an untouched-index update scans none.
    pub(crate) static IMAGE_CELL_SCANS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

impl ImageCells {
    const MAX_KEY_MEMO: usize = 32;

    fn scan(stored: &StoredRecord) -> Option<Self> {
        #[cfg(test)]
        IMAGE_CELL_SCANS.with(|scans| scans.set(scans.get() + 1));
        let text = stored.metadata.get();
        let mut row: crate::record::CellRow<'_> = Vec::with_capacity(32);
        if !stored.cells_into(&mut row) {
            return None;
        }
        let mut unescaped: Vec<String> = Vec::new();
        let mut cells = Vec::with_capacity(row.len());
        let span_of = |part: &str, unescaped: &mut Vec<String>| -> ImageSpan {
            let start = (part.as_ptr() as usize).wrapping_sub(text.as_ptr() as usize);
            match start.checked_add(part.len()) {
                Some(end) if end <= text.len() && u32::try_from(end).is_ok() => {
                    ImageSpan::Text(start as u32, end as u32)
                }
                _ => {
                    unescaped.push(part.to_string());
                    ImageSpan::Unescaped((unescaped.len() - 1) as u32)
                }
            }
        };
        for (key, cell) in row {
            let key = match key {
                std::borrow::Cow::Borrowed(part) => span_of(part, &mut unescaped),
                std::borrow::Cow::Owned(owned) => {
                    unescaped.push(owned);
                    ImageSpan::Unescaped((unescaped.len() - 1) as u32)
                }
            };
            let cell = match cell {
                crate::record::CellRef::Null => ImageCell::Null,
                crate::record::CellRef::Bool(value) => ImageCell::Bool(value),
                crate::record::CellRef::Int(value) => ImageCell::Int(value),
                crate::record::CellRef::Float(value) => ImageCell::Float(value),
                crate::record::CellRef::Str(std::borrow::Cow::Borrowed(part)) => {
                    ImageCell::Str(span_of(part, &mut unescaped))
                }
                crate::record::CellRef::Str(std::borrow::Cow::Owned(owned)) => {
                    unescaped.push(owned);
                    ImageCell::Str(ImageSpan::Unescaped((unescaped.len() - 1) as u32))
                }
                crate::record::CellRef::Envelope { index_key, raw, .. } => ImageCell::Envelope {
                    index_key: index_key.map(|part| span_of(part, &mut unescaped)),
                    raw: span_of(raw, &mut unescaped),
                },
                crate::record::CellRef::Raw(_) => ImageCell::Raw,
            };
            cells.push((key, cell));
        }
        Some(Self { cells, unescaped })
    }

    fn text<'a>(&'a self, base: &'a str, span: ImageSpan) -> &'a str {
        match span {
            ImageSpan::Text(start, end) => &base[start as usize..end as usize],
            ImageSpan::Unescaped(index) => self.unescaped[index as usize].as_str(),
        }
    }
}

impl OldImage {
    fn none() -> Self {
        Self::default()
    }

    fn from_record(record: Option<Arc<Record>>) -> Self {
        let parsed = std::sync::OnceLock::new();
        let _ = parsed.set(record);
        Self {
            stored: None,
            parsed: Arc::new(parsed),
            cells: Arc::new(std::sync::OnceLock::new()),
            keys: Arc::default(),
        }
    }

    fn from_stored(stored: Arc<StoredRecord>) -> Self {
        Self {
            stored: Some(stored),
            parsed: Arc::new(std::sync::OnceLock::new()),
            cells: Arc::new(std::sync::OnceLock::new()),
            keys: Arc::default(),
        }
    }

    fn is_some(&self) -> bool {
        self.stored.is_some() || self.parsed.get().is_some_and(Option::is_some)
    }

    fn is_none(&self) -> bool {
        !self.is_some()
    }

    fn id(&self) -> Option<&str> {
        if let Some(stored) = self.stored.as_deref() {
            return Some(stored.id.as_str());
        }
        self.parsed
            .get()
            .and_then(Option::as_ref)
            .map(|record| record.id.as_str())
    }

    fn has_vector(&self) -> bool {
        if let Some(stored) = self.stored.as_deref() {
            return stored.vector.is_some();
        }
        self.parsed
            .get()
            .and_then(Option::as_ref)
            .is_some_and(|record| record.vector.is_some())
    }

    /// The full pre-image, parsed on first use.
    fn record(&self) -> Result<Option<&Arc<Record>>> {
        if let Some(parsed) = self.parsed.get() {
            return Ok(parsed.as_ref());
        }
        let record = match self.stored.as_deref() {
            Some(stored) => Some(Arc::new(stored.to_record()?)),
            None => None,
        };
        let _ = self.parsed.set(record);
        Ok(self.parsed.get().and_then(Option::as_ref))
    }

    /// The pre-image's key under `fields`: from the resident row's cells when
    /// every field is cell-representable, else from the parsed record. Built
    /// once per (image, field list); see `keys`.
    fn index_key(&self, fields: &[IndexField]) -> Result<Option<Arc<Vec<IndexValue>>>> {
        let identity = (fields.as_ptr() as usize, fields.len());
        if let Ok(keys) = self.keys.lock() {
            if let Some(memo) = keys
                .iter()
                .find(|memo| (memo.fields_ptr, memo.fields_len) == identity)
            {
                return Ok(memo.values.clone());
            }
        }
        let key = self.build_index_key(fields)?.map(Arc::new);
        if let Ok(mut keys) = self.keys.lock() {
            if keys.len() < ImageCells::MAX_KEY_MEMO {
                keys.push(ImageKeyMemo {
                    fields_ptr: identity.0,
                    fields_len: identity.1,
                    values: key.clone(),
                    encoded: None,
                });
            }
        }
        Ok(key)
    }

    /// `encode_index_key(index_key(fields))`, encoded once per (image, field
    /// list) and shared by unique claims, validation and apply.
    fn encoded_index_key(&self, fields: &[IndexField]) -> Result<Option<Arc<[u8]>>> {
        let identity = (fields.as_ptr() as usize, fields.len());
        if let Ok(keys) = self.keys.lock() {
            if let Some(memo) = keys
                .iter()
                .find(|memo| (memo.fields_ptr, memo.fields_len) == identity)
            {
                if memo.values.is_none() {
                    return Ok(None);
                }
                if let Some(encoded) = &memo.encoded {
                    return Ok(Some(Arc::clone(encoded)));
                }
            }
        }
        let Some(values) = self.index_key(fields)? else {
            return Ok(None);
        };
        let encoded: Arc<[u8]> = Arc::from(encode_index_key(&values).into_boxed_slice());
        if let Ok(mut keys) = self.keys.lock() {
            if let Some(memo) = keys
                .iter_mut()
                .find(|memo| (memo.fields_ptr, memo.fields_len) == identity)
            {
                memo.encoded = Some(Arc::clone(&encoded));
            }
        }
        Ok(Some(encoded))
    }

    fn build_index_key(&self, fields: &[IndexField]) -> Result<Option<Vec<IndexValue>>> {
        if self.parsed.get().is_none() {
            if let Some(stored) = self.stored.as_deref() {
                if let Some(cells) = self.cells.get_or_init(|| ImageCells::scan(stored)) {
                    if let Some(key) = image_cells_index_key(stored, cells, fields) {
                        return Ok(Some(key));
                    }
                }
            }
        }
        Ok(self
            .record()?
            .map(|record| record_index_key(record, fields)))
    }

    /// Whether the pre-image satisfies the index predicate (`None` = no
    /// pre-image). A predicate-less index needs no record at all.
    fn matches_predicate(&self, definition: &IndexDefinition) -> Result<Option<bool>> {
        if definition.predicate.is_none() {
            return Ok(self.is_some().then_some(true));
        }
        Ok(match self.record()? {
            Some(record) => Some(record_matches_index_predicate(record, definition)?),
            None => None,
        })
    }
}

#[derive(Clone, Debug)]
struct IndexRecordMutation {
    // Shared (Arc) so building the mutation list clones a pointer, not the whole
    // record. Records are already stored as Arc<Record>; deep-cloning them here
    // was ~half the serial commit critical section.
    old_record: OldImage,
    /// The post-image in the same lazy form as the pre-image: an upsert that
    /// arrives as a `StoredRecord` (the SQL layer's prepared row) derives its
    /// index keys from its cells and never parses a `Value` tree unless an
    /// index kind needs one (predicates, full text, spatial, exclusion).
    new_record: OldImage,
    /// The mutated record's physical locator, used as the index payload. `None`
    /// until resolved by [`BicDb::fill_index_mutation_rowids`]: for a brand-new
    /// record it is unallocated at uniqueness-validation time (validation handles
    /// that case in pk-space) and resolved after the record is applied; for an
    /// update/delete the existing record's rowid is resolvable throughout.
    rowid: Option<RowId>,
    /// The keys the write changed against its pre-image, when known (see
    /// [`TxWrite::changed`]). An index whose fields all lie outside this set
    /// is untouched by the mutation: same record, same key, same locator.
    changed: Option<Arc<[Box<str>]>>,
}

impl IndexRecordMutation {
    /// True when this mutation cannot change `definition`'s entry for the
    /// record: an update (same id on both sides) whose changed-key set is
    /// known and disjoint from every column the index reads, on an index
    /// without a predicate or exclusion constraint (those read other columns).
    fn leaves_index_untouched(&self, definition: &IndexDefinition) -> bool {
        let Some(changed) = self.changed.as_deref() else {
            return false;
        };
        if definition.predicate.is_some() || definition.exclusion.is_some() {
            return false;
        }
        let (Some(old_id), Some(new_id)) = (self.old_record.id(), self.new_record.id()) else {
            return false;
        };
        if old_id != new_id {
            return false;
        }
        fn base_column(field: &IndexField) -> Option<&str> {
            match field {
                IndexField::MetadataPath(path) => path.first().map(String::as_str),
                IndexField::Lower(inner) | IndexField::Trim(inner) => base_column(inner),
                // The id cannot change here; timestamps and geometry are
                // not top-level keys the writer accounts for.
                IndexField::Id | IndexField::Timestamp | IndexField::Geometry => None,
            }
        }
        definition.fields.iter().all(|field| {
            base_column(field).is_some_and(|column| !changed.iter().any(|key| &**key == column))
        })
    }
}

impl VectorStore {
    /// Rebuild from every record (across all shards). `records` is cloned once to
    /// make the dimension-detection pass, so pass a cheap iterator (e.g. over
    /// `Arc<StoredRecord>` refs).
    fn rebuild_from<'a>(&mut self, records: impl Iterator<Item = &'a StoredRecord> + Clone) {
        #[cfg(test)]
        {
            self.rebuild_count = self.rebuild_count.saturating_add(1);
        }
        self.dim = None;
        self.record_ids.clear();
        self.vectors.clear();
        self.norms.clear();

        if let Some(dim) = records
            .clone()
            .find_map(|record| record.vector.as_ref().map(Vec::len))
        {
            self.dim = Some(dim);
        }

        for record in records {
            self.push_record(record);
        }
    }

    fn push_record(&mut self, record: &StoredRecord) {
        let Some(vector) = record.vector.as_deref() else {
            return;
        };

        self.dim.get_or_insert(vector.len());
        self.record_ids.push(record.id.clone());
        self.vectors.extend_from_slice(vector);
        self.norms.push(vector::vector_norm(vector));
    }

    fn profile_search(
        &self,
        collection: &str,
        records: &RecordByPk,
        query: &[f32],
        top_k: usize,
        metric: VectorMetric,
    ) -> Result<ProfiledVectorSearch> {
        self.validate_search(collection, query, top_k)?;
        let total_started = Instant::now();

        let Some(dim) = self.dim else {
            return Ok(ProfiledVectorSearch {
                results: Vec::new(),
                profile: VectorSearchProfile {
                    candidate_records: records.len(),
                    vectors_read: 0,
                    dim: query.len(),
                    top_k,
                    total: total_started.elapsed(),
                    ..VectorSearchProfile::default()
                },
            });
        };

        let read_started = Instant::now();
        for vector in self.vectors.chunks_exact(dim) {
            black_box(vector.as_ptr());
        }
        let read_vectors = read_started.elapsed();

        let query_norm = vector::vector_norm(query);
        let similarity_started = Instant::now();
        let mut score_acc = 0.0_f32;
        for (index, vector) in self.vectors.chunks_exact(dim).enumerate() {
            score_acc +=
                vector::score_with_norm(metric, query, query_norm, vector, self.norms[index]);
        }
        black_box(score_acc);
        let similarity = similarity_started.elapsed();

        let (results, top_k_heap, final_sort) =
            self.search_with_heap_timing(collection, records, query, top_k, metric)?;

        Ok(ProfiledVectorSearch {
            profile: VectorSearchProfile {
                candidate_records: records.len(),
                vectors_read: self.record_ids.len(),
                dim,
                top_k,
                read_vectors,
                similarity,
                top_k_heap,
                final_sort,
                total: total_started.elapsed(),
            },
            results,
        })
    }

    fn validate_search(&self, collection: &str, query: &[f32], top_k: usize) -> Result<()> {
        if top_k == 0 {
            return Err(BicDbError::InvalidTopK);
        }

        if let Some(expected) = self.dim {
            if expected != query.len() {
                return Err(BicDbError::DimensionMismatch {
                    collection: collection.to_string(),
                    expected,
                    actual: query.len(),
                });
            }
        }

        Ok(())
    }

    fn search_untimed_cancellable(
        &self,
        collection: &str,
        records: &RecordByPk,
        query: &[f32],
        top_k: usize,
        metric: VectorMetric,
        cancellation: &CancellationToken,
    ) -> Result<Vec<VectorSearchResult>> {
        self.validate_search(collection, query, top_k)?;
        let Some(dim) = self.dim else {
            return Ok(Vec::new());
        };

        let query_norm = vector::vector_norm(query);
        let mut heap = BinaryHeap::with_capacity(top_k.saturating_add(1));
        for (index, vector) in self.vectors.chunks_exact(dim).enumerate() {
            if index % 1024 == 0 {
                cancellation.check()?;
            }
            let score =
                vector::score_with_norm(metric, query, query_norm, vector, self.norms[index]);
            if heap.len() < top_k {
                heap.push(StoreHeapItem { score, index });
                continue;
            }

            if heap.peek().is_some_and(|worst| score > worst.score) {
                heap.pop();
                heap.push(StoreHeapItem { score, index });
            }
        }
        cancellation.check()?;

        let mut scored = heap.into_iter().collect::<Vec<_>>();
        cancellation.check()?;
        scored.sort_by(|left, right| {
            right
                .score
                .total_cmp(&left.score)
                .then_with(|| self.record_ids[left.index].cmp(&self.record_ids[right.index]))
        });
        cancellation.check()?;

        scored
            .into_iter()
            .map(|item| {
                let record_id = &self.record_ids[item.index];
                let Some(entry) = records.get(record_id) else {
                    return Err(BicDbError::CollectionNotFound(format!(
                        "vector store referenced missing record '{record_id}' in {collection}"
                    )));
                };
                Ok(VectorSearchResult {
                    record: entry.record.to_record()?,
                    score: item.score,
                })
            })
            .collect()
    }

    fn search_with_heap_timing(
        &self,
        collection: &str,
        records: &RecordByPk,
        query: &[f32],
        top_k: usize,
        metric: VectorMetric,
    ) -> Result<(Vec<VectorSearchResult>, Duration, Duration)> {
        let Some(dim) = self.dim else {
            return Ok((Vec::new(), Duration::ZERO, Duration::ZERO));
        };

        let query_norm = vector::vector_norm(query);
        let mut heap = BinaryHeap::with_capacity(top_k.saturating_add(1));
        let mut top_k_heap = Duration::ZERO;
        for (index, vector) in self.vectors.chunks_exact(dim).enumerate() {
            let score =
                vector::score_with_norm(metric, query, query_norm, vector, self.norms[index]);
            let heap_started = Instant::now();
            if heap.len() < top_k {
                heap.push(StoreHeapItem { score, index });
                top_k_heap += heap_started.elapsed();
                continue;
            }

            if heap.peek().is_some_and(|worst| score > worst.score) {
                heap.pop();
                heap.push(StoreHeapItem { score, index });
            }
            top_k_heap += heap_started.elapsed();
        }

        let mut scored = heap.into_iter().collect::<Vec<_>>();
        let sort_started = Instant::now();
        scored.sort_by(|left, right| {
            right
                .score
                .total_cmp(&left.score)
                .then_with(|| self.record_ids[left.index].cmp(&self.record_ids[right.index]))
        });
        let final_sort = sort_started.elapsed();

        let results = scored
            .into_iter()
            .map(|item| {
                let record_id = &self.record_ids[item.index];
                let Some(entry) = records.get(record_id) else {
                    return Err(BicDbError::CollectionNotFound(format!(
                        "vector store referenced missing record '{record_id}' in {collection}"
                    )));
                };
                Ok(VectorSearchResult {
                    record: entry.record.to_record()?,
                    score: item.score,
                })
            })
            .collect::<Result<Vec<_>>>()?;

        Ok((results, top_k_heap, final_sort))
    }
}

impl BicDb {
    /// Install or replace the trusted distributed commit authority. A
    /// distributed database remains read-only until this is called.
    pub fn install_commit_admission(&self, admission: Arc<dyn CommitAdmission>) {
        *self.commit_admission.write() = Some(admission);
    }

    /// Fence the installed writer while holding the same exclusive gate that
    /// every commit crosses. When this returns, all commits which passed
    /// admission have finished local apply and no later commit can be admitted.
    /// Callers must still flush WAL before issuing a durable fence receipt.
    pub fn fence_commit_admission(&self) -> Result<()> {
        let _quiesced = self.serializable_commit_admission.write();
        let admission = self.commit_admission.read().clone().ok_or_else(|| {
            BicDbError::HighAvailability(
                "cannot fence before a commit authority is installed".to_string(),
            )
        })?;
        admission.fence()
    }

    /// Create a backup at an exact commit boundary without revoking the
    /// writer. The exclusive admission gate waits for every commit already in
    /// flight and prevents a later commit from crossing until the encrypted
    /// archive is durably published. The returned sequence is therefore the
    /// precise database history represented by the archive.
    pub fn create_consistent_backup(
        &self,
        backup_path: impl AsRef<Path>,
        options: crate::backup::BackupCreateOptions,
    ) -> Result<(crate::backup::BackupCreateReport, u64)> {
        let _quiesced = self.serializable_commit_admission.write();
        let report = crate::backup::create_backup_from_open_database(self, backup_path, options)?;
        Ok((report, self.last_applied_commit_seq()))
    }

    pub fn clear_commit_admission(&self) {
        *self.commit_admission.write() = None;
    }

    pub fn commit_admission_ready(&self) -> bool {
        self.commit_admission.read().is_some()
    }

    /// Apply a command that already crossed the authenticated range consensus
    /// boundary. This is deliberately narrower than exposing a general bypass:
    /// callers provide only concrete row mutations and still pass through the
    /// ordinary transaction/WAL/index/constraint machinery.
    pub(crate) fn apply_admitted_mutations(
        &self,
        mutations: &[CommitAdmissionMutation],
    ) -> Result<()> {
        if mutations.is_empty() {
            return Ok(());
        }
        let mut tx = self.begin_transaction()?;
        tx.bypass_commit_admission = true;
        for mutation in mutations {
            match &mutation.record {
                Some(record) => tx.insert(&mutation.collection, record.clone())?,
                None => tx.delete(&mutation.collection, &mutation.record_id)?,
            }
        }
        tx.commit()
    }

    /// Apply one already-authorized anti-entropy repair batch through the
    /// ordinary transaction, WAL, index, and constraint path. The data-node
    /// service owns quorum evidence, bucket, epoch, and fence admission; this
    /// method repeats the range boundary check before using the narrow physical
    /// replication bypass.
    pub(crate) fn apply_range_anti_entropy_mutations_as_local(
        &self,
        range: &RangeDescriptor,
        mutations: &[CommitAdmissionMutation],
    ) -> Result<usize> {
        for mutation in mutations {
            if !range.contains_token(distribution_key_token(
                &mutation.collection,
                &mutation.record_id,
            )) || mutation
                .record
                .as_ref()
                .is_some_and(|record| record.id != mutation.record_id)
            {
                return Err(BicDbError::Cluster(format!(
                    "anti-entropy mutation `{}/{}` is outside range {} or has a mismatched record",
                    mutation.collection, mutation.record_id, range.id
                )));
            }
            self.ensure_collection(&mutation.collection)?;
        }
        if mutations.is_empty() {
            return Ok(0);
        }
        let mut tx = self.begin_transaction()?;
        tx.bypass_commit_admission = true;
        for mutation in mutations {
            match &mutation.record {
                Some(record) => {
                    tx.write_upserts_unchecked(&mutation.collection, vec![record.clone()])?
                }
                None => tx.delete(&mutation.collection, &mutation.record_id)?,
            }
        }
        tx.commit()?;
        Ok(mutations.len())
    }

    pub fn open(path: impl AsRef<Path>) -> Result<Self> {
        Self::open_with_config(path, DbConfig::default())
    }

    pub fn open_with_config(path: impl AsRef<Path>, config: DbConfig) -> Result<Self> {
        Self::open_inner(path, config, None, None)
    }

    pub fn open_with_encryption(
        path: impl AsRef<Path>,
        config: DbConfig,
        encryption: EncryptionConfig,
    ) -> Result<Self> {
        Self::open_inner(path, config, None, Some(encryption))
    }

    pub fn open_with_node_id(
        path: impl AsRef<Path>,
        config: DbConfig,
        node_id: NodeId,
    ) -> Result<Self> {
        Self::open_inner(path, config, Some(node_id), None)
    }

    pub fn open_with_node_id_and_encryption(
        path: impl AsRef<Path>,
        config: DbConfig,
        node_id: NodeId,
        encryption: EncryptionConfig,
    ) -> Result<Self> {
        Self::open_inner(path, config, Some(node_id), Some(encryption))
    }

    fn open_inner(
        path: impl AsRef<Path>,
        config: DbConfig,
        configured_node_id: Option<NodeId>,
        encryption_config: Option<EncryptionConfig>,
    ) -> Result<Self> {
        config.replication.validate()?;
        config.consensus.validate()?;
        let path = path.as_ref().to_path_buf();
        let open_trace = std::env::var("BICDB_OPEN_TRACE").is_ok();
        let trace_start = std::time::Instant::now();
        macro_rules! open_trace {
            ($label:expr) => {
                if open_trace {
                    eprintln!(
                        "[open_trace] {:<28} +{:>8.3}s",
                        $label,
                        trace_start.elapsed().as_secs_f64()
                    );
                }
            };
        }
        // Storage-mode fencing is entirely read-only and runs before anything
        // can write to `path`, including the format-version migration below.
        let effective_mode = format::ensure_storage_mode_compatible(&path, &config.storage_mode)?;
        format::ensure_open_compatible_in_mode(&path, config.fsync, effective_mode.clone())?;
        // Also read-only, and also before any directory is created: the paged
        // engine cannot honour encryption at rest yet, and a refused open must
        // not leave `encryption.json` behind (see ADR-004).
        encryption::ensure_compatible_with_storage_mode(
            &path,
            &effective_mode,
            encryption_config.as_ref(),
        )?;
        fs::create_dir_all(path.join(DEFAULT_SEGMENTS_DIR))?;

        // Claim the directory before anything reads or writes state in it. A
        // second writer here is unrecoverable rather than merely racy, so this
        // never blocks: waiting would turn a caller bug into a hang.
        let directory_lock = bicdb_page::DirectoryLock::acquire(&path).map_err(|_| {
            BicDbError::PagedStorage(format!(
                "database at {} is already open by another process or handle; a second writer would silently discard committed transactions and can leave the database unopenable. Stop the running server (or drop the other handle) first, or reach this database through it rather than through its files.",
                path.display()
            ))
        })?;
        // This inode must exist before recovery or any foreground append. A
        // backup takes it exclusively while every physical writer holds it
        // shared, eliminating the check-then-write race of the old marker.
        storage::initialize_backup_write_gate(&path)?;

        let encryption = encryption::open_runtime(&path, encryption_config, config.fsync)?;
        let paged_records = if effective_mode == StorageMode::ServerPaged {
            Some(Arc::new(crate::paged_collection::PagedRecords::open(
                path.join(DEFAULT_PAGED_DIR),
                crate::paged_collection::PagedRecordsOptions {
                    page_size: config.paged_page_size,
                    buffer_pool_bytes: config.paged_buffer_pool_bytes,
                    read_ahead_queue_pages: config.paged_read_ahead_queue_pages,
                    wal_max_bytes: config.paged_wal_max_bytes,
                    wal_segment_bytes: config.paged_wal_segment_bytes,
                    extent_bytes: config.paged_extent_bytes,
                    fsync: config.fsync,
                    accept_legacy_meta: config.paged_accept_legacy_meta,
                },
            )?))
        } else {
            None
        };
        let fts_generations =
            load_fts_generation_catalog(&path.join(DEFAULT_FTS_GENERATION_CATALOG))?;
        if let Some(paged) = &paged_records {
            paged.set_index_aliases(fts_generations.indexes.clone());
        }

        let ha_state = load_ha_state(&path)?;
        let consensus_state = load_consensus_state(&path, &config.consensus)?;
        let mut tx_recovery = recover_transaction_log(
            &path.join(DEFAULT_TRANSACTION_LOG),
            config.read_mode,
            &encryption,
        )?;
        let replication_state =
            load_replication_state(&path, &config.replication, tx_recovery.last_commit_seq)?;
        open_trace!("tx_recovery");
        let metas = load_catalog(&path.join(DEFAULT_COLLECTION_CATALOG), &encryption)?;
        let mut collections = FxHashMap::default();
        let mut segment_replay = SegmentReplayIndex::default();
        // Which collections carry secondary indexes — read early because the
        // paged open path must know before building each collection's resident
        // state. The catalog is a small JSON file; reading it twice is cheaper
        // than restructuring open around it.
        let paged_index_catalog: Vec<IndexDefinition> =
            if paged_records.is_some() && config.load_secondary_indexes {
                load_index_catalog(&path.join(DEFAULT_INDEX_CATALOG), &encryption)?
            } else {
                Vec::new()
            };
        let mut paged_registry_collections = FxHashSet::default();
        let mut fallback_fts_registry_collections = FxHashSet::default();
        let mut paged_fts_read_through_indexes = FxHashSet::default();
        let mut paged_fts_incomplete_build_indexes = FxHashSet::default();
        let mut paged_fts_empty_sentinel_indexes = FxHashSet::default();
        let mut fts_open_metrics = FullTextOpenMetrics::default();
        if let Some(paged) = paged_records.as_ref() {
            let index_snapshot = paged.latest_snapshot();
            // A collection whose every catalog index is a durable kind runs
            // in registry mode, and only there does the pk->rowid registry
            // exist for read-through lookups to resolve locators through.
            let mut collection_all_durable: FxHashMap<&str, bool> = FxHashMap::default();
            for definition in &paged_index_catalog {
                let durable = matches!(definition.kind, IndexKind::BTree | IndexKind::FullText);
                collection_all_durable
                    .entry(definition.collection.as_str())
                    .and_modify(|all| *all &= durable)
                    .or_insert(durable);
            }
            for definition in &paged_index_catalog {
                match definition.kind {
                    IndexKind::BTree => {
                        paged_registry_collections.insert(definition.collection.clone());
                        // Read-through: the index's own bytes stay on pages
                        // (4c-2). Eligible when the restartable build
                        // published it (generation alias), or when durable
                        // entries exist for it and the collection is
                        // registry-mode. Exclusion constraints stay resident:
                        // their validator needs resident key sets, and the
                        // restartable build refuses them for the same reason.
                        // Entries absent while rows exist (pre-4a) falls to
                        // the resident load exactly as before.
                        if fts_generations.indexes.contains_key(&definition.name) {
                            paged_fts_read_through_indexes.insert(definition.name.clone());
                        } else if definition.exclusion.is_none()
                            && collection_all_durable
                                .get(definition.collection.as_str())
                                .copied()
                                .unwrap_or(false)
                            && paged
                                .scan_index(&index_snapshot, &definition.name)?
                                .next()
                                .transpose()?
                                .is_some()
                        {
                            paged_fts_read_through_indexes.insert(definition.name.clone());
                        }
                    }
                    IndexKind::FullText => {
                        fts_open_metrics.index_count += 1;
                        let replacement_in_progress =
                            crate::fts_build::FtsBuildWorkspace::open_existing(
                                &path.join(DEFAULT_FTS_BUILD_DIR),
                                &definition.name,
                                config.fsync,
                            )?
                            .is_some();
                        let published_generation =
                            fts_generations.indexes.contains_key(&definition.name);
                        if replacement_in_progress && !published_generation {
                            // A first build has no safe generation to serve.
                            // A replacement build does: its unpublished
                            // workspace must never shadow the generation the
                            // durable alias still identifies as published.
                            paged_fts_incomplete_build_indexes.insert(definition.name.clone());
                            continue;
                        }
                        let open_state =
                            paged_full_text_open_state(paged, &index_snapshot, &definition.name)?;
                        fts_open_metrics.metadata_probes += open_state.metadata_probes;
                        if open_state.read_through_ready {
                            paged_fts_read_through_indexes.insert(definition.name.clone());
                        }
                        if open_state.empty_sentinel_candidate {
                            paged_fts_empty_sentinel_indexes.insert(definition.name.clone());
                        }
                        if open_state.registry_required {
                            paged_registry_collections.insert(definition.collection.clone());
                            fallback_fts_registry_collections.insert(definition.collection.clone());
                        }
                    }
                    _ => {}
                }
            }
        }
        // Durable-kind definitions by collection, for maintaining durable
        // index entries during WAL replay (the live path reads them from
        // `self.indexes`, which does not exist yet at this point in open).
        let paged_durable_defs: FxHashMap<String, Vec<PagedDurableIndexDef>> = {
            let mut defs: FxHashMap<String, Vec<PagedDurableIndexDef>> = FxHashMap::default();
            for definition in &paged_index_catalog {
                // A spatial index with a published packed base — or a packed
                // build in flight (workspace on disk) — keeps a durable
                // delta tail that WAL replay must maintain like any other
                // durable entry keyspace. The meta probe must PROPAGATE
                // errors: swallowing one here would silently skip delta
                // maintenance during replay, leaving stale packed entries
                // unmasked — corruption, not degradation.
                let packed_spatial = definition.kind == IndexKind::Spatial
                    && match paged_records.as_ref() {
                        Some(paged) => {
                            paged
                                .spatial_meta(&paged.latest_snapshot(), &definition.name)?
                                .is_some()
                                || crate::spatial_pack_build::SpatialPackWorkspace::load(
                                    &path,
                                    &definition.name,
                                )?
                                .is_some()
                        }
                        None => false,
                    };
                if matches!(definition.kind, IndexKind::BTree | IndexKind::FullText)
                    || packed_spatial
                {
                    let entry_format = match paged_records.as_ref() {
                        Some(paged) => paged.entry_format_cached(&definition.name)?,
                        None => crate::paged_collection::IndexEntryFormat::V2,
                    };
                    defs.entry(definition.collection.clone()).or_default().push(
                        PagedDurableIndexDef {
                            name: definition.name.clone(),
                            fields: definition.fields.clone(),
                            kind: definition.kind.clone(),
                            predicate: definition.predicate.clone(),
                            entry_format,
                            unique: definition.unique,
                        },
                    );
                }
            }
            defs
        };

        // Optional binary startup snapshot (derived cache). Loaded once for all
        // collections; `None` for disabled/missing/corrupt/version-skew, in which
        // case every collection takes the JSON segment path below unchanged.
        let mut snapshot = if config.snapshot {
            crate::snapshot::load(&path, config.read_mode, &encryption)
        } else {
            None
        };
        open_trace!("snapshot_load");

        for mut meta in metas {
            validate_collection_name(&meta.name)?;
            let segment_path = segment_path_for(&path, &meta.name);

            // PAGED OPEN: in `server_paged` the page store is the durable home
            // for rows and segments carry none, so the segment/snapshot
            // machinery below is skipped entirely.
            //
            // The default is LAZY: shards start empty and act as a cache of
            // rows touched this session, with reads falling back to the page
            // store. Open therefore does not scan the corpus — the roadmap's
            // "opening a database does not load or scan every row", measured
            // against the alternative's 97 s / 2.2 GiB for 500k rows.
            //
            // Collections with non-page-backed secondary indexes or vectors are instead
            // materialized as eviction stubs (identity fields resident, bytes
            // fetched on demand pinned to the open snapshot): index entries
            // carry rowids that must resolve through resident shard entries,
            // and the vector store is built from resident rows. Durable B-tree
            // entries still need a compact pk<->rowid registry. Generation-format
            // FTS postings carry their own dense document-id maps, so FTS alone
            // does not trigger a corpus walk or per-row startup residency.
            if let Some(paged) = &paged_records {
                let requires_rowid_registry =
                    config.paged_rowid_registry && paged_registry_collections.contains(&meta.name);
                // B-tree AND full-text indexes are durably page-backed, so
                // neither forces the collection out of lazy/registry mode.
                // Streamable spatial indexes (first-class geometry field, no
                // predicate) qualify too: their (pk, rect) entries rebuild
                // from an identity scan, never from resident rows.
                let all_indexes_durable = paged_index_catalog
                    .iter()
                    .filter(|definition| definition.collection == meta.name)
                    .all(|definition| {
                        matches!(definition.kind, IndexKind::BTree | IndexKind::FullText)
                            || (definition.kind == IndexKind::Spatial
                                && definition.predicate.is_none()
                                && matches!(definition.fields.first(), Some(IndexField::Geometry)))
                    });
                // Vector collections now qualify too (Slice 3): their rows
                // stay on pages, the HNSW index streams its vectors from the
                // page store at load, and exact search runs a streamed top-k
                // over pages — nothing per-row is resident. (The stub branch
                // below remains only for non-durable index kinds.)
                if all_indexes_durable {
                    let mut state = CollectionState::from_shards(
                        meta,
                        0,
                        (0..SHARD_COUNT).map(Shard::with_index).collect(),
                    );
                    state.paged_lazy = true;
                    // REGISTRY MODE for indexed collections: the planner needs
                    // a rowid per row (index entries are rowid-addressed), but
                    // it does not need rows, chains, or stubs — those cost
                    // ~2.8 KB/row resident where the pk<->rowid registry costs
                    // ~100 bytes. The registry is built from a key-only walk:
                    // record keys embed the id, so no heap page is read and no
                    // value is decoded. Rowid-addressed reads that miss the
                    // resident maps resolve rowid -> pk -> page store.
                    if requires_rowid_registry {
                        let as_of = paged.latest_snapshot();
                        for shard in state.shards_mut() {
                            shard.track_reverse = true;
                        }
                        for id in paged.scan_ids(&as_of, &state.meta.name)? {
                            let id = id?;
                            state.shard_mut(&id).rowid_or_alloc(&id);
                            if fallback_fts_registry_collections.contains(&state.meta.name) {
                                fts_open_metrics.fallback_row_ids_registered += 1;
                            }
                        }
                    }
                    collections.insert(state.meta.name.clone(), RwLock::new(state));
                    continue;
                }
                let as_of = paged.latest_snapshot();
                let fetch: PagedStubFetch = {
                    let paged = Arc::clone(paged);
                    let collection: Arc<str> = Arc::from(meta.name.as_str());
                    let as_of = as_of.clone();
                    Arc::new(move |pk: &str| paged.get(&as_of, &collection, pk))
                };
                let mut record_arcs: Vec<Arc<StoredRecord>> = Vec::new();
                // Identity-only decode: stubs keep exactly these fields, and
                // skipping the metadata copy + Value parse is what makes this
                // open proportional to identity bytes, not corpus bytes.
                for record in paged.scan_identities(&as_of, &meta.name)? {
                    let record = record?;
                    if let Some(vector) = record.vector.as_deref() {
                        vector::validate_vector(vector)?;
                        match meta.vector_dim {
                            Some(expected) if expected != vector.len() => {
                                return Err(BicDbError::DimensionMismatch {
                                    collection: meta.name.clone(),
                                    expected,
                                    actual: vector.len(),
                                });
                            }
                            Some(_) => {}
                            None => meta.vector_dim = Some(vector.len()),
                        }
                    }
                    record_arcs.push(Arc::new(StoredRecord::evicted_stub(
                        &record,
                        crate::record::EvictedPayload {
                            fetch: Arc::clone(&fetch),
                            pk: Arc::from(record.id.as_str()),
                        },
                    )));
                }
                let record_count = record_arcs.len() as u64;
                let shards = build_shards_parallel(record_arcs)?;
                let mut state = CollectionState::from_shards(meta, 0, shards);
                state.rebuild_vector_store();
                state.generation = AtomicU64::new(record_count);
                collections.insert(state.meta.name.clone(), RwLock::new(state));
                continue;
            }

            // How the binary snapshot is used for this collection depends on the live
            // segment's current byte length vs the size recorded in the snapshot. The
            // snapshot is taken right after a full compaction, so its prefix
            // `[0, segment_byte_len)` is exactly the clean live-record set (no tombstones
            // or superseded frames), and commits since then only APPEND whole frames
            // (rewrites invalidate the manifest). Hence:
            //   live == snapshot size -> no writes since: use the snapshot wholesale.
            //   live  > snapshot size -> tail merge: snapshot prefix + decode only the
            //                            appended tail `[segment_byte_len, live)`.
            //   live  < snapshot size -> shrunk/rewritten: ignore the snapshot.
            // Because the prefix is the clean live set, the snapshot's ids equal the
            // prefix's segment_replay marks, so prefix+tail is identical (records AND
            // replay marks) to a full segment decode — downstream WAL replay unchanged.
            let live_segment_len = match fs::metadata(&segment_path) {
                Ok(meta) => meta.len(),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => 0,
                Err(_) => u64::MAX,
            };
            let snap_meta = snapshot
                .as_ref()
                .and_then(|snap| snap.collection(&meta.name))
                .filter(|snap_meta| live_segment_len >= snap_meta.segment_byte_len)
                .cloned();

            // FUSED FAST PATH (no writes since the snapshot): decode the snapshot's
            // (already-unique, already-deduped) records STRAIGHT INTO the shards,
            // skipping the intermediate dedup HashMap and its build/teardown that the
            // segment path needs for last-write-wins. Round-tripping through that map
            // gave back exactly the decode time the binary form saves, so the fusion is
            // what makes the snapshot a net win.
            if snap_meta
                .as_ref()
                .is_some_and(|snap_meta| live_segment_len == snap_meta.segment_byte_len)
            {
                let snap_meta = snap_meta.as_ref().expect("is_some_and verified Some");
                let snap_records = snapshot
                    .as_mut()
                    .and_then(|snap| snap.records.remove(&meta.name))
                    .unwrap_or_default();
                let record_count = snap_records.len() as u64;
                // Validate vectors + aggregate vector_dim and mark replay (cheap,
                // order-insensitive) here; the expensive shard build is parallel below.
                let mut record_arcs: Vec<Arc<StoredRecord>> =
                    Vec::with_capacity(snap_records.len());
                for record in snap_records {
                    if let Some(vector) = record.vector.as_deref() {
                        vector::validate_vector(vector)?;
                        match meta.vector_dim {
                            Some(expected) if expected != vector.len() => {
                                return Err(BicDbError::DimensionMismatch {
                                    collection: meta.name.clone(),
                                    expected,
                                    actual: vector.len(),
                                });
                            }
                            Some(_) => {}
                            None => meta.vector_dim = Some(vector.len()),
                        }
                    }
                    segment_replay.mark_touched(&meta.name, &record.id);
                    record_arcs.push(Arc::new(record));
                }
                let shards = build_shards_parallel(record_arcs)?;
                let mut state =
                    CollectionState::from_shards(meta, snap_meta.segment_frame_count, shards);
                state.rebuild_vector_store();
                state.generation = AtomicU64::new(record_count);
                collections.insert(state.meta.name.clone(), RwLock::new(state));
                continue;
            }

            let (records, segment_frame_count) = {
                // TAIL MERGE or FULL DECODE. Both decode a set of record frames and
                // apply them (last-write-wins) into `records`; only the seed map and
                // which frames get read differ. Tail merge seeds the map with the
                // snapshot's clean prefix records and reads ONLY the appended tail past
                // the snapshot boundary; full decode starts empty and reads the whole
                // segment. (`live == snapshot size` was already handled above.)
                let (mut records, base_frame_count) = if let Some(snap_meta) = snap_meta.as_ref() {
                    let snap_records = snapshot
                        .as_mut()
                        .and_then(|snap| snap.records.remove(&meta.name))
                        .unwrap_or_default();
                    let mut records = FxHashMap::default();
                    for record in snap_records {
                        if let Some(vector) = record.vector.as_deref() {
                            vector::validate_vector(vector)?;
                            match meta.vector_dim {
                                Some(expected) if expected != vector.len() => {
                                    return Err(BicDbError::DimensionMismatch {
                                        collection: meta.name.clone(),
                                        expected,
                                        actual: vector.len(),
                                    });
                                }
                                Some(_) => {}
                                None => meta.vector_dim = Some(vector.len()),
                            }
                        }
                        segment_replay.mark_touched(&meta.name, &record.id);
                        let id = record.id.clone();
                        records.insert(
                            id,
                            RecordEntry {
                                offset: 0,
                                record: Arc::new(record),
                            },
                        );
                    }
                    (records, snap_meta.segment_frame_count)
                } else {
                    (FxHashMap::default(), 0)
                };
                let recovered = if let Some(snap_meta) = snap_meta.as_ref() {
                    // Only the appended tail past the snapshot boundary needs decoding.
                    storage::read_frames_from(
                        &segment_path,
                        snap_meta.segment_byte_len,
                        FrameKind::Record,
                        &encryption,
                    )?
                } else {
                    storage::read_frames(
                        &segment_path,
                        FrameKind::Record,
                        config.read_mode,
                        &encryption,
                    )?
                };
                let segment_frame_count = base_frame_count + recovered.frames.len() as u64;

                // Decode the frames across all cores; the order-sensitive apply below
                // (upsert/delete dedup by id, vector_dim aggregation) stays sequential
                // and sees frames in on-disk order, applied on top of any snapshot prefix.
                let decoded = parallel_map_ordered(&recovered.frames, |frame| {
                    let loaded = match decode_stored_record_frame(&frame.payload)? {
                        StoredRecordFrame::Upsert(record) => {
                            LoadedRecordFrame::Upsert(Arc::new(record))
                        }
                        StoredRecordFrame::Delete(id) => LoadedRecordFrame::Delete(id),
                        StoredRecordFrame::TxUpsert(tx_id, record) => {
                            LoadedRecordFrame::TxUpsert(tx_id, Arc::new(record))
                        }
                        StoredRecordFrame::TxDelete(tx_id, id) => {
                            LoadedRecordFrame::TxDelete(tx_id, id)
                        }
                    };
                    Ok((frame.offset, loaded))
                })?;
                drop(recovered);

                for (frame_offset, loaded) in decoded {
                    match loaded {
                        LoadedRecordFrame::Upsert(record) => {
                            segment_replay.mark_touched(&meta.name, &record.id);
                            if let Some(vector) = record.vector.as_deref() {
                                vector::validate_vector(vector)?;
                                match meta.vector_dim {
                                    Some(expected) if expected != vector.len() => {
                                        return Err(BicDbError::DimensionMismatch {
                                            collection: meta.name.clone(),
                                            expected,
                                            actual: vector.len(),
                                        });
                                    }
                                    Some(_) => {}
                                    None => meta.vector_dim = Some(vector.len()),
                                }
                            }

                            records.insert(
                                record.id.clone(),
                                RecordEntry {
                                    offset: frame_offset,
                                    record,
                                },
                            );
                        }
                        LoadedRecordFrame::Delete(id) => {
                            segment_replay.mark_touched(&meta.name, &id);
                            records.remove(&id);
                        }
                        LoadedRecordFrame::TxUpsert(tx_id, record) => {
                            if !tx_recovery.is_committed(tx_id) {
                                continue;
                            }
                            if let Some(vector) = record.vector.as_deref() {
                                vector::validate_vector(vector)?;
                                match meta.vector_dim {
                                    Some(expected) if expected != vector.len() => {
                                        return Err(BicDbError::DimensionMismatch {
                                            collection: meta.name.clone(),
                                            expected,
                                            actual: vector.len(),
                                        });
                                    }
                                    Some(_) => {}
                                    None => meta.vector_dim = Some(vector.len()),
                                }
                            }

                            records.insert(
                                record.id.clone(),
                                RecordEntry {
                                    offset: frame_offset,
                                    record,
                                },
                            );
                        }
                        LoadedRecordFrame::TxDelete(tx_id, id) => {
                            if !tx_recovery.is_committed(tx_id) {
                                continue;
                            }
                            records.remove(&id);
                        }
                    }
                }
                (records, segment_frame_count)
            };

            let record_count = records.len() as u64;
            // Distribute the deduped records into shards in parallel, each building its
            // single-version chain stamped with the ancient baseline TransactionId(0);
            // WAL replay below
            // marks the not-yet-in-segment ones dirty.
            let record_arcs: Vec<Arc<StoredRecord>> =
                records.into_values().map(|entry| entry.record).collect();
            let shards = build_shards_parallel(record_arcs)?;
            let mut state = CollectionState::from_shards(meta, segment_frame_count, shards);
            state.rebuild_vector_store();
            state.generation = AtomicU64::new(record_count);
            collections.insert(state.meta.name.clone(), RwLock::new(state));
        }
        open_trace!("segment_record_load");

        apply_unmaterialized_transaction_log(
            &mut tx_recovery,
            &segment_replay,
            &mut collections,
            paged_records.as_ref(),
            &paged_durable_defs,
        )?;
        // In paged mode the row-recovery value is now spent, but the same WAL
        // may also contain committed broker-outbox frames. Do not truncate it
        // until those messages have been idempotently appended below.
        // every commit it held has just been re-applied to the page store (or
        // was already there), and the page store's own WAL is what future
        // recovery replays. Without this truncation nothing ever bounds the
        // log — segment checkpointing, which truncates it in embedded mode,
        // does not run — so every open replayed the entire write history.
        // Measured: a 500k-row session left a 411 MB log whose replay cost
        // 89 s and 2.2 GiB at every subsequent open, growing without limit.
        //
        // Order matters: the paged store checkpoints FIRST, making its WAL and
        // pages durable past everything the log held, and only then is the log
        // dropped. A crash between the two leaves the old log to be replayed
        // again — duplicate-version noise, never loss.
        if let Some(paged) = &paged_records {
            paged.checkpoint()?;
        }
        open_trace!("apply_unmaterialized_tx");
        // Legacy empty indexes use a completeness sentinel but have neither
        // postings nor format-v2 corpus statistics. They may serve
        // read-through only when the just-built registry proves the
        // collection is still empty; a nonempty sentinel-only index is the
        // pre-durable upgrade case and must rebuild from rows.
        for index in &paged_fts_empty_sentinel_indexes {
            let Some(definition) = paged_index_catalog
                .iter()
                .find(|definition| definition.name == *index)
            else {
                continue;
            };
            let registered_rows = collections
                .get(&definition.collection)
                .map(|collection| {
                    collection
                        .read()
                        .read_all()
                        .iter()
                        .map(|shard| shard.pk_to_rowid.len())
                        .sum::<usize>()
                })
                .unwrap_or(0);
            if registered_rows == 0 {
                paged_fts_read_through_indexes.insert(index.clone());
            }
        }
        let indexes = if config.load_secondary_indexes {
            build_indexes_with_paged(
                load_index_catalog(&path.join(DEFAULT_INDEX_CATALOG), &encryption)?,
                &collections,
                paged_records.as_ref(),
                Some(&paged_fts_read_through_indexes),
                Some(&paged_fts_incomplete_build_indexes),
                Some(&path),
            )?
            .into_iter()
            .map(|(name, state)| (name, RwLock::new(state)))
            .collect::<FxHashMap<_, _>>()
        } else {
            FxHashMap::default()
        };
        open_trace!("build_indexes");
        let planner_stats = load_planner_stats(&path.join(DEFAULT_PLANNER_STATS), &encryption)?;
        let hnsw_indexes = RwLock::new(if config.load_secondary_indexes {
            load_hnsw_indexes(&path, &collections, paged_records.as_ref(), &encryption)?
        } else {
            FxHashMap::default()
        });
        open_trace!("hnsw_indexes");

        let sync_log = if config.sync_outbox {
            SyncLog::open(
                path.join("sync.log"),
                config.fsync,
                config.read_mode,
                encryption.clone(),
            )?
        } else {
            // CDC outbox disabled: skip the (potentially multi-GB) replay entirely.
            SyncLog::disabled(path.join("sync.log"), config.fsync, encryption.clone())
        };
        open_trace!("sync_log_open");
        let mut events = EventStream::open_with_encryption(
            event_segment_path_for(&path),
            config.fsync,
            config.read_mode,
            config.compression.clone(),
            encryption.clone(),
        )?;
        let recovered_broker_publishes = tx_recovery.committed_broker_publishes();
        let mut broker_outbox_flushed = true;
        if !recovered_broker_publishes.is_empty() {
            let mut broker = events.broker();
            for pending in &recovered_broker_publishes {
                if let Err(error) = broker.publish_prepared(pending) {
                    broker_outbox_flushed = false;
                    eprintln!(
                        "bicdb: retained committed broker outbox message {} for retry: {error}",
                        pending.message_id
                    );
                }
            }
        }
        // Record-audit events are a transaction-WAL outbox. A process may die
        // after the row commit becomes durable but before its event-segment
        // copy. Replay every committed entry here; UUID deduplication makes an
        // event already copied before the crash inert.
        let recovered_audit_outboxes = tx_recovery.committed_record_audit_outboxes();
        let mut recovered_audit_publications = Vec::with_capacity(recovered_audit_outboxes.len());
        for (tx_id, audit_events) in recovered_audit_outboxes {
            for event in audit_events {
                events.append_imported(event)?;
            }
            recovered_audit_publications.push(serde_json::to_vec(
                &TxFrame::RecordAuditPublished { tx_id },
            )?);
        }
        if !recovered_audit_publications.is_empty() {
            storage::append_frames(
                &path.join(DEFAULT_TRANSACTION_LOG),
                FrameKind::Transaction,
                &recovered_audit_publications,
                config.fsync,
                &CompressionConfig::disabled(),
                &encryption,
            )?;
        }
        if paged_records.is_some() && broker_outbox_flushed {
            let log_path = path.join(DEFAULT_TRANSACTION_LOG);
            let log_len = file_len(&log_path)?;
            if log_len > 0 {
                copy_transaction_log_tail(&log_path, log_len, config.fsync)?;
            }
        }
        let events = Mutex::new(events);
        let graphs = RwLock::new(load_graph_projections(&path, &encryption)?);
        let model_registry = RwLock::new(load_model_registry(&path, &encryption)?);
        let memory_indexes = RwLock::new(load_memory_index_catalog(&path, &encryption)?);
        let memory_index_jobs = RwLock::new(load_memory_index_jobs(&path, &encryption)?);
        let sync_state = SyncMeshState::load_or_create(
            path.join(DEFAULT_SYNC_STATE),
            configured_node_id,
            config.fsync,
        )?;
        if let Some(paged) = &paged_records {
            paged.set_value_compression(config.paged_value_compression);
        }
        let mesh_signer = if config.mesh_signing {
            Some(load_or_create_mesh_signing_key(
                &path,
                config.fsync,
                &encryption,
            )?)
        } else {
            None
        };

        open_trace!("events+graphs+sync_state");
        let tx_log = TxLogHandle::new(
            path.join(DEFAULT_TRANSACTION_LOG),
            tx_recovery.last_commit_seq,
            config.fsync,
        );
        let fts_block_cache = Arc::new(crate::fts_cache::FullTextBlockCache::new(
            config.fts_block_cache_bytes,
        ));
        Ok(Self {
            path,
            _directory_lock: Some(directory_lock),
            config,
            ha_state,
            replication_state,
            consensus_state,
            commit_admission: RwLock::new(None),
            schema_compatibility: SchemaCompatibilityAuthority::new(),
            encryption,
            collections,
            paged_records,
            paged_maintenance_lock: Arc::new(Mutex::new(())),
            fts_generations: Mutex::new(fts_generations),
            fts_block_cache,
            fts_open_metrics,
            sync_log: Mutex::new(sync_log),
            events,
            sync_state,
            sync_vector_cache: Mutex::new(SyncVectorCache::default()),
            runtime_session_id: Uuid::new_v4(),
            opened_at: std::time::Instant::now(),
            mesh_signer,
            indexes,
            planner_stats,
            model_registry,
            memory_indexes,
            memory_index_jobs,
            hnsw_indexes,
            graphs,
            tx_states: Arc::new(ShardedMutexMap::from_iter_with_shards(
                tx_recovery.states,
                orch_shard_count(),
            )),
            next_tx_id: AtomicU64::new(tx_recovery.next_tx_id),
            // MVCC visibility watermark in commit_seq units (snapshots read it).
            instance_id: NEXT_DB_INSTANCE_ID.fetch_add(1, AtomicOrdering::Relaxed),
            last_committed_tx: AtomicU64::new(tx_recovery.last_commit_seq),
            applied_watermark: Mutex::new(AppliedWatermark::new(tx_recovery.last_commit_seq)),
            commit_seq: AtomicU64::new(tx_recovery.last_commit_seq),
            index_generation: AtomicU64::new(0),
            serializable_commit_admission: RwLock::new(()),
            commit_lock: Mutex::new(()),
            write_locks: Arc::new(row_lock_waiters::RowLockTable::with_shards(
                orch_shard_count(),
            )),
            unique_claims: ShardedMutexMap::with_shards(orch_shard_count()),
            wait_graph: wait_graph::WaitForGraph::default(),
            exclusion_claims: Mutex::new(Vec::new()),
            active_snapshots: Arc::new(ActiveSnapshots::with_shards(orch_shard_count())),
            tx_log,
        })
    }

    /// Highest durable commit sequence assigned so far. Monotonic and gap-free.
    pub fn last_commit_seq(&self) -> u64 {
        self.commit_seq.load(AtomicOrdering::SeqCst)
    }

    pub fn current_commit_seq(&self) -> u64 {
        self.last_commit_seq()
    }

    pub fn replication_config(&self) -> &ReplicationConfig {
        &self.config.replication
    }

    /// Per-operator SQL work-memory limit for bounded execution paths.
    pub fn query_work_memory_bytes(&self) -> usize {
        self.config.query_work_memory_bytes
    }

    /// Per-operator temporary-disk quota for spillable SQL execution.
    pub fn query_temp_space_bytes(&self) -> u64 {
        self.config.query_temp_space_bytes
    }

    /// Aggregate temporary-disk quota shared by SQL spill operators.
    pub fn query_server_temp_space_bytes(&self) -> u64 {
        self.config.query_server_temp_space_bytes
    }

    /// Maximum number of spill runs merged concurrently by a SQL operator.
    pub fn query_merge_fan_in(&self) -> usize {
        self.config.query_merge_fan_in
    }

    /// Root directory of this database. Host-managed durable sidecars such as
    /// content-addressed extension packages must place their own data below
    /// this path rather than relying on the process working directory.
    pub fn data_path(&self) -> &Path {
        &self.path
    }

    /// Return an opaque object cipher only when this database was opened with
    /// cell-bound encryption. Callers cannot obtain the root key and can seal
    /// objects only beneath [`Self::data_path`].
    pub fn bound_object_cipher(&self) -> Option<crate::DatabaseObjectCipher> {
        self.encryption.bound_object_cipher()
    }

    /// Highest contiguous commit sequence visible to a newly started
    /// transaction. PostgreSQL snapshot compatibility maps this watermark to
    /// the `xmax` boundary rather than exposing BicDB's internal allocation ID.
    pub fn current_visibility_watermark(&self) -> u64 {
        self.last_committed_tx.load(AtomicOrdering::SeqCst)
    }

    /// PostgreSQL-compatible logical WAL insertion position. BicDB maps its
    /// durable, gap-free commit sequence onto the 64-bit LSN coordinate.
    pub fn current_wal_insert_lsn(&self) -> u64 {
        self.last_commit_seq()
    }

    /// Highest WAL position written by the coalescing transaction-log writer.
    pub fn current_wal_write_lsn(&self) -> u64 {
        self.tx_log.stats().written_seq
    }

    /// BicDB commits are synchronously durable, so flush and write positions
    /// advance together.
    pub fn current_wal_flush_lsn(&self) -> u64 {
        self.current_wal_write_lsn()
    }

    pub fn register_embedding_model(&mut self, model: ModelRegistryEntry) -> Result<()> {
        if model.name.trim().is_empty() {
            return Err(memory_error("embedding model name must not be empty"));
        }
        if model.dimension == 0 {
            return Err(memory_error(
                "embedding model dimension must be greater than zero",
            ));
        }
        self.model_registry
            .write()
            .insert(model.name.clone(), model);
        self.persist_model_registry()
    }

    pub fn register_local_onnx_embedding_model(
        &mut self,
        name: &str,
        model_dir: impl AsRef<Path>,
        dimension: usize,
    ) -> Result<ModelRegistryEntry> {
        let model_dir = model_dir.as_ref().to_path_buf();
        let model_file = model_dir.join("onnx").join("model_q4.onnx");
        let external_data_file = model_dir.join("onnx").join("model_q4.onnx_data");
        let tokenizer_file = model_dir.join("tokenizer.json");
        for path in [&model_file, &external_data_file, &tokenizer_file] {
            if !path.is_file() {
                return Err(memory_error(format!(
                    "embedding model file not found: {}",
                    path.display()
                )));
            }
        }
        let mut checksums = BTreeMap::new();
        checksums.insert("onnx/model_q4.onnx".to_string(), sha256_file(&model_file)?);
        checksums.insert(
            "onnx/model_q4.onnx_data".to_string(),
            sha256_file(&external_data_file)?,
        );
        checksums.insert("tokenizer.json".to_string(), sha256_file(&tokenizer_file)?);
        for metadata_file in ["config.json", "tokenizer_config.json"] {
            let path = model_dir.join(metadata_file);
            if path.is_file() {
                checksums.insert(metadata_file.to_string(), sha256_file(&path)?);
            }
        }
        let entry = ModelRegistryEntry {
            name: name.to_string(),
            provider: crate::memory_index::EmbeddingProviderKind::Local,
            runtime: EmbeddingRuntime::Onnx,
            dimension,
            model_dir: Some(model_dir),
            model_file: Some(model_file),
            external_data_file: Some(external_data_file),
            tokenizer_file: Some(tokenizer_file),
            checksums,
        };
        self.register_embedding_model(entry.clone())?;
        Ok(entry)
    }

    pub fn embedding_models(&self) -> Vec<ModelRegistryEntry> {
        let mut models = self
            .model_registry
            .read()
            .values()
            .cloned()
            .collect::<Vec<_>>();
        models.sort_by(|left, right| left.name.cmp(&right.name));
        models
    }

    pub fn create_memory_index(
        &mut self,
        name: &str,
        collection: &str,
        field: &str,
        model: &str,
        mode: MemoryIndexMode,
    ) -> Result<()> {
        self.ensure_collection(collection)?;
        if !self.model_registry.read().contains_key(model) {
            return Err(memory_error(format!(
                "embedding model `{model}` is not registered"
            )));
        }
        if self.memory_indexes.read().contains_key(name) {
            return Err(memory_error(format!(
                "memory index `{name}` already exists"
            )));
        }
        let consistency = match mode {
            MemoryIndexMode::Async => MemoryIndexConsistency::Eventual,
            MemoryIndexMode::Sync => MemoryIndexConsistency::Immediate,
        };
        let definition = MemoryIndexDefinition {
            name: name.to_string(),
            collection: collection.to_string(),
            field: field.to_string(),
            model: model.to_string(),
            mode,
            consistency,
            created_at: unix_timestamp(),
        };
        self.memory_indexes
            .write()
            .insert(definition.name.clone(), definition);
        self.persist_memory_index_catalog()?;
        let records = self.scan_collection_unchecked(collection)?;
        self.enqueue_memory_jobs_for_records(collection, &records)?;
        if mode == MemoryIndexMode::Sync {
            self.process_sync_memory_jobs_for_records(collection, &records)?;
        }
        Ok(())
    }

    pub fn memory_indexes(&self) -> Vec<MemoryIndexDefinition> {
        let mut indexes = self
            .memory_indexes
            .read()
            .values()
            .cloned()
            .collect::<Vec<_>>();
        indexes.sort_by(|left, right| left.name.cmp(&right.name));
        indexes
    }

    pub fn memory_index_jobs(&self) -> Vec<MemoryIndexJob> {
        let mut jobs = self.memory_index_jobs.read().clone();
        jobs.sort_by(|left, right| {
            left.created_at
                .cmp(&right.created_at)
                .then_with(|| left.job_id.cmp(&right.job_id))
        });
        jobs
    }

    pub fn process_memory_index_jobs(&self, limit: usize) -> Result<MemoryIndexProcessReport> {
        let limit = limit.max(1);
        let pending_jobs = self
            .memory_index_jobs
            .read()
            .iter()
            .filter(|job| job.status == MemoryJobStatus::Pending)
            .take(limit)
            .cloned()
            .collect::<Vec<_>>();
        self.process_memory_index_job_batch(pending_jobs)
    }

    pub fn search_memory_index(
        &self,
        collection: &str,
        field: &str,
        query: &str,
        top_k: usize,
    ) -> Result<Vec<VectorSearchResult>> {
        let definition = self
            .memory_indexes
            .read()
            .values()
            .find(|definition| {
                definition.collection == collection && definition.field.eq_ignore_ascii_case(field)
            })
            .cloned()
            .ok_or_else(|| {
                memory_error(format!(
                    "memory index on `{collection}`.`{field}` does not exist"
                ))
            })?;
        let model = self
            .model_registry
            .read()
            .get(&definition.model)
            .cloned()
            .ok_or_else(|| {
                memory_error(format!("embedding model `{}` is missing", definition.model))
            })?;
        let query_vector = embed_text(&model, query)?;
        score_memory_results(
            self.scan_collection_unchecked(collection)?,
            &query_vector,
            top_k,
        )
    }

    fn finalize_memory_jobs_for_committed_transaction(&self, tx: &Transaction) -> Result<()> {
        // Without any memory index or pending memory job there is nothing to
        // enqueue or process; skip before `memory_upserts_by_collection`
        // deep-clones every record the transaction wrote.
        if self.memory_indexes.read().is_empty() && self.memory_index_jobs.read().is_empty() {
            return Ok(());
        }
        for (collection, records) in tx.memory_upserts_by_collection() {
            self.enqueue_memory_jobs_for_records(&collection, &records)?;
            self.process_sync_memory_jobs_for_records(&collection, &records)?;
        }
        Ok(())
    }

    fn process_memory_index_job_batch(
        &self,
        jobs: Vec<MemoryIndexJob>,
    ) -> Result<MemoryIndexProcessReport> {
        let prepared = jobs
            .iter()
            .map(|job| self.prepare_memory_index_job(job))
            .collect::<Vec<_>>();
        let mut indexed_by_collection = BTreeMap::<String, Vec<(Uuid, Record)>>::new();
        let mut stale_by_collection = BTreeMap::<String, Vec<Record>>::new();
        let mut statuses = Vec::<(Uuid, MemoryJobStatus, Option<String>)>::new();
        let mut report = MemoryIndexProcessReport::default();

        for prepared in prepared {
            match prepared.action {
                PreparedMemoryIndexJobAction::Index { collection, record } => {
                    indexed_by_collection
                        .entry(collection)
                        .or_default()
                        .push((prepared.job_id, record));
                }
                PreparedMemoryIndexJobAction::Stale { collection, record } => {
                    statuses.push((prepared.job_id, MemoryJobStatus::Stale, None));
                    stale_by_collection
                        .entry(collection)
                        .or_default()
                        .push(record);
                    report.processed += 1;
                }
                PreparedMemoryIndexJobAction::Failed { status, error } => {
                    report.failures.push(error.clone());
                    statuses.push((prepared.job_id, status, Some(error)));
                    report.failed += 1;
                }
            }
        }

        for (collection, indexed) in indexed_by_collection {
            let records = indexed
                .iter()
                .map(|(_, record)| record.clone())
                .collect::<Vec<_>>();
            match self.batch_insert_with_memory_jobs(&collection, records, false) {
                Ok(()) => {
                    report.processed += indexed.len();
                    for (job_id, _) in indexed {
                        statuses.push((job_id, MemoryJobStatus::Indexed, None));
                    }
                }
                Err(error) => {
                    report.failed += indexed.len();
                    report.failures.push(error.to_string());
                    for (job_id, _) in indexed {
                        statuses.push((job_id, MemoryJobStatus::Failed, Some(error.to_string())));
                    }
                }
            }
        }

        self.update_memory_job_statuses(&statuses)?;
        for (collection, records) in stale_by_collection {
            self.enqueue_memory_jobs_for_records(&collection, &records)?;
        }
        report.pending = self
            .memory_index_jobs
            .read()
            .iter()
            .filter(|job| job.status == MemoryJobStatus::Pending)
            .count();
        Ok(report)
    }

    fn prepare_memory_index_job(&self, job: &MemoryIndexJob) -> PreparedMemoryIndexJob {
        let model = self.model_registry.read().get(&job.model).cloned();
        let Some(model) = model else {
            return PreparedMemoryIndexJob {
                job_id: job.job_id,
                action: PreparedMemoryIndexJobAction::Failed {
                    status: MemoryJobStatus::ModelMissing,
                    error: format!("embedding model `{}` is missing", job.model),
                },
            };
        };
        let record = match self.get_unchecked(&job.collection, &job.record_id) {
            Ok(Some(record)) => record,
            Ok(None) => {
                return PreparedMemoryIndexJob {
                    job_id: job.job_id,
                    action: PreparedMemoryIndexJobAction::Failed {
                        status: MemoryJobStatus::Failed,
                        error: format!(
                            "memory index source record `{}`.`{}` no longer exists",
                            job.collection, job.record_id
                        ),
                    },
                };
            }
            Err(error) => {
                return PreparedMemoryIndexJob {
                    job_id: job.job_id,
                    action: PreparedMemoryIndexJobAction::Failed {
                        status: MemoryJobStatus::Failed,
                        error: error.to_string(),
                    },
                };
            }
        };
        let Some(text) = record_memory_text(&record, &job.field) else {
            return PreparedMemoryIndexJob {
                job_id: job.job_id,
                action: PreparedMemoryIndexJobAction::Failed {
                    status: MemoryJobStatus::Failed,
                    error: format!(
                        "memory index field `{}` is missing on `{}`.`{}`",
                        job.field, job.collection, job.record_id
                    ),
                },
            };
        };
        let current_hash = source_hash(&text);
        if current_hash != job.source_hash {
            return PreparedMemoryIndexJob {
                job_id: job.job_id,
                action: PreparedMemoryIndexJobAction::Stale {
                    collection: job.collection.clone(),
                    record: record.as_ref().clone(),
                },
            };
        }
        let vector = match embed_text(&model, &text) {
            Ok(vector) => vector,
            Err(error) => {
                return PreparedMemoryIndexJob {
                    job_id: job.job_id,
                    action: PreparedMemoryIndexJobAction::Failed {
                        status: MemoryJobStatus::Failed,
                        error: error.to_string(),
                    },
                };
            }
        };
        let mut updated = record.as_ref().clone();
        updated.vector = Some(vector);
        PreparedMemoryIndexJob {
            job_id: job.job_id,
            action: PreparedMemoryIndexJobAction::Index {
                collection: job.collection.clone(),
                record: updated,
            },
        }
    }

    fn process_sync_memory_jobs_for_records(
        &self,
        collection: &str,
        records: &[Record],
    ) -> Result<()> {
        let record_ids = records
            .iter()
            .map(|record| record.id.as_str())
            .collect::<FxHashSet<_>>();
        if record_ids.is_empty() {
            return Ok(());
        }
        let sync_index_names = self
            .memory_indexes
            .read()
            .values()
            .filter(|definition| {
                definition.collection == collection && definition.mode == MemoryIndexMode::Sync
            })
            .map(|definition| definition.name.clone())
            .collect::<FxHashSet<_>>();
        if sync_index_names.is_empty() {
            return Ok(());
        }
        let jobs = self
            .memory_index_jobs
            .read()
            .iter()
            .filter(|job| {
                job.collection == collection
                    && job.status == MemoryJobStatus::Pending
                    && record_ids.contains(job.record_id.as_str())
                    && sync_index_names.contains(&job.index_name)
            })
            .cloned()
            .collect::<Vec<_>>();
        let report = self.process_memory_index_job_batch(jobs)?;
        if report.failed > 0 {
            return Err(memory_error(format!(
                "sync memory indexing failed for {} job(s): {}",
                report.failed,
                report.failure_summary()
            )));
        }
        Ok(())
    }

    fn enqueue_memory_jobs_for_records(&self, collection: &str, records: &[Record]) -> Result<()> {
        let definitions = self
            .memory_indexes
            .read()
            .values()
            .filter(|definition| definition.collection == collection)
            .cloned()
            .collect::<Vec<_>>();
        if definitions.is_empty() || records.is_empty() {
            return Ok(());
        }
        let now = unix_timestamp();
        let mut changed = false;
        {
            let mut jobs = self.memory_index_jobs.write();
            for definition in &definitions {
                for record in records {
                    let Some(text) = record_memory_text(record, &definition.field) else {
                        continue;
                    };
                    let source_hash = source_hash(&text);
                    let mut already_queued = false;
                    for job in jobs.iter_mut().filter(|job| {
                        job.index_name == definition.name && job.record_id == record.id
                    }) {
                        if job.source_hash == source_hash
                            && matches!(
                                job.status,
                                MemoryJobStatus::Pending | MemoryJobStatus::Indexed
                            )
                        {
                            already_queued = true;
                        } else if job.source_hash != source_hash
                            && job.status != MemoryJobStatus::Stale
                        {
                            job.status = MemoryJobStatus::Stale;
                            job.updated_at = now;
                            changed = true;
                        }
                    }
                    if already_queued {
                        continue;
                    }
                    jobs.push(MemoryIndexJob {
                        job_id: Uuid::new_v4(),
                        index_name: definition.name.clone(),
                        collection: definition.collection.clone(),
                        record_id: record.id.clone(),
                        field: definition.field.clone(),
                        model: definition.model.clone(),
                        source_hash,
                        status: MemoryJobStatus::Pending,
                        error: None,
                        created_at: now,
                        updated_at: now,
                    });
                    changed = true;
                }
            }
        }
        if changed {
            self.persist_memory_index_jobs()?;
        }
        Ok(())
    }

    fn update_memory_job_statuses(
        &self,
        updates: &[(Uuid, MemoryJobStatus, Option<String>)],
    ) -> Result<()> {
        if updates.is_empty() {
            return Ok(());
        }
        {
            let mut jobs = self.memory_index_jobs.write();
            let now = unix_timestamp();
            for (job_id, status, error) in updates {
                if let Some(job) = jobs.iter_mut().find(|job| job.job_id == *job_id) {
                    job.status = *status;
                    job.error = error.clone();
                    job.updated_at = now;
                }
            }
        }
        self.persist_memory_index_jobs()
    }

    fn persist_model_registry(&self) -> Result<()> {
        persist_model_registry(
            &self.path,
            &self.model_registry.read(),
            self.config.fsync,
            &self.encryption,
        )
    }

    fn persist_memory_index_catalog(&self) -> Result<()> {
        persist_memory_index_catalog(
            &self.path,
            &self.memory_indexes.read(),
            self.config.fsync,
            &self.encryption,
        )
    }

    fn persist_memory_index_jobs(&self) -> Result<()> {
        persist_memory_index_jobs(
            &self.path,
            &self.memory_index_jobs.read(),
            self.config.fsync,
            &self.encryption,
        )
    }

    pub fn replication_watermark(&self) -> ReplicationWatermark {
        let current = self.last_commit_seq();
        ReplicationWatermark {
            current_commit_seq: current,
            last_applied_commit_seq: self.last_applied_commit_seq(),
        }
    }

    pub fn replication_apply_state(&self) -> ReplicationApplyState {
        let mut state = self.replication_state.clone();
        if !self.is_replication_standby() {
            state.last_applied_commit_seq = self.last_commit_seq();
        }
        state
    }

    pub fn last_applied_commit_seq(&self) -> u64 {
        if self.is_replication_standby() {
            self.replication_state.last_applied_commit_seq
        } else {
            self.last_commit_seq()
        }
    }

    pub fn replication_lag(&self, source_commit_seq: u64) -> u64 {
        source_commit_seq.saturating_sub(self.last_applied_commit_seq())
    }

    /// Replication export requires full Write frames in the retained log. A
    /// `server_paged` database without `replication.enabled` logs materialized
    /// commit markers instead (the page WAL carries the rows), so serving
    /// frames from it would silently export EMPTY commits and starve standbys.
    /// Refuse loudly: declared replication keeps full-frame logging.
    fn ensure_replication_frames_retained(&self) -> Result<()> {
        if self.paged_records.is_some() && !self.config.replication.enabled {
            return Err(replication_error(
                "this server_paged database logs materialized commit markers, not full                  frames; open it with replication.enabled=true so commits retain full                  frames, and bootstrap existing standbys from a snapshot",
            ));
        }
        Ok(())
    }

    pub fn replication_retention_status(&self) -> Result<ReplicationRetentionStatus> {
        // No `ensure_replication_frames_retained` here: this is introspection
        // (the `bicdb_replication_status` view), and a marker-logged paged
        // database honestly reports zero retained commits. Only actual frame
        // SERVING refuses.
        //
        // Streams the WAL and decodes only each frame's header: the previous
        // implementation materialized every retained commit WITH its record
        // writes just to count them and read the first/last sequence, which
        // after a ~780k-commit TPC-C run meant ~30 GB of transient memory for
        // one status row (and a memory-guard abort of the server).
        #[derive(Deserialize)]
        struct TxFrameHeader {
            #[serde(rename = "type")]
            kind: TxFrameKind,
            tx_id: TransactionId,
            #[serde(default)]
            commit_seq: u64,
        }
        let mut commits: Vec<(u64, u64)> = Vec::new();
        let mut aborted: FxHashSet<u64> = FxHashSet::default();
        storage::stream_frames(
            &self.tx_log_path(),
            FrameKind::Transaction,
            &self.encryption,
            |_, payload| {
                let header: TxFrameHeader = serde_json::from_slice(&payload)?;
                match header.kind {
                    TxFrameKind::TxCommit => commits.push((header.commit_seq, header.tx_id.0)),
                    TxFrameKind::TxAbort => {
                        aborted.insert(header.tx_id.0);
                    }
                    _ => {}
                }
                Ok(())
            },
        )?;
        if !aborted.is_empty() {
            commits.retain(|(_, tx_id)| !aborted.contains(tx_id));
        }
        let oldest = commits.iter().map(|(seq, _)| *seq).min().unwrap_or(0);
        let newest = commits.iter().map(|(seq, _)| *seq).max().unwrap_or(0);
        Ok(ReplicationRetentionStatus {
            oldest_available_commit_seq: oldest,
            newest_available_commit_seq: newest,
            retained_commits: commits.len() as u64,
            retained_bytes: file_len(&self.tx_log_path())?,
        })
    }

    pub fn export_replication_frames_since(
        &self,
        commit_seq: u64,
        limit: usize,
    ) -> Result<Vec<CommitFrame>> {
        let limit = limit.max(1);
        self.ensure_replication_frames_retained()?;
        let commits = self.replication_commits_from_retained_wal()?;
        if let Some(oldest) = commits.first().map(|commit| commit.commit_seq) {
            if commit_seq < oldest.saturating_sub(1) {
                return Err(replication_error(format!(
                    "requested commit_seq {commit_seq} is older than retained WAL; snapshot bootstrap required from {oldest}"
                )));
            }
        }
        Ok(commits
            .into_iter()
            .filter(|commit| commit.commit_seq > commit_seq)
            .take(limit)
            .map(|commit| {
                CommitFrame::new(
                    self.config.replication.cluster_id.clone(),
                    self.config.replication.node_id.clone(),
                    DEFAULT_REPLICATION_STREAM_ID,
                    commit.commit_seq,
                    commit.tx_id,
                    commit.timestamp,
                    commit.writes,
                )
            })
            .collect())
    }

    pub fn subscribe_replication_stream(&self, start_commit_seq: u64) -> Result<Vec<CommitFrame>> {
        self.export_replication_frames_since(start_commit_seq, usize::MAX)
    }

    pub fn consensus_status(&self) -> ConsensusStatus {
        self.consensus_state.status()
    }

    /// Refuses a write-bearing commit on a node that is not the consensus
    /// leader.
    ///
    /// Without this a follower accepted writes over its own SQL port and kept
    /// them: local commits are proposed to the consensus log by the leader's
    /// loop only, so a follower's writes replicated nowhere and the node
    /// diverged permanently. Two clients on two nodes could each be told
    /// `INSERT 0 1` for different rows and never converge.
    ///
    /// Read-only transactions are unaffected: a follower is a perfectly good
    /// place to read from, and gating on `writes` keeps it one.
    pub(crate) fn ensure_writable_by_consensus(&self, tx: &Transaction) -> Result<()> {
        if !self.config.consensus.enabled || tx.writes.is_empty() {
            return Ok(());
        }
        let status = self.consensus_state.status();
        if status.role == crate::consensus::ConsensusRole::Leader {
            return Ok(());
        }
        Err(BicDbError::Consensus(format!(
            "node {} is {:?}, not the consensus leader: writes must go to the \
             leader of cluster {}",
            self.config.consensus.node_id, status.role, self.config.consensus.cluster_id
        )))
    }

    pub fn consensus_start_election(&mut self) -> Result<RequestVote> {
        self.ensure_consensus_enabled()?;
        let request = self.consensus_state.become_candidate();
        self.persist_consensus_state()?;
        Ok(request)
    }

    pub fn consensus_become_leader(&mut self) -> Result<()> {
        self.ensure_consensus_enabled()?;
        self.consensus_state.become_leader()?;
        self.persist_consensus_state()
    }

    pub fn consensus_handle_request_vote(&mut self, request: RequestVote) -> Result<VoteResponse> {
        self.ensure_consensus_enabled()?;
        let response = self.consensus_state.handle_request_vote(request)?;
        self.persist_consensus_state()?;
        Ok(response)
    }

    pub fn consensus_handle_append_entries(
        &mut self,
        request: AppendEntries,
    ) -> Result<AppendResponse> {
        self.ensure_consensus_enabled()?;
        let response = self.consensus_state.handle_append_entries(request)?;
        self.persist_consensus_state()?;
        Ok(response)
    }

    pub fn consensus_append_local_commit(
        &mut self,
        frame: CommitFrame,
    ) -> Result<crate::consensus::ConsensusLogEntry> {
        self.ensure_consensus_enabled()?;
        frame.verify_checksum()?;
        let entry = self.consensus_state.append_local_commit(frame)?;
        self.persist_consensus_state()?;
        Ok(entry)
    }

    pub fn consensus_record_append_response(
        &mut self,
        node_id: &str,
        response: &AppendResponse,
    ) -> Result<u64> {
        self.ensure_consensus_enabled()?;
        let commit_index = self
            .consensus_state
            .record_append_response(node_id, response)?;
        self.persist_consensus_state()?;
        Ok(commit_index)
    }

    pub fn consensus_append_entries_from(&self, next_index: u64) -> Result<AppendEntries> {
        self.ensure_consensus_enabled()?;
        Ok(self.consensus_state.append_entries_from(next_index))
    }

    pub fn consensus_apply_committed(&mut self) -> Result<ReplicationApplyReport> {
        self.ensure_consensus_enabled()?;
        let frames = self.consensus_state.apply_committed_prefix();
        let expected_cluster = self.config.consensus.cluster_id.clone();
        let mut applied = 0usize;
        let mut duplicates = 0usize;
        for frame in &frames {
            let report = self.apply_replication_frame_inner(frame, false, &expected_cluster)?;
            applied += report.applied;
            duplicates += report.duplicates;
        }
        let report = ReplicationApplyReport {
            applied,
            duplicates,
            last_applied_commit_seq: self.last_applied_commit_seq(),
        };
        self.persist_consensus_state()?;
        Ok(report)
    }

    fn ensure_consensus_enabled(&self) -> Result<()> {
        if !self.config.consensus.enabled {
            return Err(crate::consensus::consensus_error("consensus is disabled"));
        }
        Ok(())
    }

    pub fn is_replication_standby(&self) -> bool {
        self.ha_state.role == HaRole::Standby
            || self.config.replication.mode == ReplicationMode::Standby
    }

    fn replication_commits_from_retained_wal(&self) -> Result<Vec<RetainedReplicationCommit>> {
        let recovered = storage::read_frames(
            &self.tx_log_path(),
            FrameKind::Transaction,
            self.config.read_mode,
            &self.encryption,
        )?;
        let mut writes: BTreeMap<u64, Vec<TxWrite>> = BTreeMap::new();
        let mut commits: Vec<(u64, u64, i64)> = Vec::new();
        for frame in recovered.frames {
            let tx_frame = decode_tx_frame(&frame.payload)?;
            match tx_frame {
                TxFrame::Write { tx_id, write } => {
                    writes.entry(tx_id.0).or_default().push(*write);
                }
                TxFrame::Patch { .. } => {
                    return Err(replication_error(
                        "retained WAL contains compact update patches; enable replication before producing WAL so full row images are retained",
                    ));
                }
                TxFrame::Commit {
                    tx_id,
                    timestamp,
                    commit_seq,
                } => {
                    commits.push((commit_seq, tx_id.0, timestamp));
                }
                TxFrame::Abort { tx_id, .. } => {
                    writes.remove(&tx_id.0);
                    commits.retain(|(_, committed_tx_id, _)| *committed_tx_id != tx_id.0);
                }
                TxFrame::Truncate { tx_id, len } => {
                    if let Some(tx_writes) = writes.get_mut(&tx_id.0) {
                        tx_writes.truncate(len);
                    }
                }
                TxFrame::Begin { .. }
                | TxFrame::CommitMaterialized { .. }
                | TxFrame::BrokerPublish { .. }
                | TxFrame::RecordAudit { .. }
                | TxFrame::RecordAuditPublished { .. } => {}
            }
        }
        commits.sort_unstable_by_key(|(commit_seq, _, _)| *commit_seq);
        let mut retained = Vec::with_capacity(commits.len());
        for (commit_seq, tx_id, timestamp) in commits {
            let tx_writes = writes.remove(&tx_id).unwrap_or_default();
            let writes = tx_writes
                .iter()
                .map(|write| {
                    let collection_meta = self
                        .collections
                        .get(&write.collection)
                        .map(|state| state.read().meta.clone());
                    tx_write_to_replication_write(collection_meta, write)
                })
                .collect::<Result<Vec<_>>>()?;
            retained.push(RetainedReplicationCommit {
                commit_seq,
                tx_id,
                timestamp,
                writes,
            });
        }
        Ok(retained)
    }

    pub fn apply_replication_batch(
        &mut self,
        frames: &[CommitFrame],
    ) -> Result<ReplicationApplyReport> {
        let mut applied = 0usize;
        let mut duplicates = 0usize;
        for frame in frames {
            let report = self.apply_replication_frame(frame)?;
            applied += report.applied;
            duplicates += report.duplicates;
        }
        Ok(ReplicationApplyReport {
            applied,
            duplicates,
            last_applied_commit_seq: self.last_applied_commit_seq(),
        })
    }

    /// Apply a continuous commit suffix while discarding writes owned by other
    /// ranges. Empty filtered frames still advance the durable replication
    /// watermark, which is required before relocation promotion.
    pub fn apply_range_replication_batch(
        &mut self,
        range: &RangeDescriptor,
        frames: &[CommitFrame],
    ) -> Result<ReplicationApplyReport> {
        let filtered = frames
            .iter()
            .map(|frame| filter_commit_frame_for_range(frame, range))
            .collect::<Result<Vec<_>>>()?;
        self.apply_replication_batch(&filtered)
    }

    /// Install one bounded learner snapshot batch as an idempotent local
    /// transaction. The relocation apply catalog owns source-sequence
    /// continuity; this method owns record/range/schema validation and atomic
    /// data durability.
    pub fn apply_range_snapshot_batch(
        &mut self,
        range: &RangeDescriptor,
        collection_meta: &CollectionMeta,
        batch: &RangeSnapshotBatch,
    ) -> Result<usize> {
        if batch.range_id != range.id || batch.range_epoch != range.epoch {
            return Err(BicDbError::Cluster(format!(
                "snapshot batch range/epoch {}/{} does not match {}/{}",
                batch.range_id, batch.range_epoch, range.id, range.epoch
            )));
        }
        if collection_meta.name != batch.collection {
            return Err(BicDbError::Cluster(format!(
                "snapshot collection metadata names `{}`, batch names `{}`",
                collection_meta.name, batch.collection
            )));
        }
        for record in &batch.records {
            if !range.contains_token(distribution_key_token(&batch.collection, &record.id)) {
                return Err(BicDbError::Cluster(format!(
                    "snapshot record `{}/{}` is outside range {}",
                    batch.collection, record.id, range.id
                )));
            }
        }
        if let Some(state) = self.collections.get(&batch.collection) {
            if state.read().meta != *collection_meta {
                return Err(BicDbError::Cluster(format!(
                    "snapshot collection metadata for `{}` conflicts with the destination catalog",
                    batch.collection
                )));
            }
        } else {
            validate_collection_name(&batch.collection)?;
            self.collections.insert(
                batch.collection.clone(),
                RwLock::new(CollectionState::new(collection_meta.clone())),
            );
            self.persist_catalog()?;
            self.schema_compatibility.invalidate();
        }
        if batch.records.is_empty() {
            return Ok(0);
        }
        let count = batch.records.len();
        let mut tx = self.begin_transaction()?;
        // The authenticated relocation service has already fenced this batch
        // to an exact range and learner epoch.  Sending it back through the
        // ordinary client-write admission path would make the learner try to
        // lead a second quorum decision while it is still a non-leader.
        tx.bypass_commit_admission = true;
        tx.write_upserts_unchecked(&batch.collection, batch.records.clone())?;
        tx.commit()?;
        Ok(count)
    }

    /// Apply one source commit atomically to a learner while retaining only
    /// writes owned by the range. Empty filtered frames intentionally produce
    /// no local transaction; the durable learner apply catalog still advances
    /// the source watermark for them.
    pub fn apply_range_commit_frame_as_local(
        &mut self,
        range: &RangeDescriptor,
        frame: &CommitFrame,
    ) -> Result<usize> {
        let filtered = filter_commit_frame_for_range(frame, range)?;
        self.ensure_replication_frame_collections(&filtered)?;
        let writes = replication_writes_to_tx_writes(&filtered)?;
        if writes.is_empty() {
            return Ok(0);
        }
        let count = writes.len();
        let mut tx = self.begin_transaction()?;
        // Catch-up frames are authenticated physical replication, not new
        // logical client writes.  Their source commit is already authoritative
        // and the relocation watermark provides continuity/idempotence.
        tx.bypass_commit_admission = true;
        for write in writes {
            match write.op {
                TxWriteOp::Upsert => {
                    let record = write.record()?.cloned().ok_or_else(|| {
                        BicDbError::Cluster(format!(
                            "range commit upsert `{}/{}` has no record",
                            write.collection, write.record_id
                        ))
                    })?;
                    tx.write_upserts_unchecked(&write.collection, vec![record.as_ref().clone()])?;
                }
                TxWriteOp::Delete => tx.delete(&write.collection, &write.record_id)?,
            }
        }
        tx.commit()?;
        Ok(count)
    }

    /// Delete a bounded, pre-validated cleanup batch without applying
    /// user-facing collection policy checks. This is restricted to records
    /// whose stable keys belong to the relocated range.
    pub fn delete_range_records_as_local(
        &mut self,
        range: &RangeDescriptor,
        collection: &str,
        record_ids: &[String],
    ) -> Result<usize> {
        for record_id in record_ids {
            if !range.contains_token(distribution_key_token(collection, record_id)) {
                return Err(BicDbError::Cluster(format!(
                    "cleanup record `{collection}/{record_id}` is outside range {}",
                    range.id
                )));
            }
        }
        if record_ids.is_empty() {
            return Ok(0);
        }
        self.ensure_collection(collection)?;
        let mut tx = self.begin_transaction()?;
        // Source cleanup runs only after range ownership has moved.  It is a
        // fenced relocation operation and must not attempt a fresh quorum write
        // as the old (now non-leader) source.
        tx.bypass_commit_admission = true;
        tx.delete_many(collection, record_ids)?;
        tx.commit()?;
        Ok(record_ids.len())
    }

    pub fn apply_replication_frame(
        &mut self,
        frame: &CommitFrame,
    ) -> Result<ReplicationApplyReport> {
        let expected_cluster = self.config.replication.cluster_id.clone();
        match self.apply_replication_frame_inner(frame, true, &expected_cluster) {
            Ok(report) => Ok(report),
            Err(error) => {
                let message = error.to_string();
                let _ = self.record_replication_apply_error(message);
                Err(error)
            }
        }
    }

    fn apply_replication_frame_inner(
        &mut self,
        frame: &CommitFrame,
        require_standby: bool,
        expected_cluster_id: &str,
    ) -> Result<ReplicationApplyReport> {
        if require_standby
            && self.ha_state.role != HaRole::Standby
            && self.config.replication.mode != ReplicationMode::Standby
        {
            return Err(replication_error(
                "replication frames can only be imported by a standby",
            ));
        }
        frame.verify_checksum()?;
        if frame.cluster_id != expected_cluster_id {
            return Err(replication_error(format!(
                "replication cluster_id mismatch: expected {}, got {}",
                expected_cluster_id, frame.cluster_id
            )));
        }
        if frame.protocol_version != crate::replication::REPLICATION_PROTOCOL_VERSION {
            return Err(replication_error(format!(
                "unsupported replication protocol version {}",
                frame.protocol_version
            )));
        }
        let current = self.last_applied_commit_seq();
        if frame.commit_seq <= current {
            return Ok(ReplicationApplyReport {
                applied: 0,
                duplicates: 1,
                last_applied_commit_seq: current,
            });
        }
        let expected = current.saturating_add(1);
        if frame.commit_seq != expected || frame.previous_commit_seq != current {
            return Err(replication_error(format!(
                "replication gap or out-of-order frame: expected commit_seq {expected} after {current}, got {} after {}",
                frame.commit_seq, frame.previous_commit_seq
            )));
        }

        self.ensure_replication_frame_collections(frame)?;
        let writes = replication_writes_to_tx_writes(frame)?;
        self.apply_imported_replication_commit(frame.tx_id, frame.commit_seq, &writes)?;
        self.record_replication_apply_success(frame)?;
        Ok(ReplicationApplyReport {
            applied: 1,
            duplicates: 0,
            last_applied_commit_seq: self.last_applied_commit_seq(),
        })
    }

    fn record_replication_apply_success(&mut self, frame: &CommitFrame) -> Result<()> {
        self.replication_state.cluster_id = frame.cluster_id.clone();
        self.replication_state.source_node_id = Some(frame.source_node_id.clone());
        self.replication_state.stream_id = Some(frame.stream_id.clone());
        self.replication_state.last_applied_commit_seq = frame.commit_seq;
        self.replication_state.last_applied_at = Some(unix_timestamp());
        self.replication_state.last_error = None;
        self.persist_replication_state()
    }

    fn record_replication_apply_error(&mut self, message: String) -> Result<()> {
        self.replication_state.last_error = Some(message);
        self.persist_replication_state()
    }

    fn persist_replication_state(&self) -> Result<()> {
        persist_replication_state(&self.path, &self.replication_state, self.config.fsync)
    }

    fn ensure_replication_frame_collections(&mut self, frame: &CommitFrame) -> Result<()> {
        let mut changed = false;
        for write in &frame.writes {
            validate_replication_collection_meta(write)?;
            if self.collections.contains_key(&write.collection) {
                continue;
            }
            validate_collection_name(&write.collection)?;
            let mut meta = write
                .collection_meta
                .clone()
                .unwrap_or_else(|| CollectionMeta::standard(write.collection.clone()));
            meta.name = write.collection.clone();
            self.collections.insert(
                write.collection.clone(),
                RwLock::new(CollectionState::new(meta)),
            );
            self.persist_catalog()?;
            changed = true;
        }
        if changed {
            self.schema_compatibility.invalidate();
        }
        Ok(())
    }

    /// Current size of the transaction log (WAL) on disk in bytes. Cheap (a
    /// single `stat`); safe to poll frequently to drive WAL-size-based
    /// auto-compaction. The WAL only shrinks on [`Self::compact`].
    pub fn wal_bytes(&self) -> u64 {
        file_len(&self.tx_log_path()).unwrap_or(0)
    }

    /// Snapshot of the in-memory bookkeeping that can grow unbounded under
    /// sustained write load, for leak profiling (see `BICDB_MEM_TRACE`). The
    /// per-collection scan is O(records) so this is meant for periodic sampling,
    /// not the hot path.
    pub fn mvcc_debug_stats(&self) -> MvccDebugStats {
        let (active_snapshots, min_active_snapshot) = (
            self.active_snapshots.len(),
            self.active_snapshots.min_key().unwrap_or(0),
        );
        let mut total_versions = 0usize;
        let mut max_chain = 0usize;
        let mut total_records = 0usize;
        for lock in self.collections.values() {
            let state = lock.read();
            // This is a diagnostic aggregate, not an atomic collection snapshot.
            // Acquiring every shard up front blocks writers to all unvisited
            // shards for the duration of a potentially multi-million-row walk.
            // Keep each guard only while counting that shard.
            for shard_lock in &state.shards {
                let shard = shard_lock.read();
                total_records += shard.records.len();
                for chain in shard.versions.values() {
                    total_versions += chain.len();
                    max_chain = max_chain.max(chain.len());
                }
            }
        }
        MvccDebugStats {
            tx_states: self.tx_states.len(),
            active_snapshots,
            min_active_snapshot,
            last_committed_seq: self.last_committed_tx.load(AtomicOrdering::SeqCst),
            commit_seq: self.commit_seq.load(AtomicOrdering::SeqCst),
            total_versions,
            max_chain,
            total_records,
            wal_bytes: file_len(&self.tx_log_path()).unwrap_or(0),
        }
    }

    /// Reclaims dead row versions the write path could not: a write prunes
    /// only the chain of the row it writes, and the version it supersedes is
    /// always newer than that write's GC watermark, so every write leaves one
    /// dead version that survives until the same row is written again — for
    /// rows written once, forever. Each shard remembers those rows
    /// (`gc_pending`); this drains up to `budget` of them under the current
    /// watermark with the same rule the write path uses
    /// (`gc_versioned_chain`), re-queuing rows whose dead versions are still
    /// newer than the watermark. Returns the number of versions freed.
    /// Cheap to call often: O(rows with a dead version), never O(records).
    /// The frees are not free, though: on a host with memory to spare the
    /// caller should run this under memory pressure or at a slow cadence.
    pub fn sweep_dead_versions(&self, budget: usize) -> usize {
        let watermark = self.gc_watermark();
        let mut freed = 0usize;
        let mut remaining = budget;
        for lock in self.collections.values() {
            if remaining == 0 {
                break;
            }
            let state = lock.read();
            for shard_lock in state.shards.iter() {
                if remaining == 0 {
                    break;
                }
                // A cheap peek keeps idle shards lock-free on the write side.
                if shard_lock.read().gc_pending.is_empty() {
                    continue;
                }
                // The shard's write lock is held per small chunk, never for
                // a whole drain: committers keep their latency while the
                // sweeper walks a long list.
                const CHUNK: usize = 512;
                let mut retry = Vec::new();
                loop {
                    if remaining == 0 {
                        break;
                    }
                    let mut shard = shard_lock.write();
                    if shard.gc_pending.is_empty() {
                        break;
                    }
                    let take = shard.gc_pending.len().min(CHUNK).min(remaining);
                    let start = shard.gc_pending.len() - take;
                    let chunk: Vec<RowId> = shard.gc_pending.drain(start..).collect();
                    let shard = &mut *shard;
                    for rowid in chunk {
                        remaining -= 1;
                        let before = shard.versions.get(&rowid).map_or(0, |chain| chain.len());
                        gc_versioned_chain(
                            &mut shard.versions,
                            &mut shard.pk_to_rowid,
                            rowid,
                            watermark,
                        );
                        let after = shard.versions.get(&rowid).map_or(0, |chain| chain.len());
                        freed += before.saturating_sub(after);
                        if chain_retains_dead_version(&shard.versions, rowid) {
                            retry.push(rowid);
                        }
                    }
                }
                if !retry.is_empty() {
                    shard_lock.write().gc_pending.append(&mut retry);
                }
            }
        }
        freed
    }

    pub fn create_collection(&mut self, name: &str) -> Result<()> {
        self.create_collection_with_mode(name, CollectionMode::Standard)
    }

    pub fn create_timeseries_collection(&mut self, name: &str) -> Result<()> {
        self.create_collection_with_mode(name, CollectionMode::TimeSeries)
    }

    pub fn create_collection_with_mode(&mut self, name: &str, mode: CollectionMode) -> Result<()> {
        self.ensure_writable("create collection")?;
        validate_collection_name(name)?;
        if self.collections.contains_key(name) {
            return Ok(());
        }

        let meta = CollectionMeta {
            name: name.to_string(),
            vector_dim: None,
            mode,
            policy: None,
            mutation_policy: None,
            mesh_sync_enabled: false,
        };
        self.collections
            .insert(name.to_string(), RwLock::new(CollectionState::new(meta)));
        self.persist_catalog()?;
        self.schema_compatibility.invalidate();
        Ok(())
    }

    pub fn create_collection_with_policy(
        &mut self,
        name: &str,
        mode: CollectionMode,
        policy: CollectionPolicy,
    ) -> Result<()> {
        self.create_collection_with_mode(name, mode)?;
        self.set_collection_policy(name, policy)
    }

    pub fn set_collection_policy(
        &mut self,
        collection: &str,
        policy: CollectionPolicy,
    ) -> Result<()> {
        validate_collection_name(collection)?;
        if policy.tenant_field.trim().is_empty() {
            return Err(BicDbError::Authorization(
                "collection policy requires a tenant_field".to_string(),
            ));
        }
        protected_data::validate_policy(&policy)?;
        let state = self.collection_state_mut(collection)?;
        state.meta.policy = Some(policy);
        // A policy is a local authorization boundary. Installing one must
        // revoke any earlier mesh opt-in atomically with the catalog update.
        state.meta.mesh_sync_enabled = false;
        self.persist_catalog()?;
        self.schema_compatibility.invalidate();
        Ok(())
    }

    /// Removes a collection policy. Intended for trusted schema-lifecycle
    /// compensation when an application activation fails before publication.
    pub fn clear_collection_policy(&mut self, collection: &str) -> Result<()> {
        self.ensure_writable("clear collection policy")?;
        validate_collection_name(collection)?;
        self.collection_state_mut(collection)?.meta.policy = None;
        self.persist_catalog()?;
        self.schema_compatibility.invalidate();
        Ok(())
    }

    /// Explicitly authorizes an unprotected, pre-provisioned collection for
    /// mesh synchronization. Policy-governed collections remain local.
    pub fn set_collection_mesh_sync_enabled(
        &mut self,
        collection: &str,
        enabled: bool,
    ) -> Result<()> {
        self.ensure_writable("change collection mesh authorization")?;
        validate_collection_name(collection)?;
        let state = self.collection_state_mut(collection)?;
        if enabled && state.meta.policy.is_some() {
            return Err(BicDbError::Authorization(format!(
                "protected collection `{collection}` cannot be mesh-enabled"
            )));
        }
        state.meta.mesh_sync_enabled = enabled;
        self.persist_catalog()?;
        self.schema_compatibility.invalidate();
        Ok(())
    }

    /// Marks a relation as requiring native mutation grants and installs its
    /// below-SQL integrity policy.
    pub fn set_mutation_policy(
        &mut self,
        collection: &str,
        policy: crate::MutationPolicy,
    ) -> Result<()> {
        self.ensure_writable("set mutation policy")?;
        validate_collection_name(collection)?;
        for field in policy
            .immutable_fields
            .iter()
            .chain(policy.version_field.iter())
            .chain(policy.tenant_field.iter())
            .chain(policy.workspace_field.iter())
        {
            if field.trim().is_empty() || field.len() > 256 {
                return Err(BicDbError::MutationDenied(format!(
                    "collection `{collection}` mutation field names must contain 1..=256 bytes"
                )));
            }
        }
        self.collection_state_mut(collection)?.meta.mutation_policy = Some(policy);
        self.persist_catalog()?;
        self.schema_compatibility.invalidate();
        Ok(())
    }

    /// Removes a native mutation policy. Intended for trusted schema-lifecycle
    /// compensation and never exposed to application transactions.
    pub fn clear_mutation_policy(&mut self, collection: &str) -> Result<()> {
        self.ensure_writable("clear mutation policy")?;
        validate_collection_name(collection)?;
        self.collection_state_mut(collection)?.meta.mutation_policy = None;
        self.persist_catalog()?;
        self.schema_compatibility.invalidate();
        Ok(())
    }

    pub fn mutation_policy(&self, collection: &str) -> Result<Option<crate::MutationPolicy>> {
        Ok(self
            .collection_state(collection)?
            .meta
            .mutation_policy
            .clone())
    }

    pub fn collection_policy(&self, collection: &str) -> Result<Option<CollectionPolicy>> {
        Ok(self.collection_state(collection)?.meta.policy.clone())
    }

    pub fn backfill_protected_data_security_evidence(&mut self) -> ProtectedDataBackfillReport {
        let mut report = ProtectedDataBackfillReport::default();
        let database_id = self.sync_state.node_id.to_string();
        let collections = self
            .collections
            .iter()
            .filter_map(|(name, state)| {
                let state = state.read();
                let policy = state.meta.policy.as_ref()?;
                if protected_data::requires_field_key(policy) {
                    Some((name.clone(), policy.clone()))
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();

        for (collection, policy) in collections {
            let mut collection_changed = false;
            let records = match self.scan_collection_unchecked(&collection) {
                Ok(records) => records,
                Err(error) => {
                    report.errors.push(format!("{collection}: {error}"));
                    continue;
                }
            };
            for mut record in records {
                report.scanned_rows += 1;
                match protected_data::backfill_record(
                    &database_id,
                    &self.path,
                    &collection,
                    &policy,
                    &mut record,
                ) {
                    Ok(backfilled) => {
                        if backfilled.encrypted_fields == 0 && backfilled.blind_indexes_written == 0
                        {
                            report.skipped_rows += 1;
                            continue;
                        }
                        if backfilled.encrypted_fields > 0 {
                            report.encrypted_rows += 1;
                        }
                        if backfilled.blind_indexes_written > 0 {
                            report.blind_index_rows_written += 1;
                        }
                        if let Err(error) = self.batch_insert_unchecked_with_memory_jobs(
                            &collection,
                            vec![record],
                            true,
                        ) {
                            report.errors.push(format!("{collection}: {error}"));
                        } else {
                            collection_changed = true;
                        }
                    }
                    Err(error) => report
                        .errors
                        .push(format!("{collection}/{}: {error}", record.id)),
                }
            }
            if collection_changed {
                if let Err(error) = self.compact_collection_inner(&collection) {
                    report.errors.push(format!(
                        "{collection} compaction after protected data backfill: {error}"
                    ));
                }
            }
        }
        report.verification_status = report.errors.is_empty()
            && self
                .verify_protected_data_blind_index_coverage()
                .map(|coverage| coverage.passed)
                .unwrap_or(false)
            && self
                .sample_protected_data_ciphertext()
                .map(|sampling| sampling.passed)
                .unwrap_or(false);
        report
    }

    pub fn verify_protected_data_blind_index_coverage(
        &self,
    ) -> Result<ProtectedDataBlindIndexCoverageReport> {
        let mut report = ProtectedDataBlindIndexCoverageReport::default();
        for (collection, state) in &self.collections {
            let state = state.read();
            let Some(policy) = state.meta.policy.as_ref() else {
                continue;
            };
            for (field, security) in &policy.columns {
                if !security.encrypted {
                    continue;
                }
                if let Some(blind_index) = &security.blind_index {
                    report.approved_lookup_fields += 1;
                    if !blind_index.namespace.ends_with(':')
                        || !blind_index.namespace.contains(":v")
                    {
                        report
                            .wrong_namespaces
                            .push(format!("{collection}.{field}: {}", blind_index.namespace));
                    }
                    let blind_field = protected_data::blind_index_field(field);
                    for shard in state.read_all() {
                        for entry in shard.records.values() {
                            let metadata = entry.record.metadata_value()?;
                            if metadata.get(field).is_none() {
                                continue;
                            }
                            match metadata.get(&blind_field) {
                                Some(Value::String(value)) if !value.is_empty() => {
                                    report.indexed_rows += 1;
                                }
                                _ => report.missing_indexes.push(format!(
                                    "{collection}/{} missing {blind_field}",
                                    entry.record.id
                                )),
                            }
                        }
                    }
                }
                for index in self.indexes.values() {
                    let index = index.read();
                    if index.definition.collection == *collection
                        && index.definition.fields.iter().any(|index_field| {
                            matches!(
                                index_field,
                                IndexField::MetadataPath(path) if path.len() == 1 && path[0] == *field
                            )
                        })
                    {
                        report.plaintext_search_paths.push(format!(
                            "{} indexes encrypted field {collection}.{field}",
                            index.definition.name
                        ));
                    }
                }
            }
        }
        report.passed = report.missing_indexes.is_empty()
            && report.wrong_namespaces.is_empty()
            && report.plaintext_search_paths.is_empty();
        Ok(report)
    }

    pub fn sample_protected_data_ciphertext(
        &self,
    ) -> Result<ProtectedDataCiphertextSamplingReport> {
        let mut report = ProtectedDataCiphertextSamplingReport::default();
        let mut unauthorized_checked = false;
        for (collection, state) in &self.collections {
            let state = state.read();
            let Some(policy) = state.meta.policy.as_ref() else {
                continue;
            };
            for shard in state.read_all() {
                for entry in shard.records.values() {
                    let metadata = entry.record.metadata_value()?;
                    for (field, security) in &policy.columns {
                        if !security.encrypted {
                            continue;
                        }
                        let Some(value) = metadata.get(field) else {
                            continue;
                        };
                        report.sampled_fields += 1;
                        if !protected_data::is_envelope(value) {
                            report.plaintext_findings.push(format!(
                                "{collection}/{} stores plaintext-like {field}",
                                entry.record.id
                            ));
                        }
                        if let Some(as_string) = value.as_str() {
                            if protected_data::has_plaintext(&metadata, as_string) {
                                report.plaintext_findings.push(format!(
                                    "{collection}/{} repeats plaintext for {field}",
                                    entry.record.id
                                ));
                            }
                        }
                        if !unauthorized_checked {
                            let tenant_id = metadata
                                .get(&policy.tenant_field)
                                .and_then(Value::as_str)
                                .unwrap_or_default();
                            let ctx = SecurityContext::trusted_internal("phi-sampler", tenant_id)
                                .with_roles(["reader"]);
                            match self.get_with_context(&ctx, collection, &entry.record.id) {
                                Ok(Some(projected)) => {
                                    if projected.metadata.get(field) != Some(value) {
                                        unauthorized_checked = true;
                                    }
                                }
                                Ok(None) | Err(_) => {
                                    unauthorized_checked = true;
                                }
                            }
                        }
                    }
                }
            }
        }
        report.unauthorized_context_blocked = unauthorized_checked || report.sampled_fields == 0;
        report.passed = report.plaintext_findings.is_empty() && report.unauthorized_context_blocked;
        Ok(report)
    }

    pub fn verify_tenant_isolation_evidence(&mut self) -> TenantIsolationReport {
        let mut report = TenantIsolationReport {
            surfaces_checked: vec![
                "list".to_string(),
                "read".to_string(),
                "create".to_string(),
                "update".to_string(),
                "delete".to_string(),
                "report".to_string(),
                "export".to_string(),
                "cached_dashboard_reads".to_string(),
                "vector_search".to_string(),
                "graph_projection".to_string(),
                "sync_export_import".to_string(),
                "sql".to_string(),
                "pgwire".to_string(),
                "direct_rust_api".to_string(),
            ],
            ..TenantIsolationReport::default()
        };
        for (collection, state) in &self.collections {
            let state = state.read();
            let Some(policy) = state.meta.policy.as_ref() else {
                continue;
            };
            let mut tenants = state
                .read_all()
                .iter()
                .flat_map(|shard| shard.records.values())
                .filter_map(|entry| {
                    entry
                        .record
                        .metadata_value()
                        .ok()?
                        .get(&policy.tenant_field)
                        .and_then(Value::as_str)
                        .map(str::to_string)
                })
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            tenants.sort();
            if tenants.len() < 2 {
                continue;
            }
            for tenant in tenants.iter().take(2) {
                let ctx = SecurityContext::trusted_internal("tenant-auditor", tenant).with_roles([
                    "reader",
                    "writer",
                    "deleter",
                    "phi-reader",
                ]);
                match self.scan_collection_with_context(&ctx, collection) {
                    Ok(records) => {
                        for record in records {
                            let visible_tenant = record
                                .metadata
                                .get(&policy.tenant_field)
                                .and_then(Value::as_str);
                            if visible_tenant != Some(tenant.as_str()) {
                                report.leaks.push(format!(
                                    "list/read leak on {collection}/{} for tenant {tenant}",
                                    record.id
                                ));
                            }
                        }
                    }
                    Err(error) => report.leaks.push(format!(
                        "{collection} list/read failed closed check: {error}"
                    )),
                }
                if self.scan_collection(collection).is_ok() {
                    report
                        .leaks
                        .push(format!("{collection} direct Rust API bypassed policy"));
                }
            }
        }
        report.passed = report.leaks.is_empty();
        report
    }

    pub fn raw_sql_audit(&self, root: impl AsRef<Path>) -> Result<RawSqlAuditReport> {
        let fields = self
            .collections
            .iter()
            .flat_map(|(collection, state)| {
                let state = state.read();
                state
                    .meta
                    .policy
                    .as_ref()
                    .map(|policy| {
                        policy
                            .columns
                            .iter()
                            .filter(|(_, security)| security.encrypted)
                            .map(|(field, _)| (collection.clone(), field.clone()))
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default()
            })
            .collect::<BTreeSet<_>>();
        raw_sql_audit_path(root.as_ref(), &fields)
    }

    pub fn protected_data_security_release_gate(
        &mut self,
        source_root: impl AsRef<Path>,
    ) -> Result<ProtectedDataSecurityEvidenceReport> {
        let backfill = self.backfill_protected_data_security_evidence();
        if backfill.errors.is_empty() {
            // The release gate is the production boundary for legacy protected data data.
            // Backfill rewrites encrypted segment frames; full compaction also
            // truncates WAL/sync/event logs so stale plaintext bytes are not
            // retained in append-only storage after the gate passes.
            self.compact()?;
        }
        let blind_index_coverage = self.verify_protected_data_blind_index_coverage()?;
        let ciphertext_sampling = self.sample_protected_data_ciphertext()?;
        let tenant_isolation = self.verify_tenant_isolation_evidence();
        let raw_sql_audit = self.raw_sql_audit(source_root)?;
        let passed = backfill.verification_status
            && blind_index_coverage.passed
            && ciphertext_sampling.passed
            && tenant_isolation.passed
            && raw_sql_audit.passed;
        Ok(ProtectedDataSecurityEvidenceReport {
            backfill,
            blind_index_coverage,
            ciphertext_sampling,
            tenant_isolation,
            raw_sql_audit,
            passed,
        })
    }

    pub fn blind_index_filter(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        field: &str,
        value: serde_json::Value,
    ) -> Result<JsonFilter> {
        let state = self.collection_state(collection)?;
        let policy = state.meta.policy.as_ref().ok_or_else(|| {
            BicDbError::Authorization(format!(
                "collection `{collection}` has no protected data policy"
            ))
        })?;
        Self::authorize_read_without_audit(collection, policy, ctx)?;
        let security = policy.columns.get(field).ok_or_else(|| {
            BicDbError::Authorization(format!(
                "field `{field}` has no protected data column security metadata"
            ))
        })?;
        let blind_index = security.blind_index.as_ref().ok_or_else(|| {
            BicDbError::Authorization(format!("field `{field}` does not allow blind-index lookup"))
        })?;
        Ok(JsonFilter::new().eq(
            protected_data::blind_index_field(field),
            protected_data::blind_index_value(
                &blind_index.namespace,
                &self.sync_state.node_id.to_string(),
                &ctx.tenant_id,
                &value,
            )?,
        ))
    }

    pub fn get_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        id: &str,
    ) -> Result<Option<Arc<Record>>> {
        let Some(record) = self.get_unchecked(collection, id)? else {
            return Ok(None);
        };
        if let Some(policy) = self.collection_state(collection)?.meta.policy.as_ref() {
            Self::authorize_read_without_audit(collection, policy, ctx)?;
            if !Self::record_visible_to_policy(policy, ctx, &record)? {
                return Ok(None);
            }
            return Ok(Some(Arc::new(protected_data::project_record(
                &self.sync_state.node_id.to_string(),
                &self.path,
                collection,
                policy,
                &ctx.roles,
                &record,
                ctx.bypass_policy.is_some(),
            )?)));
        }
        Ok(Some(record))
    }

    pub fn scan_collection_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
    ) -> Result<Vec<Record>> {
        let records = self.scan_collection_unchecked(collection)?;
        let state = self.collection_state(collection)?;
        let Some(policy) = state.meta.policy.as_ref() else {
            return Ok(records);
        };
        Self::authorize_read_without_audit(collection, policy, ctx)?;
        let mut visible = Vec::new();
        for record in records {
            if Self::record_visible_to_policy(policy, ctx, &record)? {
                visible.push(protected_data::project_record(
                    &self.sync_state.node_id.to_string(),
                    &self.path,
                    collection,
                    policy,
                    &ctx.roles,
                    &record,
                    ctx.bypass_policy.is_some(),
                )?);
            }
        }
        Ok(visible)
    }

    pub fn secure(&mut self, ctx: &SecurityContext) -> SecureBicDb<'_> {
        SecureBicDb {
            db: self,
            ctx: ctx.clone(),
        }
    }

    pub fn drop_collection(&mut self, name: &str) -> Result<bool> {
        validate_collection_name(name)?;
        if !self.collections.contains_key(name) {
            return Ok(false);
        }
        // In server-paged mode the catalog is not the row store. Purge both
        // the record keyspace and its intern dictionary before publishing the
        // DROP; otherwise a same-name CREATE exposes the prior relation's
        // rows and identity mappings. Cleanup is bounded and transactional in
        // pages via remove_raw_prefix.
        if let Some(paged) = self.paged_records.clone() {
            self.remove_raw_prefix(
                &paged,
                &crate::paged_collection::collection_storage_prefix(name),
            )?;
            self.remove_raw_prefix(
                &paged,
                &crate::paged_collection::collection_intern_prefix(name),
            )?;
        }
        self.collections.remove(name);
        let before_indexes = self.indexes.len();
        self.indexes
            .retain(|_, index| index.get_mut().definition.collection != name);
        self.persist_catalog()?;
        if self.indexes.len() != before_indexes {
            // Dropped with the collection: definition caches must not keep
            // serving the removed indexes.
            self.index_generation
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            self.persist_index_catalog()?;
        }
        self.hnsw_indexes.write().remove(name);
        match fs::remove_file(self.hnsw_index_path(name)) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
        match fs::remove_file(self.segment_path(name)) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
        self.refresh_graph_projections()?;
        self.schema_compatibility.invalidate();
        Ok(true)
    }

    pub fn insert(&mut self, collection: &str, record: Record) -> Result<()> {
        self.batch_insert(collection, vec![record])
    }

    pub fn batch_insert<I>(&mut self, collection: &str, records: I) -> Result<()>
    where
        I: IntoIterator<Item = Record>,
    {
        self.ensure_writable("insert records")?;
        self.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?;
        let records = records.into_iter().collect::<Vec<_>>();
        if records.is_empty() {
            return Ok(());
        }
        self.batch_insert_with_memory_jobs(collection, records, true)
    }

    fn batch_insert_with_memory_jobs(
        &self,
        collection: &str,
        records: Vec<Record>,
        enqueue_memory_jobs: bool,
    ) -> Result<()> {
        let mut tx = self.begin_transaction()?;
        if !enqueue_memory_jobs {
            tx.disable_memory_jobs_on_commit();
        }
        tx.batch_insert(collection, records)?;
        tx.commit()
    }

    /// Insert a batch of new rows through the page store alone, skipping the
    /// resident transaction machinery.
    ///
    /// The offline-import primitive. `batch_insert` pays per row for record
    /// locks, write-set buffering, resident-shard application, and version-
    /// chain GC — bookkeeping that exists to coordinate concurrent writers and
    /// keep this session's resident cache coherent. A bulk import of ids that
    /// no reader has touched needs none of it: rows land durably in one paged
    /// transaction, and reads find them through the paged fallback that lazy
    /// collections already use.
    ///
    /// Records are sorted by id before insertion. Callers feeding pre-sorted
    /// input (e.g. `ORDER BY id` at the source) make consecutive calls sweep
    /// the B-tree left to right, so each leaf is dirtied — and its page image
    /// logged — in one narrow window instead of once per row. That ordering,
    /// not this bypass, is what collapses WAL write amplification; do both.
    ///
    /// Falls back to `batch_insert` when the bypass would be unsound:
    /// non-paged storage, a vector collection, or any index on the collection
    /// (durable entries and resident structures alike are maintained by the
    /// paths this skips). Not for updating rows that may be resident: the
    /// session cache is not invalidated, so a previously read id would serve
    /// its stale copy. Sync-outbox events and memory jobs are not emitted.
    pub fn bulk_load_insert<I>(&mut self, collection: &str, records: I) -> Result<()>
    where
        I: IntoIterator<Item = Record>,
    {
        self.ensure_writable("insert records")?;
        self.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?;
        let mut records = records.into_iter().collect::<Vec<_>>();
        if records.is_empty() {
            return Ok(());
        }
        let bypass_is_sound = {
            let state = self.collection_state(collection)?;
            state.paged_lazy
                && state.meta.vector_dim.is_none()
                && !self
                    .indexes
                    .values()
                    .any(|index| index.read().definition.collection == collection)
        };
        if !bypass_is_sound {
            return self.batch_insert_with_memory_jobs(collection, records, true);
        }
        records.sort_unstable_by(|a, b| a.id.cmp(&b.id));
        self.in_paged_transaction(|paged, xid| {
            for record in &records {
                paged.put(xid, collection, record)?;
            }
            Ok(())
        })?;
        Ok(())
    }

    fn batch_insert_unchecked_with_memory_jobs(
        &self,
        collection: &str,
        records: Vec<Record>,
        enqueue_memory_jobs: bool,
    ) -> Result<()> {
        let mut tx = self.begin_transaction()?;
        if !enqueue_memory_jobs {
            tx.disable_memory_jobs_on_commit();
        }
        tx.write_upserts_unchecked(collection, records)?;
        tx.commit()
    }
}

impl FullTextReadSession<'_> {
    /// Attach a per-query token; the pinned generation remains unchanged.
    pub fn with_cancellation(mut self, cancellation: CancellationToken) -> Self {
        self.cancellation = Some(cancellation);
        self
    }

    fn check_cancellation(&self) -> Result<()> {
        if let Some(token) = &self.cancellation {
            token.check()?;
        }
        Ok(())
    }
    pub fn logical_index(&self) -> &str {
        &self.logical_index
    }

    pub fn physical_generation(&self) -> &str {
        &self.physical_index
    }

    pub fn snapshot_xmax(&self) -> bicdb_page::Xid {
        self.snapshot.xmax
    }

    pub fn transaction_id(&self) -> bicdb_page::Xid {
        self.xid
    }

    pub fn term_statistics(
        &self,
        term: &str,
    ) -> Result<Option<crate::fts_format::FullTextTermStatistics>> {
        if !full_text_term_is_indexable(term) {
            return Ok(None);
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        let encoded: Arc<[u8]> = Arc::from(full_text_term_entry_key(term));
        self.cached_term_statistics(paged, encoded)
    }

    /// Read a bounded page of lexemes from the published packed generation.
    ///
    /// `after` is exclusive and can be set to the final term returned by the
    /// previous call. The read session pins one generation, so a complete scan
    /// cannot mix terms from an index being replaced concurrently.
    pub fn sealed_term_dictionary_page(
        &self,
        after: Option<&str>,
        limit: usize,
    ) -> Result<Vec<crate::fts_format::FullTextTermDictionaryEntry>> {
        const MAX_PAGE_SIZE: usize = 100_000;
        if limit == 0 {
            return Ok(Vec::new());
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        let set = paged
            .fts_segment_for(&self.physical_index)?
            .ok_or_else(|| {
                BicDbError::Index(format!(
                    "full-text index `{}` has no published packed segment",
                    self.logical_index
                ))
            })?;
        let encoded_after = after.map(full_text_term_entry_key);
        set.term_dictionary_page(encoded_after.as_deref(), limit.min(MAX_PAGE_SIZE))?
            .into_iter()
            .map(|(encoded, statistics)| {
                let values = decode_index_key(&encoded);
                let [IndexValue::String(term)] = values.as_slice() else {
                    return Err(BicDbError::Index(format!(
                        "full-text index `{}` contains a malformed term key",
                        self.logical_index
                    )));
                };
                Ok(crate::fts_format::FullTextTermDictionaryEntry {
                    term: term.clone(),
                    statistics,
                })
            })
            .collect()
    }

    pub fn collection_statistics(
        &self,
    ) -> Result<Option<crate::fts_format::FullTextCollectionStatistics>> {
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        paged.full_text_collection_statistics(&self.snapshot, &self.physical_index)
    }

    /// Resolve an exact, generation-attached filter without reading source
    /// collection rows. Reserved filter postings are positionless and are
    /// never passed to ranking as query terms.
    pub fn document_filter_from_sealed_value(
        &self,
        filter_name: &str,
        filter_value: &str,
    ) -> Result<crate::fts_filters::FullTextDocumentFilter> {
        let term = crate::fts_format::full_text_filter_term(filter_name, filter_value)?;
        let encoded = full_text_term_entry_key(&term);
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        if paged
            .scan_index_exact(&self.snapshot, &self.physical_index, &encoded)?
            .next()
            .transpose()?
            .is_some()
            || paged
                .scan_posting_tombstones(&self.snapshot, &self.physical_index, &encoded)?
                .next()
                .transpose()?
                .is_some()
        {
            return Err(BicDbError::Index(
                "sealed full-text filters cannot be resolved across a mutable posting tail"
                    .to_string(),
            ));
        }
        let document_count = self
            .collection_statistics()?
            .map_or(0, |statistics| statistics.document_count);
        let mut document_ids = Vec::new();
        for block in
            paged.scan_numeric_posting_blocks(&self.snapshot, &self.physical_index, &encoded)?
        {
            let (_, bytes) = block?;
            document_ids.extend(
                crate::paged_collection::decode_numeric_posting_block(&bytes)?
                    .into_iter()
                    .map(|posting| posting.document_id),
            );
        }
        Ok(
            crate::fts_filters::FullTextDocumentFilter::from_document_ids(
                document_count,
                document_ids,
            ),
        )
    }

    pub fn block_max_wand_top_k(
        &self,
        terms: &[&str],
        weights: [f32; 4],
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
    ) -> Result<Option<Vec<crate::fts_postings::FullTextRankedPosting>>> {
        const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
        if terms.len() < 2
            || keep == 0
            || weights != DEFAULT_WEIGHTS
            || terms.iter().any(|term| !full_text_term_is_indexable(term))
        {
            return Ok(None);
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        if !paged.index_has_numeric_posting_blocks(&self.snapshot, &self.physical_index)? {
            return Ok(None);
        }
        let mut blocks_by_term = Vec::with_capacity(terms.len());
        let mut upper_bounds = Vec::with_capacity(terms.len());
        for term in terms {
            let encoded = encode_index_key(&[IndexValue::String((*term).to_string())]);
            let cache_term: Arc<[u8]> = Arc::from(encoded.clone());
            let mut tail =
                paged.scan_index_exact(&self.snapshot, &self.physical_index, &encoded)?;
            if let Some(entry) = tail.next() {
                entry?;
                return Ok(None);
            }
            let mut tombstones =
                paged.scan_posting_tombstones(&self.snapshot, &self.physical_index, &encoded)?;
            if let Some(entry) = tombstones.next() {
                entry?;
                return Ok(None);
            }
            let statistics = self
                .cached_term_statistics(paged, Arc::clone(&cache_term))?
                .unwrap_or_default();
            upper_bounds.push(statistics.maximum_contribution.max(0.0));
            blocks_by_term.push(
                paged
                    .scan_numeric_posting_blocks(&self.snapshot, &self.physical_index, &encoded)?
                    .map(|entry| {
                        entry.map(|(last_document_id, bytes)| {
                            self.encoded_posting_block(
                                Arc::clone(&cache_term),
                                last_document_id,
                                bytes,
                            )
                        })
                    })
                    .collect::<Result<Vec<_>>>()?,
            );
        }
        // The traversal is a pure function of already-loaded blocks, so it
        // parallelises without touching storage, MVCC or the on-disk format.
        let hits = crate::fts_postings::block_max_wand_top_k_parallel(
            blocks_by_term,
            &upper_bounds,
            weights,
            keep,
            filter,
            crate::db::effective_fts_partitions(self.db.config.fts_query_partitions, keep),
        )?;
        self.materialize_ranked_hits(hits)
    }

    pub fn block_max_ranked_and_top_k(
        &self,
        terms: &[&str],
        weights: [f32; 4],
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
    ) -> Result<Option<Vec<crate::fts_postings::FullTextRankedPosting>>> {
        const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
        if terms.len() < 2
            || keep == 0
            || weights != DEFAULT_WEIGHTS
            || terms.iter().any(|term| !full_text_term_is_indexable(term))
        {
            return Ok(None);
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        if !paged.index_has_numeric_posting_blocks(&self.snapshot, &self.physical_index)? {
            return Ok(None);
        }
        // Terms close to the rarest operand advance approximately in
        // lockstep. Fetch adjacent blocks for those cursors with one B-tree
        // range descent; much denser operands retain single-block seeks so a
        // sparse driver never drags unrelated common-term blocks into cache.
        const SEQUENTIAL_BLOCK_BATCH: usize = 16;
        let frequencies = terms
            .iter()
            .map(|term| self.term_statistics(term))
            .collect::<Result<Vec<_>>>()?;
        let rarest_frequency = frequencies
            .iter()
            .filter_map(|statistics| {
                statistics
                    .as_ref()
                    .map(|statistics| statistics.document_frequency)
            })
            .min();
        let mut sources: Vec<
            Box<dyn FnMut(u64) -> Result<Vec<crate::fts_postings::EncodedPostingBlock>> + '_>,
        > = Vec::with_capacity(terms.len());
        for (slot, term) in terms.iter().enumerate() {
            let encoded = encode_index_key(&[IndexValue::String((*term).to_string())]);
            let cache_term: Arc<[u8]> = Arc::from(encoded.clone());
            let mut tail =
                paged.scan_index_exact(&self.snapshot, &self.physical_index, &encoded)?;
            if let Some(entry) = tail.next() {
                entry?;
                return Ok(None);
            }
            let mut tombstones =
                paged.scan_posting_tombstones(&self.snapshot, &self.physical_index, &encoded)?;
            if let Some(entry) = tombstones.next() {
                entry?;
                return Ok(None);
            }
            let block_batch = match (
                rarest_frequency,
                frequencies[slot]
                    .as_ref()
                    .map(|statistics| statistics.document_frequency),
            ) {
                (Some(rarest), Some(frequency)) if frequency <= rarest.saturating_mul(4) => {
                    SEQUENTIAL_BLOCK_BATCH
                }
                _ => 1,
            };
            sources.push(Box::new(move |document_id| {
                paged
                    .numeric_posting_fetch_for_with_key(
                        &self.snapshot,
                        &self.physical_index,
                        &encoded,
                        document_id,
                        block_batch,
                    )
                    .map(|blocks| {
                        blocks
                            .into_iter()
                            .map(|fetched| {
                                self.encoded_posting_block_from_fetch(
                                    Arc::clone(&cache_term),
                                    fetched,
                                )
                            })
                            .collect()
                    })
            }));
        }
        let hits = crate::fts_postings::block_max_ranked_and_top_k_seeking(
            sources, weights, keep, filter,
        )?;
        self.materialize_ranked_hits(hits)
    }

    /// Exact conjunctive BM25 over document-ordered posting blocks. This path
    /// streams adjacent blocks for similarly dense terms and uses each
    /// block's maximum term frequency to skip ranges which cannot enter the
    /// current top-k.
    pub fn block_max_bm25_and_top_k(
        &self,
        terms: &[&str],
        parameters: crate::fts_scoring::Bm25Parameters,
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
    ) -> Result<Option<Vec<crate::fts_postings::FullTextRankedPosting>>> {
        let Some(hits) = self.block_max_bm25_hits(terms, parameters, keep, filter, true)? else {
            return Ok(None);
        };
        self.materialize_ranked_hits(hits)
    }

    /// The block-max conjunction returning unmaterialized hits (positions in
    /// `terms` order). `check_authority` gates on the per-term transactional
    /// tail and tombstones; the tail-merged path passes `false` because it
    /// layers that write set itself and excludes the affected documents.
    fn block_max_bm25_hits(
        &self,
        terms: &[&str],
        parameters: crate::fts_scoring::Bm25Parameters,
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
        check_authority: bool,
    ) -> Result<Option<Vec<crate::fts_postings::WandHit>>> {
        self.check_cancellation()?;
        if terms.is_empty()
            || keep == 0
            || !parameters.k1.is_finite()
            || parameters.k1 < 0.0
            || !parameters.b.is_finite()
            || !(0.0..=1.0).contains(&parameters.b)
            || terms.iter().any(|term| !full_text_term_is_indexable(term))
        {
            return Ok(None);
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        if !paged.index_has_numeric_posting_blocks(&self.snapshot, &self.physical_index)? {
            return Ok(None);
        }
        let Some(collection_statistics) =
            paged.full_text_collection_statistics(&self.snapshot, &self.physical_index)?
        else {
            return Ok(None);
        };

        let encoded_terms = terms
            .iter()
            .map(|term| encode_index_key(&[IndexValue::String((*term).to_string())]))
            .collect::<Vec<_>>();
        let mut frequencies = Vec::with_capacity(terms.len());
        let mut inverse_document_frequencies = Vec::with_capacity(terms.len());
        for encoded in &encoded_terms {
            let cache_term: Arc<[u8]> = Arc::from(encoded.clone());
            if check_authority {
                let mut tail =
                    paged.scan_index_exact(&self.snapshot, &self.physical_index, encoded)?;
                if let Some(entry) = tail.next() {
                    entry?;
                    return Ok(None);
                }
                let mut tombstones =
                    paged.scan_posting_tombstones(&self.snapshot, &self.physical_index, encoded)?;
                if let Some(entry) = tombstones.next() {
                    entry?;
                    return Ok(None);
                }
            }
            let Some(statistics) = self.cached_term_statistics(paged, cache_term)? else {
                return Ok(Some(Vec::new()));
            };
            frequencies.push(statistics.document_frequency);
            inverse_document_frequencies.push(crate::fts_scoring::bm25_inverse_document_frequency(
                collection_statistics.document_count,
                statistics.document_frequency,
            ));
        }

        // Large batches amortize B-tree range descent for every term. Dense
        // secondary operands used to fetch one block per seek, turning a
        // common-term intersection into thousands of repeated root-to-leaf
        // descents. Blocks remain encoded until the cursor reaches them, so
        // batching the adjacent byte ranges does not eagerly decode postings.
        const SEQUENTIAL_BLOCK_BATCH: usize = 256;
        if let [encoded] = encoded_terms.as_slice() {
            let encoded = encoded.clone();
            let cache_term: Arc<[u8]> = Arc::from(encoded.clone());
            let source: Box<
                dyn FnMut(u64, usize) -> Result<Vec<crate::fts_postings::EncodedPostingBlock>> + '_,
            > = Box::new(move |document_id, max_blocks| {
                self.check_cancellation()?;
                paged
                    .numeric_posting_fetch_for_with_key(
                        &self.snapshot,
                        &self.physical_index,
                        &encoded,
                        document_id,
                        max_blocks.max(SEQUENTIAL_BLOCK_BATCH),
                    )
                    .map(|blocks| {
                        blocks
                            .into_iter()
                            .map(|fetched| {
                                self.encoded_posting_block_from_fetch(
                                    Arc::clone(&cache_term),
                                    fetched,
                                )
                            })
                            .collect()
                    })
            });
            let hits = crate::fts_postings::block_max_bm25_single_term_seeking(
                source,
                inverse_document_frequencies[0],
                collection_statistics.average_document_length,
                parameters,
                keep,
                filter,
            )?;
            return Ok(Some(hits));
        }
        let mut term_order = (0..terms.len()).collect::<Vec<_>>();
        term_order.sort_unstable_by_key(|slot| frequencies[*slot]);
        let mut initial_best = if check_authority && keep > 1 {
            self.impact_ordered_bm25_hits(terms, parameters, keep, filter, true)
                .ok()
                .flatten()
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        // The optional seed may decline or fail; cancellation must not be
        // swallowed by its best-effort fallback.
        self.check_cancellation()?;
        for hit in &mut initial_best {
            let original_positions = std::mem::take(&mut hit.term_positions);
            hit.term_positions = term_order
                .iter()
                .map(|slot| original_positions[*slot].clone())
                .collect();
        }
        let ordered_inverse_document_frequencies = term_order
            .iter()
            .map(|slot| inverse_document_frequencies[*slot])
            .collect::<Vec<_>>();
        let mut sources: Vec<
            Box<
                dyn FnMut(u64, usize) -> Result<Vec<crate::fts_postings::EncodedPostingBlock>> + '_,
            >,
        > = Vec::with_capacity(terms.len());
        let mut secondary_boundary_sources: Vec<
            Box<dyn FnMut(u64) -> Result<Vec<(u64, u32)>> + '_>,
        > = Vec::with_capacity(terms.len().saturating_sub(1));
        // The cursor chooses the payload batch per fetch: the sequential
        // leader streams large batches, secondaries adapt between single
        // blocks (scattered drivers) and amortized runs (uniform plateaus).
        for (ordered_slot, slot) in term_order.iter().copied().enumerate() {
            let encoded = encoded_terms[slot].clone();
            let cache_term: Arc<[u8]> = Arc::from(encoded.clone());
            sources.push(Box::new(move |document_id, max_blocks| {
                paged
                    .numeric_posting_fetch_for_with_key(
                        &self.snapshot,
                        &self.physical_index,
                        &encoded,
                        document_id,
                        max_blocks,
                    )
                    .map(|blocks| {
                        blocks
                            .into_iter()
                            .map(|fetched| {
                                self.encoded_posting_block_from_fetch(
                                    Arc::clone(&cache_term),
                                    fetched,
                                )
                            })
                            .collect()
                    })
            }));
            if ordered_slot > 0 {
                let encoded = encoded_terms[slot].clone();
                secondary_boundary_sources.push(Box::new(move |document_id| {
                    paged.numeric_posting_block_boundaries_for_with_key(
                        &self.snapshot,
                        &self.physical_index,
                        &encoded,
                        document_id,
                        SEQUENTIAL_BLOCK_BATCH,
                    )
                }));
            }
        }
        drop(sources);
        drop(secondary_boundary_sources);

        // Broad conjunctions parallelize: the rarest term's key-only block
        // boundaries split the document-id space into contiguous ranges, and
        // each range runs the ordinary seeking conjunction on its own
        // thread with a local top-k. Exactness is structural — every global
        // winner is its range's local winner — so the merge just re-ranks
        // the union. Selective conjunctions stay sequential: their scan is
        // already bounded by the driver.
        const PARALLEL_RAREST_DF_FLOOR: u64 = 262_144;
        let rarest_frequency = term_order
            .first()
            .map(|slot| frequencies[*slot])
            .unwrap_or(0);
        // One control for both ranked paths. This previously hard-coded
        // `min(8)`, so a 24-core search node silently left 16 cores idle and
        // ignored whatever the operator had configured. `fts_query_partitions`
        // now means the same thing everywhere it appears.
        let workers =
            crate::db::effective_fts_partitions(self.db.config.fts_query_partitions, keep).min(
                std::thread::available_parallelism()
                    .map(usize::from)
                    .unwrap_or(1),
            );
        let ordered_terms: Vec<usize> = term_order.clone();
        let leader_encoded = encoded_terms[ordered_terms[0]].clone();
        let mut scan_permits: Option<FtsScanPermits> = None;
        let ranges = if initial_best.is_empty()
            && rarest_frequency >= PARALLEL_RAREST_DF_FLOOR
            && workers > 1
        {
            let mut boundaries = Vec::new();
            let mut from = 0u64;
            loop {
                self.check_cancellation()?;
                let batch = paged.numeric_posting_block_boundaries_for_with_key(
                    &self.snapshot,
                    &self.physical_index,
                    &leader_encoded,
                    from,
                    1_024,
                )?;
                let Some(&(last, _)) = batch.last() else {
                    break;
                };
                boundaries.extend(batch.iter().map(|(last_document_id, _)| *last_document_id));
                let Some(next) = last.checked_add(1) else {
                    break;
                };
                from = next;
            }
            if boundaries.len() >= workers * 4 {
                // Concurrency governor: fan out only as far as the global
                // extra-thread budget allows right now. A saturated host
                // grants zero and this query runs sequentially — aggregate
                // throughput then matches the single-threaded engine
                // instead of collapsing under oversubscription.
                let granted = acquire_fts_scan_permits(workers.saturating_sub(1));
                crate::fts_format::record_ranked_plan(workers.saturating_sub(1), granted);
                // ALL OF THE PLAN OR NONE OF IT.
                //
                // Partitioning costs WAND pruning, and a partial plan pays
                // that cost while buying only part of the parallelism. Worse,
                // a partial grant is itself the signal that the machine is
                // already busy — and when concurrency alone saturates the
                // cores, splitting each query is pure loss.
                //
                // Measured at 16 concurrent clients on 24 cores: 1 partition
                // gave 48 q/s at p50 296 ms; 8 gave 26 q/s at p50 613 ms.
                // Serial beat every parallel setting, because the cores were
                // already busy and each split merely re-read postings that
                // pruning would have skipped.
                let wanted_extra = workers.saturating_sub(1);
                let granted = if granted > 0 && granted < wanted_extra {
                    fts_scan_permit_pool().fetch_add(granted as isize, AtomicOrdering::AcqRel);
                    0
                } else {
                    granted
                };
                let permits = FtsScanPermits(granted);
                let workers = granted + 1;
                if workers < 2 {
                    drop(permits);
                    vec![(0, u64::MAX)]
                } else {
                    let per_range = boundaries.len().div_ceil(workers);
                    let mut ranges = Vec::with_capacity(workers);
                    let mut start = 0u64;
                    for chunk in boundaries.chunks(per_range) {
                        let end = *chunk.last().expect("non-empty chunk");
                        ranges.push((start, end));
                        start = end.saturating_add(1);
                    }
                    if let Some(last) = ranges.last_mut() {
                        last.1 = u64::MAX;
                    }
                    scan_permits = Some(permits);
                    ranges
                }
            } else {
                vec![(0, u64::MAX)]
            }
        } else {
            vec![(0, u64::MAX)]
        };

        let mut hits = if ranges.len() > 1 {
            let results = std::thread::scope(|scope| {
                let handles = ranges
                    .iter()
                    .map(|range| {
                        let range = *range;
                        let ordered_terms = &ordered_terms;
                        let encoded_terms = &encoded_terms;
                        let ordered_inverse_document_frequencies =
                            &ordered_inverse_document_frequencies;
                        let session = &*self;
                        scope.spawn(move || {
                            session.seeking_hits_in_range(
                                ordered_terms,
                                encoded_terms,
                                ordered_inverse_document_frequencies,
                                collection_statistics.average_document_length,
                                parameters,
                                keep,
                                filter,
                                range,
                                Vec::new(),
                            )
                        })
                    })
                    .collect::<Vec<_>>();
                let mut results = Vec::with_capacity(handles.len());
                for handle in handles {
                    match handle.join() {
                        Ok(result) => results.push(result?),
                        Err(payload) => std::panic::resume_unwind(payload),
                    }
                }
                Ok::<_, BicDbError>(results)
            })?;
            let mut merged: Vec<crate::fts_postings::WandHit> =
                results.into_iter().flatten().collect();
            merged.sort_by(|left, right| {
                right
                    .score
                    .partial_cmp(&left.score)
                    .unwrap_or(Ordering::Equal)
                    .then_with(|| left.document_id.cmp(&right.document_id))
            });
            merged.truncate(keep);
            drop(scan_permits.take());
            merged
        } else {
            self.seeking_hits_in_range(
                &ordered_terms,
                &encoded_terms,
                &ordered_inverse_document_frequencies,
                collection_statistics.average_document_length,
                parameters,
                keep,
                filter,
                (0, u64::MAX),
                initial_best,
            )?
        };
        for hit in &mut hits {
            let ordered_positions = std::mem::take(&mut hit.term_positions);
            let mut original_positions = vec![None; terms.len()];
            for (ordered_slot, positions) in ordered_positions.into_iter().enumerate() {
                original_positions[term_order[ordered_slot]] = positions;
            }
            hit.term_positions = original_positions;
        }
        Ok(Some(hits))
    }

    /// One contiguous document-id range of the multi-term seeking
    /// conjunction: the leader source is clamped to the range (which is
    /// built on the leader's own block boundaries, so blocks never
    /// straddle); secondaries follow the leader's candidates as usual.
    #[allow(clippy::too_many_arguments)]
    fn seeking_hits_in_range(
        &self,
        ordered_terms: &[usize],
        encoded_terms: &[Vec<u8>],
        ordered_inverse_document_frequencies: &[f32],
        average_document_length: f64,
        parameters: crate::fts_scoring::Bm25Parameters,
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
        range: (u64, u64),
        initial_best: Vec<crate::fts_postings::WandHit>,
    ) -> Result<Vec<crate::fts_postings::WandHit>> {
        const SEQUENTIAL_BLOCK_BATCH: usize = 256;
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        let (range_start, range_end) = range;
        let mut sources: Vec<
            Box<
                dyn FnMut(u64, usize) -> Result<Vec<crate::fts_postings::EncodedPostingBlock>> + '_,
            >,
        > = Vec::with_capacity(ordered_terms.len());
        let mut secondary_boundary_sources: Vec<
            Box<dyn FnMut(u64) -> Result<Vec<(u64, u32)>> + '_>,
        > = Vec::with_capacity(ordered_terms.len().saturating_sub(1));
        for (ordered_slot, slot) in ordered_terms.iter().copied().enumerate() {
            let encoded = encoded_terms[slot].clone();
            let cache_term: Arc<[u8]> = Arc::from(encoded.clone());
            let leader = ordered_slot == 0;
            sources.push(Box::new(move |document_id, max_blocks| {
                let target = if leader {
                    document_id.max(range_start)
                } else {
                    document_id
                };
                self.check_cancellation()?;
                if leader && target > range_end {
                    return Ok(Vec::new());
                }
                paged
                    .numeric_posting_fetch_for_with_key(
                        &self.snapshot,
                        &self.physical_index,
                        &encoded,
                        target,
                        max_blocks,
                    )
                    .map(|blocks| {
                        blocks
                            .into_iter()
                            .filter(|fetched| !leader || fetched.last_document_id <= range_end)
                            .map(|fetched| {
                                self.encoded_posting_block_from_fetch(
                                    Arc::clone(&cache_term),
                                    fetched,
                                )
                            })
                            .collect()
                    })
            }));
            if ordered_slot > 0 {
                let encoded = encoded_terms[slot].clone();
                secondary_boundary_sources.push(Box::new(move |document_id| {
                    self.check_cancellation()?;
                    paged.numeric_posting_block_boundaries_for_with_key(
                        &self.snapshot,
                        &self.physical_index,
                        &encoded,
                        document_id,
                        SEQUENTIAL_BLOCK_BATCH,
                    )
                }));
            }
        }
        crate::fts_postings::block_max_bm25_and_top_k_seeking(
            sources,
            Some(secondary_boundary_sources),
            ordered_inverse_document_frequencies,
            average_document_length,
            parameters,
            keep,
            filter,
            initial_best,
        )
    }

    /// Exact conjunctive BM25 that LAYERS the per-term transactional write
    /// set — unfolded tail postings and tombstones — over the sealed posting
    /// blocks instead of declining. The sealed corpus is still served by the
    /// block-max seeking conjunction; documents touched by the write layer
    /// are excluded from it and re-scored from their current (tail) truth,
    /// so fresh inserts compete for the top-k, updates rank by their new
    /// term frequencies, and deletes disappear. Folding remains worthwhile
    /// (it shrinks the layer) but is no longer required for the fast path.
    ///
    /// Ranking uses the sealed generation's collection/term statistics; the
    /// unfolded layer shifts document counts by at most its own size, which
    /// for a bounded layer is a vanishing IDF perturbation. Returns
    /// `Ok(None)` when the write layer exceeds the merge budget (fold first)
    /// or the index has no numeric blocks.
    pub fn tail_merged_bm25_and_top_k(
        &self,
        terms: &[&str],
        parameters: crate::fts_scoring::Bm25Parameters,
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
    ) -> Result<Option<Vec<crate::fts_postings::FullTextRankedPosting>>> {
        const MAX_WRITE_LAYER_ENTRIES: usize = 65_536;
        self.check_cancellation()?;
        if terms.is_empty()
            || keep == 0
            || !parameters.k1.is_finite()
            || parameters.k1 < 0.0
            || !parameters.b.is_finite()
            || !(0.0..=1.0).contains(&parameters.b)
            || terms.iter().any(|term| !full_text_term_is_indexable(term))
        {
            return Ok(None);
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        if !paged.index_has_numeric_posting_blocks(&self.snapshot, &self.physical_index)? {
            return Ok(None);
        }
        let Some(collection_statistics) =
            paged.full_text_collection_statistics(&self.snapshot, &self.physical_index)?
        else {
            return Ok(None);
        };

        struct TailPosting {
            doc_length: u32,
            doc_distinct: u32,
            packed_positions: Vec<u16>,
        }
        let encoded_terms = terms
            .iter()
            .map(|term| encode_index_key(&[IndexValue::String((*term).to_string())]))
            .collect::<Vec<_>>();
        let mut tails: Vec<FxHashMap<String, TailPosting>> = Vec::with_capacity(terms.len());
        let mut tombstones: Vec<FxHashSet<String>> = Vec::with_capacity(terms.len());
        let mut affected: FxHashSet<String> = FxHashSet::default();
        let mut inverse_document_frequencies = Vec::with_capacity(terms.len());
        let mut entries = 0usize;
        for encoded in &encoded_terms {
            let mut term_tail: FxHashMap<String, TailPosting> = FxHashMap::default();
            let mut packed = Vec::new();
            for entry in paged.scan_index_exact(&self.snapshot, &self.physical_index, encoded)? {
                self.check_cancellation()?;
                let (pk, payload) = entry?;
                entries += 1;
                if entries > MAX_WRITE_LAYER_ENTRIES {
                    return Ok(None);
                }
                let Some((doc_length, doc_distinct)) =
                    decode_fts_posting_payload_into(&payload, &mut packed)
                else {
                    // A legacy payload the numeric layer cannot score.
                    return Ok(None);
                };
                affected.insert(pk.clone());
                term_tail.insert(
                    pk,
                    TailPosting {
                        doc_length,
                        doc_distinct,
                        packed_positions: packed.clone(),
                    },
                );
            }
            let mut term_tombstones = FxHashSet::default();
            for pk in
                paged.scan_posting_tombstones(&self.snapshot, &self.physical_index, encoded)?
            {
                let pk = pk?;
                self.check_cancellation()?;
                entries += 1;
                if entries > MAX_WRITE_LAYER_ENTRIES {
                    return Ok(None);
                }
                affected.insert(pk.clone());
                term_tombstones.insert(pk);
            }
            tails.push(term_tail);
            tombstones.push(term_tombstones);
            let statistics = self
                .cached_term_statistics(paged, Arc::from(encoded.clone()))?
                .unwrap_or_default();
            inverse_document_frequencies.push(crate::fts_scoring::bm25_inverse_document_frequency(
                collection_statistics.document_count,
                statistics.document_frequency,
            ));
        }
        if affected.is_empty() {
            // Nothing to layer; the plain block path declined for another
            // reason and this path has nothing more to offer.
            return Ok(None);
        }

        // Sealed documents touched by the write layer must not be scored
        // from their stale block postings.
        let mut excluded_ids: FxHashSet<u64> = FxHashSet::default();
        let mut sealed_id_of: FxHashMap<String, u64> = FxHashMap::default();
        for pk in &affected {
            self.check_cancellation()?;
            if let Some(document_id) =
                paged.full_text_document_id_for_pk(&self.snapshot, &self.physical_index, pk)?
            {
                excluded_ids.insert(document_id);
                sealed_id_of.insert(pk.clone(), document_id);
            }
        }

        let inflated_keep = keep.saturating_add(excluded_ids.len());
        let Some(mut block_hits) =
            self.block_max_bm25_hits(terms, parameters, inflated_keep, filter, false)?
        else {
            return Ok(None);
        };
        block_hits.retain(|hit| !excluded_ids.contains(&hit.document_id));
        block_hits.truncate(keep);
        let Some(mut merged) = self.materialize_ranked_hits(block_hits)? else {
            return Ok(None);
        };

        // Score every write-layer candidate from its current truth: the tail
        // posting when present, the sealed block posting otherwise, absent
        // (or tombstoned) meaning the conjunction fails.
        'candidate: for pk in &affected {
            self.check_cancellation()?;
            let mut any_tail = false;
            let mut score = 0.0f32;
            let mut document_length = 0u32;
            let mut document_distinct_terms = 0u32;
            let mut term_positions = Vec::with_capacity(terms.len());
            for slot in 0..terms.len() {
                if let Some(posting) = tails[slot].get(pk) {
                    any_tail = true;
                    score += crate::fts_scoring::bm25_term_score(
                        posting.packed_positions.len().max(1) as u32,
                        inverse_document_frequencies[slot],
                        posting.doc_length,
                        collection_statistics.average_document_length,
                        parameters,
                    );
                    document_length = posting.doc_length;
                    document_distinct_terms = posting.doc_distinct;
                    term_positions.push(Some(posting.packed_positions.clone()));
                    continue;
                }
                if tombstones[slot].contains(pk) {
                    continue 'candidate;
                }
                let Some(document_id) = sealed_id_of.get(pk) else {
                    continue 'candidate;
                };
                let Some(posting) =
                    self.sealed_posting_for_document(&encoded_terms[slot], *document_id)?
                else {
                    continue 'candidate;
                };
                score += crate::fts_scoring::bm25_term_score(
                    posting.packed_positions.len().max(1) as u32,
                    inverse_document_frequencies[slot],
                    posting.doc_length,
                    collection_statistics.average_document_length,
                    parameters,
                );
                if document_length == 0 {
                    document_length = posting.doc_length;
                    document_distinct_terms = posting.doc_distinct;
                }
                term_positions.push(Some(posting.packed_positions));
            }
            if !any_tail {
                // Pure tombstones: the document lost these terms or was
                // deleted; its block postings were already excluded.
                continue;
            }
            let sealed_id = sealed_id_of.get(pk).copied();
            if filter.is_some() {
                // Native filters are generation-qualified document bitsets;
                // a document outside the sealed generation cannot satisfy
                // one, and a sealed document must still pass it.
                match sealed_id {
                    Some(document_id)
                        if filter.is_some_and(|filter| filter.contains(document_id)) => {}
                    _ => {
                        crate::fts_format::record_filter_rejections(1);
                        continue;
                    }
                }
            }
            merged.push(crate::fts_postings::FullTextRankedPosting {
                document_id: sealed_id.unwrap_or(u64::MAX),
                primary_key: pk.clone(),
                score,
                document_length,
                document_distinct_terms,
                term_positions,
            });
        }

        merged.sort_by(|left, right| {
            right
                .score
                .partial_cmp(&left.score)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| left.primary_key.cmp(&right.primary_key))
        });
        merged.truncate(keep);
        crate::fts_format::record_tail_merged_bm25();
        Ok(Some(merged))
    }

    /// One sealed posting for `(term, document_id)`, decoded from its block.
    fn sealed_posting_for_document(
        &self,
        encoded_term: &[u8],
        document_id: u64,
    ) -> Result<Option<crate::paged_collection::NumericBlockPosting>> {
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        let Some((_, bytes)) = paged.numeric_posting_block_for_with_key(
            &self.snapshot,
            &self.physical_index,
            encoded_term,
            document_id,
        )?
        else {
            return Ok(None);
        };
        let postings = crate::paged_collection::decode_numeric_posting_block(&bytes)?;
        Ok(postings
            .binary_search_by_key(&document_id, |posting| posting.document_id)
            .ok()
            .map(|slot| postings[slot].clone()))
    }

    /// Exact conjunctive BM25 over the impact-ordered sidecars. One impact
    /// block per term is consumed per round. Every newly encountered document
    /// is random-access checked against all operands and scored exactly; the
    /// scan stops when the kth score beats the maximum BM25 score any document
    /// still unseen in every stream can attain.
    ///
    /// The existing impact order is monotone in term frequency when the
    /// generation contains exactly one populated field. Mixed-field
    /// generations return `None` and retain the document-order compatibility
    /// path. Likewise, mutable tails/tombstones fall back until folded.
    pub fn impact_ordered_bm25_and_top_k(
        &self,
        terms: &[&str],
        parameters: crate::fts_scoring::Bm25Parameters,
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
    ) -> Result<Option<Vec<crate::fts_postings::FullTextRankedPosting>>> {
        let Some(hits) = self.impact_ordered_bm25_hits(terms, parameters, keep, filter, false)?
        else {
            return Ok(None);
        };
        self.materialize_ranked_hits(hits)
    }

    fn impact_ordered_bm25_hits(
        &self,
        terms: &[&str],
        parameters: crate::fts_scoring::Bm25Parameters,
        keep: usize,
        filter: Option<&crate::fts_filters::FullTextDocumentFilter>,
        stop_when_full: bool,
    ) -> Result<Option<Vec<crate::fts_postings::WandHit>>> {
        self.check_cancellation()?;
        if terms.is_empty()
            || keep == 0
            || terms.iter().any(|term| !full_text_term_is_indexable(term))
        {
            return Ok(None);
        }
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        if !paged.index_has_numeric_posting_blocks(&self.snapshot, &self.physical_index)? {
            return Ok(None);
        }
        let Some(collection_statistics) =
            paged.full_text_collection_statistics(&self.snapshot, &self.physical_index)?
        else {
            return Ok(None);
        };
        if collection_statistics
            .field_total_lengths
            .iter()
            .filter(|length| **length != 0)
            .count()
            != 1
        {
            return Ok(None);
        }

        let encoded_terms = terms
            .iter()
            .map(|term| encode_index_key(&[IndexValue::String((*term).to_string())]))
            .collect::<Vec<_>>();
        let mut inverse_document_frequencies = Vec::with_capacity(terms.len());
        for encoded in &encoded_terms {
            let mut tail = paged.scan_index_exact(&self.snapshot, &self.physical_index, encoded)?;
            if let Some(entry) = tail.next() {
                entry?;
                return Ok(None);
            }
            let mut tombstones =
                paged.scan_posting_tombstones(&self.snapshot, &self.physical_index, encoded)?;
            if let Some(entry) = tombstones.next() {
                entry?;
                return Ok(None);
            }
            let Some(statistics) =
                paged.full_text_term_statistics(&self.snapshot, &self.physical_index, encoded)?
            else {
                return Ok(Some(Vec::new()));
            };
            if statistics.impact_block_count == 0 {
                return Ok(None);
            }
            inverse_document_frequencies.push(crate::fts_scoring::bm25_inverse_document_frequency(
                collection_statistics.document_count,
                statistics.document_frequency,
            ));
        }

        let mut streams = encoded_terms
            .iter()
            .map(|encoded| {
                paged
                    .scan_numeric_impact_blocks(&self.snapshot, &self.physical_index, encoded)
                    .map(Iterator::peekable)
            })
            .collect::<Result<Vec<_>>>()?;
        let mut seen = FxHashSet::<u64>::default();
        let mut best = Vec::<crate::fts_postings::WandHit>::with_capacity(keep);
        let mut scored = 0usize;
        let mut skipped = 0usize;
        let mut stopped_by_bound = false;
        let mut rounds = 0usize;

        loop {
            let mut candidates = Vec::<u64>::new();
            self.check_cancellation()?;
            let mut exhausted = false;
            for stream in &mut streams {
                let Some(block) = stream.next() else {
                    exhausted = true;
                    continue;
                };
                let (_, bytes) = block?;
                if crate::paged_collection::compact_impact_block_header(&bytes).is_some() {
                    crate::paged_collection::visit_compact_impact_block(&bytes, |document_id| {
                        candidates.push(document_id);
                        Ok(true)
                    })?;
                } else {
                    candidates.extend(
                        crate::paged_collection::decode_numeric_posting_block(&bytes)?
                            .into_iter()
                            .map(|posting| posting.document_id),
                    );
                }
            }
            if candidates.is_empty() {
                break;
            }
            candidates.sort_unstable();
            candidates.dedup();
            candidates.retain(|document_id| {
                let novel = seen.insert(*document_id);
                if novel && filter.is_some_and(|filter| !filter.contains(*document_id)) {
                    crate::fts_format::record_filter_rejections(1);
                    skipped = skipped.saturating_add(1);
                    false
                } else {
                    novel
                }
            });

            let postings_by_term = encoded_terms
                .iter()
                .map(|encoded| self.numeric_postings_for_candidates(paged, encoded, &candidates))
                .collect::<Result<Vec<_>>>()?;
            for (candidate, document_id) in candidates.iter().copied().enumerate() {
                if candidate % 256 == 0 {
                    self.check_cancellation()?;
                }
                if postings_by_term
                    .iter()
                    .any(|postings| postings[candidate].is_none())
                {
                    skipped = skipped.saturating_add(1);
                    continue;
                }
                let first = postings_by_term[0][candidate]
                    .as_ref()
                    .expect("conjunctive candidate has first posting");
                let mut score = 0.0f32;
                let mut positions = Vec::with_capacity(terms.len());
                for (slot, postings) in postings_by_term.iter().enumerate() {
                    let posting = postings[candidate]
                        .as_ref()
                        .expect("conjunctive candidate has every posting");
                    score += crate::fts_scoring::bm25_term_score(
                        posting.packed_positions.len().max(1) as u32,
                        inverse_document_frequencies[slot],
                        posting.doc_length,
                        collection_statistics.average_document_length,
                        parameters,
                    );
                    positions.push(Some(posting.packed_positions.clone()));
                }
                scored = scored.saturating_add(1);
                let position = best
                    .binary_search_by(|existing| {
                        score
                            .partial_cmp(&existing.score)
                            .unwrap_or(Ordering::Equal)
                            .then_with(|| existing.document_id.cmp(&document_id))
                    })
                    .unwrap_or_else(|position| position);
                if position < keep {
                    best.insert(
                        position,
                        crate::fts_postings::WandHit {
                            document_id,
                            score,
                            document_length: first.doc_length,
                            document_distinct_terms: first.doc_distinct,
                            term_positions: positions,
                        },
                    );
                    best.truncate(keep);
                }
            }

            rounds = rounds.saturating_add(1);
            if stop_when_full && (best.len() >= keep || rounds >= 8) {
                break;
            }

            if exhausted {
                break;
            }
            if best.len() >= keep {
                let mut unseen_upper_bound = 0.0f32;
                let mut all_have_future = true;
                for (slot, stream) in streams.iter_mut().enumerate() {
                    let Some(next) = stream.peek() else {
                        all_have_future = false;
                        break;
                    };
                    let (_, bytes) = next.as_ref().map_err(|error| {
                        BicDbError::PagedStorage(format!("read impact-ordered BM25 block: {error}"))
                    })?;
                    let bucket = if let Some(header) =
                        crate::paged_collection::compact_impact_block_header(bytes)
                    {
                        header.max_impact
                    } else {
                        crate::paged_collection::numeric_posting_block_header(bytes)
                            .ok_or_else(|| {
                                BicDbError::PagedStorage(
                                    "corrupt BM25 impact block header".to_string(),
                                )
                            })?
                            .max_impact
                    };
                    let maximum_frequency =
                        crate::fts_scoring::unweighted_term_frequency_ceiling(bucket);
                    unseen_upper_bound += crate::fts_scoring::bm25_term_score(
                        maximum_frequency,
                        inverse_document_frequencies[slot],
                        0,
                        collection_statistics.average_document_length,
                        parameters,
                    );
                }
                let kth = best.last().map(|hit| hit.score).unwrap_or_default();
                if !all_have_future || kth > unseen_upper_bound {
                    stopped_by_bound = all_have_future;
                    break;
                }
            }
        }
        crate::fts_format::record_wand(scored, skipped, usize::from(stopped_by_bound));
        Ok(Some(best))
    }

    fn numeric_postings_for_candidates(
        &self,
        paged: &crate::paged_collection::PagedRecords,
        encoded_term: &[u8],
        candidates: &[u64],
    ) -> Result<Vec<Option<crate::paged_collection::NumericBlockPosting>>> {
        let mut output = vec![None; candidates.len()];
        let mut current_last = None::<u64>;
        let mut current = Vec::<crate::paged_collection::NumericBlockPosting>::new();
        for (slot, document_id) in candidates.iter().copied().enumerate() {
            if current_last.is_none_or(|last| document_id > last) {
                self.check_cancellation()?;
                let Some((last, bytes)) = paged.numeric_posting_block_for_with_key(
                    &self.snapshot,
                    &self.physical_index,
                    encoded_term,
                    document_id,
                )?
                else {
                    current.clear();
                    current_last = Some(u64::MAX);
                    continue;
                };
                current = crate::paged_collection::decode_numeric_posting_block(&bytes)?;
                current_last = Some(last);
            }
            if let Ok(position) =
                current.binary_search_by_key(&document_id, |posting| posting.document_id)
            {
                output[slot] = Some(current[position].clone());
            }
        }
        Ok(output)
    }

    /// Wrap a native-representation fetch: slim segment blocks keep their
    /// slim bytes and directory-served metadata; the kernels decode slim
    /// directly and no v1 bytes ever exist on this path.
    fn encoded_posting_block_from_fetch(
        &self,
        term: Arc<[u8]>,
        fetched: crate::paged_collection::FetchedPostingBlock,
    ) -> crate::fts_postings::EncodedPostingBlock {
        let cached_rank_metadata = fetched.slim.as_ref().and_then(|context| {
            context
                .header
                .map(|(max_rank, weight_mask)| (max_rank, context.max_term_frequency, weight_mask))
        });
        crate::fts_postings::EncodedPostingBlock {
            last_document_id: fetched.last_document_id,
            bytes: Arc::from(fetched.bytes),
            slim: fetched.slim,
            cache: Some((
                Arc::clone(&self.db.fts_block_cache),
                crate::fts_cache::FullTextBlockCacheKey {
                    generation: Arc::clone(&self.physical_index),
                    term,
                    last_document_id: fetched.last_document_id,
                },
            )),
            prefetched: None,
            cached_rank_metadata,
            prefetch_blocks: self.db.config.fts_prefetch_blocks,
        }
    }

    fn encoded_posting_block(
        &self,
        term: Arc<[u8]>,
        last_document_id: u64,
        bytes: Vec<u8>,
    ) -> crate::fts_postings::EncodedPostingBlock {
        crate::fts_postings::EncodedPostingBlock {
            last_document_id,
            bytes: Arc::from(bytes),
            slim: None,
            cache: Some((
                Arc::clone(&self.db.fts_block_cache),
                crate::fts_cache::FullTextBlockCacheKey {
                    generation: Arc::clone(&self.physical_index),
                    term,
                    last_document_id,
                },
            )),
            prefetched: None,
            cached_rank_metadata: None,
            prefetch_blocks: self.db.config.fts_prefetch_blocks,
        }
    }

    fn cached_term_statistics(
        &self,
        paged: &crate::paged_collection::PagedRecords,
        term: Arc<[u8]>,
    ) -> Result<Option<crate::fts_format::FullTextTermStatistics>> {
        if let Some(statistics) = self
            .db
            .fts_block_cache
            .get_term(&self.physical_index, &term)
        {
            return Ok(Some(statistics));
        }
        let statistics =
            paged.full_text_term_statistics(&self.snapshot, &self.physical_index, &term)?;
        if let Some(statistics) = statistics.as_ref() {
            self.db.fts_block_cache.insert_term(
                Arc::clone(&self.physical_index),
                term,
                statistics.clone(),
            );
        }
        Ok(statistics)
    }

    fn materialize_ranked_hits(
        &self,
        hits: Vec<crate::fts_postings::WandHit>,
    ) -> Result<Option<Vec<crate::fts_postings::FullTextRankedPosting>>> {
        let paged = self
            .db
            .paged_records
            .as_ref()
            .expect("FTS read session requires page storage");
        let primary_keys = bounded_parallel_read_map(&hits, |hit| {
            self.check_cancellation()?;
            paged
                .full_text_pk_for_document_id(
                    &self.snapshot,
                    &self.physical_index,
                    hit.document_id,
                )?
                .ok_or_else(|| BicDbError::Corruption {
                    path: PathBuf::from(DEFAULT_PAGED_DIR),
                    message: format!(
                        "full-text document id {} has no primary-key mapping",
                        hit.document_id
                    ),
                })
        })?;
        let mut ranked = Vec::with_capacity(hits.len());
        for (hit, primary_key) in hits.into_iter().zip(primary_keys) {
            ranked.push(crate::fts_postings::FullTextRankedPosting {
                document_id: hit.document_id,
                primary_key,
                score: hit.score,
                document_length: hit.document_length,
                document_distinct_terms: hit.document_distinct_terms,
                term_positions: hit.term_positions,
            });
        }
        Ok(Some(ranked))
    }
}

impl SecureBicDb<'_> {
    pub fn insert(&mut self, collection: &str, record: Record) -> Result<()> {
        self.batch_insert(collection, vec![record])
    }

    pub fn batch_insert<I>(&mut self, collection: &str, records: I) -> Result<()>
    where
        I: IntoIterator<Item = Record>,
    {
        self.db
            .ensure_no_native_mutation_grant_required(collection, SecureOperation::Write)?;
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Write, &self.ctx)?;
        let records = records.into_iter().collect::<Vec<_>>();
        if let Some(policy) = policy.as_ref() {
            for record in &records {
                BicDb::validate_record_tenant(policy, &self.ctx, record)?;
            }
        }
        self.db
            .batch_insert_unchecked_with_memory_jobs(collection, records, true)
    }

    pub fn get(&mut self, collection: &str, id: &str) -> Result<Option<Arc<Record>>> {
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Read, &self.ctx)?;
        let Some(record) = self.db.get_unchecked(collection, id)? else {
            return Ok(None);
        };
        if let Some(policy) = policy.as_ref() {
            if !BicDb::record_visible_to_policy(policy, &self.ctx, &record)? {
                return Ok(None);
            }
            return Ok(Some(Arc::new(protected_data::project_record(
                &self.db.sync_state.node_id.to_string(),
                &self.db.path,
                collection,
                policy,
                &self.ctx.roles,
                &record,
                self.ctx.bypass_policy.is_some(),
            )?)));
        }
        Ok(Some(record))
    }

    pub fn scan_collection(&mut self, collection: &str) -> Result<Vec<Record>> {
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Read, &self.ctx)?;
        let records = self.db.scan_collection_unchecked(collection)?;
        self.filter_visible(collection, policy.as_ref(), records)
    }

    pub fn write_attachment_from_reader(
        &mut self,
        collection: &str,
        id: &str,
        field: &str,
        media_type: Option<&str>,
        reader: impl std::io::Read,
    ) -> Result<LargeValueRef> {
        self.db
            .ensure_no_native_mutation_grant_required(collection, SecureOperation::Write)?;
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Write, &self.ctx)?;
        if let Some(policy) = policy.as_ref() {
            let record = self.db.get_unchecked(collection, id)?.ok_or_else(|| {
                BicDbError::LargeValue(format!(
                    "attachment target record `{id}` in `{collection}` does not exist"
                ))
            })?;
            BicDb::validate_record_tenant(policy, &self.ctx, &record)?;
        }
        self.db
            .write_attachment_unchecked(collection, id, field, media_type, reader)
    }

    pub fn open_attachment_reader(
        &mut self,
        collection: &str,
        id: &str,
        field: &str,
    ) -> Result<Option<LargeValueReader>> {
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Read, &self.ctx)?;
        let Some(record) = self.db.get_unchecked(collection, id)? else {
            return Ok(None);
        };
        if let Some(policy) = policy.as_ref() {
            if !BicDb::record_visible_to_policy(policy, &self.ctx, &record)? {
                return Ok(None);
            }
        }
        self.db.open_attachment_reader_for_record(&record, field)
    }

    pub fn delete(&mut self, collection: &str, id: &str) -> Result<bool> {
        Ok(self.batch_delete(collection, std::iter::once(id))? > 0)
    }

    pub fn batch_delete<I, S>(&mut self, collection: &str, ids: I) -> Result<usize>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        self.db
            .ensure_no_native_mutation_grant_required(collection, SecureOperation::Delete)?;
        let policy =
            self.db
                .authorize_collection(collection, SecureOperation::Delete, &self.ctx)?;
        let ids = ids
            .into_iter()
            .map(|id| id.as_ref().to_string())
            .collect::<Vec<_>>();
        if let Some(policy) = policy.as_ref() {
            let mut seen_ids = FxHashSet::default();
            for id in &ids {
                if id.is_empty() || !seen_ids.insert(id.clone()) {
                    continue;
                }
                let Some(record) = self.db.get_unchecked(collection, id)? else {
                    continue;
                };
                if !BicDb::record_visible_to_policy(policy, &self.ctx, &record)? {
                    return Err(BicDbError::Authorization(format!(
                        "delete denied for record `{id}` in `{collection}`"
                    )));
                }
            }
        }
        self.db.batch_delete_unchecked(collection, ids)
    }

    pub fn search_vector(
        &mut self,
        collection: &str,
        query: &[f32],
        top_k: usize,
        filter: Option<&JsonFilter>,
    ) -> Result<Vec<VectorSearchResult>> {
        self.search_vector_with_metric(collection, query, top_k, filter, VectorMetric::Cosine)
    }

    pub fn search_vector_with_metric(
        &mut self,
        collection: &str,
        query: &[f32],
        top_k: usize,
        filter: Option<&JsonFilter>,
        metric: VectorMetric,
    ) -> Result<Vec<VectorSearchResult>> {
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Read, &self.ctx)?;
        if let Some(policy) = policy.as_ref() {
            BicDb::validate_secure_filter(policy, filter)?;
        }
        if policy.is_none() {
            return self
                .db
                .search_vector_with_metric_unchecked(collection, query, top_k, filter, metric);
        }
        let records = self.scan_collection(collection)?;
        // The policy-projected records are already materialized; the search input is
        // the compact form, so convert this (non-hot, secure-context) scan.
        let stored = records
            .iter()
            .map(StoredRecord::from_record)
            .collect::<Result<Vec<_>>>()?;
        vector::search(collection, stored.iter(), query, top_k, filter, metric)
    }

    pub fn search_vector_ann(
        &mut self,
        collection: &str,
        query: &[f32],
        top_k: usize,
        ef_search: usize,
    ) -> Result<Vec<VectorSearchResult>> {
        let metric = self
            .db
            .hnsw_indexes
            .read()
            .get(collection)
            .map(|index| index.config().distance)
            .ok_or_else(|| {
                BicDbError::Index(format!("HNSW vector index for `{collection}` not found"))
            })?;
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Read, &self.ctx)?;
        let results = self.db.search_vector_ann_with_metric_unchecked(
            collection,
            query,
            top_k.saturating_mul(4).max(top_k),
            ef_search,
            metric,
        )?;
        let mut filtered = Vec::new();
        for result in results {
            if policy
                .as_ref()
                .map(|policy| BicDb::record_visible_to_policy(policy, &self.ctx, &result.record))
                .transpose()?
                .unwrap_or(true)
            {
                let record = if let Some(policy) = policy.as_ref() {
                    protected_data::project_record(
                        &self.db.sync_state.node_id.to_string(),
                        &self.db.path,
                        collection,
                        policy,
                        &self.ctx.roles,
                        &result.record,
                        self.ctx.bypass_policy.is_some(),
                    )?
                } else {
                    result.record
                };
                filtered.push(VectorSearchResult {
                    record,
                    score: result.score,
                });
            }
            if filtered.len() == top_k {
                break;
            }
        }
        Ok(filtered)
    }

    pub fn scan_time_range(
        &mut self,
        collection: &str,
        start_ts: i64,
        end_ts: i64,
    ) -> Result<Vec<Record>> {
        let policy = self
            .db
            .authorize_collection(collection, SecureOperation::Read, &self.ctx)?;
        let records = self
            .db
            .scan_time_range_unchecked(collection, start_ts, end_ts)?;
        self.filter_visible(collection, policy.as_ref(), records)
    }

    pub fn build_graph_projection(
        &mut self,
        projection: GraphProjection,
    ) -> Result<GraphProjectionData> {
        validate_graph_projection_name(&projection.name)?;
        let graph = self.materialize_graph_projection(projection)?;
        self.db.persist_graph_projection(&graph)?;
        self.db
            .graphs
            .write()
            .insert(graph.name.clone(), graph.clone());
        Ok(graph)
    }

    fn filter_visible(
        &self,
        collection: &str,
        policy: Option<&CollectionPolicy>,
        records: Vec<Record>,
    ) -> Result<Vec<Record>> {
        let Some(policy) = policy else {
            return Ok(records);
        };
        let mut visible = Vec::new();
        for record in records {
            if BicDb::record_visible_to_policy(policy, &self.ctx, &record)? {
                visible.push(protected_data::project_record(
                    &self.db.sync_state.node_id.to_string(),
                    &self.db.path,
                    collection,
                    policy,
                    &self.ctx.roles,
                    &record,
                    self.ctx.bypass_policy.is_some(),
                )?);
            }
        }
        Ok(visible)
    }

    fn materialize_graph_projection(
        &mut self,
        projection: GraphProjection,
    ) -> Result<GraphProjectionData> {
        let mut records_by_collection = HashMap::new();
        for collection in projection.collection_names() {
            records_by_collection.insert(collection.clone(), self.scan_collection(&collection)?);
        }
        let mut events_by_stream = HashMap::new();
        for stream in projection.stream_names() {
            events_by_stream.insert(stream.clone(), self.db.events.lock().read(&stream));
        }
        GraphProjectionData::build(projection, &records_by_collection, &events_by_stream)
    }
}

impl Transaction {
    /// Queue an opaque deferred hook (a DEFERRABLE INITIALLY DEFERRED trigger
    /// call serialized by the SQL layer) to fire immediately before this
    /// transaction commits.
    pub fn push_deferred_hook(&mut self, hook: serde_json::Value) {
        self.deferred_hooks.push(hook);
    }

    pub fn has_deferred_hooks(&self) -> bool {
        !self.deferred_hooks.is_empty()
    }

    /// Take the queued hooks for firing. Firing may queue more (a deferred
    /// body writing rows that carry deferred triggers), so callers loop until
    /// this returns empty.
    pub fn take_deferred_hooks(&mut self) -> Vec<serde_json::Value> {
        std::mem::take(&mut self.deferred_hooks)
    }

    pub fn id(&self) -> TransactionId {
        self.id
    }

    pub fn state(&self) -> TxState {
        self.state
    }

    /// Fixed MVCC watermark captured when this transaction began.
    pub fn visibility_watermark(&self) -> u64 {
        self.snapshot_tx.0
    }

    pub fn isolation(&self) -> TransactionIsolation {
        self.isolation
    }

    /// Register a relation whose rows or predicates influenced this
    /// transaction. This is a no-op below serializable isolation.
    pub fn record_serializable_read(&mut self, relation: &str) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.isolation == TransactionIsolation::Serializable {
            self.serializable_reads.insert(relation.to_string());
        }
        Ok(())
    }

    /// Advance a trusted read-committed transaction to the latest contiguous
    /// committed watermark before its next host statement. Pending writes stay
    /// overlaid on the refreshed snapshot and retain their conflict metadata.
    pub fn refresh_read_committed_snapshot(&mut self) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.isolation != TransactionIsolation::ReadCommitted {
            return Ok(());
        }
        let (snapshot, paged_snapshot) = {
            let db = self.db_ref();
            (
                db.last_committed_tx.load(AtomicOrdering::SeqCst),
                db.paged_records
                    .as_ref()
                    .map(|paged| paged.latest_snapshot()),
            )
        };
        if snapshot <= self.snapshot_tx.0 {
            return Ok(());
        }
        self.active_snapshots.incr(snapshot);
        self.active_snapshots.decr_remove(self.snapshot_tx.0);
        self.snapshot_tx = TransactionId(snapshot);
        self.applied_snapshot = snapshot;
        self.paged_snapshot = paged_snapshot;
        Ok(())
    }

    pub fn mutation_actor(&self) -> Option<&MutationActor> {
        self.mutation_actor.as_ref()
    }

    /// Issue a transaction-local native mutation grant. This method is useful
    /// only on a transaction created with
    /// [`BicDb::begin_application_transaction`]; ordinary transactions fail
    /// closed.
    pub fn issue_mutation_grant(&mut self, spec: MutationGrantSpec) -> Result<MutationGrantId> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let actor = self.mutation_actor.clone().ok_or_else(|| {
            BicDbError::MutationDenied(
                "ordinary transactions cannot issue MutationGrants".to_string(),
            )
        })?;
        validate_collection_name(&spec.relation)?;
        self.db_ref().ensure_collection(&spec.relation)?;
        if spec.maximum_affected_rows == 0 || spec.statement_budget == 0 {
            return Err(BicDbError::MutationDenied(
                "MutationGrant row and statement budgets must be positive".to_string(),
            ));
        }
        if spec.bulk && spec.operation != MutationOperation::Bulk {
            return Err(BicDbError::MutationDenied(
                "bulk MutationGrant must use the bulk operation".to_string(),
            ));
        }
        if !spec.bulk && spec.maximum_affected_rows != 1 && spec.record_id.is_some() {
            return Err(BicDbError::MutationDenied(
                "record-scoped MutationGrant cannot affect more than one row".to_string(),
            ));
        }
        if spec.record_id.is_some() && spec.record_id_prefix.is_some() {
            return Err(BicDbError::MutationDenied(
                "MutationGrant cannot declare both record_id and record_id_prefix".to_string(),
            ));
        }
        if spec
            .record_id
            .as_ref()
            .is_some_and(|record_id| record_id.is_empty())
            || spec
                .record_id_prefix
                .as_ref()
                .is_some_and(|prefix| prefix.is_empty())
        {
            return Err(BicDbError::MutationDenied(
                "MutationGrant record restrictions cannot be empty".to_string(),
            ));
        }
        let id = MutationGrantId(self.next_mutation_grant);
        self.next_mutation_grant = self
            .next_mutation_grant
            .checked_add(1)
            .ok_or_else(|| BicDbError::MutationDenied("MutationGrant id exhausted".to_string()))?;
        self.mutation_grants.insert(
            id,
            MutationGrant {
                id,
                actor,
                remaining_rows: spec.maximum_affected_rows,
                remaining_statements: spec.statement_budget,
                spec,
            },
        );
        Ok(id)
    }

    pub fn register_commit_validator(&mut self, validator: NativeCommitValidator) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.mutation_actor.is_none() {
            return Err(BicDbError::MutationDenied(
                "ordinary transactions cannot register commit validators".to_string(),
            ));
        }
        self.commit_validators.push(validator);
        Ok(())
    }

    pub fn get_authorized(&self, collection: &str, id: &str) -> Result<Option<Arc<Record>>> {
        let actor = self.mutation_actor.as_ref().ok_or_else(|| {
            BicDbError::Authorization(
                "authorized reads require an application transaction".to_string(),
            )
        })?;
        let Some(record) = self.get_visible_unchecked(collection, id)? else {
            return Ok(None);
        };
        let db = self.db_ref();
        let state = db.collection_state(collection)?;
        let Some(policy) = state.meta.policy.as_ref() else {
            return Ok(Some(record));
        };
        let context = mutation_security_context(actor)?;
        BicDb::authorize_read_without_audit(collection, policy, &context)?;
        if !BicDb::record_visible_to_policy(policy, &context, &record)? {
            return Ok(None);
        }
        Ok(Some(Arc::new(protected_data::project_record(
            &db.sync_state.node_id.to_string(),
            &db.path,
            collection,
            policy,
            &context.roles,
            &record,
            false,
        )?)))
    }

    pub fn insert_with_grant(
        &mut self,
        grant: MutationGrantId,
        collection: &str,
        record: Record,
    ) -> Result<()> {
        let audit = self.authorize_mutation(
            grant,
            collection,
            MutationOperation::Insert,
            &[record.clone()],
        )?;
        self.write_upserts_unchecked(collection, vec![record])?;
        self.enqueue_mutation_audit(audit);
        Ok(())
    }

    pub fn update_with_grant(
        &mut self,
        grant: MutationGrantId,
        collection: &str,
        record: Record,
    ) -> Result<()> {
        let audit = self.authorize_mutation(
            grant,
            collection,
            MutationOperation::Update,
            &[record.clone()],
        )?;
        self.write_upserts_unchecked(collection, vec![record])?;
        self.enqueue_mutation_audit(audit);
        Ok(())
    }

    pub fn upsert_with_grant(
        &mut self,
        grant: MutationGrantId,
        collection: &str,
        record: Record,
    ) -> Result<()> {
        let operation = if self
            .get_visible_unchecked(collection, &record.id)?
            .is_some()
        {
            MutationOperation::Update
        } else {
            MutationOperation::Insert
        };
        let audit = self.authorize_mutation(grant, collection, operation, &[record.clone()])?;
        self.write_upserts_unchecked(collection, vec![record])?;
        self.enqueue_mutation_audit(audit);
        Ok(())
    }

    pub fn delete_with_grant(
        &mut self,
        grant: MutationGrantId,
        collection: &str,
        id: &str,
    ) -> Result<()> {
        let existing = self
            .get_visible_unchecked(collection, id)?
            .map(|record| record.as_ref().clone())
            .unwrap_or_else(|| Record::new(id));
        let audit =
            self.authorize_mutation(grant, collection, MutationOperation::Delete, &[existing])?;
        self.delete_many_unchecked(collection, std::iter::once(id))?;
        self.enqueue_mutation_audit(audit);
        Ok(())
    }

    fn authorize_mutation(
        &mut self,
        grant_id: MutationGrantId,
        collection: &str,
        operation: MutationOperation,
        records: &[Record],
    ) -> Result<Option<crate::broker::PendingBrokerPublish>> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let actor = self.mutation_actor.clone().ok_or_else(|| {
            BicDbError::MutationDenied(
                "mutation-grant writes require an application transaction".to_string(),
            )
        })?;
        let grant = self
            .mutation_grants
            .get(&grant_id)
            .cloned()
            .ok_or_else(|| {
                BicDbError::MutationDenied("unknown or consumed MutationGrant".to_string())
            })?;
        if grant.id != grant_id || grant.actor != actor {
            return Err(BicDbError::MutationDenied(
                "MutationGrant belongs to another transaction or actor".to_string(),
            ));
        }
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_millis() as i64)
            .unwrap_or_default();
        if actor.deadline_unix_ms <= now {
            return Err(BicDbError::QueryTimedOut);
        }
        if !grant.spec.relation.eq_ignore_ascii_case(collection) {
            return Err(BicDbError::MutationDenied(format!(
                "MutationGrant for `{}` cannot mutate `{collection}`",
                grant.spec.relation
            )));
        }
        let operation_allowed = grant.spec.operation == operation
            || (grant.spec.operation == MutationOperation::Restore
                && operation == MutationOperation::Update)
            || (grant.spec.operation == MutationOperation::Bulk && grant.spec.bulk);
        if !operation_allowed {
            return Err(BicDbError::MutationDenied(format!(
                "MutationGrant operation {:?} cannot authorize {operation:?}",
                grant.spec.operation
            )));
        }
        let rows = records.len() as u64;
        if rows == 0
            || rows > grant.remaining_rows
            || grant.remaining_statements == 0
            || (!grant.spec.bulk && rows > 1)
        {
            return Err(BicDbError::MutationDenied(
                "MutationGrant row or statement budget exceeded".to_string(),
            ));
        }
        let mutation_policy = {
            let db = self.db_ref();
            db.collection_state(collection)?
                .meta
                .mutation_policy
                .clone()
                .unwrap_or_default()
        };
        if mutation_policy.audit_required && grant.spec.audit_metadata.is_empty() {
            return Err(BicDbError::MutationDenied(format!(
                "collection `{collection}` requires non-empty MutationGrant audit metadata"
            )));
        }
        if mutation_policy.append_only && operation != MutationOperation::Insert {
            return Err(BicDbError::CommitValidation(format!(
                "collection `{collection}` is append-only"
            )));
        }
        for record in records {
            if grant
                .spec
                .record_id
                .as_ref()
                .is_some_and(|expected| expected != &record.id)
                || grant
                    .spec
                    .record_id_prefix
                    .as_ref()
                    .is_some_and(|prefix| !record.id.starts_with(prefix))
            {
                return Err(BicDbError::MutationDenied(format!(
                    "MutationGrant does not cover record `{}`",
                    record.id
                )));
            }
            let existing = self.get_visible_unchecked(collection, &record.id)?;
            let columns = mutation_changed_columns(operation, existing.as_deref(), record);
            if operation != MutationOperation::Delete
                && !columns.is_subset(&grant.spec.allowed_columns)
            {
                let denied = columns
                    .difference(&grant.spec.allowed_columns)
                    .cloned()
                    .collect::<Vec<_>>();
                return Err(BicDbError::MutationDenied(format!(
                    "MutationGrant does not allow columns {denied:?}"
                )));
            }
            if operation == MutationOperation::Insert && existing.is_some() {
                return Err(BicDbError::TransactionConflict(format!(
                    "record `{}` already exists in `{collection}`",
                    record.id
                )));
            }
            if matches!(
                operation,
                MutationOperation::Update | MutationOperation::Restore
            ) && existing.is_none()
            {
                return Err(BicDbError::TransactionConflict(format!(
                    "record `{}` does not exist in `{collection}`",
                    record.id
                )));
            }
            if let Some(existing) = existing.as_deref() {
                for field in &mutation_policy.immutable_fields {
                    if existing.metadata.get(field) != record.metadata.get(field) {
                        return Err(BicDbError::CommitValidation(format!(
                            "field `{field}` is immutable on `{collection}`"
                        )));
                    }
                }
                if let Some(expected) = grant.spec.expected_version {
                    let version_field = grant
                        .spec
                        .version_field
                        .as_ref()
                        .or(mutation_policy.version_field.as_ref())
                        .ok_or_else(|| {
                            BicDbError::MutationDenied(
                                "optimistic grant requires a version field".to_string(),
                            )
                        })?;
                    let actual = existing
                        .metadata
                        .get(version_field)
                        .and_then(Value::as_u64)
                        .ok_or_else(|| {
                            BicDbError::CommitValidation(format!(
                                "record `{}` lacks numeric version field `{version_field}`",
                                record.id
                            ))
                        })?;
                    if actual != expected {
                        return Err(BicDbError::TransactionConflict(format!(
                            "optimistic version conflict on `{collection}`/`{}`: expected {expected}, found {actual}",
                            record.id
                        )));
                    }
                }
            }
            validate_mutation_actor_field(
                collection,
                record,
                grant
                    .spec
                    .tenant_field
                    .as_ref()
                    .or(mutation_policy.tenant_field.as_ref()),
                actor.tenant_id.as_deref(),
                "tenant",
            )?;
            validate_mutation_actor_field(
                collection,
                record,
                grant
                    .spec
                    .workspace_field
                    .as_ref()
                    .or(mutation_policy.workspace_field.as_ref()),
                actor.workspace_id.as_deref(),
                "workspace",
            )?;
        }
        let audit = mutation_policy.audit_required.then(|| {
            let record_ids = records
                .iter()
                .take(100)
                .map(|record| record.id.clone())
                .collect::<Vec<_>>();
            let idempotency_key = format!(
                "mutation-audit/{}/{}/{}",
                self.id.0, grant_id.0, grant.remaining_statements
            );
            crate::broker::PendingBrokerPublish {
                queue: "__bicdb_mutation_audit".to_string(),
                payload: serde_json::json!({
                    "transaction_id": self.id.0,
                    "grant_id": grant_id.0,
                    "relation": collection,
                    "operation": operation,
                    "record_count": records.len(),
                    "record_ids": record_ids,
                    "record_ids_truncated": records.len() > 100,
                    "actor": actor,
                    "audit_metadata": grant.spec.audit_metadata,
                }),
                options: crate::broker::PublishOptions {
                    headers: serde_json::json!({
                        "trace_id": actor.trace_id,
                        "actor_id": actor.actor_id,
                        "tenant_id": actor.tenant_id,
                        "workspace_id": actor.workspace_id,
                        "originating_plugin": actor.originating_plugin,
                    }),
                    idempotency_key: Some(idempotency_key),
                    delay_ms: None,
                    max_attempts: None,
                },
                message_id: Uuid::new_v4(),
            }
        });
        let grant = self
            .mutation_grants
            .get_mut(&grant_id)
            .expect("grant was validated above");
        grant.remaining_rows -= rows;
        grant.remaining_statements -= 1;
        if grant.remaining_rows == 0 || grant.remaining_statements == 0 {
            self.mutation_grants.remove(&grant_id);
        }
        Ok(audit)
    }

    fn enqueue_mutation_audit(&self, audit: Option<crate::broker::PendingBrokerPublish>) {
        if let Some(audit) = audit {
            self.pending_broker_publishes.lock().push(audit);
        }
    }

    /// Pre-serializes the WAL Write-frame payloads for the buffered writes so the
    /// serde work runs OFF the serial commit critical section. Call after the
    /// writes are buffered and before committing (e.g. before acquiring the
    /// database write lock). Reads only `self`; the commit path falls back to
    /// inline serialization if this was not called or produced a partial result.
    pub fn prepare_wal_payloads(&mut self) {
        // A repair can replace a buffered row at commit. Encoding beforehand
        // would be discarded, and the old fallback reparsed every other write
        // too. The repair finalizer encodes once after all rows are locked and
        // their absolute values are final.
        if self.writes.iter().any(|write| write.repair.is_some()) {
            return;
        }
        self.prepare_final_wal_payloads();
    }

    pub(crate) fn prepare_final_wal_payloads(&mut self) {
        if self.writes.is_empty() || !self.prepared_wal.is_empty() {
            return;
        }
        // Paged mode logs a marker, not the writes — pre-serializing Write
        // frames here would be pure wasted CPU on the pgwire hot path. Same
        // replication exception as the commit path: a replicating primary
        // still logs full records.
        let (compact_updates, single_buffer) = {
            let db = self.db_ref();
            if db.paged_records.is_some() && !db.config.replication.enabled {
                return;
            }
            (
                compact_update_wal_enabled()
                    && db.paged_records.is_none()
                    && !db.config.replication.enabled,
                single_buffer_wal_enabled() && !db.encryption.is_enabled(),
            )
        };
        // A patch is relative to the compact pre-image supplied by SQL. If a
        // transaction writes the same row twice, that pre-image is not
        // necessarily the immediately preceding write, so retain full frames
        // for that uncommon shape.
        // `write_index` already contains one entry per distinct
        // (collection, record id). Nearly every transaction -- including
        // NewOrder -- writes each row once, so prove that common case in O(n)
        // instead of comparing every write with every other write. Preserve the
        // exact per-row result for the uncommon repeated-write shape because
        // only those rows need full WAL frames.
        let unique_rows = if self.writes_are_unique() {
            vec![true; self.writes.len()]
        } else {
            self.writes
                .iter()
                .enumerate()
                .map(|(idx, write)| {
                    !self.writes.iter().enumerate().any(|(other_idx, other)| {
                        idx != other_idx
                            && write.collection == other.collection
                            && write.record_id == other.record_id
                    })
                })
                .collect::<Vec<_>>()
        };
        let mut payloads = if single_buffer {
            PreparedWal::PlainFrames {
                count: 0,
                bytes: Vec::with_capacity(
                    self.writes
                        .iter()
                        .map(|write| {
                            write
                                .stored
                                .as_ref()
                                .map_or(0, |row| row.metadata.get().len())
                                + write.collection.len()
                                + write.record_id.len() * 2
                                + 512
                        })
                        .sum(),
                ),
            }
        } else {
            PreparedWal::Payloads(Vec::with_capacity(self.writes.len()))
        };
        let tx_id = self.id;
        for (idx, write) in self.writes.iter_mut().enumerate() {
            // Compact the record once: the raw JSON inside the StoredRecord is
            // the frame's record field AND the resident row after commit.
            if write.stored.is_none() {
                if let (TxWriteOp::Upsert, Some(record)) =
                    (write.op, write.record_opt().map(Arc::as_ref))
                {
                    match StoredRecord::from_record(record) {
                        Ok(stored) => write.stored = Some(Arc::new(stored)),
                        Err(_) => return,
                    }
                }
            }
            let patch = (compact_updates && unique_rows[idx])
                .then(|| compact_wal_patch(write))
                .flatten();
            let encoded = match (patch, write.stored.as_deref()) {
                (Some((before, after)), _) => payloads.push(
                    &TxFrameRef::Patch {
                        tx_id,
                        patch: TxPatchRef {
                            collection: &write.collection,
                            record_id: &write.record_id,
                            before: &before,
                            after: &after,
                            timestamp: write.timestamp,
                            statement_snapshot: write.statement_snapshot,
                        },
                    },
                    before.get().len()
                        + after.get().len()
                        + write.collection.len()
                        + write.record_id.len()
                        + 192,
                ),
                (None, Some(stored)) if compact_wal::enabled() => payloads.push(
                    &compact_wal::StoredWriteFrame::new(tx_id, write, stored),
                    stored.metadata.get().len()
                        + write.collection.len()
                        + write.record_id.len()
                        + stored.id.len()
                        + 256,
                ),
                (None, Some(stored)) => {
                    // The frame is the row's text plus a fixed envelope: size
                    // the buffer once instead of growing it through the row.
                    payloads.push(
                        &TxFrameRef::WriteStored {
                            tx_id,
                            write: TxWriteStoredRef {
                                collection: &write.collection,
                                op: write.op,
                                record_id: &write.record_id,
                                record: Some(stored),
                                timestamp: write.timestamp,
                                statement_snapshot: write.statement_snapshot,
                            },
                        },
                        stored.metadata.get().len()
                            + write.collection.len()
                            + write.record_id.len()
                            + stored.id.len()
                            + 256,
                    )
                }
                (None, None) => payloads.push(&TxFrameRef::Write { tx_id, write }, 0),
            };
            // Leave empty; commit serializes inline as a correctness fallback.
            if encoded.is_err() {
                return;
            }
        }
        self.prepared_wal = payloads;
    }

    #[inline]
    fn writes_are_unique(&self) -> bool {
        self.write_index.values().map(FxHashMap::len).sum::<usize>() == self.writes.len()
    }

    /// Records this transaction has written to `collection` but not yet
    /// committed, newest write per record id.
    ///
    /// Constraint validation runs against committed state, which cannot see a
    /// row this same transaction just inserted. Uniqueness checks need this to
    /// notice a key the transaction is already writing.
    pub fn pending_records(&self, collection: &str) -> Vec<Arc<Record>> {
        let mut latest: BTreeMap<&str, Option<Arc<Record>>> = BTreeMap::new();
        for write in &self.writes {
            if write.collection != collection {
                continue;
            }
            latest.insert(write.record_id.as_str(), write.record_opt().cloned());
        }
        latest.into_values().flatten().collect()
    }

    pub fn get(&self, collection: &str, id: &str) -> Result<Option<Arc<Record>>> {
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.get_visible_unchecked(collection, id)
    }

    /// Reserve a snapshot-visible row without changing it. The caller must
    /// separately enforce its SQL UPDATE privilege; native read policy is
    /// enforced here. Returns false on contention without waiting, enabling
    /// SQL NOWAIT/SKIP LOCKED without confusing contention with other errors.
    /// Locks use the same table as mutations and follow transaction/savepoint
    /// lifetime. A changed snapshot produces a retryable conflict, never stale
    /// data reported as successfully locked.
    pub fn try_lock_visible_record(
        &self,
        context: Option<&SecurityContext>,
        collection: &str,
        id: &str,
    ) -> Result<bool> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let visible = match context {
            Some(context) => self.get_with_context(context, collection, id)?,
            None => self.get(collection, id)?,
        };
        if visible.is_none() {
            return Ok(false);
        }
        let db = self.db_ref();
        match db.lock_tx_record_with_attempts(
            self.id,
            collection,
            id,
            0,
            false,
            false,
            &self.locked_keys,
        ) {
            Ok(()) => {}
            Err(BicDbError::TransactionConflict(_)) => return Ok(false),
            Err(error) => return Err(error),
        }
        if self.last_pending_write(collection, id).is_none() {
            let state = db.collection_state(collection)?;
            let shard = state.shard(id).read();
            let changed = shard.rowid_of(id).is_none_or(|rowid| {
                version_chain_max_tx(&shard.versions, rowid) > self.applied_snapshot
            });
            if changed {
                return Err(BicDbError::TransactionConflict(format!(
                    "row changed since locking query snapshot: {collection}:{id}"
                )));
            }
        }
        Ok(true)
    }

    /// Snapshot-visible point read authorized by a [`SecurityContext`]. Pending
    /// writes from this transaction are overlaid before collection policy and
    /// protected-field projection are applied.
    pub fn get_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        id: &str,
    ) -> Result<Option<Arc<Record>>> {
        let records = self.filter_context_visible(
            ctx,
            collection,
            vec![self.get_visible_unchecked(collection, id)?],
        )?;
        Ok(records.into_iter().next().flatten())
    }

    /// Point read with no policy or protection gate, for engine-internal
    /// integrity work (unique-key checks, pending-write merges) whose result
    /// never leaves the engine unfiltered — never for caller-visible reads.
    pub fn get_for_integrity_check(
        &self,
        collection: &str,
        id: &str,
    ) -> Result<Option<Arc<Record>>> {
        self.get_visible_unchecked(collection, id)
    }

    /// Batch existence probe for engine-internal primary-key arbitration.
    ///
    /// Unlike a caller-visible read this neither materializes records nor
    /// populates the transaction's read-image/observed-version maps. Its caller
    /// buffers inserts with explicit statement snapshots, so conflict detection
    /// and the commit-time unique-key claims still provide the required race
    /// protection. Keeping one collection guard across the batch removes a
    /// catalog lookup and several owned-key allocations per inserted row.
    pub fn contains_for_integrity_check<'a, I>(&self, collection: &str, ids: I) -> Result<Vec<bool>>
    where
        I: IntoIterator<Item = &'a str>,
    {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let state = db.collection_state(collection)?;
        let snapshot = self.snapshot_tx;
        let ids = ids.into_iter();
        let mut out = Vec::with_capacity(ids.size_hint().0);
        for id in ids {
            if let Some(write) = self.last_pending_write(collection, id) {
                out.push(matches!(write.op, TxWriteOp::Upsert));
                continue;
            }
            let shard = state.shard(id).read();
            let versions = shard
                .rowid_of(id)
                .and_then(|rowid| shard.versions.get(&rowid));
            let exists = match versions {
                Some(versions) => visible_version(versions, snapshot).is_some(),
                None if state.paged_lazy => {
                    drop(shard);
                    match (&self.paged_snapshot, &db.paged_records) {
                        (Some(snapshot), Some(paged)) => {
                            paged.get(snapshot, collection, id)?.is_some()
                        }
                        _ => false,
                    }
                }
                None => false,
            };
            out.push(exists);
        }
        Ok(out)
    }

    fn get_visible_unchecked(&self, collection: &str, id: &str) -> Result<Option<Arc<Record>>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let (record, observed_version, read_stored) = {
            let state = db.collection_state(collection)?;
            let shard = state.shard(id).read();
            // Lazy paged collections: a row is "touched this session" exactly
            // when it has a version chain; only then is the chain authoritative
            // (including an "invisible" verdict). A registry rowid alone (the
            // indexed-collection bootstrap allocates one per row without any
            // chain) says nothing about content, so it must not suppress the
            // page-store fallback.
            let versions = shard
                .rowid_of(id)
                .and_then(|rowid| shard.versions.get(&rowid));
            match versions {
                Some(versions) => {
                    let visible = visible_version(versions, self.snapshot_tx);
                    // Exact state this read observed. Future mutations above
                    // the snapshot are deliberately excluded.
                    let observed =
                        visible
                            .map(|version| version.created_tx.0)
                            .unwrap_or_else(|| {
                                versions
                                    .iter()
                                    .flat_map(|version| {
                                        std::iter::once(version.created_tx.0)
                                            .chain(version.deleted_tx.map(|tx| tx.0))
                                    })
                                    .filter(|version| *version <= self.snapshot_tx.0)
                                    .max()
                                    .unwrap_or_default()
                            });
                    let stored = visible.map(|version| Arc::clone(&version.record));
                    let record = stored
                        .as_deref()
                        .map(StoredRecord::to_record)
                        .transpose()?
                        .map(Arc::new);
                    (record, observed, stored)
                }
                None if state.paged_lazy => {
                    drop(shard);
                    let record = match (&self.paged_snapshot, &db.paged_records) {
                        (Some(snapshot), Some(paged)) => {
                            paged.get(snapshot, collection, id)?.map(Arc::new)
                        }
                        _ => None,
                    };
                    // An untouched paged baseline predates core commit
                    // sequences; its first resident mutation conflicts with 0.
                    (record, 0, None)
                }
                None => (None, 0, None),
            }
        };
        if let (Some(stored), Some(record)) = (read_stored, record.as_ref()) {
            // Only a fully resident row is worth remembering: an eviction stub
            // is re-fetched from the page store at commit anyway.
            if stored.evicted.is_none() {
                self.read_images
                    .lock()
                    .remember(collection, id, stored, Arc::clone(record));
            }
        }
        {
            let mut observed = self.observed_record_versions.lock();
            // Two-level map so the common re-read allocates nothing; keys are
            // only materialized on the first observation of a row.
            match observed.get_mut(collection) {
                Some(rows) => match rows.get_mut(id) {
                    // Re-reading cannot make an earlier stale read uninfluence
                    // the transaction. Retain the conservative boundary.
                    Some(existing) => *existing = (*existing).min(observed_version),
                    None => {
                        rows.insert(id.to_string(), observed_version);
                    }
                },
                None => {
                    let mut rows = FxHashMap::default();
                    rows.insert(id.to_string(), observed_version);
                    observed.insert(collection.to_string(), rows);
                }
            }
        }
        Ok(self.overlay_pending_write(collection, id, record))
    }

    pub fn record_system_metadata(
        &self,
        collection: &str,
        pk: &str,
    ) -> Result<Option<RecordSystemMetadata>> {
        self.record_system_metadata_batch(collection, &[pk.to_string()])
            .map(|mut metadata| metadata.pop().flatten())
    }

    pub fn record_system_metadata_batch(
        &self,
        collection: &str,
        pks: &[String],
    ) -> Result<Vec<Option<RecordSystemMetadata>>> {
        self.record_system_metadata_batch_with_presence(collection, pks, false)
    }

    /// Batch system metadata for rows the caller has already materialized from
    /// this transaction's snapshot. Existence in the page store is proven, so
    /// the per-row `paged.get` presence probe on lazy collections is skipped —
    /// that probe is a full point lookup per row and dominates row output cost
    /// on paged collections.
    pub fn record_system_metadata_batch_for_materialized(
        &self,
        collection: &str,
        pks: &[String],
    ) -> Result<Vec<Option<RecordSystemMetadata>>> {
        self.record_system_metadata_batch_with_presence(collection, pks, true)
    }

    fn record_system_metadata_batch_with_presence(
        &self,
        collection: &str,
        pks: &[String],
        rows_materialized: bool,
    ) -> Result<Vec<Option<RecordSystemMetadata>>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let pending: FxHashMap<&str, &TxWrite> = self
            .pending_writes_for_collection(collection)
            .map(|write| (write.record_id.as_str(), write))
            .collect();
        let state = db.collection_state(collection)?;
        let mut result = Vec::with_capacity(pks.len());
        for pk in pks {
            let shard = state.shard(pk).read();
            let rowid = shard.rowid_of(pk);
            let metadata = if let Some(write) = pending.get(pk.as_str()) {
                match write.op {
                    TxWriteOp::Delete => None,
                    TxWriteOp::Upsert => {
                        let rowid = rowid.unwrap_or_else(|| RowId::provisional(pk));
                        let (tid_block, tid_offset) = postgres_tid_at_epoch(rowid, self.id.0);
                        Some(RecordSystemMetadata {
                            xmin: self.id,
                            xmax: None,
                            tid_block,
                            tid_offset,
                        })
                    }
                }
            } else if state.paged_lazy
                && rowid
                    .map(|rowid| !shard.versions.contains_key(&rowid))
                    .unwrap_or(true)
            {
                // Untouched row of a lazy collection: existence comes from the
                // page store; system columns take baseline values, matching
                // what a materialized bootstrap would have stamped. When the
                // caller materialized the row from this snapshot, existence is
                // already proven and the per-row point lookup is skipped.
                drop(shard);
                match (&self.paged_snapshot, &db.paged_records) {
                    (Some(snapshot), Some(paged))
                        if rows_materialized || paged.get(snapshot, collection, pk)?.is_some() =>
                    {
                        let rowid = RowId::provisional(pk);
                        let (tid_block, tid_offset) =
                            postgres_tid_at_epoch(rowid, self.snapshot_tx.0);
                        Some(RecordSystemMetadata {
                            xmin: TransactionId(0),
                            xmax: None,
                            tid_block,
                            tid_offset,
                        })
                    }
                    _ => None,
                }
            } else {
                rowid
                    .and_then(|rowid| shard.versions.get(&rowid).map(|versions| (rowid, versions)))
                    .and_then(|(rowid, versions)| {
                        visible_version(versions, self.snapshot_tx).map(|version| {
                            let (tid_block, tid_offset) =
                                postgres_tid_at_epoch(rowid, self.snapshot_tx.0);
                            RecordSystemMetadata {
                                xmin: version.created_tx,
                                xmax: version.deleted_tx,
                                tid_block,
                                tid_offset,
                            }
                        })
                    })
            };
            result.push(metadata);
        }
        Ok(result)
    }

    /// Registry-mode fallback for a rowid-addressed transactional read: rowid
    /// -> pk (reverse registry) -> page store at this transaction's paged
    /// snapshot. `None` unless the collection is lazy-paged and the rowid has
    /// no chain (a chain is authoritative, including "invisible").
    fn registry_stored_by_rowid(
        &self,
        state: &CollectionState,
        collection: &str,
        rowid: RowId,
    ) -> Result<Option<Arc<StoredRecord>>> {
        if !state.paged_lazy {
            return Ok(None);
        }
        let db = self.db_ref();
        let pk = {
            let shard = state.shard_by_rowid(rowid).read();
            if shard.versions.contains_key(&rowid) {
                return Ok(None);
            }
            shard.rowid_to_pk.get(&rowid).cloned()
        };
        let (Some(pk), Some(snapshot), Some(paged)) = (pk, &self.paged_snapshot, &db.paged_records)
        else {
            return Ok(None);
        };
        match paged.get(snapshot, collection, &pk)? {
            Some(record) => Ok(Some(Arc::new(StoredRecord::from_record(&record)?))),
            None => Ok(None),
        }
    }
    /// Snapshot-visible record for a physical [`RowId`] (an index payload), with the
    /// transaction's own pending writes overlaid — the rowid-addressed analog of
    /// [`Self::get`]. O(1) to the shard, no String hashing/cloning when the
    /// transaction has no buffered writes for `collection` (the common read case);
    /// only then is the primary key consulted to overlay a pending write.
    pub fn get_by_rowid(&self, collection: &str, rowid: RowId) -> Result<Option<Arc<Record>>> {
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        db.ensure_collection(collection)?;
        let has_pending = self.has_pending_writes(collection);
        let state = db.collection_state(collection)?;
        let shard = state.shard_by_rowid(rowid).read();
        let version = shard
            .versions
            .get(&rowid)
            .and_then(|versions| visible_version(versions, self.snapshot_tx))
            .cloned();
        let version = match version {
            Some(version) => version,
            None => {
                drop(shard);
                let Some(stored) = self.registry_stored_by_rowid(&state, collection, rowid)? else {
                    return Ok(None);
                };
                let record = Arc::new(stored.to_record()?);
                if !has_pending {
                    return Ok(Some(record));
                }
                let pk = stored.id.clone();
                let mut out = Some(record);
                out = self.overlay_pending_write(collection, &pk, out);
                return Ok(out);
            }
        };
        if !has_pending {
            return Ok(Some(Arc::new(version.record.to_record()?)));
        }
        // A buffered write for this collection may overlay this record — resolve its
        // pk to check (only on this cold path).
        let pk = version.record.id.clone();
        let mut record = Some(Arc::new(version.record.to_record()?));
        drop(shard);
        record = self.overlay_pending_write(collection, &pk, record);
        Ok(record)
    }

    /// Snapshot-visible batch twin of [`Self::get_by_rowid`]: one collection read
    /// lock for the whole set, with public `Record` deserialization after release.
    pub fn get_records_by_rowids(
        &self,
        collection: &str,
        rowids: &[RowId],
    ) -> Result<Vec<Option<Arc<Record>>>> {
        self.db_ref()
            .ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.get_records_by_rowids_visible(collection, rowids)
    }

    /// [`Self::get_records_by_rowids`] authorized by a `SecurityContext`
    /// instead of the legacy unprotected-only gate: the context must pass the
    /// collection policy, rows invisible to it are elided, and protected
    /// fields are projected away — matching [`BicDb::get_with_context`].
    pub fn get_records_by_rowids_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        rowids: &[RowId],
    ) -> Result<Vec<Option<Arc<Record>>>> {
        let records = self.get_records_by_rowids_visible(collection, rowids)?;
        self.filter_context_visible(ctx, collection, records)
    }

    /// Rows a `SecurityContext` may see, with protected fields projected away.
    fn filter_context_visible(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        records: Vec<Option<Arc<Record>>>,
    ) -> Result<Vec<Option<Arc<Record>>>> {
        let db = self.db_ref();
        let state = db.collection_state(collection)?;
        let Some(policy) = state.meta.policy.as_ref() else {
            return Ok(records);
        };
        BicDb::authorize_read_without_audit(collection, policy, ctx)?;
        records
            .into_iter()
            .map(|record| {
                let Some(record) = record else {
                    return Ok(None);
                };
                if !BicDb::record_visible_to_policy(policy, ctx, &record)? {
                    return Ok(None);
                }
                Ok(Some(Arc::new(protected_data::project_record(
                    &db.sync_state.node_id.to_string(),
                    &db.path,
                    collection,
                    policy,
                    &ctx.roles,
                    &record,
                    ctx.bypass_policy.is_some(),
                )?)))
            })
            .collect()
    }

    fn get_records_by_rowids_visible(
        &self,
        collection: &str,
        rowids: &[RowId],
    ) -> Result<Vec<Option<Arc<Record>>>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let has_pending = self.has_pending_writes(collection);
        let snapshot = self.snapshot_tx;
        let stored: Vec<Option<Arc<StoredRecord>>> = {
            let state = db.collection_state(collection)?;
            let mut stored = Vec::with_capacity(rowids.len());
            for &rowid in rowids {
                let resident = {
                    let shard = state.shard_by_rowid(rowid).read();
                    shard
                        .versions
                        .get(&rowid)
                        .and_then(|versions| visible_version(versions, snapshot))
                        .map(|version| version.record.clone())
                };
                stored.push(match resident {
                    Some(record) => Some(record),
                    None => self.registry_stored_by_rowid(&state, collection, rowid)?,
                });
            }
            stored
        };
        let mut out = deserialize_stored_batch(stored)?;
        if has_pending {
            for slot in out.iter_mut() {
                let pk = match slot.as_ref() {
                    Some(record) => record.id.clone(),
                    None => continue,
                };
                *slot = self.overlay_pending_write(collection, &pk, slot.take());
            }
        }
        Ok(out)
    }

    /// Snapshot-visible batch rowid fetch of the compact stored records (no
    /// metadata deserialization) for the typed-row read path. Callers must
    /// guarantee the transaction has NO buffered writes for `collection`
    /// (the rowid fast path's eligibility check) — pending writes are NOT
    /// overlaid here.
    pub fn get_stored_by_rowids(
        &self,
        collection: &str,
        rowids: &[RowId],
    ) -> Result<Vec<Option<Arc<StoredRecord>>>> {
        self.db_ref()
            .ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.get_stored_by_rowids_visible(collection, rowids)
    }

    /// [`Self::get_stored_by_rowids`] authorized by a `SecurityContext`: the
    /// context must pass the collection policy and rows invisible to it are
    /// elided. Feeds internal predicate evaluation only — callers re-apply
    /// row policies before any row leaves the engine.
    pub fn get_stored_by_rowids_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        rowids: &[RowId],
    ) -> Result<Vec<Option<Arc<StoredRecord>>>> {
        let stored = self.get_stored_by_rowids_visible(collection, rowids)?;
        let db = self.db_ref();
        let state = db.collection_state(collection)?;
        let Some(policy) = state.meta.policy.as_ref() else {
            return Ok(stored);
        };
        BicDb::authorize_read_without_audit(collection, policy, ctx)?;
        stored
            .into_iter()
            .map(|record| {
                let Some(record) = record else {
                    return Ok(None);
                };
                if !BicDb::record_visible_to_policy(policy, ctx, &record.to_record()?)? {
                    return Ok(None);
                }
                Ok(Some(record))
            })
            .collect()
    }

    fn get_stored_by_rowids_visible(
        &self,
        collection: &str,
        rowids: &[RowId],
    ) -> Result<Vec<Option<Arc<StoredRecord>>>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        debug_assert!(
            !self.has_pending_writes(collection),
            "typed-row stored fetch requires no pending writes for the collection"
        );
        let snapshot = self.snapshot_tx;
        let state = db.collection_state(collection)?;
        let mut out = Vec::with_capacity(rowids.len());
        for &rowid in rowids {
            let resident = {
                let shard = state.shard_by_rowid(rowid).read();
                shard
                    .versions
                    .get(&rowid)
                    .and_then(|versions| visible_version(versions, snapshot))
                    .map(|version| version.record.clone())
            };
            out.push(match resident {
                Some(record) => Some(record),
                None => self.registry_stored_by_rowid(&state, collection, rowid)?,
            });
        }
        Ok(out)
    }

    /// Snapshot-visible primary-key batch fetch. Pending writes are overlaid by
    /// requested pk, matching [`Self::get`] for missing committed-visible versions.
    pub fn get_records_by_pks(
        &self,
        collection: &str,
        pks: &[String],
    ) -> Result<Vec<Option<Arc<Record>>>> {
        self.db_ref()
            .ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.get_records_by_pks_visible(collection, pks)
    }

    /// [`Self::get_records_by_pks`] authorized by a `SecurityContext`; see
    /// [`Self::get_records_by_rowids_with_context`].
    pub fn get_records_by_pks_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
        pks: &[String],
    ) -> Result<Vec<Option<Arc<Record>>>> {
        let records = self.get_records_by_pks_visible(collection, pks)?;
        self.filter_context_visible(ctx, collection, records)
    }

    fn get_records_by_pks_visible(
        &self,
        collection: &str,
        pks: &[String],
    ) -> Result<Vec<Option<Arc<Record>>>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let has_pending = self.has_pending_writes(collection);
        let snapshot = self.snapshot_tx;
        let (stored, lazy_misses): (Vec<Option<Arc<StoredRecord>>>, Vec<usize>) = {
            let state = db.collection_state(collection)?;
            let mut lazy_misses = Vec::new();
            let stored = pks
                .iter()
                .enumerate()
                .map(|(index, pk)| {
                    let shard = state.shard(pk).read();
                    match shard
                        .rowid_of(pk)
                        .and_then(|rowid| shard.versions.get(&rowid))
                    {
                        Some(versions) => visible_version(versions, snapshot)
                            .map(|version| version.record.clone()),
                        None => {
                            // No chain: untouched this session. A registry
                            // rowid without a chain is still untouched.
                            if state.paged_lazy {
                                lazy_misses.push(index);
                            }
                            None
                        }
                    }
                })
                .collect();
            (stored, lazy_misses)
        };
        let mut out = deserialize_stored_batch(stored)?;
        if !lazy_misses.is_empty() {
            if let (Some(snapshot), Some(paged)) = (&self.paged_snapshot, &db.paged_records) {
                for index in lazy_misses {
                    out[index] = paged.get(snapshot, collection, &pks[index])?.map(Arc::new);
                }
            }
        }
        if has_pending {
            for (slot, pk) in out.iter_mut().zip(pks.iter()) {
                *slot = self.overlay_pending_write(collection, pk, slot.take());
            }
        }
        Ok(out)
    }

    pub fn scan_collection(&self, collection: &str) -> Result<Vec<Record>> {
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.scan_collection_visible_unchecked(collection)
    }

    /// Count a resident collection at this transaction's snapshot without
    /// decoding row payloads. The final buffered write for each key is overlaid
    /// just as in `scan_collection`. Lazy paged collections decline explicitly:
    /// their page-store base and resident version chains need a separate merge.
    pub fn try_count_collection_visible_cancellable(
        &self,
        collection: &str,
        cancellation: &CancellationToken,
    ) -> Result<Option<usize>> {
        cancellation.check()?;
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        let state = db.collection_state(collection)?;
        if state.paged_lazy {
            return Ok(None);
        }
        let mut count = 0usize;
        let mut visited = 0usize;
        for shard in state.read_all() {
            for versions in shard.versions.values() {
                if visited % 1024 == 0 {
                    cancellation.check()?;
                }
                visited += 1;
                count += usize::from(visible_version(versions, self.snapshot_tx).is_some());
            }
        }
        for write in self.pending_writes_for_collection(collection) {
            cancellation.check()?;
            let shard = state.shard(&write.record_id).read();
            let was_visible = shard
                .rowid_of(&write.record_id)
                .and_then(|rowid| shard.versions.get(&rowid))
                .and_then(|versions| visible_version(versions, self.snapshot_tx))
                .is_some();
            match write.op {
                TxWriteOp::Upsert if !was_visible && write.record()?.is_some() => count += 1,
                TxWriteOp::Delete if was_visible => count -= 1,
                _ => {}
            }
        }
        cancellation.check()?;
        Ok(Some(count))
    }

    /// Snapshot-visible collection scan with pending writes overlaid but no
    /// policy gate. This is restricted to engine-internal integrity checks
    /// (unique, foreign-key, and exclusion constraints), whose results never
    /// leave the engine. PostgreSQL evaluates those constraints independently
    /// of row-level visibility as well.
    pub fn scan_collection_for_integrity_check(&self, collection: &str) -> Result<Vec<Record>> {
        self.scan_collection_visible_unchecked(collection)
    }

    /// Snapshot-visible collection scan authorized by a [`SecurityContext`].
    /// This is the transaction-aware counterpart of
    /// [`BicDb::scan_collection_with_context`].
    pub fn scan_collection_with_context(
        &self,
        ctx: &SecurityContext,
        collection: &str,
    ) -> Result<Vec<Record>> {
        let records = self
            .scan_collection_visible_unchecked(collection)?
            .into_iter()
            .map(|record| Some(Arc::new(record)))
            .collect();
        Ok(self
            .filter_context_visible(ctx, collection, records)?
            .into_iter()
            .flatten()
            .map(|record| record.as_ref().clone())
            .collect())
    }

    pub fn scan_collection_authorized(&self, collection: &str) -> Result<Vec<Record>> {
        let actor = self.mutation_actor.as_ref().ok_or_else(|| {
            BicDbError::Authorization(
                "authorized scans require an application transaction".to_string(),
            )
        })?;
        let records = self.scan_collection_visible_unchecked(collection)?;
        let db = self.db_ref();
        let state = db.collection_state(collection)?;
        let Some(policy) = state.meta.policy.as_ref() else {
            return Ok(records);
        };
        let context = mutation_security_context(actor)?;
        BicDb::authorize_read_without_audit(collection, policy, &context)?;
        let mut visible = Vec::new();
        for record in records {
            if BicDb::record_visible_to_policy(policy, &context, &record)? {
                visible.push(protected_data::project_record(
                    &db.sync_state.node_id.to_string(),
                    &db.path,
                    collection,
                    policy,
                    &context.roles,
                    &record,
                    false,
                )?);
            }
        }
        Ok(visible)
    }

    /// Acquires invocation-scoped write locks without mutating rows. Locks are
    /// released on commit, rollback, or drop and cannot be obtained by an
    /// ordinary transaction lacking a trusted application actor.
    pub fn lock_rows_authorized(&mut self, collection: &str, ids: &[String]) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let actor = self.mutation_actor.as_ref().ok_or_else(|| {
            BicDbError::Authorization("row locks require an application transaction".to_string())
        })?;
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        if let Some(policy) = db.collection_state(collection)?.meta.policy.as_ref() {
            let context = mutation_security_context(actor)?;
            BicDb::authorize_read_without_audit(collection, policy, &context)?;
        }
        let tx_id = self.id;
        for id in ids {
            if id.is_empty() {
                return Err(BicDbError::EmptyRecordId);
            }
            db.lock_tx_record_for_read_committed_update(tx_id, collection, id, &self.locked_keys)?;
        }
        Ok(())
    }

    /// Executes native BM25 retrieval and then rechecks every hit through the
    /// transaction's actor/RLS snapshot. No protected row bypasses policy just
    /// because its identifier came from an index.
    pub fn full_text_search_authorized(
        &self,
        expected_collection: &str,
        index: &str,
        query: &str,
        limit: usize,
    ) -> Result<Vec<Record>> {
        let db = self.db_ref();
        let collection = db.index_collection(index)?;
        if !collection.eq_ignore_ascii_case(expected_collection) {
            return Err(BicDbError::Authorization(format!(
                "full-text index `{index}` belongs to `{collection}`, not `{expected_collection}`"
            )));
        }
        let terms = query
            .split_whitespace()
            .map(|term| term.to_ascii_lowercase())
            .filter(|term| full_text_term_is_indexable(term))
            .collect::<Vec<_>>();
        if terms.is_empty() || limit == 0 {
            return Ok(Vec::new());
        }
        let term_refs = terms.iter().map(String::as_str).collect::<Vec<_>>();
        let ranked = db.full_text_bm25_top_k(
            index,
            &term_refs,
            crate::fts_scoring::Bm25Parameters::default(),
            limit,
            true,
        )?;
        let hits = match ranked {
            Some(ranked) => ranked
                .into_iter()
                .map(|posting| (posting.primary_key, Some(posting.score)))
                .collect::<Vec<_>>(),
            None => {
                let mut intersection: Option<BTreeSet<String>> = None;
                for term in &terms {
                    let postings = db
                        .lookup_full_text_term(index, term, false)?
                        .into_iter()
                        .collect::<BTreeSet<_>>();
                    intersection = Some(match intersection {
                        Some(current) => current.intersection(&postings).cloned().collect(),
                        None => postings,
                    });
                }
                intersection
                    .unwrap_or_default()
                    .into_iter()
                    .take(limit)
                    .map(|id| (id, None))
                    .collect()
            }
        };
        let mut records = Vec::with_capacity(hits.len());
        for (id, score) in hits {
            if let Some(record) = self.get_authorized(&collection, &id)? {
                let mut record = record.as_ref().clone();
                if let Some(score) = score {
                    if let Some(metadata) = record.metadata.as_object_mut() {
                        metadata.insert("_score".to_string(), Value::from(score));
                    }
                }
                records.push(record);
            }
        }
        Ok(records)
    }

    fn scan_collection_visible_unchecked(&self, collection: &str) -> Result<Vec<Record>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let mut records = BTreeMap::<String, Record>::new();
        let state = db.collection_state(collection)?;
        // Lazy paged collection: the shards hold only rows touched this
        // session, so the base set comes from the page store at this
        // transaction's paged snapshot. Rows that ARE in the shards then
        // override per key below — their chains are authoritative, including
        // the baseline versions seeded on first touch, so a chain verdict of
        // "invisible" genuinely means the row is gone for this snapshot.
        if state.paged_lazy {
            if let (Some(snapshot), Some(paged)) = (&self.paged_snapshot, &db.paged_records) {
                for record in paged.scan(snapshot, collection)? {
                    let record = record?;
                    records.insert(record.id.clone(), record);
                }
            }
        }
        for shard in state.read_all() {
            if state.paged_lazy {
                // Chains override the paged base per key (insert or remove).
                // Iterating the chains — not the pk registry — matters twice
                // over: registry-mode collections register every pk while only
                // touched rows have chains, and only a chain carries a verdict.
                for versions in shard.versions.values() {
                    let Some(pk) = versions.first().map(|version| version.record.id.clone()) else {
                        continue;
                    };
                    match visible_version(versions, self.snapshot_tx) {
                        Some(version) => {
                            records.insert(pk, version.record.to_record()?);
                        }
                        None => {
                            records.remove(&pk);
                        }
                    }
                }
                continue;
            }
            for versions in shard.versions.values() {
                if let Some(version) = visible_version(versions, self.snapshot_tx) {
                    let record = version.record.to_record()?;
                    records.insert(record.id.clone(), record);
                }
            }
        }
        for write in self.pending_writes_for_collection(collection) {
            match write.op {
                TxWriteOp::Upsert => {
                    if let Some(record) = write.record()?.cloned() {
                        records.insert(write.record_id.clone(), record.as_ref().clone());
                    }
                }
                TxWriteOp::Delete => {
                    records.remove(&write.record_id);
                }
            }
        }
        Ok(records.into_values().collect())
    }

    pub fn scan_collection_record_ids_with_prefix(
        &self,
        collection: &str,
        id_prefix: &str,
    ) -> Result<Vec<String>> {
        self.db_ref()
            .ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.scan_collection_record_ids_with_prefix_unchecked(collection, id_prefix)
    }

    /// Prefix id scan with no policy or protection gate; see
    /// [`BicDb::scan_collection_record_ids_with_prefix_unchecked`].
    pub fn scan_collection_record_ids_with_prefix_unchecked(
        &self,
        collection: &str,
        id_prefix: &str,
    ) -> Result<Vec<String>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let state = db.collection_state(collection)?;
        let mut ids = if state.paged_lazy {
            // Base ids from the page store, then per-key chain overrides —
            // same shape as `scan_collection`, for the same reason.
            let mut ids = BTreeSet::new();
            if let (Some(snapshot), Some(paged)) = (&self.paged_snapshot, &db.paged_records) {
                for record in paged.scan(snapshot, collection)? {
                    let record = record?;
                    if record.id.starts_with(id_prefix) {
                        ids.insert(record.id);
                    }
                }
            }
            for shard in state.read_all() {
                for versions in shard.versions.values() {
                    let Some(pk) = versions.first().map(|version| version.record.id.as_str())
                    else {
                        continue;
                    };
                    if !pk.starts_with(id_prefix) {
                        continue;
                    }
                    match visible_version(versions, self.snapshot_tx) {
                        Some(_) => {
                            ids.insert(pk.to_string());
                        }
                        None => {
                            ids.remove(pk);
                        }
                    }
                }
            }
            ids
        } else {
            state
                .read_all()
                .iter()
                .flat_map(|shard| shard.versions.values())
                .filter_map(|versions| {
                    visible_version(versions, self.snapshot_tx)
                        .map(|version| version.record.id.clone())
                })
                .filter(|id| id.starts_with(id_prefix))
                .collect::<BTreeSet<_>>()
        };
        for write in self
            .pending_writes_for_collection(collection)
            .filter(|write| write.record_id.starts_with(id_prefix))
        {
            match write.op {
                TxWriteOp::Upsert => {
                    ids.insert(write.record_id.clone());
                }
                TxWriteOp::Delete => {
                    ids.remove(&write.record_id);
                }
            }
        }
        Ok(ids.into_iter().collect())
    }

    pub fn pending_record_ids_for_collection(&self, collection: &str) -> Vec<String> {
        let mut ids: Vec<String> = self
            .write_index
            .get(collection)
            .map(|rows| rows.keys().cloned().collect())
            .unwrap_or_default();
        ids.sort_unstable();
        ids
    }

    /// True when this transaction has buffered at least one write for
    /// `collection`. One hash probe; never allocates.
    pub fn has_pending_writes(&self, collection: &str) -> bool {
        self.write_index
            .get(collection)
            .is_some_and(|rows| !rows.is_empty())
    }

    /// The last buffered write for `(collection, id)`, if any. Later writes to
    /// the same key supersede earlier ones, so the last one is the overlay.
    pub(crate) fn last_pending_write(&self, collection: &str, id: &str) -> Option<&TxWrite> {
        let idx = *self.write_index.get(collection)?.get(id)?;
        Some(&self.writes[idx])
    }

    /// Applies the transaction's own buffered write for `(collection, id)` on
    /// top of `current` (the snapshot-visible record). Equivalent to replaying
    /// every matching write in order, since only the last one survives.
    /// Snapshot-visible point read in the cheapest form that needs no JSON
    /// parse: the resident `StoredRecord` when the row is committed and
    /// untouched by this transaction, the buffered `Record` when this
    /// transaction has written it. Same visibility, observed-version
    /// bookkeeping and access checks as [`Self::get`].
    pub fn get_stored(&self, collection: &str, id: &str) -> Result<Option<VisibleRow>> {
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        self.get_stored_visible_unchecked(collection, id)
    }

    fn get_stored_visible_unchecked(
        &self,
        collection: &str,
        id: &str,
    ) -> Result<Option<VisibleRow>> {
        let db = self.db_ref();
        db.ensure_collection(collection)?;
        let (row, observed_version) = {
            let state = db.collection_state(collection)?;
            let shard = state.shard(id).read();
            let versions = shard
                .rowid_of(id)
                .and_then(|rowid| shard.versions.get(&rowid));
            match versions {
                Some(versions) => {
                    let visible = visible_version(versions, self.snapshot_tx);
                    let observed =
                        visible
                            .map(|version| version.created_tx.0)
                            .unwrap_or_else(|| {
                                versions
                                    .iter()
                                    .flat_map(|version| {
                                        std::iter::once(version.created_tx.0)
                                            .chain(version.deleted_tx.map(|tx| tx.0))
                                    })
                                    .filter(|version| *version <= self.snapshot_tx.0)
                                    .max()
                                    .unwrap_or_default()
                            });
                    (
                        visible.map(|version| VisibleRow::Stored(Arc::clone(&version.record))),
                        observed,
                    )
                }
                None if state.paged_lazy => {
                    drop(shard);
                    let record = match (&self.paged_snapshot, &db.paged_records) {
                        (Some(snapshot), Some(paged)) => paged
                            .get(snapshot, collection, id)?
                            .map(|record| VisibleRow::Pending(Arc::new(record))),
                        _ => None,
                    };
                    (record, 0)
                }
                None => (None, 0),
            }
        };
        {
            let mut observed = self.observed_record_versions.lock();
            match observed.get_mut(collection) {
                Some(rows) => match rows.get_mut(id) {
                    Some(existing) => *existing = (*existing).min(observed_version),
                    None => {
                        rows.insert(id.to_string(), observed_version);
                    }
                },
                None => {
                    let mut rows = FxHashMap::default();
                    rows.insert(id.to_string(), observed_version);
                    observed.insert(collection.to_string(), rows);
                }
            }
        }
        Ok(match self.last_pending_write(collection, id) {
            None => row,
            Some(write) => match write.op {
                TxWriteOp::Upsert => write.pending_visible_row(),
                TxWriteOp::Delete => None,
            },
        })
    }

    /// Batch form of [`Self::get_stored`] by primary key; pending writes are
    /// overlaid per requested key exactly as [`Self::get_records_by_pks`] does.
    pub fn get_stored_by_pks(
        &self,
        collection: &str,
        pks: &[String],
    ) -> Result<Vec<Option<VisibleRow>>> {
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Read)?;
        db.ensure_collection(collection)?;
        let has_pending = self.has_pending_writes(collection);
        let snapshot = self.snapshot_tx;
        let mut observed_versions = Vec::with_capacity(pks.len());
        let mut out: Vec<Option<VisibleRow>> = {
            let state = db.collection_state(collection)?;
            let mut out = Vec::with_capacity(pks.len());
            for pk in pks {
                let shard = state.shard(pk).read();
                let (row, observed_version) = match shard
                    .rowid_of(pk)
                    .and_then(|rowid| shard.versions.get(&rowid))
                {
                    Some(versions) => {
                        let visible = visible_version(versions, snapshot);
                        let observed =
                            visible
                                .map(|version| version.created_tx.0)
                                .unwrap_or_else(|| {
                                    versions
                                        .iter()
                                        .flat_map(|version| {
                                            std::iter::once(version.created_tx.0)
                                                .chain(version.deleted_tx.map(|tx| tx.0))
                                        })
                                        .filter(|version| *version <= snapshot.0)
                                        .max()
                                        .unwrap_or_default()
                                });
                        (
                            visible.map(|version| VisibleRow::Stored(Arc::clone(&version.record))),
                            observed,
                        )
                    }
                    None => {
                        drop(shard);
                        let row = if state.paged_lazy {
                            match (&self.paged_snapshot, &db.paged_records) {
                                (Some(snapshot), Some(paged)) => paged
                                    .get(snapshot, collection, pk)?
                                    .map(|record| VisibleRow::Pending(Arc::new(record))),
                                _ => None,
                            }
                        } else {
                            None
                        };
                        (row, 0)
                    }
                };
                out.push(row);
                observed_versions.push(observed_version);
            }
            out
        };
        // Match single-point reads: the session's read-your-writes floor can
        // cover commits that had not applied when this batch read the row.
        // Record the actual observed versions, not that potentially newer
        // floor. One guard covers the batch, after releasing collection/shard
        // guards; rereads retain the earliest observation.
        if !pks.is_empty() {
            let mut observed = self.observed_record_versions.lock();
            if !observed.contains_key(collection) {
                observed.insert(collection.to_string(), FxHashMap::default());
            }
            let rows = observed.get_mut(collection).expect("inserted collection");
            for (pk, version) in pks.iter().zip(observed_versions) {
                match rows.get_mut(pk.as_str()) {
                    Some(existing) => *existing = (*existing).min(version),
                    None => {
                        rows.insert(pk.clone(), version);
                    }
                }
            }
        }
        if has_pending {
            for (slot, pk) in out.iter_mut().zip(pks.iter()) {
                if let Some(write) = self.last_pending_write(collection, pk) {
                    *slot = match write.op {
                        TxWriteOp::Upsert => write.pending_visible_row(),
                        TxWriteOp::Delete => None,
                    };
                }
            }
        }
        Ok(out)
    }

    pub fn overlay_pending_write(
        &self,
        collection: &str,
        id: &str,
        current: Option<Arc<Record>>,
    ) -> Option<Arc<Record>> {
        match self.last_pending_write(collection, id) {
            None => current,
            Some(write) => match write.op {
                TxWriteOp::Upsert => write.record_opt().cloned(),
                TxWriteOp::Delete => None,
            },
        }
    }

    /// The effective (last) buffered write per record id for `collection`, in
    /// no particular order. Consumers that fold upserts/deletes into a map get
    /// the same final state as replaying the whole log in order.
    pub(crate) fn pending_writes_for_collection<'a>(
        &'a self,
        collection: &str,
    ) -> impl Iterator<Item = &'a TxWrite> + 'a {
        self.write_index
            .get(collection)
            .into_iter()
            .flat_map(move |rows| rows.values().map(move |&idx| &self.writes[idx]))
    }

    /// Appends buffered writes and indexes them. The only sanctioned way to
    /// grow `writes`.
    fn push_writes(&mut self, writes: Vec<TxWrite>) {
        if !writes.is_empty() && !self.prepared_wal.is_empty() {
            self.prepared_wal.clear();
        }
        let start = self.writes.len();
        self.writes.extend(writes);
        {
            let images = self.read_images.lock();
            if images.len > 0 {
                for write in &mut self.writes[start..] {
                    if write.op == TxWriteOp::Upsert && write.previous.is_none() {
                        write.previous = images.get(&write.collection, &write.record_id);
                    }
                }
            }
        }
        for idx in start..self.writes.len() {
            let write = &self.writes[idx];
            match self.write_index.get_mut(write.collection.as_str()) {
                Some(rows) => {
                    rows.insert(write.record_id.clone(), idx);
                }
                None => {
                    let mut rows = FxHashMap::default();
                    rows.insert(write.record_id.clone(), idx);
                    self.write_index.insert(write.collection.clone(), rows);
                }
            }
        }
    }

    /// Rebuilds the write index after `writes` was truncated (savepoint
    /// rollback). Rare path; O(writes).
    fn rebuild_write_index(&mut self) {
        // Savepoint rollback can replace a prepared write with a different
        // write while keeping the same count. A matching payload count is not
        // a valid cache identity; invalidate when the write set changes.
        if !self.prepared_wal.is_empty() {
            self.prepared_wal.clear();
        }
        self.write_index.clear();
        for (idx, write) in self.writes.iter().enumerate() {
            self.write_index
                .entry(write.collection.clone())
                .or_default()
                .insert(write.record_id.clone(), idx);
        }
    }

    pub fn insert(&mut self, collection: &str, record: Record) -> Result<()> {
        self.write_upsert(collection, record)
    }

    pub fn batch_insert<I>(&mut self, collection: &str, records: I) -> Result<()>
    where
        I: IntoIterator<Item = Record>,
    {
        let records = records.into_iter().collect::<Vec<_>>();
        if records.is_empty() {
            return Ok(());
        }
        self.write_upserts(collection, records)
    }

    pub fn update(&mut self, collection: &str, record: Record) -> Result<()> {
        self.write_upsert(collection, record)
    }

    pub fn delete(&mut self, collection: &str, id: &str) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        self.delete_many(collection, std::iter::once(id))
    }

    fn conflict_snapshot_for_write(
        &self,
        collection: &str,
        record_id: &str,
        explicit_statement_snapshot: u64,
    ) -> u64 {
        if explicit_statement_snapshot != 0 {
            return explicit_statement_snapshot;
        }
        self.observed_record_versions
            .lock()
            .get(collection)
            .and_then(|rows| rows.get(record_id))
            .copied()
            // Blind writes retain the established snapshot-isolation boundary.
            // The raised floor is legitimate read-your-writes authority for
            // that operation. Only a point read proves that the row itself was
            // observed below the floor and must take the conservative branch.
            .unwrap_or(self.snapshot_tx.0)
    }

    pub fn delete_many<I, S>(&mut self, collection: &str, ids: I) -> Result<()>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        self.delete_many_with_statement_snapshots(collection, ids.into_iter().map(|id| (id, 0)))
    }

    pub fn delete_many_with_statement_snapshots<I, S>(
        &mut self,
        collection: &str,
        ids: I,
    ) -> Result<()>
    where
        I: IntoIterator<Item = (S, u64)>,
        S: AsRef<str>,
    {
        self.delete_many_with_statement_snapshots_inner(collection, ids, true)
    }

    fn delete_many_unchecked<I, S>(&mut self, collection: &str, ids: I) -> Result<()>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        self.delete_many_with_statement_snapshots_inner(
            collection,
            ids.into_iter().map(|id| (id, 0)),
            false,
        )
    }

    fn delete_many_with_statement_snapshots_inner<I, S>(
        &mut self,
        collection: &str,
        ids: I,
        enforce_legacy_access: bool,
    ) -> Result<()>
    where
        I: IntoIterator<Item = (S, u64)>,
        S: AsRef<str>,
    {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let ids = ids
            .into_iter()
            .map(|(id, statement_snapshot)| (id.as_ref().to_string(), statement_snapshot))
            .collect::<Vec<_>>();
        if ids.is_empty() {
            return Ok(());
        }
        let tx_id = self.id;
        let timestamp = unix_timestamp();
        let mut writes = Vec::with_capacity(ids.len());
        let db = self.db_ref();
        if enforce_legacy_access {
            db.ensure_unprotected_legacy_access(collection, SecureOperation::Delete)?;
        }
        db.ensure_collection(collection)?;
        for (id, statement_snapshot) in ids {
            if id.is_empty() {
                return Err(BicDbError::EmptyRecordId);
            }
            db.lock_tx_record(tx_id, collection, &id, &self.locked_keys)?;
            let statement_snapshot =
                self.conflict_snapshot_for_write(collection, &id, statement_snapshot);
            writes.push(TxWrite {
                collection: collection.to_string(),
                op: TxWriteOp::Delete,
                record_id: id,
                record: OnceLock::from(None),
                timestamp,
                statement_snapshot,
                repair: None,
                stored: None,
                previous: None,
                previous_stored: None,
                changed: None,
            });
        }
        self.push_writes(writes);
        Ok(())
    }

    pub fn commit(mut self) -> Result<()> {
        let db = self.db;
        // Safety: see db_mut; this avoids holding a borrow through `self`.
        let commit_seq = unsafe { db.as_ref() }.commit_transaction(&mut self)?;
        // Direct (single-owner) commits are durable on return: write inline. The
        // pgwire path instead defers this to decoupled group commit after
        // releasing the database write lock.
        unsafe { db.as_ref() }.tx_log.write_durable(commit_seq)?;
        self.finalize_commit_admission()?;
        self.finalize_committed_broker_outbox();
        self.finalize_committed_memory_jobs()
    }

    /// Checkpoint the range command as locally applied only after the caller's
    /// ordinary WAL durability boundary has completed.
    pub fn finalize_commit_admission(&mut self) -> Result<()> {
        self.finalize_committed_record_audit_events()?;
        if let Some((admission, ticket)) = self.commit_admission_ticket.as_ref() {
            let commit_seq = self.committed_seq.ok_or_else(|| {
                BicDbError::HighAvailability(
                    "admitted commit has no durable local sequence".to_string(),
                )
            })?;
            admission.local_applied(ticket, commit_seq)?;
            self.commit_admission_ticket = None;
        }
        Ok(())
    }

    /// Publish record-audit entries only after the transaction WAL is durable.
    /// Event ids make retries idempotent, and recovery republishes committed
    /// entries that were still pending when a process died.
    fn finalize_committed_record_audit_events(&mut self) -> Result<()> {
        if self.state != TxState::Committed {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.pending_record_audit_events.is_empty() {
            return Ok(());
        }
        let db = unsafe { self.db.as_ref() };
        let mut events = db.events.lock();
        for event in &self.pending_record_audit_events {
            events.append(event.clone())?;
        }
        drop(events);
        db.persist_record_audit_publication(self.id)?;
        self.pending_record_audit_events.clear();
        Ok(())
    }

    pub fn rollback(mut self) -> Result<()> {
        let mut db = self.db;
        // Safety: see db_mut; this avoids holding a borrow through `self`.
        unsafe { db.as_mut() }.rollback_transaction(&mut self)
    }

    pub fn write_len(&self) -> usize {
        self.writes.len()
    }

    pub fn finalize_committed_memory_jobs(&self) -> Result<()> {
        if self.state != TxState::Committed {
            return Err(memory_error(
                "memory jobs can only be finalized after a transaction commits",
            ));
        }
        if !self.enqueue_memory_jobs_on_commit {
            return Ok(());
        }
        // Safety: the transaction stores the database pointer it was created
        // from. This mirrors commit/rollback and only uses shared database APIs.
        unsafe { self.db.as_ref() }.finalize_memory_jobs_for_committed_transaction(self)
    }

    /// Appends the transaction's durable outbox messages after its commit WAL
    /// is durable. A failed append remains represented in the transaction WAL
    /// and is retried during recovery; callers must never publish before the
    /// corresponding `write_durable` succeeds.
    pub fn finalize_committed_broker_outbox(&self) {
        if self.state != TxState::Committed {
            return;
        }
        let publishes = self.pending_broker_publishes.lock().clone();
        if publishes.is_empty() {
            return;
        }
        let db = unsafe { self.db.as_ref() };
        let mut events = db.events.lock();
        let mut broker = events.broker();
        for pending in &publishes {
            if let Err(error) = broker.publish_prepared(pending) {
                eprintln!(
                    "bicdb: committed broker outbox message {} retained for recovery retry: {error}",
                    pending.message_id
                );
            }
        }
    }

    fn disable_memory_jobs_on_commit(&mut self) {
        self.enqueue_memory_jobs_on_commit = false;
    }

    fn memory_upserts_by_collection(&self) -> BTreeMap<String, Vec<Record>> {
        let mut by_collection = BTreeMap::<String, BTreeMap<String, Record>>::new();
        for write in &self.writes {
            if write.op != TxWriteOp::Upsert {
                continue;
            }
            let Some(record) = write.record_opt() else {
                continue;
            };
            by_collection
                .entry(write.collection.clone())
                .or_default()
                .insert(write.record_id.clone(), record.as_ref().clone());
        }
        by_collection
            .into_iter()
            .map(|(collection, records)| (collection, records.into_values().collect()))
            .collect()
    }

    /// Buffers a broker publish to run when this transaction commits (and to
    /// vanish with it on rollback). Returns the pre-allocated message id the
    /// publish will use. Name/option validation happens here so the caller
    /// fails fast; idempotency-key deduplication happens at commit time.
    pub fn buffer_broker_publish(
        &self,
        queue: &str,
        payload: serde_json::Value,
        options: crate::broker::PublishOptions,
    ) -> Result<Uuid> {
        crate::broker::validate_broker_name("queue", queue)?;
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let message_id = Uuid::new_v4();
        self.pending_broker_publishes
            .lock()
            .push(crate::broker::PendingBrokerPublish {
                queue: queue.to_string(),
                payload,
                options,
                message_id,
            });
        Ok(message_id)
    }

    /// Capture a rollback boundary. The caller must serialize operations on
    /// this transaction while creating and restoring its marks.
    pub fn rollback_mark(&self) -> TransactionRollbackMark {
        TransactionRollbackMark {
            transaction_id: self.id,
            write_len: self.write_len(),
            lock_len: self.lock_len(),
            broker_publish_len: self.broker_publish_len(),
            deferred_hook_len: self.deferred_hooks.len(),
        }
    }

    /// Restore a mark captured from this transaction. Database/schema changes
    /// maintained outside the transaction still need their own undo handling.
    pub fn rollback_to_mark(&mut self, mark: TransactionRollbackMark) -> Result<()> {
        if mark.transaction_id != self.id {
            return Err(BicDbError::TransactionConflict(
                "rollback mark belongs to a different transaction".into(),
            ));
        }
        self.truncate_writes_and_locks(mark.write_len, mark.lock_len)?;
        self.truncate_broker_publishes(mark.broker_publish_len);
        self.deferred_hooks.truncate(mark.deferred_hook_len);
        Ok(())
    }

    /// Release only read locks acquired after a rollback mark. This is useful
    /// when a joined locking-read candidate must be skipped. Earlier locks and
    /// all buffered writes/effects remain intact. Refuse a suffix containing a
    /// buffered write: dropping its lock could violate transaction integrity.
    /// The caller must serialize transaction operations while using the mark.
    pub fn release_read_locks_since(&self, mark: TransactionRollbackMark) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if mark.transaction_id != self.id {
            return Err(BicDbError::TransactionConflict(
                "read-lock mark belongs to a different transaction".into(),
            ));
        }
        let released = {
            let mut locked = self.locked_keys.lock();
            if mark.lock_len > locked.len() {
                return Err(BicDbError::TransactionConflict(
                    "read-lock mark is no longer valid".into(),
                ));
            }
            if locked.order[mark.lock_len..]
                .iter()
                .any(|(collection, id)| self.last_pending_write(collection, id).is_some())
            {
                return Err(BicDbError::TransactionConflict(
                    "cannot release locks protecting buffered writes".into(),
                ));
            }
            locked.split_off(mark.lock_len)
        };
        release_owned_write_locks(&self.write_locks, self.id, &released);
        Ok(())
    }

    /// Number of buffered publish-on-commit messages (savepoint bookkeeping).
    pub fn broker_publish_len(&self) -> usize {
        self.pending_broker_publishes.lock().len()
    }

    /// Drops buffered publishes past `len` (rollback-to-savepoint).
    pub fn truncate_broker_publishes(&self, len: usize) {
        let mut pending = self.pending_broker_publishes.lock();
        if len < pending.len() {
            pending.truncate(len);
        }
    }

    /// Number of distinct row locks acquired by this transaction. Savepoints
    /// capture this alongside `write_len`: a statement can lock a row before
    /// type/constraint validation has produced a buffered write.
    pub fn lock_len(&self) -> usize {
        self.locked_keys.lock().len()
    }

    pub fn truncate_writes(&mut self, len: usize) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if len < self.writes.len() {
            self.writes.truncate(len);
            self.rebuild_write_index();
        }
        let retained = self
            .writes
            .iter()
            .map(|write| (write.collection.clone(), write.record_id.clone()))
            .collect::<FxHashSet<_>>();
        let released = self
            .locked_keys
            .get_mut()
            .extract(|key| !retained.contains(key));
        release_owned_write_locks(&self.write_locks, self.id, &released);
        Ok(())
    }

    /// Restore both buffered writes and acquired row locks to a savepoint.
    /// Lock order is duplicate-free, so releasing the suffix cannot discard a
    /// lock that was already held when the savepoint was created.
    pub fn truncate_writes_and_locks(&mut self, write_len: usize, lock_len: usize) -> Result<()> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if write_len < self.writes.len() {
            self.writes.truncate(write_len);
            self.rebuild_write_index();
        }
        let released = {
            let locked = self.locked_keys.get_mut();
            locked.split_off(lock_len)
        };
        release_owned_write_locks(&self.write_locks, self.id, &released);
        Ok(())
    }

    fn write_upsert(&mut self, collection: &str, record: Record) -> Result<()> {
        self.write_upserts(collection, vec![record])
    }

    fn write_upserts(&mut self, collection: &str, records: Vec<Record>) -> Result<()> {
        self.write_upserts_with_statement_snapshots(
            collection,
            records.into_iter().map(|record| (record, 0)),
        )
    }

    fn write_upserts_unchecked(&mut self, collection: &str, records: Vec<Record>) -> Result<()> {
        self.write_upserts_with_statement_snapshots_inner(
            collection,
            records.into_iter().map(|record| (record, 0)),
            false,
        )
    }

    pub fn write_upserts_with_statement_snapshots<I>(
        &mut self,
        collection: &str,
        records: I,
    ) -> Result<()>
    where
        I: IntoIterator<Item = (Record, u64)>,
    {
        self.write_upserts_with_statement_snapshots_inner(collection, records, true)
    }

    fn write_upserts_with_statement_snapshots_inner<I>(
        &mut self,
        collection: &str,
        records: I,
        enforce_legacy_access: bool,
    ) -> Result<()>
    where
        I: IntoIterator<Item = (Record, u64)>,
    {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let records = records.into_iter().collect::<Vec<_>>();
        if records.is_empty() {
            return Ok(());
        }
        let tx_id = self.id;
        let timestamp = unix_timestamp();
        let mut writes = Vec::with_capacity(records.len());
        {
            // Buffering only reads the shared BicDb (existence checks, vector
            // dims) and takes per-record write locks via interior mutability, so
            // it runs through a shared &BicDb and can execute concurrently.
            let db = self.db_ref();
            if enforce_legacy_access {
                db.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?;
            }
            db.ensure_collection(collection)?;
            let (mut next_dim, policy) = {
                let state = db.collection_state(collection)?;
                (state.meta.vector_dim, state.meta.policy.clone())
            };
            for (mut record, statement_snapshot) in records {
                // Field encryption, blind indexes, and fail-closed key checks
                // for policied collections. The pre-MVCC write path ran this in
                // prepare_mutations; the transactional path must too, or secure
                // inserts silently store protected data plaintext.
                if let Some(policy) = policy.as_ref() {
                    protected_data::prepare_record(
                        &db.sync_state.node_id.to_string(),
                        collection,
                        policy,
                        &mut record,
                    )?;
                }
                let record_id = record.id.clone();
                validate_record(collection, &record, &mut next_dim)?;
                db.lock_tx_record(tx_id, collection, &record_id, &self.locked_keys)?;
                let statement_snapshot =
                    self.conflict_snapshot_for_write(collection, &record_id, statement_snapshot);
                writes.push(TxWrite {
                    collection: collection.to_string(),
                    op: TxWriteOp::Upsert,
                    record_id,
                    record: OnceLock::from(Some(record.into())),
                    timestamp,
                    statement_snapshot,
                    repair: None,
                    stored: None,
                    previous: None,
                    previous_stored: None,
                    changed: None,
                });
            }
        }
        self.push_writes(writes);
        Ok(())
    }

    /// Buffer upserts already in their resident form. The SQL layer builds a
    /// row's new stored form directly (an UPDATE splices the assigned columns
    /// into the old row's JSON text); buffering it here means the commit
    /// never parses a `Value` tree for it: the WAL frame carries the stored
    /// bytes, the resident row is this very `Arc`, and the index keys come
    /// from its cells. Collections with a protection policy (field
    /// encryption, blind indexes) need the parsed record and take the record
    /// path. `statement_snapshot` as in
    /// [`Self::write_upserts_with_statement_snapshots`].
    pub fn write_stored_upserts_with_statement_snapshots<I>(
        &mut self,
        collection: &str,
        rows: I,
    ) -> Result<()>
    where
        I: IntoIterator<Item = (Arc<StoredRecord>, u64)>,
    {
        self.write_stored_upserts_with_repairs(
            collection,
            rows.into_iter()
                .map(|(stored, snapshot)| (stored, snapshot, None)),
        )
    }

    /// Buffer rows that SQL has already proven are new primary-key inserts.
    ///
    /// Unlike an upsert, an insert does not need to hold an uncontended row
    /// lock until commit. The caller's absence check supplies the conflict
    /// snapshot. Commit conflict detection rejects a key committed since that
    /// snapshot, while atomic unique-key claims arbitrate the simultaneous
    /// validation race before WAL or resident state is changed. This removes
    /// two lock-table entries (and their owned key copies) from every inserted
    /// row while preserving a clean pre-WAL conflict outcome.
    pub fn write_stored_inserts_with_statement_snapshots<I>(
        &mut self,
        collection: &str,
        rows: I,
    ) -> Result<()>
    where
        I: IntoIterator<Item = (Arc<StoredRecord>, u64)>,
    {
        self.write_stored_updates_with_changes_inner(
            collection,
            rows.into_iter()
                .map(|(stored, snapshot)| (None, stored, snapshot, None, None)),
            true,
        )
    }

    /// [`Self::write_stored_upserts_with_statement_snapshots`] with an optional
    /// commit-time [`RepairPlan`] per row (see
    /// [`Self::write_upserts_with_repairs`]): a repairing write skips the
    /// statement-time row lock, and a conflict at commit rebuilds the row from
    /// its parsed form on top of the latest committed version.
    pub fn write_stored_upserts_with_repairs<I>(&mut self, collection: &str, rows: I) -> Result<()>
    where
        I: IntoIterator<Item = (Arc<StoredRecord>, u64, Option<RepairPlan>)>,
    {
        self.write_stored_upserts_with_changes(
            collection,
            rows.into_iter()
                .map(|(stored, snapshot, repair)| (stored, snapshot, repair, None)),
        )
    }

    /// [`Self::write_stored_upserts_with_repairs`] where each row also names
    /// the top-level keys the writer changed against the row's pre-image
    /// (`None` = unknown). The set must be exact or a superset of the keys
    /// whose values differ; commit skips index maintenance for indexes whose
    /// fields lie outside it.
    pub fn write_stored_upserts_with_changes<I>(&mut self, collection: &str, rows: I) -> Result<()>
    where
        I: IntoIterator<
            Item = (
                Arc<StoredRecord>,
                u64,
                Option<RepairPlan>,
                Option<Arc<[Box<str>]>>,
            ),
        >,
    {
        self.write_stored_updates_with_changes(
            collection,
            rows.into_iter().map(|(stored, snapshot, repair, changed)| {
                (None, stored, snapshot, repair, changed)
            }),
        )
    }

    /// Stored-form UPDATE sibling of [`Self::write_stored_upserts_with_changes`]
    /// that also carries the exact compact pre-image. Supplying it lets the WAL
    /// encode old/new changed cells without re-fetching or parsing the row.
    pub fn write_stored_updates_with_changes<I>(&mut self, collection: &str, rows: I) -> Result<()>
    where
        I: IntoIterator<
            Item = (
                Option<Arc<StoredRecord>>,
                Arc<StoredRecord>,
                u64,
                Option<RepairPlan>,
                Option<Arc<[Box<str>]>>,
            ),
        >,
    {
        self.write_stored_updates_with_changes_inner(collection, rows, false)
    }

    fn write_stored_updates_with_changes_inner<I>(
        &mut self,
        collection: &str,
        rows: I,
        optimistic_inserts: bool,
    ) -> Result<()>
    where
        I: IntoIterator<
            Item = (
                Option<Arc<StoredRecord>>,
                Arc<StoredRecord>,
                u64,
                Option<RepairPlan>,
                Option<Arc<[Box<str>]>>,
            ),
        >,
    {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let rows = rows.into_iter().collect::<Vec<_>>();
        if rows.is_empty() {
            return Ok(());
        }
        let tx_id = self.id;
        let timestamp = unix_timestamp();
        let mut writes = Vec::with_capacity(rows.len());
        {
            let db = self.db_ref();
            db.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?;
            db.ensure_collection(collection)?;
            let (mut next_dim, policy) = {
                let state = db.collection_state(collection)?;
                (state.meta.vector_dim, state.meta.policy.clone())
            };
            if policy.is_some() {
                drop(db);
                let records = rows
                    .into_iter()
                    .map(|(_, stored, snapshot, repair, _)| {
                        Ok((stored.to_record()?, snapshot, repair))
                    })
                    .collect::<Result<Vec<_>>>()?;
                return self.write_upserts_with_repairs(collection, records);
            }
            for (previous_stored, stored, statement_snapshot, repair, changed) in rows {
                let record_id = stored.id.clone();
                validate_record_parts(
                    collection,
                    &stored.id,
                    stored.vector.as_deref(),
                    &mut next_dim,
                )?;
                if repair.is_none() && !optimistic_inserts {
                    db.lock_tx_record(tx_id, collection, &record_id, &self.locked_keys)?;
                }
                let statement_snapshot =
                    self.conflict_snapshot_for_write(collection, &record_id, statement_snapshot);
                writes.push(TxWrite {
                    collection: collection.to_string(),
                    op: TxWriteOp::Upsert,
                    record_id,
                    record: OnceLock::new(),
                    timestamp,
                    statement_snapshot,
                    repair: repair.map(Arc::new),
                    stored: Some(stored),
                    previous: None,
                    previous_stored,
                    changed,
                });
            }
        }
        self.push_writes(writes);
        Ok(())
    }

    /// Like [`Self::write_upserts_with_statement_snapshots`], but writes that
    /// carry a [`RepairPlan`] skip the statement-time row lock entirely: their
    /// conflict window is deferred to the commit section, where
    /// `repair_conflicting_delta_writes` takes the lock for microseconds and
    /// rebuilds the record on top of the latest committed version.
    pub fn write_upserts_with_repairs<I>(&mut self, collection: &str, records: I) -> Result<()>
    where
        I: IntoIterator<Item = (Record, u64, Option<RepairPlan>)>,
    {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        let records = records.into_iter().collect::<Vec<_>>();
        if records.is_empty() {
            return Ok(());
        }
        let tx_id = self.id;
        let timestamp = unix_timestamp();
        let mut writes = Vec::with_capacity(records.len());
        {
            let db = self.db_ref();
            db.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?;
            db.ensure_collection(collection)?;
            let mut next_dim = db.collection_state(collection)?.meta.vector_dim;
            for (record, statement_snapshot, repair) in records {
                let record_id = record.id.clone();
                validate_record(collection, &record, &mut next_dim)?;
                if repair.is_none() {
                    db.lock_tx_record(tx_id, collection, &record_id, &self.locked_keys)?;
                }
                let statement_snapshot =
                    self.conflict_snapshot_for_write(collection, &record_id, statement_snapshot);
                writes.push(TxWrite {
                    collection: collection.to_string(),
                    op: TxWriteOp::Upsert,
                    record_id,
                    record: OnceLock::from(Some(record.into())),
                    timestamp,
                    statement_snapshot,
                    repair: repair.map(Arc::new),
                    stored: None,
                    previous: None,
                    previous_stored: None,
                    changed: None,
                });
            }
        }
        self.push_writes(writes);
        Ok(())
    }

    pub fn read_committed_update_record(
        &mut self,
        collection: &str,
        id: &str,
    ) -> Result<Option<(Option<Record>, u64)>> {
        self.read_committed_mutation_record(collection, id, MutationOperation::Update, None)
    }

    /// Grant-aware sibling of [`Self::read_committed_update_record`] used by
    /// compiler-signed embedded SQL. The grant is validated without consuming
    /// its row or statement budget; the eventual mutation still performs the
    /// complete record/column/policy authorization and consumes the budget.
    pub fn read_committed_update_record_with_grant(
        &mut self,
        grant: MutationGrantId,
        collection: &str,
        id: &str,
    ) -> Result<Option<(Option<Record>, u64)>> {
        self.read_committed_mutation_record(collection, id, MutationOperation::Update, Some(grant))
    }

    fn read_committed_mutation_record(
        &mut self,
        collection: &str,
        id: &str,
        operation: MutationOperation,
        grant: Option<MutationGrantId>,
    ) -> Result<Option<(Option<Record>, u64)>> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.last_pending_write(collection, id).is_some() {
            return Ok(None);
        }
        let tx_id = self.id;

        let db = self.db_ref();
        match grant {
            Some(grant) => {
                self.validate_mutation_grant_operation(grant, collection, id, operation)?
            }
            None => db.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?,
        }
        db.ensure_collection(collection)?;
        db.lock_tx_record_for_read_committed_update(tx_id, collection, id, &self.locked_keys)?;
        let state = db.collection_state(collection)?;
        let shard = state.shard(id).read();
        let Some(rowid) = shard.rowid_of(id) else {
            return Ok(Some((None, 0)));
        };
        let max_tx = version_chain_max_tx(&shard.versions, rowid);
        if max_tx <= self.applied_snapshot {
            // Fresh row: everything at or below the un-floored APPLIED
            // watermark was physically applied before this transaction began,
            // so the caller's candidate IS the latest version and the common
            // uncontended case skips re-materialization entirely. The row lock
            // above still pins the record, so `max_tx` cannot advance before
            // this transaction commits or rolls back. Note this deliberately
            // does NOT trust the floored `snapshot_tx`: a commit seq in the
            // (applied, snapshot] gap may not have been applied when the
            // statement read the row, so the candidate could predate it.
            return Ok(None);
        }
        let latest = shard
            .records
            .get(&rowid)
            .map(|entry| entry.record.to_record())
            .transpose()?;
        Ok(Some((latest, max_tx)))
    }

    /// [`Self::read_committed_update_record`] in the stored form: the latest
    /// committed row as its resident `Arc<StoredRecord>` (no parse), or
    /// `Some((None, 0))` when the row is gone; `None` when nothing newer than
    /// this transaction's snapshot exists or the row is already written here.
    pub fn read_committed_update_stored(
        &mut self,
        collection: &str,
        id: &str,
    ) -> Result<Option<(Option<Arc<StoredRecord>>, u64)>> {
        self.read_committed_update_stored_inner(collection, id, false)
    }

    /// Reservation-shaped sibling of [`Self::read_committed_update_stored`].
    /// Its first row lock may wait cycle-free instead of selecting a loser;
    /// subsequent locks retain the ordinary deadlock-prevention policy.
    pub fn read_committed_update_stored_reservation(
        &mut self,
        collection: &str,
        id: &str,
    ) -> Result<Option<(Option<Arc<StoredRecord>>, u64)>> {
        self.read_committed_update_stored_inner(collection, id, true)
    }

    fn read_committed_update_stored_inner(
        &mut self,
        collection: &str,
        id: &str,
        reservation: bool,
    ) -> Result<Option<(Option<Arc<StoredRecord>>, u64)>> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.last_pending_write(collection, id).is_some() {
            return Ok(None);
        }
        let tx_id = self.id;
        let db = self.db_ref();
        db.ensure_unprotected_legacy_access(collection, SecureOperation::Write)?;
        db.ensure_collection(collection)?;
        if reservation {
            db.lock_tx_first_record_for_reservation(tx_id, collection, id, &self.locked_keys)?;
        } else {
            db.lock_tx_record_for_read_committed_update(tx_id, collection, id, &self.locked_keys)?;
        }
        let state = db.collection_state(collection)?;
        let shard = state.shard(id).read();
        let Some(rowid) = shard.rowid_of(id) else {
            return Ok(Some((None, 0)));
        };
        let max_tx = version_chain_max_tx(&shard.versions, rowid);
        if max_tx <= self.applied_snapshot {
            return Ok(None);
        }
        let latest = shard
            .records
            .get(&rowid)
            .map(|entry| Arc::clone(&entry.record));
        Ok(Some((latest, max_tx)))
    }

    pub fn read_committed_delete_record(
        &mut self,
        collection: &str,
        id: &str,
    ) -> Result<Option<(Option<Record>, u64)>> {
        self.read_committed_delete_record_inner(collection, id, None)
    }

    /// Grant-aware sibling of [`Self::read_committed_delete_record`] used by
    /// compiler-signed embedded SQL.
    pub fn read_committed_delete_record_with_grant(
        &mut self,
        grant: MutationGrantId,
        collection: &str,
        id: &str,
    ) -> Result<Option<(Option<Record>, u64)>> {
        self.read_committed_delete_record_inner(collection, id, Some(grant))
    }

    fn read_committed_delete_record_inner(
        &mut self,
        collection: &str,
        id: &str,
        grant: Option<MutationGrantId>,
    ) -> Result<Option<(Option<Record>, u64)>> {
        if self.state != TxState::Pending {
            return Err(BicDbError::TransactionNotPending);
        }
        if self.last_pending_write(collection, id).is_some() {
            return Ok(None);
        }
        let tx_id = self.id;

        let db = self.db_ref();
        match grant {
            Some(grant) => self.validate_mutation_grant_operation(
                grant,
                collection,
                id,
                MutationOperation::Delete,
            )?,
            None => db.ensure_unprotected_legacy_access(collection, SecureOperation::Delete)?,
        }
        db.ensure_collection(collection)?;
        db.lock_tx_record_for_read_committed_update(tx_id, collection, id, &self.locked_keys)?;
        let state = db.collection_state(collection)?;
        let shard = state.shard(id).read();
        let Some(rowid) = shard.rowid_of(id) else {
            return Ok(None);
        };
        let max_tx = version_chain_max_tx(&shard.versions, rowid);
        // See read_committed_update_record: freshness is judged against the
        // un-floored applied watermark, never the floored snapshot.
        if max_tx <= self.applied_snapshot {
            return Ok(None);
        }
        let latest = shard
            .records
            .get(&rowid)
            .map(|entry| entry.record.to_record())
            .transpose()?;
        Ok(Some((latest, max_tx)))
    }

    fn validate_mutation_grant_operation(
        &self,
        grant_id: MutationGrantId,
        collection: &str,
        record_id: &str,
        operation: MutationOperation,
    ) -> Result<()> {
        let actor = self.mutation_actor.as_ref().ok_or_else(|| {
            BicDbError::MutationDenied(
                "mutation-grant row locks require an application transaction".to_string(),
            )
        })?;
        let grant = self.mutation_grants.get(&grant_id).ok_or_else(|| {
            BicDbError::MutationDenied("unknown or consumed MutationGrant".to_string())
        })?;
        if grant.id != grant_id || &grant.actor != actor {
            return Err(BicDbError::MutationDenied(
                "MutationGrant belongs to another transaction or actor".to_string(),
            ));
        }
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_millis() as i64)
            .unwrap_or_default();
        if actor.deadline_unix_ms <= now {
            return Err(BicDbError::QueryTimedOut);
        }
        if !grant.spec.relation.eq_ignore_ascii_case(collection) {
            return Err(BicDbError::MutationDenied(format!(
                "MutationGrant for `{}` cannot lock `{collection}`",
                grant.spec.relation
            )));
        }
        let operation_allowed = grant.spec.operation == operation
            || (grant.spec.operation == MutationOperation::Restore
                && operation == MutationOperation::Update)
            || (grant.spec.operation == MutationOperation::Bulk && grant.spec.bulk);
        if !operation_allowed {
            return Err(BicDbError::MutationDenied(format!(
                "MutationGrant operation {:?} cannot lock for {operation:?}",
                grant.spec.operation
            )));
        }
        if grant
            .spec
            .record_id
            .as_ref()
            .is_some_and(|expected| expected != record_id)
            || grant
                .spec
                .record_id_prefix
                .as_ref()
                .is_some_and(|prefix| !record_id.starts_with(prefix))
        {
            return Err(BicDbError::MutationDenied(format!(
                "MutationGrant does not cover record `{record_id}`"
            )));
        }
        if grant.remaining_rows == 0 || grant.remaining_statements == 0 {
            return Err(BicDbError::MutationDenied(
                "MutationGrant row or statement budget exceeded".to_string(),
            ));
        }
        Ok(())
    }

    fn db_ref(&self) -> &BicDb {
        // Safety: Transaction is created only by BicDb::begin_transaction. The
        // SQL layer uses it as a single-owner read overlay while the transaction
        // is pending.
        unsafe { self.db.as_ref() }
    }
}

fn mutation_changed_columns(
    operation: MutationOperation,
    existing: Option<&Record>,
    next: &Record,
) -> BTreeSet<String> {
    if operation == MutationOperation::Delete {
        return BTreeSet::new();
    }
    if operation == MutationOperation::Insert || existing.is_none() {
        let mut columns = next
            .metadata
            .as_object()
            .map(|metadata| metadata.keys().cloned().collect::<BTreeSet<_>>())
            .unwrap_or_default();
        columns.insert("id".to_string());
        if next.vector.is_some() {
            columns.insert("vector".to_string());
        }
        if next.geometry.is_some() {
            columns.insert("geometry".to_string());
        }
        if next.timestamp.is_some() {
            columns.insert("timestamp".to_string());
        }
        if next.payload.is_some() {
            columns.insert("payload".to_string());
        }
        return columns;
    }

    let existing = existing.expect("checked above");
    let old = existing.metadata.as_object();
    let new = next.metadata.as_object();
    let mut columns = old
        .into_iter()
        .flatten()
        .map(|(field, _)| field)
        .chain(new.into_iter().flatten().map(|(field, _)| field))
        .filter(|field| {
            old.and_then(|metadata| metadata.get(*field))
                != new.and_then(|metadata| metadata.get(*field))
        })
        .cloned()
        .collect::<BTreeSet<_>>();
    for (field, changed) in [
        ("vector", existing.vector != next.vector),
        ("geometry", existing.geometry != next.geometry),
        ("timestamp", existing.timestamp != next.timestamp),
        ("payload", existing.payload != next.payload),
    ] {
        if changed {
            columns.insert(field.to_string());
        }
    }
    columns
}

fn mutation_security_context(actor: &MutationActor) -> Result<SecurityContext> {
    let tenant_id = actor.tenant_id.clone().ok_or_else(|| {
        BicDbError::Authorization(
            "tenant-protected reads require a tenant-bound actor context".to_string(),
        )
    })?;
    // A delegated end-user principal. `MutationActor` carries no
    // authentication strength, so this stays at the weakest value rather than
    // inheriting the strength of whatever in-process worker is executing it.
    let mut context = SecurityContext::new(&actor.actor_id, tenant_id)
        .with_roles(actor.roles.iter().cloned())
        .with_scopes(actor.scopes.iter().cloned());
    if let Some(workspace_id) = &actor.workspace_id {
        context = context.with_workspace_id(workspace_id);
    }
    Ok(context)
}

fn validate_mutation_actor_field(
    collection: &str,
    record: &Record,
    field: Option<&String>,
    expected: Option<&str>,
    boundary: &str,
) -> Result<()> {
    let Some(field) = field else {
        return Ok(());
    };
    let expected = expected.ok_or_else(|| {
        BicDbError::MutationDenied(format!(
            "{boundary}-scoped collection `{collection}` requires a {boundary}-bound actor"
        ))
    })?;
    let actual = record.metadata.get(field).and_then(Value::as_str);
    if actual != Some(expected) {
        return Err(BicDbError::MutationDenied(format!(
            "cross-{boundary} mutation denied for `{collection}`/`{}`",
            record.id
        )));
    }
    Ok(())
}

fn release_owned_write_locks(
    write_locks: &row_lock_waiters::RowLockTable,
    tx_id: TransactionId,
    keys: &[RecordLockKey],
) {
    // Release only the keys this transaction actually acquired. This remains
    // O(the transaction's locks), preserving disjoint-commit concurrency while
    // also covering pre-write locks that never reached `Transaction::writes`.
    for key in keys {
        let shard_idx = write_locks.shard_idx(key);
        let mut shard = write_locks.shards[shard_idx].lock();
        match shard.remove(key) {
            // Never steal a lock if bookkeeping is inconsistent.
            Some(owner) if owner != tx_id => {
                shard.insert(key.clone(), owner);
            }
            _ => {}
        }
        drop(shard);
        write_locks.notify_released(key, shard_idx);
    }
}

impl Drop for Transaction {
    fn drop(&mut self) {
        if self.state == TxState::Pending {
            // Release this transaction's record locks for abandoned (never
            // committed/rolled-back) transactions. We go through our own handle
            // to the shared lock map rather than dereferencing `db`, so drop is
            // sound even when another thread holds the database write lock.
            // Recovery ignores the abandoned TxWrite frames because no TxCommit
            // frame was ever written.
            let locked_keys = self.locked_keys.get_mut().take_all();
            release_owned_write_locks(&self.write_locks, self.id, &locked_keys);
            // Remove this abandoned/conflict-dropped txn's Pending entry. The
            // pgwire shared-commit retry loop drops a conflicted Transaction and
            // begins a fresh one; without this, each retry leaked a Pending entry.
            // Goes through our own Arc handle to stay sound under concurrent `db`
            // access (mirrors the lock release above and the snapshot deregister
            // below). Committed/aborted txns already removed their entry.
            self.tx_states.remove(&self.id.0);
        }
        // Deregister this transaction's read snapshot so GC can advance past it.
        // Goes through the shared handle (not `db`) to stay sound under
        // concurrent access, mirroring the record-lock release above.
        self.active_snapshots.decr_remove(self.snapshot_tx.0);
    }
}

/// [`rewrite_record_segment`] for resident [`StoredRecord`]s: serializes each
/// via [`RecordFrameRef`] (raw-metadata passthrough), skipping the
/// `Record`/`Value` materialization. Used by the incremental checkpoint.
fn rewrite_stored_record_segment(
    path: &Path,
    records: &[Arc<StoredRecord>],
    fsync: bool,
    compression: &CompressionConfig,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u64>> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }

    let tmp_path = compact_tmp_path(path);
    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }

    let payloads = records
        .iter()
        .map(|record| {
            serde_json::to_vec(&RecordFrameRef::Upsert {
                record: record.as_ref(),
            })
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;

    rewrite_frame_file_with_tmp(
        path,
        &tmp_path,
        FrameKind::Record,
        &payloads,
        fsync,
        compression,
        encryption,
    )
}

fn rewrite_record_segment(
    path: &Path,
    records: &[Record],
    fsync: bool,
    compression: &CompressionConfig,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u64>> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }

    let tmp_path = compact_tmp_path(path);
    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }

    let payloads = records
        .iter()
        .map(|record| {
            serde_json::to_vec(&RecordFrame::Upsert {
                record: record.clone(),
            })
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;

    rewrite_frame_file_with_tmp(
        path,
        &tmp_path,
        FrameKind::Record,
        &payloads,
        fsync,
        compression,
        encryption,
    )
}

/// Records rewritten per append while compacting a collection segment.
/// Each batch is decoded, serialized, appended and dropped before the next,
/// so a rewrite holds a bounded slice of the collection rather than three
/// whole copies of it (decoded records, frame payloads, resident store) —
/// which is what took `bicdb compact` past 50 GB on a 16-warehouse TPC-C seed.
const COMPACT_REWRITE_BATCH: usize = 4096;

/// Rewrite a record segment from resident records in batches, returning the
/// new frame offset of each record in `stored` order.
fn rewrite_record_segment_streamed(
    path: &Path,
    stored: &[Arc<StoredRecord>],
    fsync: bool,
    compression: &CompressionConfig,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u64>> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let tmp_path = compact_tmp_path(path);
    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    fs::File::create(&tmp_path)?;

    let mut offsets = Vec::with_capacity(stored.len());
    for batch in stored.chunks(COMPACT_REWRITE_BATCH) {
        let payloads = batch
            .iter()
            .map(|stored| {
                serde_json::to_vec(&RecordFrame::Upsert {
                    record: stored.to_record()?,
                })
                .map_err(BicDbError::from)
            })
            .collect::<Result<Vec<_>>>()?;
        // One durable sync of the finished file below instead of one per batch.
        offsets.extend(storage::append_frames_for_object(
            &tmp_path,
            path,
            FrameKind::Record,
            &payloads,
            false,
            compression,
            encryption,
        )?);
    }
    if fsync {
        storage::sync_file(&tmp_path)?;
    }

    replace_file(&tmp_path, path)?;
    if fsync {
        storage::sync_file(path)?;
        sync_parent_dir(path)?;
    }
    Ok(offsets)
}

pub(crate) fn rewrite_frame_file(
    path: &Path,
    kind: FrameKind,
    payloads: &[Vec<u8>],
    fsync: bool,
    compression: &CompressionConfig,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u64>> {
    let tmp_path = compact_tmp_path(path);
    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    rewrite_frame_file_with_tmp(
        path,
        &tmp_path,
        kind,
        payloads,
        fsync,
        compression,
        encryption,
    )
}

/// [`rewrite_frame_file`] over a payload stream: frames append to the tmp
/// file in bounded groups instead of materializing every payload first. A
/// segment rewrite previously held the source events, every serialized
/// payload, AND the file being written — three copies of the log at once.
pub(crate) fn rewrite_frame_file_iter(
    path: &Path,
    kind: FrameKind,
    payloads: impl Iterator<Item = Result<Vec<u8>>>,
    fsync: bool,
    compression: &CompressionConfig,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u64>> {
    const APPEND_GROUP: usize = 1_024;
    let tmp_path = compact_tmp_path(path);
    match fs::remove_file(&tmp_path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::File::create(&tmp_path)?;
    let mut offsets = Vec::new();
    let mut group: Vec<Vec<u8>> = Vec::with_capacity(APPEND_GROUP);
    let flush = |group: &mut Vec<Vec<u8>>, offsets: &mut Vec<u64>| -> Result<()> {
        if group.is_empty() {
            return Ok(());
        }
        offsets.extend(storage::append_frames_for_object(
            &tmp_path,
            path,
            kind,
            group,
            fsync,
            compression,
            encryption,
        )?);
        group.clear();
        Ok(())
    };
    for payload in payloads {
        group.push(payload?);
        if group.len() >= APPEND_GROUP {
            flush(&mut group, &mut offsets)?;
        }
    }
    flush(&mut group, &mut offsets)?;

    replace_file(&tmp_path, path)?;
    if fsync {
        storage::sync_file(path)?;
        sync_parent_dir(path)?;
    }
    Ok(offsets)
}

fn rewrite_frame_file_with_tmp(
    path: &Path,
    tmp_path: &Path,
    kind: FrameKind,
    payloads: &[Vec<u8>],
    fsync: bool,
    compression: &CompressionConfig,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u64>> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let offsets = if payloads.is_empty() {
        fs::File::create(tmp_path)?;
        Vec::new()
    } else {
        storage::append_frames_for_object(
            tmp_path,
            path,
            kind,
            payloads,
            fsync,
            compression,
            encryption,
        )?
    };

    replace_file(tmp_path, path)?;
    if fsync {
        storage::sync_file(path)?;
        sync_parent_dir(path)?;
    }

    Ok(offsets)
}

fn compact_tmp_path(path: &Path) -> PathBuf {
    let mut tmp = path.to_path_buf();
    let tmp_name = format!(
        ".{}.compact-{}",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("segment"),
        Uuid::new_v4()
    );
    tmp.set_file_name(tmp_name);
    tmp
}

fn load_ha_state(path: &Path) -> Result<HaState> {
    let state_path = path.join(DEFAULT_HA_STATE);
    match fs::read(&state_path) {
        Ok(bytes) => Ok(serde_json::from_slice(&bytes)?),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(HaState::default()),
        Err(error) => Err(error.into()),
    }
}

fn load_replication_state(
    path: &Path,
    config: &ReplicationConfig,
    recovered_commit_seq: u64,
) -> Result<ReplicationApplyState> {
    let state_path = path.join(DEFAULT_REPLICATION_STATE);
    let mut state = match fs::read(&state_path) {
        Ok(bytes) => serde_json::from_slice::<ReplicationApplyState>(&bytes)?,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(ReplicationApplyState::new(
                config.cluster_id.clone(),
                recovered_commit_seq,
            ));
        }
        Err(error) => return Err(error.into()),
    };
    let enforce_config_cluster =
        config.enabled || !matches!(config.mode, ReplicationMode::Disabled);
    if enforce_config_cluster && state.cluster_id != config.cluster_id {
        return Err(replication_error(format!(
            "replication state cluster_id mismatch: config={}, state={}",
            config.cluster_id, state.cluster_id
        )));
    }
    state.last_applied_commit_seq = state.last_applied_commit_seq.max(recovered_commit_seq);
    Ok(state)
}

fn load_model_registry(
    path: &Path,
    encryption: &EncryptionRuntime,
) -> Result<FxHashMap<String, ModelRegistryEntry>> {
    let registry_path = path.join(DEFAULT_MODEL_REGISTRY);
    match read_optional_sidecar(&registry_path, FrameKind::Index, encryption)? {
        Some(bytes) => {
            let entries = serde_json::from_slice::<Vec<ModelRegistryEntry>>(&bytes)?;
            Ok(entries
                .into_iter()
                .map(|entry| (entry.name.clone(), entry))
                .collect())
        }
        None => Ok(FxHashMap::default()),
    }
}

fn load_memory_index_catalog(
    path: &Path,
    encryption: &EncryptionRuntime,
) -> Result<FxHashMap<String, MemoryIndexDefinition>> {
    let catalog_path = path.join(DEFAULT_MEMORY_INDEX_CATALOG);
    match read_optional_sidecar(&catalog_path, FrameKind::Index, encryption)? {
        Some(bytes) => {
            let entries = serde_json::from_slice::<Vec<MemoryIndexDefinition>>(&bytes)?;
            Ok(entries
                .into_iter()
                .map(|entry| (entry.name.clone(), entry))
                .collect())
        }
        None => Ok(FxHashMap::default()),
    }
}

fn load_memory_index_jobs(
    path: &Path,
    encryption: &EncryptionRuntime,
) -> Result<Vec<MemoryIndexJob>> {
    let jobs_path = path.join(DEFAULT_MEMORY_INDEX_JOBS);
    match read_optional_sidecar(&jobs_path, FrameKind::Search, encryption)? {
        Some(bytes) => Ok(serde_json::from_slice::<Vec<MemoryIndexJob>>(&bytes)?),
        None => Ok(Vec::new()),
    }
}

fn load_consensus_state(path: &Path, config: &ConsensusConfig) -> Result<ConsensusState> {
    let state_path = path.join(DEFAULT_CONSENSUS_STATE);
    let mut state = match fs::read(&state_path) {
        Ok(bytes) => serde_json::from_slice::<ConsensusState>(&bytes)?,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(ConsensusState::new(config));
        }
        Err(error) => return Err(error.into()),
    };
    if config.enabled {
        if state.cluster_id != config.cluster_id {
            return Err(crate::consensus::consensus_error(format!(
                "consensus state cluster_id mismatch: config={}, state={}",
                config.cluster_id, state.cluster_id
            )));
        }
        if state.node_id != config.node_id {
            return Err(crate::consensus::consensus_error(format!(
                "consensus state node_id mismatch: config={}, state={}",
                config.node_id, state.node_id
            )));
        }
        state.voters = config.voter_ids();
        for voter in &state.voters {
            state.match_index.entry(voter.clone()).or_insert(0);
        }
    }
    Ok(state)
}

fn persist_ha_state(path: &Path, state: &HaState, fsync: bool) -> Result<()> {
    fs::create_dir_all(path)?;
    let state_path = path.join(DEFAULT_HA_STATE);
    let tmp_path = state_path.with_extension("json.tmp");
    fs::write(&tmp_path, serde_json::to_vec_pretty(state)?)?;
    if fsync {
        storage::sync_file(&tmp_path)?;
    }
    fs::rename(&tmp_path, &state_path)?;
    if fsync {
        storage::sync_file(&state_path)?;
    }
    Ok(())
}

fn persist_replication_state(
    path: &Path,
    state: &ReplicationApplyState,
    fsync: bool,
) -> Result<()> {
    fs::create_dir_all(path)?;
    storage::write_atomic(
        &path.join(DEFAULT_REPLICATION_STATE),
        &serde_json::to_vec_pretty(state)?,
        fsync,
    )
}

fn persist_model_registry(
    path: &Path,
    registry: &FxHashMap<String, ModelRegistryEntry>,
    fsync: bool,
    encryption: &EncryptionRuntime,
) -> Result<()> {
    let mut entries = registry.values().cloned().collect::<Vec<_>>();
    entries.sort_by(|left, right| left.name.cmp(&right.name));
    fs::create_dir_all(path)?;
    write_sidecar(
        &path.join(DEFAULT_MODEL_REGISTRY),
        FrameKind::Index,
        &serde_json::to_vec_pretty(&entries)?,
        fsync,
        encryption,
    )
}

