fn ship_to_standby(source_path: &Path, standby_path: &Path) -> Result<HaApplyReport> {
    let source_path = source_path.to_path_buf();
    let standby_path = standby_path.to_path_buf();
    if source_path == standby_path {
        return Err(BicDbError::HighAvailability(
            "primary and standby paths must be different".to_string(),
        ));
    }

    let primary = BicDb::open(&source_path)?;
    if primary.ha_state.role == HaRole::Standby {
        return Err(BicDbError::HighAvailability(
            "cannot ship from a standby; promote it first".to_string(),
        ));
    }
    primary.flush()?;
    drop(primary);

    fs::create_dir_all(&standby_path)?;
    let source_checkpoint_bytes = storage::total_dir_size(&source_path)?;
    let mut files = Vec::new();
    collect_ha_files(&source_path, &source_path, &mut files)?;
    let mut files_copied = 0;

    let apply = (|| -> Result<()> {
        for relative in &files {
            let source = source_path.join(relative);
            let target = standby_path.join(relative);
            if let Some(parent) = target.parent() {
                fs::create_dir_all(parent)?;
            }
            copy_ha_regular_file(&source, &target)?;
            files_copied += 1;
        }
        remove_standby_orphan_files(&standby_path, &files)?;
        Ok(())
    })();

    let mut state = HaState {
        role: HaRole::Standby,
        source_path: Some(source_path.clone()),
        source_checkpoint_bytes,
        applied_checkpoint_bytes: 0,
        last_apply_at: Some(unix_timestamp()),
        last_apply_error: None,
        promoted_at: None,
    };

    match apply {
        Ok(()) => {
            state.applied_checkpoint_bytes = source_checkpoint_bytes;
            persist_ha_state(&standby_path, &state, true)?;
            // An apply interrupted mid-copy leaves `.ha-tmp` files behind.
            // `collect_ha_files` SKIPS them, so they were invisible to every
            // later apply and nothing ever removed them — each interruption
            // leaked a full-sized partial copy onto the standby permanently.
            // A completed apply is the safe point to reclaim them.
            reclaim_stale_ha_temporaries(&standby_path);
            Ok(HaApplyReport {
                source_path,
                standby_path,
                source_checkpoint_bytes,
                applied_checkpoint_bytes: state.applied_checkpoint_bytes,
                files_copied,
            })
        }
        Err(error) => {
            state.last_apply_error = Some(error.to_string());
            let _ = persist_ha_state(&standby_path, &state, true);
            Err(error)
        }
    }
}

/// Delete `.ha-tmp` artifacts left by interrupted applies.
///
/// Failures are ignored: the apply has succeeded and is durable, and refusing to
/// report a successful apply because cleanup failed would turn a full disk
/// into a failed standby sync.
fn reclaim_stale_ha_temporaries(root: &Path) {
    let Ok(entries) = fs::read_dir(root) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        if file_type.is_symlink() {
            continue;
        }
        if file_type.is_dir() {
            reclaim_stale_ha_temporaries(&path);
        } else if entry.file_name().to_string_lossy().ends_with(".ha-tmp") {
            let _ = fs::remove_file(&path);
        }
    }
}

fn collect_ha_files(root: &Path, current: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
    for entry in fs::read_dir(current)? {
        let entry = entry?;
        let path = entry.path();
        let name = entry.file_name();
        if name == DEFAULT_HA_STATE || name.to_string_lossy().ends_with(".ha-tmp") {
            continue;
        }
        let file_type = entry.file_type()?;
        if file_type.is_symlink() {
            return Err(BicDbError::HighAvailability(format!(
                "HA checkpoint path {} is a symbolic link",
                path.display()
            )));
        }
        if file_type.is_dir() {
            collect_ha_files(root, &path, files)?;
        } else if file_type.is_file() {
            files.push(path.strip_prefix(root).unwrap().to_path_buf());
        }
    }
    files.sort();
    Ok(())
}

fn copy_ha_regular_file(source: &Path, target: &Path) -> Result<()> {
    let tmp = target.with_file_name(format!(
        ".{}.{}.ha-tmp",
        target
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("bicdb"),
        Uuid::new_v4().simple()
    ));
    let result = (|| -> Result<()> {
        let mut source_options = fs::OpenOptions::new();
        source_options.read(true);
        let mut target_options = fs::OpenOptions::new();
        target_options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            source_options.custom_flags(libc::O_NOFOLLOW);
            target_options.custom_flags(libc::O_NOFOLLOW).mode(0o600);
        }
        let mut input = source_options.open(source)?;
        if !input.metadata()?.is_file() {
            return Err(BicDbError::HighAvailability(format!(
                "HA source {} is not a regular file",
                source.display()
            )));
        }
        let mut output = target_options.open(&tmp)?;
        std::io::copy(&mut input, &mut output)?;
        output.sync_all()?;
        drop(output);
        fs::rename(&tmp, target)?;
        sync_parent_dir(target)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&tmp);
    }
    result
}

fn remove_standby_orphan_files(standby_path: &Path, source_files: &[PathBuf]) -> Result<()> {
    let mut standby_files = Vec::new();
    collect_ha_files(standby_path, standby_path, &mut standby_files)?;
    for relative in standby_files {
        if source_files.binary_search(&relative).is_err() {
            fs::remove_file(standby_path.join(relative))?;
        }
    }
    Ok(())
}

fn replace_file(from: &Path, to: &Path) -> Result<()> {
    match fs::rename(from, to) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
            fs::remove_file(to)?;
            fs::rename(from, to)?;
            Ok(())
        }
        Err(error) => Err(error.into()),
    }
}

// wasm/WASI (and OPFS underneath) has no directory fd to fsync; rename
// durability there is the storage layer's job, so this is a no-op.
#[cfg(target_arch = "wasm32")]
fn sync_parent_dir(_path: &Path) -> Result<()> {
    Ok(())
}

#[cfg(all(not(target_arch = "wasm32"), unix))]
fn sync_parent_dir(path: &Path) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::File::open(parent)?.sync_all()?;
    }
    Ok(())
}

// Windows cannot fsync a directory through std (opening a directory as a
// File fails with access denied); rely on file-level sync_all only.
#[cfg(all(not(target_arch = "wasm32"), not(unix)))]
fn sync_parent_dir(_path: &Path) -> Result<()> {
    Ok(())
}

fn path_entry_exists(path: &Path) -> Result<bool> {
    match fs::symlink_metadata(path) {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error.into()),
    }
}

fn truncate_log_file(path: &Path, fsync: bool) -> Result<()> {
    let tmp_path = compact_tmp_path(path);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    File::create(&tmp_path)?;
    replace_file(&tmp_path, path)?;
    if fsync {
        storage::sync_file(path)?;
        sync_parent_dir(path)?;
    }
    Ok(())
}

/// Copies the transaction-log byte range `[keep_from_offset .. end]` into a fresh
/// log, dropping the prefix below the offset. The WAL is an append-only stream of
/// self-describing frames with NO file-level header, written in commit_seq order,
/// so a byte offset captured at a frame boundary (the log length right after a
/// flush -- see [`BicDb::checkpoint_begin`]) cleanly separates the
/// already-checkpointed commits below it from the retained suffix at/above it.
/// This is O(suffix bytes) with no frame parsing, so the phase-2 write-lock hold
/// stays short even for a multi-GB log.
///
/// Crash-safe: temp file + fsync + atomic rename, so a crash leaves either the old
/// (full) or new (suffix) log; together with the segments, both reconstruct the
/// exact committed state. Caller MUST hold the exclusive write lock and have
/// flushed pending WAL writes first, so no commit can append concurrently.
fn copy_transaction_log_tail(path: &Path, keep_from_offset: u64, fsync: bool) -> Result<()> {
    use std::io::{Seek, SeekFrom};

    let tmp_path = compact_tmp_path(path);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    {
        let mut src = File::open(path)?;
        let len = src.metadata()?.len();
        // Offsets past EOF (nothing to keep) yield an empty log; clamp defensively.
        let start = keep_from_offset.min(len);
        src.seek(SeekFrom::Start(start))?;
        let mut dst = File::create(&tmp_path)?;
        std::io::copy(&mut src, &mut dst)?;
        if fsync {
            dst.sync_all()?;
        }
    }
    replace_file(&tmp_path, path)?;
    if fsync {
        storage::sync_file(path)?;
        sync_parent_dir(path)?;
    }
    Ok(())
}

fn file_len(path: &Path) -> Result<u64> {
    match fs::metadata(path) {
        Ok(metadata) => Ok(metadata.len()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(0),
        Err(error) => Err(error.into()),
    }
}

fn sha256_file(path: &Path) -> Result<String> {
    let mut reader = BufReader::new(File::open(path)?);
    let mut hasher = sha2::Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let read = reader.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(hex::encode(hasher.finalize()))
}

fn duration_millis(duration: Duration) -> u64 {
    duration.as_millis().min(u128::from(u64::MAX)) as u64
}

fn reclaim_percent(bytes_before: u64, bytes_reclaimed: u64) -> u8 {
    if bytes_before == 0 {
        return 0;
    }
    ((bytes_reclaimed.saturating_mul(100)) / bytes_before).min(100) as u8
}

fn estimate_dead_records(collections: &[CollectionCompactionReport]) -> usize {
    collections
        .iter()
        .map(|collection| {
            if collection.bytes_after == 0 {
                0
            } else {
                let avg = (collection.bytes_after / collection.live_records.max(1) as u64).max(1);
                (collection.bytes_reclaimed / avg) as usize
            }
        })
        .sum()
}

fn throttle_compaction_io(options: &CompactionOptions, bytes: u64) -> Result<()> {
    let Some(max_io) = options.max_io_bytes_per_sec else {
        return Ok(());
    };
    if max_io == 0 || bytes == 0 {
        return Ok(());
    }
    let sleep = Duration::from_secs_f64(bytes as f64 / max_io as f64);
    if let Some(max_pause_ms) = options.max_pause_ms {
        let max_pause = Duration::from_millis(max_pause_ms);
        if sleep > max_pause {
            return Err(BicDbError::Compaction(format!(
                "compaction IO throttle would exceed max pause budget of {max_pause_ms}ms"
            )));
        }
    }
    std::thread::sleep(sleep);
    Ok(())
}

struct TxRecovery {
    states: BTreeMap<u64, TxState>,
    writes: BTreeMap<u64, Vec<RecoveredTxWrite>>,
    broker_publishes: BTreeMap<u64, Vec<crate::broker::PendingBrokerPublish>>,
    record_audit_events: BTreeMap<u64, Vec<Event>>,
    record_audit_published: FxHashSet<u64>,
    materialized_commits: FxHashSet<u64>,
    /// commit_seq assigned to each committed transaction (from its WAL Commit
    /// frame). MVCC version stamps are commit_seq values, so replay must stamp
    /// each recovered version with its transaction's commit_seq and apply in
    /// commit_seq order.
    commit_seq_by_tx: BTreeMap<u64, u64>,
    next_tx_id: u64,
    last_commit_seq: u64,
}

#[derive(Clone, Debug)]
enum RecoveredTxWrite {
    Full(TxWrite),
    Patch(TxPatch),
}

impl RecoveredTxWrite {
    fn collection(&self) -> &str {
        match self {
            Self::Full(write) => &write.collection,
            Self::Patch(patch) => &patch.collection,
        }
    }

    #[cfg(test)]
    fn record_id(&self) -> &str {
        match self {
            Self::Full(write) => &write.record_id,
            Self::Patch(patch) => &patch.record_id,
        }
    }
}

impl TxRecovery {
    fn is_committed(&self, tx_id: TransactionId) -> bool {
        self.states.get(&tx_id.0) == Some(&TxState::Committed)
    }

    fn is_materialized(&self, tx_id: TransactionId) -> bool {
        self.materialized_commits.contains(&tx_id.0)
    }

    fn committed_broker_publishes(&self) -> Vec<crate::broker::PendingBrokerPublish> {
        self.broker_publishes
            .iter()
            .filter(|(tx_id, _)| self.states.get(tx_id) == Some(&TxState::Committed))
            .flat_map(|(_, publishes)| publishes.iter().cloned())
            .collect()
    }

    fn committed_record_audit_outboxes(&self) -> Vec<(TransactionId, Vec<Event>)> {
        let mut committed = self
            .record_audit_events
            .iter()
            .filter_map(|(tx_id, events)| {
                (self.states.get(tx_id) == Some(&TxState::Committed)
                    && !self.record_audit_published.contains(tx_id))
                .then(|| {
                    (
                        self.commit_seq_by_tx
                            .get(tx_id)
                            .copied()
                            .unwrap_or(u64::MAX),
                        *tx_id,
                        events,
                    )
                })
            })
            .collect::<Vec<_>>();
        committed.sort_by_key(|(commit_seq, tx_id, _)| (*commit_seq, *tx_id));
        committed
            .into_iter()
            .map(|(_, tx_id, events)| (TransactionId(tx_id), events.clone()))
            .collect()
    }
}

#[derive(Default)]
struct SegmentReplayIndex {
    touched_record_ids: FxHashMap<String, FxHashSet<String>>,
}

impl SegmentReplayIndex {
    fn mark_touched(&mut self, collection: &str, record_id: &str) {
        self.touched_record_ids
            .entry(collection.to_string())
            .or_default()
            .insert(record_id.to_string());
    }

    fn touched(&self, collection: &str, record_id: &str) -> bool {
        self.touched_record_ids
            .get(collection)
            .is_some_and(|ids| ids.contains(record_id))
    }
}

fn recover_transaction_log(
    path: &Path,
    _read_mode: SegmentReadMode,
    encryption: &EncryptionRuntime,
) -> Result<TxRecovery> {
    let mut states = BTreeMap::new();
    let mut writes: BTreeMap<u64, Vec<RecoveredTxWrite>> = BTreeMap::new();
    let mut broker_publishes: BTreeMap<u64, Vec<crate::broker::PendingBrokerPublish>> =
        BTreeMap::new();
    let mut record_audit_events: BTreeMap<u64, Vec<Event>> = BTreeMap::new();
    let mut record_audit_published = FxHashSet::default();
    let mut materialized_commits = FxHashSet::default();
    let mut commit_seq_by_tx: BTreeMap<u64, u64> = BTreeMap::new();
    let mut max_tx = 0_u64;
    let mut max_commit_seq = 0_u64;

    // Stream the WAL independently of the record-segment read mode. Preserve
    // torn-tail repair, without retaining every raw frame beside decoded rows.
    storage::stream_frames(path, FrameKind::Transaction, encryption, |_, payload| {
        let tx_frame = decode_tx_frame(&payload)?;
        match tx_frame {
            TxFrame::Begin { tx_id, .. } => {
                max_tx = max_tx.max(tx_id.0);
                states.entry(tx_id.0).or_insert(TxState::Pending);
            }
            TxFrame::Write { tx_id, write } => {
                max_tx = max_tx.max(tx_id.0);
                writes
                    .entry(tx_id.0)
                    .or_default()
                    .push(RecoveredTxWrite::Full(*write));
                states.entry(tx_id.0).or_insert(TxState::Pending);
            }
            TxFrame::Patch { tx_id, patch } => {
                max_tx = max_tx.max(tx_id.0);
                writes
                    .entry(tx_id.0)
                    .or_default()
                    .push(RecoveredTxWrite::Patch(*patch));
                states.entry(tx_id.0).or_insert(TxState::Pending);
            }
            TxFrame::Truncate { tx_id, len } => {
                max_tx = max_tx.max(tx_id.0);
                if let Some(tx_writes) = writes.get_mut(&tx_id.0) {
                    tx_writes.truncate(len);
                }
                states.entry(tx_id.0).or_insert(TxState::Pending);
            }
            TxFrame::BrokerPublish { tx_id, publish } => {
                max_tx = max_tx.max(tx_id.0);
                broker_publishes.entry(tx_id.0).or_default().push(publish);
                states.entry(tx_id.0).or_insert(TxState::Pending);
            }
            TxFrame::RecordAudit { tx_id, event } => {
                max_tx = max_tx.max(tx_id.0);
                record_audit_events.entry(tx_id.0).or_default().push(event);
                states.entry(tx_id.0).or_insert(TxState::Pending);
            }
            TxFrame::RecordAuditPublished { tx_id } => {
                max_tx = max_tx.max(tx_id.0);
                record_audit_published.insert(tx_id.0);
            }
            TxFrame::Commit {
                tx_id, commit_seq, ..
            } => {
                max_tx = max_tx.max(tx_id.0);
                max_commit_seq = max_commit_seq.max(commit_seq);
                commit_seq_by_tx.insert(tx_id.0, commit_seq);
                states.insert(tx_id.0, TxState::Committed);
            }
            TxFrame::CommitMaterialized {
                tx_id, commit_seq, ..
            } => {
                max_tx = max_tx.max(tx_id.0);
                max_commit_seq = max_commit_seq.max(commit_seq);
                states.insert(tx_id.0, TxState::Committed);
                materialized_commits.insert(tx_id.0);
                commit_seq_by_tx.insert(tx_id.0, commit_seq);
            }
            TxFrame::Abort { tx_id, .. } => {
                max_tx = max_tx.max(tx_id.0);
                states.insert(tx_id.0, TxState::Aborted);
                commit_seq_by_tx.remove(&tx_id.0);
                materialized_commits.remove(&tx_id.0);
                broker_publishes.remove(&tx_id.0);
                record_audit_events.remove(&tx_id.0);
                record_audit_published.remove(&tx_id.0);
            }
        }
        Ok(())
    })?;

    // A transaction that was in progress when the process died is aborted by
    // definition: its writes are never replayed (only committed ones are), and
    // no live object will ever resolve it. Leaving the `Pending` entries in the
    // recovered table made them immortal, and `ensure_no_pending_transactions`
    // then refused compaction and event-log trimming FOREVER after any hard
    // kill — the transaction/sync logs grow unbounded with no way back.
    // Recovery already treats an absent entry as "not pending", and live
    // transactions re-insert their own entry when they begin.
    states.retain(|_, state| *state == TxState::Committed);

    Ok(TxRecovery {
        states,
        writes,
        broker_publishes,
        record_audit_events,
        record_audit_published,
        materialized_commits,
        commit_seq_by_tx,
        next_tx_id: max_tx.saturating_add(1).max(1),
        last_commit_seq: max_commit_seq,
    })
}

fn apply_unmaterialized_transaction_log(
    recovery: &mut TxRecovery,
    segment_replay: &SegmentReplayIndex,
    collections: &mut FxHashMap<String, RwLock<CollectionState>>,
    // `Some` in paged mode. Recovered writes are re-applied to the page store
    // BEFORE the resident stubs are built, closing the crash window between
    // "commit durable in the core WAL" and "paged apply finished": without
    // this, a commit recovered from the core log existed in shards and
    // segments but not in pages — and paged-mode reads consult pages, so the
    // recovered row was invisible. Re-putting a row the page store already has
    // creates a value-equal duplicate version, which is benign; losing the row
    // is not.
    paged: Option<&Arc<crate::paged_collection::PagedRecords>>,
    // B-tree index definitions per collection, so replayed writes maintain the
    // durable index entries exactly as the live commit path does.
    paged_durable_defs: &FxHashMap<String, Vec<PagedDurableIndexDef>>,
) -> Result<()> {
    let mut replayed_collections = FxHashSet::default();
    // MVCC stamps are commit_seq values, so replay committed transactions in
    // commit_seq order (the durable commit order) and stamp each version with its
    // transaction's commit_seq. File/id order may differ once commits ran
    // concurrently; commit_seq is the authoritative total order.
    let mut ordered: Vec<(u64, u64)> = recovery
        .states
        .iter()
        .filter(|(_, state)| **state == TxState::Committed)
        .filter_map(|(tx_id, _)| {
            let tx_id = *tx_id;
            if recovery.is_materialized(TransactionId(tx_id)) {
                return None;
            }
            recovery
                .commit_seq_by_tx
                .get(&tx_id)
                .map(|seq| (*seq, tx_id))
        })
        .collect();
    ordered.sort_unstable();
    let mut dropped_collection_writes: BTreeMap<String, usize> = BTreeMap::new();
    for (commit_seq, tx_id) in ordered {
        // Once this transaction has been replayed its decoded rows are no
        // longer needed. Retain commit state and outboxes, not a second copy
        // of every historical row throughout the rest of database open.
        let Some(tx_writes) = recovery.writes.remove(&tx_id) else {
            continue;
        };
        for recovered_write in &tx_writes {
            // Collection create/drop is persisted synchronously in the
            // collection catalog and never appears in the transaction log. A
            // retained write for a subsequently dropped collection must be
            // ignored before trying to resolve a patch's base row.
            if !collections.contains_key(recovered_write.collection()) {
                *dropped_collection_writes
                    .entry(recovered_write.collection().to_string())
                    .or_default() += 1;
                continue;
            }
            let materialized_patch = match recovered_write {
                RecoveredTxWrite::Full(_) => None,
                RecoveredTxWrite::Patch(patch) => {
                    materialize_recovered_patch(collections, segment_replay, patch)?
                }
            };
            let write = match recovered_write {
                RecoveredTxWrite::Full(write) => write,
                RecoveredTxWrite::Patch(_) => {
                    let Some(write) = materialized_patch.as_ref() else {
                        continue;
                    };
                    write
                }
            };
            // Only old commit frames lack a commit sequence. Modern WAL is
            // ordered redo: a row made absent by replaying a DELETE must not
            // cause its later committed INSERT to be mistaken for obsolete
            // pre-segment history.
            if commit_seq == 0
                && legacy_tx_write_superseded_by_segment(collections, segment_replay, write)
            {
                continue;
            }
            // Paged first, resident stub second — same ordering, same reason as
            // the live commit path.
            let paged_ctx = match paged {
                Some(paged) => {
                    let _guard = paged.write_guard();
                    let (xid, _) = paged.begin();
                    let index_defs = paged_durable_defs
                        .get(&write.collection)
                        .map(Vec::as_slice)
                        .unwrap_or(&[]);
                    let pre_snapshot = bicdb_page::Snapshot {
                        xid: 0,
                        xmax: xid,
                        in_flight: empty_in_flight(),
                    };
                    let applied = (|| -> Result<()> {
                        let previous = if index_defs.is_empty() {
                            None
                        } else {
                            paged.get(&pre_snapshot, &write.collection, &write.record_id)?
                        };
                        match write.op {
                            TxWriteOp::Upsert => {
                                let record =
                                    write.record()?.ok_or_else(|| BicDbError::Corruption {
                                        path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
                                        message: "transaction upsert missing record".to_string(),
                                    })?;
                                let locator = paged.put(xid, &write.collection, record)?;
                                apply_paged_index_upsert(
                                    paged,
                                    xid,
                                    &write.collection,
                                    index_defs,
                                    previous.as_ref(),
                                    record,
                                    Some((locator, xid)),
                                )?;
                            }
                            TxWriteOp::Delete => {
                                paged.delete(xid, &write.collection, &write.record_id)?;
                                if let Some(previous) = &previous {
                                    apply_paged_index_delete(
                                        paged,
                                        xid,
                                        &write.collection,
                                        index_defs,
                                        previous,
                                        &write.record_id,
                                    )?;
                                }
                            }
                        }
                        Ok(())
                    })();
                    match applied {
                        Ok(()) => {
                            paged.commit(xid)?;
                            let post_snapshot = bicdb_page::Snapshot {
                                xid,
                                xmax: xid + 1,
                                in_flight: empty_in_flight(),
                            };
                            let pre_snapshot = bicdb_page::Snapshot {
                                xid: 0,
                                xmax: xid,
                                in_flight: empty_in_flight(),
                            };
                            let post: PagedStubFetch = {
                                let paged = Arc::clone(paged);
                                let collection: Arc<str> = Arc::from(write.collection.as_str());
                                Arc::new(move |pk: &str| paged.get(&post_snapshot, &collection, pk))
                            };
                            let pre: PagedStubFetch = {
                                let paged = Arc::clone(paged);
                                let collection: Arc<str> = Arc::from(write.collection.as_str());
                                Arc::new(move |pk: &str| paged.get(&pre_snapshot, &collection, pk))
                            };
                            Some(PagedApplyCtx { xid, post, pre })
                        }
                        Err(error) => {
                            let _ = paged.abort(xid);
                            return Err(error);
                        }
                    }
                }
                None => None,
            };
            // No snapshot survives database open, and replay is ordered by
            // commit sequence. Versions superseded by this commit cannot be
            // observed by any future snapshot or needed by a later patch,
            // which reads the current row. Reclaim them now: retaining them
            // makes hot-row replay scan ever-growing histories quadratically.
            apply_committed_tx_write_to_collections(
                collections,
                commit_seq,
                write,
                commit_seq,
                paged_ctx.as_ref(),
            )?;
            replayed_collections.insert(write.collection.clone());
        }
    }
    for (collection, skipped) in dropped_collection_writes {
        eprintln!(
            "[recovery] skipped {skipped} committed write(s) to dropped collection `{collection}`"
        );
    }
    for collection in replayed_collections {
        let state = collections
            .get_mut(&collection)
            .ok_or_else(|| BicDbError::CollectionNotFound(collection.clone()))?
            .get_mut();
        state.rebuild_vector_store();
    }
    Ok(())
}

fn legacy_tx_write_superseded_by_segment(
    collections: &FxHashMap<String, RwLock<CollectionState>>,
    segment_replay: &SegmentReplayIndex,
    write: &TxWrite,
) -> bool {
    if !segment_replay.touched(&write.collection, &write.record_id) {
        return false;
    }

    let final_record = collections.get(&write.collection).and_then(|lock| {
        let state = lock.read();
        let shard = state.shard(&write.record_id).read();
        shard
            .get_record(&write.record_id)
            .map(|entry| Arc::clone(&entry.record))
    });
    match write.op {
        TxWriteOp::Upsert => {
            let Some(record) = write.record_opt() else {
                return false;
            };
            // Compare in the compact form (raw-JSON equality == Value equality).
            let Ok(stored) = StoredRecord::from_record(record) else {
                return false;
            };
            final_record.map(|entry| *entry == stored).unwrap_or(true)
        }
        TxWriteOp::Delete => final_record.is_none(),
    }
}

fn materialize_recovered_patch(
    collections: &FxHashMap<String, RwLock<CollectionState>>,
    segment_replay: &SegmentReplayIndex,
    patch: &TxPatch,
) -> Result<Option<TxWrite>> {
    let after: BTreeMap<String, Box<RawValue>> = serde_json::from_str(patch.after.get())?;
    let before: BTreeMap<String, Box<RawValue>> = serde_json::from_str(patch.before.get())?;
    if before.len() != after.len() || before.keys().ne(after.keys()) {
        return Err(BicDbError::Corruption {
            path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
            message: format!(
                "transaction patch for {}:{} has different before/after keys",
                patch.collection, patch.record_id
            ),
        });
    }
    let keys = after
        .keys()
        .map(|key| Box::<str>::from(key.as_str()))
        .collect::<Vec<_>>();
    let current = collections.get(&patch.collection).and_then(|lock| {
        let state = lock.read();
        let shard = state.shard(&patch.record_id).read();
        shard
            .rowid_of(&patch.record_id)
            .and_then(|rowid| shard.records.get(&rowid))
            .map(|entry| Arc::clone(&entry.record))
    });
    let Some(current) = current else {
        if segment_replay.touched(&patch.collection, &patch.record_id) {
            // A later checkpointed delete supersedes this retained patch.
            return Ok(None);
        }
        return Err(BicDbError::Corruption {
            path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
            message: format!(
                "transaction patch base row is absent: {}:{}",
                patch.collection, patch.record_id
            ),
        });
    };
    let current_values = crate::record::project_json_object_text(current.metadata.get(), &keys)
        .ok_or_else(|| BicDbError::Corruption {
            path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
            message: format!(
                "transaction patch keys are absent from {}:{}",
                patch.collection, patch.record_id
            ),
        })?;
    if current_values == patch.after.get() {
        // The checkpoint already contains this exact update.
        return Ok(None);
    }
    if current_values != patch.before.get() {
        if segment_replay.touched(&patch.collection, &patch.record_id) {
            // The segment contains a later value for at least one patched
            // column, so replaying this older absolute patch would regress it.
            return Ok(None);
        }
        return Err(BicDbError::Corruption {
            path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
            message: format!(
                "transaction patch base mismatch for {}:{}",
                patch.collection, patch.record_id
            ),
        });
    }
    let patches = after
        .iter()
        .map(|(key, value)| (key.as_str(), Some(value.get())))
        .collect::<Vec<_>>();
    let metadata = crate::record::splice_json_object_text(current.metadata.get(), &patches)
        .or_else(|| crate::record::patch_json_object_text(current.metadata.get(), &patches))
        .ok_or_else(|| BicDbError::Corruption {
            path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
            message: format!(
                "transaction patch base is not an object: {}:{}",
                patch.collection, patch.record_id
            ),
        })?;
    let stored = Arc::new(current.with_metadata_text(metadata)?);
    Ok(Some(TxWrite {
        collection: patch.collection.clone(),
        op: TxWriteOp::Upsert,
        record_id: patch.record_id.clone(),
        record: OnceLock::new(),
        timestamp: patch.timestamp,
        statement_snapshot: patch.statement_snapshot,
        repair: None,
        stored: Some(stored),
        previous: None,
        previous_stored: None,
        changed: None,
    }))
}

fn apply_committed_tx_write_to_collections(
    collections: &mut FxHashMap<String, RwLock<CollectionState>>,
    commit_seq: u64,
    write: &TxWrite,
    gc_watermark: u64,
    paged_ctx: Option<&PagedApplyCtx>,
) -> Result<()> {
    // MVCC version stamps are commit_seq values (see VersionedRecord).
    let stamp = TransactionId(commit_seq);
    let state = collections
        .get_mut(&write.collection)
        .ok_or_else(|| BicDbError::CollectionNotFound(write.collection.clone()))?
        .get_mut();
    match write.op {
        TxWriteOp::Upsert => {
            let record = write
                .record()?
                .cloned()
                .ok_or_else(|| BicDbError::Corruption {
                    path: PathBuf::from(DEFAULT_TRANSACTION_LOG),
                    message: "transaction upsert missing record".to_string(),
                })?;
            let mut next_dim = state.meta.vector_dim;
            validate_record(&write.collection, &record, &mut next_dim)?;
            state.meta.vector_dim = next_dim;
            let stored = match paged_ctx {
                Some(ctx) => Arc::new(StoredRecord::evicted_stub(
                    &record,
                    crate::record::EvictedPayload {
                        fetch: Arc::clone(&ctx.post),
                        pk: Arc::from(record.id.as_str()),
                    },
                )),
                None => Arc::new(StoredRecord::from_record(&record)?),
            };
            let paged_lazy = state.paged_lazy;
            let shard = state.shard_mut(&record.id);
            if paged_lazy {
                if let Some(ctx) = paged_ctx {
                    // Replay runs at open, before any plan has seeded the
                    // estimate, so the newness signal has no consumer here.
                    let _ = ctx.seed_baseline(shard, &record.id)?;
                }
            }
            let rowid = shard.rowid_or_alloc(&record.id);
            shard.records.insert(
                rowid,
                RecordEntry {
                    offset: 0,
                    record: stored.clone(),
                },
            );
            apply_versioned_upsert(
                &mut shard.versions,
                &mut shard.pk_to_rowid,
                &mut shard.gc_pending,
                rowid,
                stamp,
                write.timestamp,
                stored,
                gc_watermark,
            );
        }
        TxWriteOp::Delete => {
            let paged_lazy = state.paged_lazy;
            let shard = state.shard_mut(&write.record_id);
            // Lazy first touch: seed the pre-image so old snapshots keep
            // seeing the row this delete removes.
            if paged_lazy {
                if let Some(ctx) = paged_ctx {
                    let _ = ctx.seed_baseline(shard, &write.record_id)?;
                }
            }
            if let Some(rowid) = shard.rowid_of(&write.record_id) {
                shard.records.remove(&rowid);
                apply_versioned_delete(
                    &mut shard.versions,
                    &mut shard.pk_to_rowid,
                    &mut shard.gc_pending,
                    rowid,
                    stamp,
                    gc_watermark,
                );
            }
        }
    }
    // This write was replayed from the WAL and is not yet in the segment, so
    // the next incremental checkpoint must append it — embedded mode only; in
    // paged mode segments carry no rows and a dirty row would make the next
    // checkpoint serialize a stub, which Serialize refuses.
    if paged_ctx.is_none() {
        let shard = state.shard_mut(&write.record_id);
        match write.op {
            TxWriteOp::Upsert => {
                if let Some(rowid) = shard.rowid_of(&write.record_id) {
                    shard.dirty_resident.insert(rowid);
                }
            }
            TxWriteOp::Delete => {
                shard.dirty_unresolved.insert(write.record_id.clone());
            }
        }
    }
    state.generation.fetch_add(1, AtomicOrdering::Relaxed);
    Ok(())
}

fn versions_from_records(records: &RecordMap, tx_id: TransactionId) -> VersionMap {
    records
        .iter()
        .map(|(&rowid, entry)| {
            (
                rowid,
                smallvec::smallvec![VersionedRecord {
                    created_tx: tx_id,
                    deleted_tx: None,
                    timestamp: entry.record.timestamp.unwrap_or_default(),
                    record: entry.record.clone(),
                }],
            )
        })
        .collect()
}

/// Largest transaction id that created or deleted a version of `rowid`.
/// Chains are normally one inline entry (two briefly for an updated row), so
/// deriving the watermark in-cache is cheaper than maintaining another hash
/// table entry for every row and removes a second hash insertion from every
/// fresh insert.
fn version_chain_max_tx(versions: &VersionMap, rowid: RowId) -> u64 {
    versions.get(&rowid).map_or(0, |chain| {
        chain.iter().fold(0, |high, version| {
            high.max(
                version
                    .created_tx
                    .0
                    .max(version.deleted_tx.map_or(0, |deleted| deleted.0)),
            )
        })
    })
}

/// Prunes a single record's version chain of entries that are invisible to every
/// snapshot at or above `watermark` (see [`BicDb::gc_watermark`]). A version is
/// dead for all such snapshots once it has been deleted at or before the
/// watermark (`deleted_tx <= watermark`): for any snapshot `S >= watermark`,
/// `deleted_tx <= watermark <= S` means `visible_version` filters it out. Live
/// versions (and versions deleted strictly after the watermark) are kept, which
/// always retains the version visible at the watermark itself plus all newer.
fn gc_versioned_chain(
    versions: &mut VersionMap,
    pk_to_rowid: &mut FxHashMap<String, RowId>,
    rowid: RowId,
    watermark: u64,
) {
    let Some(chain) = versions.get_mut(&rowid) else {
        return;
    };
    let before = chain.len();
    // Cheap (Arc refcount) handle to recover the primary key if this prune empties
    // the chain — all versions of a key share the same id, so any survivor works.
    let sample = chain.first().map(|version| version.record.clone());
    chain.retain(|version| {
        version
            .deleted_tx
            .map_or(true, |deleted| deleted.0 > watermark)
    });
    if chain.len() == before {
        return;
    }
    if chain.is_empty() {
        versions.remove(&rowid);
        // The key is fully aged out (an emptied chain means the record was deleted
        // and every version aged past the watermark — no live record can remain).
        // Drop its registry entry so a later re-insert allocates a fresh locator,
        // rowid<->pk is bijective for a key's lifetime, so this removes the right
        // entry.
        if let Some(record) = sample {
            pk_to_rowid.remove(record.id.as_str());
        }
    }
}

/// Apply one collection's record/version/vector mutations to `state`, using only
/// shared (`&CollectionState`) access: each record's shard is locked for write
/// individually, the vector store and generation are interior-mutable. Safe to
/// call whether the caller holds the shared collection read guard (common,
/// concurrent path) or the exclusive write guard (the dimension-change path).
fn apply_record_writes_to_state(
    state: &CollectionState,
    writes: &[&TxWrite],
    index_mutations: &[IndexRecordMutation],
    tx_id: TransactionId,
    gc_watermark: u64,
    tx_log_path: &Path,
    // `Some` in paged mode: rows enter the shards as eviction stubs whose bytes
    // stay in the page store, fetched through the ctx's pinned handles on
    // demand. `None` in embedded mode: rows stay fully resident, as before.
    paged_ctx: Option<&PagedApplyCtx>,
) -> Result<RecordApplyOutcome> {
    let mut outcome = RecordApplyOutcome::default();
    for (write, index_mutation) in writes.iter().copied().zip(index_mutations.iter()) {
        match write.op {
            TxWriteOp::Upsert => {
                let missing = || BicDbError::Corruption {
                    path: tx_log_path.to_path_buf(),
                    message: "transaction upsert missing record".to_string(),
                };
                // Compact to the resident form once; the same Arc is shared by the
                // records map and the version chain. In paged mode the resident
                // form is a stub — the page store already holds the bytes (the
                // paged apply ran first), so memory keeps only identity fields.
                // A write buffered in its stored form is applied as-is: no
                // `Value` tree is ever built for it here.
                let stored = match paged_ctx {
                    Some(ctx) => {
                        let record = write.record()?.ok_or_else(missing)?;
                        Arc::new(StoredRecord::evicted_stub(
                            record,
                            crate::record::EvictedPayload {
                                fetch: Arc::clone(&ctx.post),
                                pk: Arc::from(record.id.as_str()),
                            },
                        ))
                    }
                    None => match &write.stored {
                        Some(stored) => Arc::clone(stored),
                        None => {
                            let record = write.record()?.ok_or_else(missing)?;
                            Arc::new(StoredRecord::from_record(record)?)
                        }
                    },
                };
                let record_id = write.record_id.as_str();
                {
                    let mut shard = state.shard(record_id).write();
                    // Reborrow into a plain `&mut Shard` so disjoint fields can
                    // be split-borrowed.
                    let shard = &mut *shard;
                    // Lazy first touch of a pre-existing row: seed its chain
                    // with the pre-image so readers whose snapshot predates
                    // this commit keep seeing the value it replaces. The seed
                    // also answers "is this row NEW?" for free — the planner
                    // row estimate counts exactly first-touch upserts whose
                    // pre-image was absent. Touched rows (chain present) are
                    // updates and move nothing.
                    if state.paged_lazy {
                        if let Some(ctx) = paged_ctx {
                            if ctx.seed_baseline(shard, record_id)? == Some(false) {
                                state.nudge_row_estimate(1);
                            }
                        }
                    }
                    let rowid = shard.rowid_or_alloc(record_id);
                    shard.records.insert(
                        rowid,
                        RecordEntry {
                            offset: 0,
                            record: stored.clone(),
                        },
                    );
                    // Mark dirty so the next incremental checkpoint appends this
                    // record's new value to the segment — embedded mode only.
                    // In paged mode the page store is the durable home for rows
                    // and segments carry none; a dirty pk here would make the
                    // checkpoint serialize a stub, which Serialize refuses.
                    if paged_ctx.is_none() {
                        shard.dirty_resident.insert(rowid);
                    }
                    apply_versioned_upsert(
                        &mut shard.versions,
                        &mut shard.pk_to_rowid,
                        &mut shard.gc_pending,
                        rowid,
                        tx_id,
                        write.timestamp,
                        stored.clone(),
                        gc_watermark,
                    );
                }
                if index_mutation.old_record.has_vector() {
                    outcome.rebuild_vector_store = true;
                } else {
                    state.push_vector_record(&stored);
                }
                outcome.refresh_hnsw |= stored.vector.is_some();
            }
            TxWriteOp::Delete => {
                let removed = {
                    let mut shard = state.shard(&write.record_id).write();
                    let shard = &mut *shard;
                    // Mark dirty so the next incremental checkpoint appends a delete
                    // tombstone for this record to the segment — embedded only,
                    // as above; in paged mode the delete is already durable in
                    // the page store.
                    if paged_ctx.is_none() {
                        shard.dirty_unresolved.insert(write.record_id.clone());
                    }
                    // Lazy first touch: as in the upsert arm, the pre-image
                    // must exist in the chain for old snapshots before the
                    // delete supersedes it — and "pre-image existed" means
                    // this delete removes a live row the estimate counted.
                    if state.paged_lazy {
                        if let Some(ctx) = paged_ctx {
                            if ctx.seed_baseline(shard, &write.record_id)? == Some(true) {
                                state.nudge_row_estimate(-1);
                            }
                        }
                    }
                    match shard.rowid_of(&write.record_id) {
                        Some(rowid) => {
                            let removed = shard.records.remove(&rowid);
                            if removed.is_some() {
                                // A live TOUCHED row (created or updated this
                                // session) leaves the estimate here; untouched
                                // rows left it via the seed signal above.
                                state.nudge_row_estimate(-1);
                            }
                            apply_versioned_delete(
                                &mut shard.versions,
                                &mut shard.pk_to_rowid,
                                &mut shard.gc_pending,
                                rowid,
                                tx_id,
                                gc_watermark,
                            );
                            removed
                        }
                        None => None,
                    }
                };
                if removed
                    .as_ref()
                    .is_some_and(|entry| entry.record.vector.is_some())
                {
                    outcome.rebuild_vector_store = true;
                    outcome.hnsw_tombstones.push(write.record_id.clone());
                }
            }
        }
    }
    Ok(outcome)
}

/// Whether `rowid`'s chain still holds a version that some later watermark
/// will be able to reclaim (deleted, but after the watermark this write used).
fn chain_retains_dead_version(versions: &VersionMap, rowid: RowId) -> bool {
    versions
        .get(&rowid)
        .is_some_and(|chain| chain.iter().any(|version| version.deleted_tx.is_some()))
}

fn apply_versioned_upsert(
    versions: &mut VersionMap,
    pk_to_rowid: &mut FxHashMap<String, RowId>,
    gc_pending: &mut Vec<RowId>,
    rowid: RowId,
    tx_id: TransactionId,
    timestamp: i64,
    record: Arc<StoredRecord>,
    gc_watermark: u64,
) {
    let record_versions = versions.entry(rowid).or_default();
    for version in record_versions
        .iter_mut()
        .filter(|version| version.deleted_tx.is_none())
    {
        version.deleted_tx = Some(tx_id);
    }
    record_versions.push(VersionedRecord {
        created_tx: tx_id,
        deleted_tx: None,
        timestamp,
        record,
    });
    // Incrementally bound the chain: prior versions deleted at or below the GC
    // watermark can never be read again. This keeps hot rows (updated thousands
    // of times) from growing an unbounded chain that every upsert and read scan.
    gc_versioned_chain(versions, pk_to_rowid, rowid, gc_watermark);
    // The version this write superseded is deleted at `tx_id > watermark`, so
    // it always survives here; hand it to the sweeper.
    if chain_retains_dead_version(versions, rowid) {
        gc_pending.push(rowid);
    }
}

fn apply_versioned_delete(
    versions: &mut VersionMap,
    pk_to_rowid: &mut FxHashMap<String, RowId>,
    gc_pending: &mut Vec<RowId>,
    rowid: RowId,
    tx_id: TransactionId,
    gc_watermark: u64,
) {
    if let Some(record_versions) = versions.get_mut(&rowid) {
        for version in record_versions
            .iter_mut()
            .filter(|version| version.deleted_tx.is_none())
        {
            version.deleted_tx = Some(tx_id);
        }
    }
    // The just-deleted version has `deleted_tx = tx_id > watermark` so it is
    // retained; this only reaps older versions that aged below the watermark.
    gc_versioned_chain(versions, pk_to_rowid, rowid, gc_watermark);
    if chain_retains_dead_version(versions, rowid) {
        gc_pending.push(rowid);
    }
}

fn deserialize_stored_batch(
    stored: Vec<Option<Arc<StoredRecord>>>,
) -> Result<Vec<Option<Arc<Record>>>> {
    stored
        .into_iter()
        .map(|opt| match opt {
            Some(stored) => Ok(Some(Arc::new(stored.to_record()?))),
            None => Ok(None),
        })
        .collect()
}

/// Preserve input order while overlapping independent paged-store reads.
/// Ranked retrieval commonly materializes 100 scattered winners; issuing
/// those point reads serially leaves NVMe queue depth at one and makes result
/// projection dominate the already-pruned posting intersection.
fn bounded_parallel_read_map<T, U>(
    inputs: &[T],
    read: impl Fn(&T) -> Result<U> + Sync,
) -> Result<Vec<U>>
where
    T: Sync,
    U: Send,
{
    const MIN_PARALLEL_READS: usize = 8;
    const MAX_READ_WORKERS: usize = 16;
    let workers = std::thread::available_parallelism()
        .map(usize::from)
        .unwrap_or(1)
        .min(MAX_READ_WORKERS)
        .min(inputs.len().max(1));
    if inputs.len() < MIN_PARALLEL_READS || workers == 1 {
        return inputs.iter().map(&read).collect();
    }
    let chunk_size = inputs.len().div_ceil(workers);
    std::thread::scope(|scope| {
        let handles = inputs
            .chunks(chunk_size)
            .map(|chunk| scope.spawn(|| chunk.iter().map(&read).collect::<Result<Vec<_>>>()));
        let mut output = Vec::with_capacity(inputs.len());
        for handle in handles {
            let chunk = handle.join().map_err(|_| {
                BicDbError::Index("parallel paged read worker panicked".to_string())
            })??;
            output.extend(chunk);
        }
        Ok(output)
    })
}

fn visible_version(versions: &[VersionedRecord], tx_id: TransactionId) -> Option<&VersionedRecord> {
    versions
        .iter()
        .filter(|version| {
            version.created_tx <= tx_id
                && version
                    .deleted_tx
                    .map(|deleted_tx| deleted_tx > tx_id)
                    .unwrap_or(true)
        })
        .max_by_key(|version| version.created_tx)
}

#[derive(Debug, Default)]
struct SyncVectorCache {
    vector: SyncVector,
    next_offset: u64,
}

/// Immutable per-query ceilings for full-text execution. `None` = no limit.
/// Wall-clock deadlines ride on the [`CancellationToken`] itself, so a
/// budget carries only work-volume ceilings. Exhaustion is an error
/// (`query_budget_exceeded`), never a silent fallback to a wider scan.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct FtsQueryLimits {
    /// Posting blocks decoded (the page-read proxy for FTS work).
    pub max_posting_blocks: Option<u64>,
    /// Postings materialized/decoded into memory.
    pub max_postings: Option<u64>,
    /// Candidate documents accumulated by a query.
    pub max_candidates: Option<u64>,
    /// Records hydrated from candidate identifiers.
    pub max_hydrated_records: Option<u64>,
}

impl FtsQueryLimits {
    pub const UNLIMITED: Self = Self {
        max_posting_blocks: None,
        max_postings: None,
        max_candidates: None,
        max_hydrated_records: None,
    };
}

/// A live query budget: immutable limits plus running charges plus a
/// cancellation token checked between batches (every 64 charges), so even
/// an in-budget scan stops promptly when the client disconnects or the
/// statement deadline passes.
#[derive(Clone, Debug)]
pub struct FtsQueryBudget {
    limits: FtsQueryLimits,
    cancellation: CancellationToken,
    posting_blocks: u64,
    postings: u64,
    candidates: u64,
    hydrated_records: u64,
    tick: u32,
}

impl FtsQueryBudget {
    pub fn new(limits: FtsQueryLimits, cancellation: CancellationToken) -> Self {
        Self {
            limits,
            cancellation,
            posting_blocks: 0,
            postings: 0,
            candidates: 0,
            hydrated_records: 0,
            tick: 0,
        }
    }

    pub fn unlimited() -> Self {
        Self::new(FtsQueryLimits::UNLIMITED, CancellationToken::uncancelable())
    }

    #[inline]
    fn tick_cancellation(&mut self) -> Result<()> {
        self.tick = self.tick.wrapping_add(1);
        if self.tick & 0x3F == 0 {
            self.cancellation.check()?;
        }
        Ok(())
    }

    #[inline]
    fn charge(
        counter: &mut u64,
        amount: u64,
        limit: Option<u64>,
        resource: &'static str,
    ) -> Result<()> {
        *counter = counter.saturating_add(amount);
        if let Some(limit) = limit {
            if *counter > limit {
                return Err(BicDbError::QueryBudgetExceeded { resource, limit });
            }
        }
        Ok(())
    }

    #[inline]
    pub fn charge_posting_blocks(&mut self, amount: u64) -> Result<()> {
        Self::charge(
            &mut self.posting_blocks,
            amount,
            self.limits.max_posting_blocks,
            "posting_blocks",
        )?;
        self.tick_cancellation()
    }

    #[inline]
    pub fn charge_postings(&mut self, amount: u64) -> Result<()> {
        Self::charge(
            &mut self.postings,
            amount,
            self.limits.max_postings,
            "postings",
        )?;
        self.tick_cancellation()
    }

    #[inline]
    pub fn charge_candidates(&mut self, amount: u64) -> Result<()> {
        Self::charge(
            &mut self.candidates,
            amount,
            self.limits.max_candidates,
            "candidates",
        )?;
        self.tick_cancellation()
    }

    #[inline]
    pub fn charge_hydrated_records(&mut self, amount: u64) -> Result<()> {
        Self::charge(
            &mut self.hydrated_records,
            amount,
            self.limits.max_hydrated_records,
            "hydrated_records",
        )?;
        self.tick_cancellation()
    }
}

/// One side of an unresolved concurrent write, preserved for review. The
/// deterministic projection picks one candidate so replicas converge, but
/// that choice is a projection rule, not a claim of semantic correctness —
/// which is why the losing candidates stay available here.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct RecordConflictCandidate {
    pub event_id: Uuid,
    pub origin_node: NodeId,
    pub origin_sequence: u64,
    pub timestamp: i64,
    pub deleted: bool,
    pub record: Option<Record>,
}

/// A record whose latest writes are genuinely concurrent: no candidate's
/// write context covers the others. Derived deterministically from the audit
/// stream, so every converged replica reports the identical conflict — and a
/// subsequent write made after seeing all candidates clears it everywhere.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct RecordConflict {
    pub collection: String,
    pub record_id: String,
    /// The candidate the deterministic projection currently shows.
    pub projected_event_id: Uuid,
    /// Winner first, then the concurrent alternatives in projection order.
    pub candidates: Vec<RecordConflictCandidate>,
}

fn record_conflict_from_mutations(
    collection: &str,
    record_id: &str,
    mutations: &[AuditMutation],
) -> Option<RecordConflict> {
    let mut frontier = audit_concurrent_frontier(mutations);
    if frontier.len() < 2 {
        return None;
    }
    frontier.sort_by(|a, b| b.order.cmp(&a.order));
    Some(RecordConflict {
        collection: collection.to_string(),
        record_id: record_id.to_string(),
        projected_event_id: frontier[0].event_id,
        candidates: frontier
            .into_iter()
            .map(|mutation| RecordConflictCandidate {
                event_id: mutation.event_id,
                origin_node: mutation.origin_node.clone(),
                origin_sequence: mutation.origin_sequence,
                timestamp: mutation.order.timestamp,
                deleted: matches!(mutation.action, AuditAction::Delete),
                record: match &mutation.action {
                    AuditAction::Upsert(record) => Some(record.clone()),
                    AuditAction::Delete => None,
                },
            })
            .collect(),
    })
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct AuditOrder {
    timestamp: i64,
    sequence: u64,
    node_id: NodeId,
}

#[derive(Clone, Debug)]
struct AuditMutation {
    collection: String,
    record_id: String,
    collection_mode: CollectionMode,
    event_id: Uuid,
    origin_node: NodeId,
    origin_sequence: u64,
    order: AuditOrder,
    /// The writer's per-origin coverage at write time. `None` for events
    /// authored before context stamping (or appended raw): such writes can
    /// still be dominated, but never prove dominance themselves — they
    /// degrade to the concurrent path, which surfaces rather than guesses.
    context: Option<SyncVector>,
    action: AuditAction,
}

/// The maximal concurrent frontier: every mutation not causally dominated by
/// another. Honest contexts cannot produce an empty frontier from a
/// non-empty set (mutual domination would require each write to precede the
/// other); if hand-built contexts ever do, fall back to the full set so the
/// deterministic order still produces a winner instead of losing the record.
fn audit_concurrent_frontier(mutations: &[AuditMutation]) -> Vec<&AuditMutation> {
    // For each origin, retain the two highest context watermarks supplied by
    // different mutations. A candidate is dominated when any *other*
    // mutation's context covers its origin position. This is O(total context
    // entries + mutations), replacing the former O(mutations²) scan.
    let mut coverage = BTreeMap::<String, ((u64, usize), Option<(u64, usize)>)>::new();
    for (index, mutation) in mutations.iter().enumerate() {
        let Some(context) = mutation.context.as_ref() else {
            continue;
        };
        for (origin, sequence) in &context.origins {
            match coverage.get_mut(origin) {
                None => {
                    coverage.insert(origin.clone(), ((*sequence, index), None));
                }
                Some((highest, second)) if *sequence > highest.0 => {
                    *second = Some(*highest);
                    *highest = (*sequence, index);
                }
                Some((highest, second)) if highest.1 != index => {
                    if second.is_none_or(|current| *sequence > current.0) {
                        *second = Some((*sequence, index));
                    }
                }
                Some(_) => {}
            }
        }
    }
    let frontier: Vec<&AuditMutation> = mutations
        .iter()
        .enumerate()
        .filter_map(|(index, candidate)| {
            let origin = candidate.origin_node.to_string();
            let dominated = coverage.get(&origin).is_some_and(|(highest, second)| {
                let other = if highest.1 == index {
                    second.as_ref()
                } else {
                    Some(highest)
                };
                other.is_some_and(|(sequence, _)| *sequence >= candidate.origin_sequence)
            });
            (!dominated).then_some(candidate)
        })
        .collect();
    if frontier.is_empty() {
        return mutations.iter().collect();
    }
    frontier
}

#[cfg(test)]
mod audit_frontier_tests {
    use super::*;

    fn mutation(
        event: u128,
        origin_node: NodeId,
        origin_sequence: u64,
        context: Option<SyncVector>,
    ) -> AuditMutation {
        AuditMutation {
            collection: "records".to_string(),
            record_id: "one".to_string(),
            collection_mode: CollectionMode::Standard,
            event_id: Uuid::from_u128(event),
            origin_node: origin_node.clone(),
            origin_sequence,
            order: AuditOrder {
                timestamp: origin_sequence as i64,
                sequence: origin_sequence,
                node_id: origin_node,
            },
            context,
            action: AuditAction::Delete,
        }
    }

    #[test]
    fn long_causal_history_has_one_frontier_member() {
        let origin = NodeId(Uuid::from_u128(1));
        let mutations = (0..10_000_u64)
            .map(|sequence| {
                let context = (sequence > 0).then(|| {
                    let mut vector = SyncVector::default();
                    vector.observe(&origin, sequence - 1);
                    vector
                });
                mutation(u128::from(sequence) + 1, origin.clone(), sequence, context)
            })
            .collect::<Vec<_>>();
        let frontier = audit_concurrent_frontier(&mutations);
        assert_eq!(frontier.len(), 1);
        assert_eq!(frontier[0].origin_sequence, 9_999);
    }

    #[test]
    fn impossible_mutual_dominance_falls_back_without_losing_data() {
        let left = NodeId(Uuid::from_u128(1));
        let right = NodeId(Uuid::from_u128(2));
        let mut left_context = SyncVector::default();
        left_context.observe(&right, 5);
        let mut right_context = SyncVector::default();
        right_context.observe(&left, 5);
        let mutations = vec![
            mutation(1, left, 5, Some(left_context)),
            mutation(2, right, 5, Some(right_context)),
        ];
        assert_eq!(audit_concurrent_frontier(&mutations).len(), 2);
    }
}

/// The freshest replicated clock observation per unordered origin pair,
/// derived deterministically from [`CLOCK_OBSERVATION_STREAM`] events: every
/// converged replica builds the identical table.
#[derive(Debug, Default)]
struct ClockPairTable {
    entries: BTreeMap<(String, String), ClockPairObservation>,
}

#[derive(Clone, Debug)]
struct ClockPairObservation {
    observer: NodeId,
    /// Peer clock minus observer clock, in milliseconds.
    offset_ms: i64,
    error_ms: i64,
    timestamp: i64,
    event_id: Uuid,
}

impl ClockPairTable {
    fn pair_key(a: &NodeId, b: &NodeId) -> (String, String) {
        let (a, b) = (a.to_string(), b.to_string());
        if a <= b {
            (a, b)
        } else {
            (b, a)
        }
    }

    fn observe(&mut self, observation: ClockPairObservation, peer: &NodeId) {
        let key = Self::pair_key(&observation.observer, peer);
        match self.entries.get(&key) {
            Some(existing)
                if (existing.timestamp, existing.event_id)
                    >= (observation.timestamp, observation.event_id) => {}
            _ => {
                self.entries.insert(key, observation);
            }
        }
    }

    fn between(&self, a: &NodeId, b: &NodeId) -> Option<&ClockPairObservation> {
        self.entries.get(&Self::pair_key(a, b))
    }
}

#[derive(Clone, Debug)]
enum AuditAction {
    Upsert(Record),
    Delete,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct AuditMergeReport {
    records_merged: usize,
    conflicts_resolved: usize,
}

impl AuditMutation {
    fn from_event(owner_node_id: &NodeId, stored: &StoredEvent) -> Result<Option<Self>> {
        Self::from_event_based(owner_node_id, 0, stored)
    }

    fn from_event_based(
        owner_node_id: &NodeId,
        origin_position_base: u64,
        stored: &StoredEvent,
    ) -> Result<Option<Self>> {
        let event = &stored.event;
        if !matches!(
            event.event_type.as_str(),
            "RecordCreated" | "RecordUpdated" | "RecordDeleted"
        ) {
            return Ok(None);
        }
        let collection = event_payload_string(event, "collection")?.to_string();
        let record_id = event_payload_string(event, "record_id")?.to_string();
        let collection_mode = event
            .payload
            .get("collection_mode")
            .cloned()
            .map(serde_json::from_value)
            .transpose()?
            .unwrap_or(CollectionMode::Standard);
        let envelope = envelope_from_metadata(event)?.unwrap_or_else(|| {
            sync_mesh::envelope_for_event_based(owner_node_id, origin_position_base, stored)
                .expect("local event envelope")
        });
        let order = AuditOrder {
            timestamp: envelope.timestamp,
            sequence: envelope.sequence,
            node_id: envelope.node_id.clone(),
        };
        // Tolerate absent or malformed contexts (pre-context data, raw
        // appends): degrading to "concurrent" surfaces a conflict instead of
        // inventing causality.
        let context = event
            .payload
            .get("write_context")
            .and_then(|value| serde_json::from_value::<SyncVector>(value.clone()).ok());
        let action = match event.event_type.as_str() {
            "RecordDeleted" => AuditAction::Delete,
            _ => {
                let record = event
                    .payload
                    .get("record")
                    .cloned()
                    .ok_or_else(|| {
                        BicDbError::ProjectionError(format!(
                            "{} event is missing `record`",
                            event.event_type
                        ))
                    })
                    .and_then(|value| serde_json::from_value(value).map_err(Into::into))?;
                AuditAction::Upsert(record)
            }
        };

        Ok(Some(Self {
            collection,
            record_id,
            collection_mode,
            event_id: event.id,
            origin_node: envelope.node_id,
            origin_sequence: envelope.sequence,
            order,
            context,
            action,
        }))
    }
}

fn verify_integrity_for(
    path: &Path,
    read_mode: SegmentReadMode,
    encryption: &EncryptionRuntime,
    metadata: Option<&EncryptionMetadata>,
    metas: &[CollectionMeta],
) -> Result<IntegrityReport> {
    let mut report = IntegrityReport {
        path: path.to_path_buf(),
        encrypted: metadata.is_some_and(|metadata| metadata.mode == EncryptionMode::Enabled),
        key_version: metadata.map(|metadata| metadata.key_version),
        collections_checked: 0,
        record_frames: 0,
        event_frames: 0,
        sync_frames: 0,
        tx_frames: 0,
        encrypted_frames: 0,
        unencrypted_frames: 0,
        bytes_checked: 0,
        large_value_blobs_checked: 0,
        large_value_bytes_checked: 0,
        large_value_checksum_failures: Vec::new(),
        large_value_orphan_tmp_files: 0,
        paged_storage: None,
    };

    for meta in metas {
        validate_collection_name(&meta.name)?;
        let verification = storage::verify_frames(
            &segment_path_for(path, &meta.name),
            FrameKind::Record,
            read_mode,
            encryption,
        )?;
        report.collections_checked += 1;
        report.record_frames += verification.frame_count;
        add_frame_verification(&mut report, verification);
    }

    let event_verification = storage::verify_frames(
        &event_segment_path_for(path),
        FrameKind::Event,
        read_mode,
        encryption,
    )?;
    report.event_frames += event_verification.frame_count;
    add_frame_verification(&mut report, event_verification);

    let sync_verification = storage::verify_frames(
        &path.join("sync.log"),
        FrameKind::Sync,
        read_mode,
        encryption,
    )?;
    report.sync_frames += sync_verification.frame_count;
    add_frame_verification(&mut report, sync_verification);

    let tx_verification = storage::verify_frames(
        &path.join(DEFAULT_TRANSACTION_LOG),
        FrameKind::Transaction,
        read_mode,
        encryption,
    )?;
    report.tx_frames += tx_verification.frame_count;
    add_frame_verification(&mut report, tx_verification);

    let large_values = large_value::verify_store(path, encryption)?;
    report.large_value_blobs_checked = large_values.blobs_checked;
    report.large_value_bytes_checked = large_values.bytes_checked;
    report.large_value_checksum_failures = large_values.checksum_failures;
    report.large_value_orphan_tmp_files = large_values.orphan_tmp_files;

    Ok(report)
}

fn add_frame_verification(report: &mut IntegrityReport, verification: storage::FrameVerification) {
    report.encrypted_frames += verification.encrypted_frames;
    report.unencrypted_frames += verification.unencrypted_frames;
    report.bytes_checked += verification.bytes_checked;
}

fn load_catalog(path: &Path, encryption: &EncryptionRuntime) -> Result<Vec<CollectionMeta>> {
    let Some(bytes) = read_optional_sidecar(path, FrameKind::Index, encryption)? else {
        return Ok(Vec::new());
    };
    if bytes.is_empty() {
        return Ok(Vec::new());
    }

    let catalog: CollectionCatalog = serde_json::from_slice(&bytes)?;
    for collection in &catalog.collections {
        validate_collection_name(&collection.name)?;
    }
    Ok(catalog.collections)
}

fn load_index_catalog(path: &Path, encryption: &EncryptionRuntime) -> Result<Vec<IndexDefinition>> {
    let Some(bytes) = read_optional_sidecar(path, FrameKind::Index, encryption)? else {
        return Ok(Vec::new());
    };
    if bytes.is_empty() {
        return Ok(Vec::new());
    }

    let catalog: IndexCatalog = serde_json::from_slice(&bytes)?;
    for definition in &catalog.indexes {
        validate_index_definition(definition)?;
    }
    Ok(catalog.indexes)
}

fn load_fts_generation_catalog(path: &Path) -> Result<FtsGenerationCatalog> {
    match fs::read(path) {
        Ok(bytes) if bytes.is_empty() => Ok(FtsGenerationCatalog::default()),
        Ok(bytes) => Ok(serde_json::from_slice(&bytes)?),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            Ok(FtsGenerationCatalog::default())
        }
        Err(error) => Err(error.into()),
    }
}

fn load_planner_stats(path: &Path, encryption: &EncryptionRuntime) -> Result<PlannerStatsCatalog> {
    let Some(bytes) = read_optional_sidecar(path, FrameKind::Index, encryption)? else {
        return Ok(PlannerStatsCatalog::default());
    };
    if bytes.is_empty() {
        return Ok(PlannerStatsCatalog::default());
    }

    Ok(serde_json::from_slice(&bytes)?)
}

fn load_hnsw_indexes(
    path: &Path,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
    paged: Option<&Arc<crate::paged_collection::PagedRecords>>,
    encryption: &EncryptionRuntime,
) -> Result<FxHashMap<String, HnswIndex>> {
    let dir = path.join(DEFAULT_VECTOR_INDEX_DIR);
    if !dir.exists() {
        return Ok(FxHashMap::default());
    }

    let mut indexes = FxHashMap::default();
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("json") {
            continue;
        }
        let Some(file_name) = path.file_name().and_then(|file_name| file_name.to_str()) else {
            continue;
        };
        let Some(collection) = file_name.strip_suffix(".hnsw.json") else {
            continue;
        };
        let Some(state) = collections.get(collection).map(|lock| lock.read()) else {
            continue;
        };
        let bytes = read_immutable_sidecar(&path, storage::FrameKind::Search, encryption)?;
        if bytes.is_empty() {
            continue;
        }
        let persisted: PersistedHnswIndex = serde_json::from_slice(&bytes)?;
        // A lazy paged collection has NO resident rows — its vectors stream
        // from the page store's identity projection (raw f32s under the
        // binary codec). Validating against resident shards here would
        // tombstone every node, exactly the B9 failure shape.
        let vectors = match (&paged, state.paged_lazy) {
            (Some(paged), true) => {
                let snapshot = paged.latest_snapshot();
                let mut vectors = Vec::new();
                for record in paged.scan_identities(&snapshot, collection)? {
                    let record = record?;
                    if let Some(vector) = record.vector {
                        vectors.push(HnswVector {
                            record_id: record.id,
                            vector,
                        });
                    }
                }
                vectors.sort_by(|left, right| left.record_id.cmp(&right.record_id));
                vectors
            }
            _ => hnsw_vectors_from_state(&state),
        };
        let index = HnswIndex::from_persisted(collection, persisted, vectors)?;
        indexes.insert(collection.to_string(), index);
    }
    Ok(indexes)
}

fn hnsw_index_path_for(path: &Path, collection: &str) -> PathBuf {
    path.join(DEFAULT_VECTOR_INDEX_DIR)
        .join(format!("{collection}.hnsw.json"))
}

fn hnsw_vectors_from_state(state: &CollectionState) -> Vec<HnswVector> {
    let mut vectors = state
        .read_all()
        .iter()
        .flat_map(|shard| shard.records.values())
        .filter_map(|entry| {
            entry.record.vector.as_ref().map(|vector| HnswVector {
                record_id: entry.record.id.clone(),
                vector: vector.clone(),
            })
        })
        .collect::<Vec<_>>();
    vectors.sort_by(|left, right| left.record_id.cmp(&right.record_id));
    vectors
}

fn load_graph_projections(
    path: &Path,
    encryption: &EncryptionRuntime,
) -> Result<FxHashMap<String, GraphProjectionData>> {
    let dir = path.join(DEFAULT_GRAPH_DIR);
    if !dir.exists() {
        return Ok(FxHashMap::default());
    }

    let mut graphs = FxHashMap::default();
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("json") {
            continue;
        }
        let bytes = read_immutable_sidecar(&path, storage::FrameKind::Index, encryption)?;
        if bytes.is_empty() {
            continue;
        }
        let graph: GraphProjectionData = serde_json::from_slice(&bytes)?;
        validate_graph_projection_name(&graph.name)?;
        graphs.insert(graph.name.clone(), graph);
    }
    Ok(graphs)
}

fn read_immutable_sidecar(
    path: &Path,
    kind: storage::FrameKind,
    encryption: &EncryptionRuntime,
) -> Result<Vec<u8>> {
    if encryption.bound_object_cipher().is_none() {
        return Ok(fs::read(path)?);
    }
    let recovered = storage::read_frames_strict(path, kind, SegmentReadMode::Buffered, encryption)?;
    if recovered.frames.len() != 1 || recovered.truncated_bytes != 0 {
        return Err(BicDbError::Corruption {
            path: path.to_path_buf(),
            message: "immutable cell-bound sidecar must contain exactly one complete frame"
                .to_string(),
        });
    }
    Ok(recovered.frames.into_iter().next().unwrap().payload)
}

fn read_optional_sidecar(
    path: &Path,
    kind: FrameKind,
    encryption: &EncryptionRuntime,
) -> Result<Option<Vec<u8>>> {
    match fs::symlink_metadata(path) {
        Ok(metadata)
            if encryption.bound_object_cipher().is_some()
                && (metadata.file_type().is_symlink() || !metadata.is_file()) =>
        {
            return Err(BicDbError::Corruption {
                path: path.to_path_buf(),
                message: "cell-bound sidecar must be a regular non-symlink file".to_string(),
            });
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(error.into()),
    }
    read_immutable_sidecar(path, kind, encryption).map(Some)
}

fn write_sidecar(
    path: &Path,
    kind: FrameKind,
    bytes: &[u8],
    fsync: bool,
    encryption: &EncryptionRuntime,
) -> Result<()> {
    if encryption.bound_object_cipher().is_some() {
        storage::write_frame_atomic(path, kind, bytes, fsync, encryption)
    } else {
        storage::write_atomic(path, bytes, fsync)
    }
}

fn graph_projection_path_for(path: &Path, projection: &str) -> PathBuf {
    path.join(DEFAULT_GRAPH_DIR)
        .join(format!("{projection}.graph.json"))
}

fn validate_graph_projection_name(name: &str) -> Result<()> {
    if name.is_empty()
        || !name
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_'))
    {
        return Err(graph_error(format!(
            "invalid graph projection name `{name}`: use ASCII letters, digits, '-' or '_'"
        )));
    }
    Ok(())
}

/// Parallel ordered map used on the open/recovery path to spread the JSON-decode
/// loops (segment record load, index build, sync-log replay) across cores. Splits
/// `items` into contiguous chunks (one per worker), maps each in its own scoped
/// thread, and concatenates the results in input order so order-sensitive folds
/// downstream see the exact same sequence as the sequential version. Falls back to
/// sequential for small inputs; any worker error or panic propagates.
/// Build one shard from its deduped records: allocate a per-shard sequential RowId
/// for each and populate the records / version-chain / pk_to_rowid maps. Every
/// version is stamped with the ancient baseline `TransactionId(0)` (matching the
/// segment-load path); WAL replay later marks the not-yet-in-segment ones dirty.
fn build_one_shard(index: usize, bucket: Vec<Arc<StoredRecord>>) -> Shard {
    let mut shard = Shard::with_index(index);
    shard.records.reserve(bucket.len());
    shard.versions.reserve(bucket.len());
    shard.pk_to_rowid.reserve(bucket.len());
    let mut next_local = 0_u64;
    for record in bucket {
        let rowid = RowId::new(index, next_local);
        next_local += 1;
        shard.pk_to_rowid.insert(record.id.clone(), rowid);
        let timestamp = record.timestamp.unwrap_or_default();
        shard.versions.insert(
            rowid,
            smallvec::smallvec![VersionedRecord {
                created_tx: TransactionId(0),
                deleted_tx: None,
                timestamp,
                record: record.clone(),
            }],
        );
        shard
            .records
            .insert(rowid, RecordEntry { offset: 0, record });
    }
    shard.next_local = next_local;
    shard
}

/// Build a collection's [`SHARD_COUNT`] shards from its deduped live records,
/// spreading the per-record work (RowId allocation + version-chain `Vec` + map
/// inserts — the dominant open-time cost, ~3s on the 16wh seed) across cores. A
/// record lives in shard `hash(pk) % SHARD_COUNT`, so shards are independent: we
/// partition once (cheap hashing), then build each shard in isolation on a worker
/// and reassemble in canonical index order. Used by every open path (snapshot fused,
/// snapshot tail-merge, and full JSON segment decode).
fn build_shards_parallel(records: Vec<Arc<StoredRecord>>) -> Result<Vec<Shard>> {
    let total = records.len();
    let mut buckets: Vec<Vec<Arc<StoredRecord>>> = (0..SHARD_COUNT).map(|_| Vec::new()).collect();
    for record in records {
        let idx = shard_index(&record.id);
        buckets[idx].push(record);
    }

    let nthreads = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
        .min(SHARD_COUNT);
    if nthreads <= 1 || total < 4096 {
        return Ok(buckets
            .into_iter()
            .enumerate()
            .map(|(index, bucket)| build_one_shard(index, bucket))
            .collect());
    }

    // Move contiguous (index, bucket) groups into worker threads so each thread owns
    // its buckets (no per-record id clone for sharing); reassemble by index.
    let chunk = SHARD_COUNT.div_ceil(nthreads);
    let mut indexed: Vec<(usize, Vec<Arc<StoredRecord>>)> =
        buckets.into_iter().enumerate().collect();
    let mut groups: Vec<Vec<(usize, Vec<Arc<StoredRecord>>)>> = Vec::new();
    while !indexed.is_empty() {
        let take = chunk.min(indexed.len());
        groups.push(indexed.drain(..take).collect());
    }

    let mut built: Vec<Option<Shard>> = (0..SHARD_COUNT).map(|_| None).collect();
    std::thread::scope(|scope| -> Result<()> {
        let handles: Vec<_> = groups
            .into_iter()
            .map(|group| {
                scope.spawn(move || {
                    group
                        .into_iter()
                        .map(|(index, bucket)| (index, build_one_shard(index, bucket)))
                        .collect::<Vec<(usize, Shard)>>()
                })
            })
            .collect();
        for handle in handles {
            let part = handle.join().map_err(|_| {
                BicDbError::Index("parallel shard build worker panicked".to_string())
            })?;
            for (index, shard) in part {
                built[index] = Some(shard);
            }
        }
        Ok(())
    })?;

    Ok(built
        .into_iter()
        .map(|shard| shard.expect("every shard index built"))
        .collect())
}

pub(crate) fn parallel_map_ordered<T, R, F>(items: &[T], f: F) -> Result<Vec<R>>
where
    T: Sync,
    R: Send,
    F: Fn(&T) -> Result<R> + Sync,
{
    let len = items.len();
    if len == 0 {
        return Ok(Vec::new());
    }
    let nthreads = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
        .min(len);
    if nthreads <= 1 || len < 2048 {
        return items.iter().map(&f).collect();
    }
    let chunk = len.div_ceil(nthreads);
    std::thread::scope(|scope| {
        let f = &f;
        let handles: Vec<_> = items
            .chunks(chunk)
            .map(|c| scope.spawn(move || c.iter().map(f).collect::<Result<Vec<R>>>()))
            .collect();
        let mut out = Vec::with_capacity(len);
        for handle in handles {
            let part = handle.join().map_err(|_| {
                BicDbError::Index("parallel recovery worker panicked".to_string())
            })??;
            out.extend(part);
        }
        Ok(out)
    })
}

fn build_indexes(
    definitions: Vec<IndexDefinition>,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
) -> Result<FxHashMap<String, IndexState>> {
    build_indexes_with_paged(definitions, collections, None, None, None, None)
}

struct PagedFullTextOpenState {
    read_through_ready: bool,
    registry_required: bool,
    empty_sentinel_candidate: bool,
    metadata_probes: u64,
}

fn paged_full_text_open_state(
    paged: &Arc<crate::paged_collection::PagedRecords>,
    snapshot: &bicdb_page::Snapshot,
    index: &str,
) -> Result<PagedFullTextOpenState> {
    let statistics = paged.full_text_collection_statistics(snapshot, index)?;
    let complete = paged.index_v2_complete(snapshot, index)?;
    if let Some(statistics) = statistics.as_ref().filter(|statistics| {
        crate::fts_format::full_text_generation_format_is_readable(statistics.format_version)
    }) {
        if !complete {
            return Ok(PagedFullTextOpenState {
                read_through_ready: false,
                registry_required: true,
                empty_sentinel_candidate: false,
                metadata_probes: 2,
            });
        }
        if statistics.document_count == 0
            || paged
                .full_text_pk_for_document_id(snapshot, index, 0)?
                .is_some()
        {
            return Ok(PagedFullTextOpenState {
                read_through_ready: true,
                registry_required: false,
                empty_sentinel_candidate: false,
                metadata_probes: 2 + u64::from(statistics.document_count != 0),
            });
        }
        // A format-v2 statistics record without the required dense mapping is
        // an interrupted or pre-release generation. Rebuild it from rows
        // instead of trusting numeric blocks that cannot resolve results.
        return Ok(PagedFullTextOpenState {
            read_through_ready: false,
            registry_required: true,
            empty_sentinel_candidate: false,
            metadata_probes: 3,
        });
    }

    let has_blocks = paged.index_has_any_posting_blocks(snapshot, index)?;
    if has_blocks && !complete {
        // A crash may have left only a prefix of the immutable blocks.
        return Ok(PagedFullTextOpenState {
            read_through_ready: false,
            registry_required: true,
            empty_sentinel_candidate: false,
            metadata_probes: 3,
        });
    }
    let has_entries = paged.index_has_entries(snapshot, index)?;
    Ok(PagedFullTextOpenState {
        // A sentinel by itself is not evidence that a pre-format-v2 index
        // covers a now-nonempty collection. Durable entries or blocks are.
        read_through_ready: has_blocks || has_entries,
        // Legacy PK postings remain read-through but core RowId APIs and
        // index verification still need the compact registry.
        registry_required: true,
        empty_sentinel_candidate: complete && !has_blocks && !has_entries,
        metadata_probes: 4,
    })
}

fn build_indexes_with_paged(
    definitions: Vec<IndexDefinition>,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
    paged: Option<&Arc<crate::paged_collection::PagedRecords>>,
    paged_fts_read_through_indexes: Option<&FxHashSet<String>>,
    paged_fts_incomplete_build_indexes: Option<&FxHashSet<String>>,
    db_path: Option<&Path>,
) -> Result<FxHashMap<String, IndexState>> {
    let mut indexes = FxHashMap::default();
    for definition in definitions {
        // Paged mode, B-tree kind: the durable entries written at commit time
        // (Phase 4a) ARE the index — load them directly instead of recomputing
        // every key from every row. The rebuild path costs a full-record fetch
        // and a JSON parse per row (each resident entry is an eviction stub);
        // the load path costs one ordered walk of the index's own key range
        // and no row reads at all. This is also what makes the durable entries
        // load-bearing rather than a write-only mirror.
        if let (Some(paged), IndexKind::FullText) = (paged, &definition.kind) {
            if paged_fts_incomplete_build_indexes
                .is_some_and(|building| building.contains(&definition.name))
            {
                indexes.insert(
                    definition.name.clone(),
                    IndexState {
                        definition,
                        store: new_index_store(),
                        spatial: None,
                        packed_spatial: None,
                        spatial_tombstones: FxHashSet::default(),
                        spatial_delta_durable: false,
                        paged_read_through: false,
                        // Empty store, nothing durable to read through. Marked
                        // so lookups refuse rather than answer "no matches".
                        full_text_build_incomplete: true,
                    },
                );
                continue;
            }
            // READ-THROUGH: durable FTS postings are not loaded at open — the
            // resident store stays EMPTY and lookups range-scan the durable
            // keyspace through the buffer pool. This is what removes the
            // resident-postings memory wall for larger-than-RAM corpora
            // (bulk-loading 40M documents' postings is hundreds of GB of
            // heap; the pages are already on disk).
            // Blocks are only trustworthy once the backfill or fold that
            // wrote them committed its completeness sentinel LAST. A crash
            // mid direct-to-blocks backfill leaves partial blocks; serving
            // them read-through would silently drop documents, so such an
            // index falls back to the resident rebuild below until it is
            // recreated.
            // Pre-upgrade probe: entries absent while rows exist means the
            // index predates durable FTS entries — rebuild resident from
            // page rows, as before (repeats every open until recreated).
            if paged_fts_read_through_indexes.is_some_and(|ready| ready.contains(&definition.name))
            {
                indexes.insert(
                    definition.name.clone(),
                    IndexState {
                        definition,
                        store: new_index_store(),
                        spatial: None,
                        packed_spatial: None,
                        spatial_tombstones: FxHashSet::default(),
                        spatial_delta_durable: false,
                        paged_read_through: true,
                        full_text_build_incomplete: false,
                    },
                );
                continue;
            }
            let collection_state = collections
                .get(&definition.collection)
                .ok_or_else(|| BicDbError::CollectionNotFound(definition.collection.clone()))?
                .read();
            let (state, _live_rows) =
                paged_index_state_from_rows(&definition, &collection_state, paged)?;
            drop(collection_state);
            indexes.insert(state.definition.name.clone(), state);
            continue;
        }
        // Streamed spatial on a still-lazy collection: rebuild the R-tree
        // from an identity scan of the page store. The resident-shard rebuild
        // below would silently produce an EMPTY tree — lazy shards hold no
        // rows.
        if definition.kind == IndexKind::Spatial
            && definition.predicate.is_none()
            && matches!(definition.fields.first(), Some(IndexField::Geometry))
        {
            if let Some(paged) = paged {
                // A pack build in flight owns its workspace and its node
                // generation. Its checkpoint resumes only if the store
                // horizon is untouched, so open must neither sweep its nodes
                // nor commit anything on its behalf.
                let in_flight_generation = db_path.and_then(|db_path| {
                    crate::spatial_pack_build::SpatialPackWorkspace::active_generation(
                        db_path,
                        &definition.name,
                    )
                });
                // A published packed base wins outright: open loads the meta
                // and the delta tail, lazy or not — never the corpus.
                if let Some(state) = packed_spatial_index_state(&definition, paged)? {
                    // Sweep generations an interrupted pack left behind (the
                    // published one is the only generation anything reads;
                    // an in-flight re-pack keeps its own).
                    let mut keep: Vec<u64> = state
                        .packed_spatial
                        .as_ref()
                        .map(|meta| vec![meta.generation])
                        .unwrap_or_default();
                    keep.extend(in_flight_generation);
                    if in_flight_generation.is_none() {
                        sweep_stale_spatial_generations(paged, &definition.name, &keep)?;
                    }
                    indexes.insert(state.definition.name.clone(), state);
                    continue;
                }
                if in_flight_generation.is_some() {
                    // First pack interrupted mid-build: DO NOT stream-build
                    // the resident tree — that corpus-sized build is the OOM
                    // the packed pipeline exists to avoid. Load an empty
                    // state; re-running the pack resumes the checkpoint and
                    // publishes. Queries are incomplete until then, the same
                    // contract as during the original build. Delta rows KEEP
                    // being written (spatial_delta_durable): they mask every
                    // pk touched after the interrupted scan, which is what
                    // makes the eventual resume sound.
                    indexes.insert(
                        definition.name.clone(),
                        IndexState {
                            definition,
                            store: new_index_store(),
                            spatial: Some(RTree::new()),
                            packed_spatial: None,
                            spatial_tombstones: FxHashSet::default(),
                            spatial_delta_durable: true,
                            paged_read_through: false,
                            full_text_build_incomplete: false,
                        },
                    );
                    continue;
                }
                // No published base, no build in flight: any node generation
                // on disk is a crash-orphaned side-build — delete it all.
                sweep_stale_spatial_generations(paged, &definition.name, &[])?;
                let lazy = collections
                    .get(&definition.collection)
                    .is_some_and(|state| state.read().paged_lazy);
                if lazy {
                    let (state, _entries) = paged_spatial_index_state(&definition, paged)?;
                    indexes.insert(state.definition.name.clone(), state);
                    continue;
                }
            }
        }
        if let (Some(paged), IndexKind::BTree) = (paged, &definition.kind) {
            if paged_fts_read_through_indexes.is_some_and(|ready| ready.contains(&definition.name))
            {
                indexes.insert(
                    definition.name.clone(),
                    IndexState {
                        definition,
                        store: new_index_store(),
                        spatial: None,
                        packed_spatial: None,
                        spatial_tombstones: FxHashSet::default(),
                        spatial_delta_durable: false,
                        paged_read_through: true,
                        full_text_build_incomplete: false,
                    },
                );
                continue;
            }
            match load_paged_btree_index(definition, collections, paged)? {
                LoadedPagedIndex::Loaded(state) => {
                    indexes.insert(state.definition.name.clone(), state);
                    continue;
                }
                // A database indexed before durable entries existed has none
                // to load; rebuild from the PAGE STORE's rows. Resident shards
                // are not a substitute source: in registry mode they hold no
                // rows, and an index rebuilt from them would be silently
                // empty. The entries stay durably incomplete until the index
                // is recreated, so this fallback repeats at every open —
                // correct, just not fast.
                LoadedPagedIndex::NoDurableEntries(definition) => {
                    let collection_state = collections
                        .get(&definition.collection)
                        .ok_or_else(|| {
                            BicDbError::CollectionNotFound(definition.collection.clone())
                        })?
                        .read();
                    let (state, _live_rows) =
                        paged_index_state_from_rows(&definition, &collection_state, paged)?;
                    drop(collection_state);
                    indexes.insert(state.definition.name.clone(), state);
                    continue;
                }
            }
        }
        let state = build_index_state(definition, collections)?;
        indexes.insert(state.definition.name.clone(), state);
    }
    Ok(indexes)
}

/// Build a resident B-tree [`IndexState`] from its durable paged entries:
/// `(encoded key, pk)` pairs from the reserved keyspace, with each pk resolved
/// to its already-built resident rowid. No row bytes are read.
/// Recompute a B-tree index's expected content from the page store, for
/// verifying a registry-mode collection (whose shards hold no rows to
/// recompute from). Rowids come from the same registry the live index uses,
/// so entries compare like-for-like.
fn build_index_state_for_verify_from_paged(
    definition: &IndexDefinition,
    db: &BicDb,
    paged: &Arc<crate::paged_collection::PagedRecords>,
) -> Result<(IndexState, usize)> {
    let state = db.collection_state(&definition.collection)?;
    paged_index_state_from_rows(definition, &state, paged)
}

/// Build a resident [`IndexState`] for a durable-kind index by scanning the
/// PAGE STORE's rows (not resident shards, which hold nothing in registry
/// mode). Rowids resolve through the collection's registry. Used by verify
/// and by the open-time fallback for indexes that predate durable entries.
/// Build a resident spatial [`IndexState`] by streaming *identity* rows
/// (id + geometry, metadata lexed past) from the page store. The collection
/// stays lazy: R-tree entries are (pk, rect), and query results resolve
/// through the paged fallback like any other lazy read. Peak memory is the
/// entry vector plus the tree — not the corpus.
///
/// Returns the state and the number of entries indexed.
/// Delete every packed-node generation of `index` except `keep` (`None`
/// deletes them all): crash-orphaned side-builds from an interrupted pack.
/// A pack OOM-killed mid-build leaves committed node batches under an
/// unpublished generation — invisible to every reader and potentially many
/// GiB — so open sweeps them instead of waiting for the next successful pack
/// or DROP INDEX. Batched deletes, bounded WAL per transaction.
fn sweep_stale_spatial_generations(
    paged: &Arc<crate::paged_collection::PagedRecords>,
    index: &str,
    keep: &[u64],
) -> Result<usize> {
    const SWEEP_BATCH_ENTRIES: usize = 8_192;
    const SWEEP_BATCH_BYTES: usize = 64 * 1024 * 1024;
    let physical = paged.resolve_index_name(index);
    let mut removed = 0usize;
    for generation in paged.spatial_node_generations(&paged.latest_snapshot(), index)? {
        if keep.contains(&generation) {
            continue;
        }
        let prefix = crate::paged_collection::spatial_generation_prefix(&physical, generation);
        // The cursor advances past every visited key: a deleted key can stay
        // visible as a dead historical entry, so restarting from the prefix
        // would spin forever on the first batch.
        let mut after = None::<Vec<u8>>;
        loop {
            let snapshot = paged.latest_snapshot();
            let keys = paged.raw_keys_with_prefix_batch_after(
                &snapshot,
                &prefix,
                after.as_deref(),
                SWEEP_BATCH_ENTRIES,
                SWEEP_BATCH_BYTES,
            )?;
            if keys.is_empty() {
                break;
            }
            after = keys.last().cloned();
            let (xid, _) = paged.begin();
            let mut apply = || -> Result<()> {
                for key in &keys {
                    paged.delete_raw(xid, key)?;
                }
                Ok(())
            };
            match apply() {
                Ok(()) => paged.commit(xid)?,
                Err(error) => {
                    let _ = paged.abort(xid);
                    return Err(error);
                }
            }
            removed += keys.len();
        }
    }
    Ok(removed)
}

/// Resident state for a spatial index with a PUBLISHED PACKED BASE: the meta
/// plus a delta tree and tombstone set rebuilt from the durable delta tail.
/// Open cost is the delta scan — never the corpus. `None` when no packed
/// generation has been published (callers fall through to the streamed or
/// resident build).
fn packed_spatial_index_state(
    definition: &IndexDefinition,
    paged: &Arc<crate::paged_collection::PagedRecords>,
) -> Result<Option<IndexState>> {
    let snapshot = paged.latest_snapshot();
    let Some(bytes) = paged.spatial_meta(&snapshot, &definition.name)? else {
        return Ok(None);
    };
    let meta = PackedSpatialMeta::decode(&bytes)?;
    let mut tombstones = FxHashSet::default();
    let mut delta = Vec::new();
    for entry in paged.scan_spatial_delta(&snapshot, &definition.name)? {
        let (pk, value) = entry?;
        if let Some((min, max, point)) = spatial_packed::decode_delta(&value)? {
            delta.push(SpatialIndexEntry {
                record_id: pk.clone(),
                envelope: AABB::from_corners(min, max),
                point,
            });
        }
        tombstones.insert(pk);
    }
    Ok(Some(IndexState {
        definition: definition.clone(),
        store: new_index_store(),
        spatial: Some(RTree::bulk_load(delta)),
        packed_spatial: Some(meta),
        spatial_tombstones: tombstones,
        spatial_delta_durable: true,
        paged_read_through: false,
        full_text_build_incomplete: false,
    }))
}

fn paged_spatial_index_state(
    definition: &IndexDefinition,
    paged: &Arc<crate::paged_collection::PagedRecords>,
) -> Result<(IndexState, usize)> {
    let field = definition
        .fields
        .first()
        .ok_or_else(|| BicDbError::Index("spatial index requires a field".to_string()))?;
    let snapshot = paged.latest_snapshot();
    let mut entries: Vec<SpatialIndexEntry> = Vec::new();
    for record in paged.scan_identities(&snapshot, &definition.collection)? {
        let record = record?;
        if let Some(geometry) = record_spatial_geometry(&record, field)? {
            entries.push(spatial_index_entry(record.id.clone(), &geometry)?);
        }
    }
    let indexed = entries.len();
    Ok((
        IndexState {
            definition: definition.clone(),
            store: new_index_store(),
            spatial: Some(RTree::bulk_load(entries)),
            packed_spatial: None,
            spatial_tombstones: FxHashSet::default(),
            spatial_delta_durable: false,
            paged_read_through: false,
            full_text_build_incomplete: false,
        },
        indexed,
    ))
}

fn paged_index_state_from_rows(
    definition: &IndexDefinition,
    state: &CollectionState,
    paged: &Arc<crate::paged_collection::PagedRecords>,
) -> Result<(IndexState, usize)> {
    let index = IndexState {
        definition: definition.clone(),
        store: new_index_store(),
        spatial: None,
        packed_spatial: None,
        spatial_tombstones: FxHashSet::default(),
        spatial_delta_durable: false,
        paged_read_through: false,
        full_text_build_incomplete: false,
    };
    let snapshot = paged.latest_snapshot();
    let mut entries: Vec<(Vec<u8>, RowId)> = Vec::new();
    let mut live_rows = 0usize;
    for record in paged.scan(&snapshot, &definition.collection)? {
        let record = record?;
        let Some(rowid) = state.shard(&record.id).read().rowid_of(&record.id) else {
            // A row in the page store that the registry does not know is a
            // divergence verify exists to surface; an absent rowid would hide
            // it, so surface it as a mismatch by synthesizing nothing.
            continue;
        };
        match definition.kind {
            IndexKind::FullText => {
                // Bulk-built rows carry no in-row projection: their expected
                // terms come from the index's doc-terms blob, same source the
                // UPDATE/DELETE diff uses.
                let (postings, _) =
                    full_text_diff_postings(paged, &definition.name, &definition.fields, &record)?;
                let terms: Vec<String> = postings.into_iter().map(|(term, _)| term).collect();
                // `indexed_records` for full-text counts DISTINCT ROWIDS, and a
                // row with an empty projection contributes none — count live
                // rows the same way or empty rows read as missing entries.
                if !terms.is_empty() {
                    live_rows += 1;
                }
                for term in terms {
                    entries.push((full_text_term_entry_key(&term), rowid));
                }
            }
            _ => {
                if !record_matches_index_predicate(&record, definition)? {
                    continue;
                }
                live_rows += 1;
                let key = encode_index_key(&record_index_key(&record, &definition.fields));
                entries.push((key, rowid));
            }
        }
    }
    index.store.bulk_load(entries);
    Ok((index, live_rows))
}

enum LoadedPagedIndex {
    Loaded(IndexState),
    /// The durable keyspace has no entries for this index while the collection
    /// has rows — a pre-Phase-4a database. The definition is handed back for
    /// the rebuild path.
    NoDurableEntries(IndexDefinition),
}

fn load_paged_btree_index(
    definition: IndexDefinition,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
    paged: &Arc<crate::paged_collection::PagedRecords>,
) -> Result<LoadedPagedIndex> {
    validate_index_definition(&definition)?;
    let state = collections
        .get(&definition.collection)
        .ok_or_else(|| BicDbError::CollectionNotFound(definition.collection.clone()))?
        .read();
    let index = IndexState {
        definition,
        store: new_index_store(),
        spatial: None,
        packed_spatial: None,
        spatial_tombstones: FxHashSet::default(),
        spatial_delta_durable: false,
        paged_read_through: false,
        full_text_build_incomplete: false,
    };
    let snapshot = paged.latest_snapshot();
    let mut entries: Vec<(Vec<u8>, RowId)> = Vec::new();
    for entry in paged.scan_index(&snapshot, &index.definition.name)? {
        let (encoded_key, pk) = entry?;
        // A pk in the durable index without a resident rowid means the stub
        // bootstrap and the index disagree about which rows exist — corruption
        // worth failing open over, not skipping past.
        let rowid =
            state
                .shard(&pk)
                .read()
                .rowid_of(&pk)
                .ok_or_else(|| BicDbError::Corruption {
                    path: PathBuf::from(DEFAULT_PAGED_DIR),
                    message: format!(
                        "durable index `{}` references `{pk}`, which has no resident row",
                        index.definition.name
                    ),
                })?;
        entries.push((encoded_key, rowid));
    }
    let registered_rows: usize = state
        .read_all()
        .iter()
        .map(|shard| shard.pk_to_rowid.len())
        .sum();
    if entries.is_empty() && registered_rows > 0 {
        return Ok(LoadedPagedIndex::NoDurableEntries(index.definition));
    }
    index.store.bulk_load(entries);
    Ok(LoadedPagedIndex::Loaded(index))
}

fn build_index_state(
    definition: IndexDefinition,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
) -> Result<IndexState> {
    build_index_state_with_options(definition, collections, true)
}

fn build_index_state_for_verify(
    definition: IndexDefinition,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
) -> Result<IndexState> {
    build_index_state_with_options(definition, collections, false)
}

fn build_index_state_with_options(
    definition: IndexDefinition,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
    enforce_unique: bool,
) -> Result<IndexState> {
    validate_index_definition(&definition)?;
    let state = collections
        .get(&definition.collection)
        .ok_or_else(|| BicDbError::CollectionNotFound(definition.collection.clone()))?
        .read();
    let mut index = IndexState {
        definition,
        store: new_index_store(),
        spatial: None,
        packed_spatial: None,
        spatial_tombstones: FxHashSet::default(),
        spatial_delta_durable: false,
        paged_read_through: false,
        full_text_build_incomplete: false,
    };
    match index.definition.kind {
        IndexKind::BTree => {
            // Collect (rowid, record) refs under the shard read locks, then decode
            // (to_record JSON parse + key encode) across all cores. Insertion into
            // the single store stays sequential.
            let trace = std::env::var("BICDB_INDEX_TRACE").is_ok();
            let t0 = std::time::Instant::now();
            let mut entries: Vec<(RowId, Arc<StoredRecord>)> = Vec::new();
            for shard in state.read_all() {
                entries.reserve(shard.records.len());
                for (&rowid, entry) in shard.records.iter() {
                    entries.push((rowid, entry.record.clone()));
                }
            }
            let t_gather = t0.elapsed();
            let encoded = parallel_map_ordered(&entries, |(rowid, record)| {
                let record = record.to_record()?;
                if !record_matches_index_predicate(&record, &index.definition)? {
                    return Ok(None);
                }
                let key = record_index_key(&record, &index.definition.fields);
                Ok(Some((encode_index_key(&key), *rowid)))
            })?
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
            let t_parse = t0.elapsed();
            let encoded_len = encoded.len();
            index.store.bulk_load(encoded);
            let t_insert = t0.elapsed();
            let mut has_duplicate = false;
            index.store.scan_from(&[], &mut |key, ids| {
                if ids.count() > 1 && !index_key_contains_null(&decode_index_key(key)) {
                    has_duplicate = true;
                    return false;
                }
                true
            });
            if trace {
                let t_scan = t0.elapsed();
                eprintln!(
                    "[index_trace] {:<28} n={:>8} gather={:>6.3} parse={:>6.3} insert={:>6.3} scan={:>6.3}",
                    index.definition.name,
                    encoded_len,
                    t_gather.as_secs_f64(),
                    (t_parse - t_gather).as_secs_f64(),
                    (t_insert - t_parse).as_secs_f64(),
                    (t_scan - t_insert).as_secs_f64(),
                );
            }
            if enforce_unique && index.definition.unique && has_duplicate {
                return Err(BicDbError::Index(format!(
                    "unique index `{}` has duplicate keys",
                    index.definition.name
                )));
            }
        }
        IndexKind::FullText | IndexKind::Jsonb | IndexKind::Array => {
            let fields = &index.definition.fields;
            let mut entries: Vec<(RowId, Arc<StoredRecord>)> = Vec::new();
            for shard in state.read_all() {
                entries.reserve(shard.records.len());
                for (&rowid, entry) in shard.records.iter() {
                    entries.push((rowid, entry.record.clone()));
                }
            }
            let encoded = parallel_map_ordered(&entries, |(rowid, record)| {
                Ok(record_full_text_terms(&record.to_record()?, fields)?
                    .into_iter()
                    .map(|term| (encode_index_key(&[IndexValue::String(term)]), *rowid))
                    .collect::<Vec<_>>())
            })?
            .into_iter()
            .flatten()
            .collect();
            index.store.bulk_load(encoded);
        }
        IndexKind::Spatial => {
            let field = index
                .definition
                .fields
                .first()
                .expect("validated spatial field");
            let mut records: Vec<Arc<StoredRecord>> = Vec::new();
            for shard in state.read_all() {
                records.reserve(shard.records.len());
                for entry in shard.records.values() {
                    records.push(entry.record.clone());
                }
            }
            let entries: Vec<_> = parallel_map_ordered(&records, |record| {
                match record_spatial_geometry(&record.to_record()?, field)? {
                    Some(geometry) => Ok(Some(spatial_index_entry(record.id.clone(), &geometry)?)),
                    None => Ok(None),
                }
            })?
            .into_iter()
            .flatten()
            .collect();
            index.spatial = Some(RTree::bulk_load(entries));
        }
    }
    Ok(index)
}

fn verify_index_state(
    state: &IndexState,
    expected: &IndexState,
    collections: &FxHashMap<String, RwLock<CollectionState>>,
) -> Result<IndexVerifyReport> {
    let collection = collections
        .get(&state.definition.collection)
        .ok_or_else(|| BicDbError::CollectionNotFound(state.definition.collection.clone()))?
        .read();
    let indexed_records = match state.definition.kind {
        IndexKind::BTree => state.store.total_entries(),
        IndexKind::FullText | IndexKind::Jsonb | IndexKind::Array => {
            full_text_index_rowids(state).len()
        }
        IndexKind::Spatial => state.spatial.as_ref().map(RTree::size).unwrap_or_default(),
    };
    let expected_records = match state.definition.kind {
        IndexKind::BTree if state.definition.predicate.is_some() => expected.store.total_entries(),
        IndexKind::FullText | IndexKind::Jsonb | IndexKind::Array => {
            full_text_index_rowids(expected).len()
        }
        _ => collection.record_count(),
    };
    let (missing_entries, stale_entries, duplicate_entries, wrong_entries) =
        diff_index_state(state, expected);
    let valid = indexed_records == expected_records
        && missing_entries == 0
        && stale_entries == 0
        && duplicate_entries == 0
        && wrong_entries == 0;
    Ok(IndexVerifyReport {
        index_name: state.definition.name.clone(),
        collection: state.definition.collection.clone(),
        kind: state.definition.kind.clone(),
        indexed_records,
        expected_records,
        missing_entries,
        stale_entries,
        duplicate_entries,
        wrong_entries,
        size_bytes: index_state_size_bytes(state),
        last_verified_unix_ms: None,
        valid,
    })
}

fn diff_index_state(state: &IndexState, expected: &IndexState) -> (usize, usize, usize, usize) {
    match state.definition.kind {
        IndexKind::BTree => {
            let actual_entries = flatten_btree_index_entries(state.store.as_ref());
            let expected_entries = flatten_btree_index_entries(expected.store.as_ref());
            let missing_entries = expected_entries.difference(&actual_entries).count();
            let stale_entries = actual_entries.difference(&expected_entries).count();
            let duplicate_entries = if state.definition.unique {
                let mut dups = 0usize;
                state.store.scan_from(&[], &mut |key, ids| {
                    if !index_key_contains_null(&decode_index_key(key)) {
                        dups += ids.count().saturating_sub(1);
                    }
                    true
                });
                dups
            } else {
                0
            };
            let wrong_entries = if missing_entries == 0 && stale_entries == 0 {
                0
            } else {
                missing_entries.max(stale_entries)
            };
            (
                missing_entries,
                stale_entries,
                duplicate_entries,
                wrong_entries,
            )
        }
        IndexKind::FullText | IndexKind::Jsonb | IndexKind::Array => {
            let actual_entries = flatten_btree_index_entries(state.store.as_ref());
            let expected_entries = flatten_btree_index_entries(expected.store.as_ref());
            let missing_entries = expected_entries.difference(&actual_entries).count();
            let stale_entries = actual_entries.difference(&expected_entries).count();
            let wrong_entries = missing_entries.max(stale_entries);
            (missing_entries, stale_entries, 0, wrong_entries)
        }
        IndexKind::Spatial => {
            let actual_entries = flatten_spatial_index_entries(state);
            let expected_entries = flatten_spatial_index_entries(expected);
            let missing_entries = expected_entries.difference(&actual_entries).count();
            let stale_entries = actual_entries.difference(&expected_entries).count();
            let wrong_entries = if missing_entries == 0 && stale_entries == 0 {
                0
            } else {
                missing_entries.max(stale_entries)
            };
            (missing_entries, stale_entries, 0, wrong_entries)
        }
    }
}

fn full_text_index_rowids(state: &IndexState) -> BTreeSet<RowId> {
    flatten_btree_index_entries(state.store.as_ref())
        .into_iter()
        .map(|(_, rowid)| rowid)
        .collect()
}

fn flatten_btree_index_entries(store: &dyn OrderedIndexStore) -> BTreeSet<(Vec<u8>, RowId)> {
    let mut entries = BTreeSet::new();
    store.scan_from(&[], &mut |key, ids| {
        for id in ids {
            entries.insert((key.to_vec(), id));
        }
        true
    });
    entries
}

fn flatten_spatial_index_entries(state: &IndexState) -> BTreeSet<(String, String)> {
    state
        .spatial
        .as_ref()
        .map(|tree| {
            tree.iter()
                .map(|entry| {
                    (
                        entry.record_id.clone(),
                        format!("{:?}:{:?}", entry.envelope.lower(), entry.envelope.upper()),
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

fn index_state_size_bytes(state: &IndexState) -> u64 {
    match state.definition.kind {
        IndexKind::BTree | IndexKind::FullText | IndexKind::Jsonb | IndexKind::Array => {
            // `resident_bytes` is what each store reports for ITSELF: key and
            // id-set payload plus node and Vec-capacity overhead. The old sum
            // walked every entry (O(entries), one dyn iterator per key) and
            // counted payload only, so it understated the real cost — the
            // number an operator needs for memory attribution.
            state.store.resident_bytes()
        }
        IndexKind::Spatial => {
            state.spatial.as_ref().map(RTree::size).unwrap_or_default() as u64
                * std::mem::size_of::<SpatialIndexEntry>() as u64
        }
    }
}

/// Server-paged B-tree entries live in the page store, not the heap, so
/// there is no `resident_bytes` to ask. Report the durable entry footprint
/// (entry count x the per-entry key+locator record) rather than 0, which
/// made index attribution impossible.
fn paged_btree_entry_bytes(entries: usize) -> u64 {
    const APPROXIMATE_PAGED_ENTRY_BYTES: u64 = 48;
    entries as u64 * APPROXIMATE_PAGED_ENTRY_BYTES
}

fn index_state_record_count(state: &IndexState) -> usize {
    match state.definition.kind {
        IndexKind::BTree => state.store.total_entries(),
        IndexKind::FullText | IndexKind::Jsonb | IndexKind::Array => {
            full_text_index_rowids(state).len()
        }
        IndexKind::Spatial => state.spatial.as_ref().map(RTree::size).unwrap_or_default(),
    }
}

fn validate_index_definition(definition: &IndexDefinition) -> Result<()> {
    validate_collection_name(&definition.name)?;
    validate_collection_name(&definition.collection)?;
    if definition.fields.is_empty() {
        return Err(BicDbError::Index(format!(
            "index `{}` must include at least one field",
            definition.name
        )));
    }
    if let Some(predicate) = &definition.predicate {
        if definition.kind != IndexKind::BTree {
            return Err(BicDbError::Index(format!(
                "partial index `{}` must use B-tree kind",
                definition.name
            )));
        }
        validate_index_predicate_definition(&definition.name, predicate)?;
    }
    if let Some(exclusion) = &definition.exclusion {
        if definition.kind != IndexKind::BTree
            || definition.unique
            || definition.predicate.is_some()
        {
            return Err(BicDbError::Index(format!(
                "exclusion index `{}` must be a non-unique, non-partial B-tree",
                definition.name
            )));
        }
        if exclusion.elements.is_empty() || exclusion.elements.len() > 16 {
            return Err(BicDbError::Index(format!(
                "exclusion index `{}` requires 1..=16 elements",
                definition.name
            )));
        }
        let mut element_fields = BTreeSet::new();
        for element in &exclusion.elements {
            match element {
                IndexExclusionElement::Equal { field } => {
                    validate_index_field(&definition.name, field)?;
                    element_fields.insert(field.clone());
                }
                IndexExclusionElement::Overlaps { start, end, .. } => {
                    validate_index_field(&definition.name, start)?;
                    validate_index_field(&definition.name, end)?;
                    element_fields.insert(start.clone());
                    element_fields.insert(end.clone());
                }
            }
        }
        if element_fields.len() != definition.fields.len()
            || definition
                .fields
                .iter()
                .any(|field| !element_fields.contains(field))
        {
            return Err(BicDbError::Index(format!(
                "exclusion index `{}` fields must exactly match its elements",
                definition.name
            )));
        }
    }
    if definition.kind == IndexKind::FullText {
        if definition
            .fields
            .iter()
            .any(|field| !matches!(field, IndexField::MetadataPath(_)))
        {
            return Err(BicDbError::Index(format!(
                "full-text index `{}` must contain only metadata projection fields",
                definition.name,
            )));
        }
        if definition.unique {
            return Err(BicDbError::Index(format!(
                "full-text index `{}` cannot be unique",
                definition.name,
            )));
        }
    } else if matches!(definition.kind, IndexKind::Jsonb | IndexKind::Array) {
        let kind = if definition.kind == IndexKind::Jsonb {
            "JSONB"
        } else {
            "array"
        };
        if definition.fields.len() != 1
            || !matches!(definition.fields.first(), Some(IndexField::MetadataPath(_)))
        {
            return Err(BicDbError::Index(format!(
                "{kind} index `{}` must include exactly one metadata projection field",
                definition.name,
            )));
        }
        if definition.unique {
            return Err(BicDbError::Index(format!(
                "{kind} index `{}` cannot be unique",
                definition.name,
            )));
        }
    } else if definition.kind == IndexKind::Spatial {
        if definition.fields.len() != 1 {
            return Err(BicDbError::Index(format!(
                "spatial index `{}` must include exactly one geometry field",
                definition.name
            )));
        }
        if definition.unique {
            return Err(BicDbError::Index(format!(
                "spatial index `{}` cannot be unique",
                definition.name
            )));
        }
    } else if definition.fields.iter().any(index_field_contains_geometry) {
        return Err(BicDbError::Index(format!(
            "index `{}` cannot use geometry without spatial index kind",
            definition.name
        )));
    }
    for field in &definition.fields {
        validate_index_field(&definition.name, field)?;
    }
    Ok(())
}

fn validate_index_predicate_definition(name: &str, predicate: &IndexPredicate) -> Result<()> {
    match predicate {
        IndexPredicate::Field { field } => validate_index_field(name, field),
        IndexPredicate::Literal { value } => {
            if value.is_array() || value.is_object() {
                Err(BicDbError::Index(format!(
                    "partial index `{name}` predicate literals must be scalar"
                )))
            } else {
                Ok(())
            }
        }
        IndexPredicate::Unary { value, .. } => validate_index_predicate_definition(name, value),
        IndexPredicate::Binary { left, right, .. } => {
            validate_index_predicate_definition(name, left)?;
            validate_index_predicate_definition(name, right)
        }
    }
}

fn validate_secure_index_field(
    collection: &str,
    unique: bool,
    policy: &CollectionPolicy,
    field: &IndexField,
) -> Result<()> {
    match field {
        IndexField::Id | IndexField::Timestamp => Ok(()),
        IndexField::Geometry => {
            if policy.protected {
                return Err(BicDbError::Index(format!(
                    "protected collection `{collection}` cannot create normal spatial indexes unless vectors/geometry are declared non-sensitive"
                )));
            }
            Ok(())
        }
        IndexField::MetadataPath(path) => {
            if protected_data::encrypted_field(policy, path).is_some() {
                return Err(BicDbError::Index(format!(
                    "encrypted field `{}` cannot be indexed directly; use its approved blind-index field",
                    path.join(".")
                )));
            }
            if unique
                && protected_data::is_security_classified(policy, path)
                && !protected_data::is_approved_blind_index(policy, path)
            {
                return Err(BicDbError::Index(format!(
                    "protected collection `{collection}` cannot create a normal unique index on security-classified field `{}`; use its approved blind-index field",
                    path.join(".")
                )));
            }
            Ok(())
        }
        IndexField::Lower(inner) | IndexField::Trim(inner) => {
            validate_secure_index_field(collection, unique, policy, inner)
        }
    }
}

fn index_field_contains_geometry(field: &IndexField) -> bool {
    match field {
        IndexField::Geometry => true,
        IndexField::Lower(inner) | IndexField::Trim(inner) => index_field_contains_geometry(inner),
        IndexField::Id | IndexField::Timestamp | IndexField::MetadataPath(_) => false,
    }
}

fn validate_index_field(index: &str, field: &IndexField) -> Result<()> {
    match field {
        IndexField::MetadataPath(path) => {
            if path.is_empty() || path.iter().any(|part| part.is_empty()) {
                return Err(BicDbError::Index(format!(
                    "index `{index}` contains an empty metadata path"
                )));
            }
        }
        IndexField::Lower(inner) | IndexField::Trim(inner) => validate_index_field(index, inner)?,
        IndexField::Id | IndexField::Timestamp | IndexField::Geometry => {}
    }
    Ok(())
}

/// Diagnostic (env `BICDB_REPAIR_TRACE=<record_id substring>`): log repair
/// decisions for matching rows.
fn repair_trace_filter() -> Option<&'static str> {
    static FILTER: OnceLock<Option<String>> = OnceLock::new();
    FILTER
        .get_or_init(|| std::env::var("BICDB_REPAIR_TRACE").ok())
        .as_deref()
}

fn repair_trace(
    collection: &str,
    record_id: &str,
    tx_id: u64,
    snapshot: u64,
    max_tx: u64,
    path: impl FnOnce() -> String,
) {
    let Some(filter) = repair_trace_filter() else {
        return;
    };
    if collection.contains(filter) || record_id.contains(filter) {
        let path = path();
        eprintln!(
            "REPAIR_TRACE {collection}:{record_id} tx={tx_id} snapshot={snapshot} max_tx={max_tx} {path}"
        );
    }
}

/// Rebuild `latest` with a [`RepairPlan`]'s numeric deltas applied. `None`
/// (caller converts to a conflict) when a repaired key is missing or holds a
/// non-numeric value, or when integer addition would overflow.
fn apply_repair_deltas(mut repaired: Record, plan: &RepairPlan) -> Option<Record> {
    apply_repair_deltas_to_metadata(&mut repaired.metadata, plan)?;
    Some(repaired)
}

/// Repair only the changed cells, leaving the rest of the compact row as raw
/// JSON. Declines noncompact/unsupported shapes to the authoritative full-row
/// path. Numeric arithmetic and envelope/index-key updates are shared with it.
fn apply_stored_repair_deltas(latest: &StoredRecord, plan: &RepairPlan) -> Option<StoredRecord> {
    if latest.evicted.is_some() {
        return None;
    }
    let keys: Vec<&str> = plan.deltas.iter().map(|(key, _)| key.as_str()).collect();
    let projected = crate::record::project_json_object_text(latest.metadata.get(), &keys)?;
    let mut metadata: Value = serde_json::from_str(&projected).ok()?;
    apply_repair_deltas_to_metadata(&mut metadata, plan)?;
    let patches: Vec<(&str, String)> = metadata
        .as_object()?
        .iter()
        .map(|(key, value)| Some((key.as_str(), serde_json::to_string(value).ok()?)))
        .collect::<Option<_>>()?;
    let patches: Vec<(&str, Option<&str>)> = patches
        .iter()
        .map(|(key, value)| (*key, Some(value.as_str())))
        .collect();
    let text = crate::record::splice_json_object_text(latest.metadata.get(), &patches)?;
    latest.with_metadata_text_spliced(text).ok()
}

fn apply_repair_deltas_to_metadata(metadata: &mut Value, plan: &RepairPlan) -> Option<()> {
    let Value::Object(map) = metadata else {
        return None;
    };
    for (key, delta) in &plan.deltas {
        let slot = map.get_mut(key)?;
        if let Some((current_units, current_scale)) = typed_numeric_repair_decimal(slot) {
            let (delta_units, delta_scale) = match delta {
                RepairDelta::Int(delta) => (*delta as i128, 0),
                RepairDelta::Decimal { units, scale } => (*units, *scale),
                RepairDelta::Float(_) => return None,
            };
            let scale = current_scale.max(delta_scale);
            let sum = align_decimal_scale(current_units, current_scale, scale)?
                .checked_add(align_decimal_scale(delta_units, delta_scale, scale)?)?;
            set_typed_numeric_repair_decimal(slot, sum, scale)?;
            continue;
        }
        match &*slot {
            Value::Number(current) => {
                let next = match delta {
                    RepairDelta::Int(delta) => {
                        if let Some(current) = current.as_i64() {
                            serde_json::Number::from(current.checked_add(*delta)?)
                        } else {
                            serde_json::Number::from_f64(current.as_f64()? + *delta as f64)?
                        }
                    }
                    RepairDelta::Float(delta) => {
                        serde_json::Number::from_f64(current.as_f64()? + *delta)?
                    }
                    RepairDelta::Decimal { units, scale } => serde_json::Number::from_f64(
                        current.as_f64()? + (*units as f64) / 10f64.powi(*scale as i32),
                    )?,
                };
                *slot = Value::Number(next);
            }
            // NUMERIC columns store canonical decimal text; add exactly in
            // fixed point, preserving the wider of the two scales.
            Value::String(current) => {
                let (current_units, current_scale) = parse_repair_decimal(current)?;
                let (delta_units, delta_scale) = match delta {
                    RepairDelta::Int(delta) => (*delta as i128, 0),
                    RepairDelta::Decimal { units, scale } => (*units, *scale),
                    RepairDelta::Float(_) => return None,
                };
                let scale = current_scale.max(delta_scale);
                let sum = align_decimal_scale(current_units, current_scale, scale)?
                    .checked_add(align_decimal_scale(delta_units, delta_scale, scale)?)?;
                *slot = Value::String(format_repair_decimal(sum, scale));
            }
            _ => return None,
        }
    }
    Some(())
}

fn record_index_key(record: &Record, fields: &[IndexField]) -> Vec<IndexValue> {
    fields
        .iter()
        .map(|field| record_index_field_value(record, field))
        .collect()
}

/// `record_index_key` computed from a resident row's borrowed cells, without
/// parsing its JSON into a `Value`. `None` when any field is not
/// cell-representable (nested metadata paths, a top-level `metadata` object
/// standing in for a missing key, legacy byte-array index keys): the caller
/// then takes the parsed-record path, so the two are exact twins.
/// `stored_index_key` over cells parsed once (`StoredRecord::owned_cells`):
/// the same values, the same declines (nested values, envelopes without a
/// usable key, absent keys next to a nested `metadata` object).
fn image_cells_index_key(
    stored: &StoredRecord,
    cells: &ImageCells,
    fields: &[IndexField],
) -> Option<Vec<IndexValue>> {
    fn cell_index_value(base: &str, cells: &ImageCells, name: &str) -> Option<IndexValue> {
        let cell = match cells
            .cells
            .iter()
            .find(|(key, _)| cells.text(base, *key) == name)
        {
            Some((_, cell)) => cell,
            None => {
                return cells
                    .cells
                    .iter()
                    .all(|(key, _)| cells.text(base, *key) != "metadata")
                    .then_some(IndexValue::Null);
            }
        };
        Some(match cell {
            ImageCell::Null => IndexValue::Null,
            ImageCell::Bool(value) => IndexValue::Bool(*value),
            ImageCell::Int(value) => IndexValue::Int(*value),
            ImageCell::Float(value) => IndexValue::Float(ordered_f64(*value)),
            ImageCell::Str(text) => IndexValue::String(cells.text(base, *text).to_string()),
            ImageCell::Envelope { index_key, raw } => match index_key {
                Some(hex) => {
                    let hex = cells.text(base, *hex);
                    if hex.is_empty()
                        || hex.len() % 2 != 0
                        || !hex
                            .bytes()
                            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
                    {
                        return None;
                    }
                    let mut label = String::with_capacity(13 + hex.len());
                    label.push_str("\0bicdb:typed:");
                    label.push_str(hex);
                    IndexValue::String(label)
                }
                None => IndexValue::String(cells.text(base, *raw).to_string()),
            },
            ImageCell::Raw => return None,
        })
    }
    fn field_value(
        stored: &StoredRecord,
        cells: &ImageCells,
        field: &IndexField,
    ) -> Option<IndexValue> {
        let base = stored.metadata.get();
        Some(match field {
            IndexField::Id => IndexValue::String(stored.id.clone()),
            IndexField::Timestamp => stored
                .timestamp
                .map(IndexValue::Int)
                .unwrap_or(IndexValue::Null),
            IndexField::Geometry => stored
                .geometry
                .as_ref()
                .map(|geometry| IndexValue::String(geometry.to_wkt()))
                .unwrap_or(IndexValue::Null),
            IndexField::MetadataPath(path) => match path.as_slice() {
                [name] => cell_index_value(base, cells, name)?,
                _ => return None,
            },
            IndexField::Lower(inner) => match field_value(stored, cells, inner)? {
                IndexValue::Null => IndexValue::Null,
                value => IndexValue::String(index_value_text(&value).to_ascii_lowercase()),
            },
            IndexField::Trim(inner) => match field_value(stored, cells, inner)? {
                IndexValue::Null => IndexValue::Null,
                value => IndexValue::String(index_value_text(&value).trim().to_string()),
            },
        })
    }
    fields
        .iter()
        .map(|field| field_value(stored, cells, field))
        .collect()
}

fn stored_index_key(stored: &StoredRecord, fields: &[IndexField]) -> Option<Vec<IndexValue>> {
    let mut cells = Vec::new();
    if !stored.cells_into(&mut cells) {
        return None;
    }
    fn cell_index_value(cells: &crate::record::CellRow<'_>, name: &str) -> Option<IndexValue> {
        let cell = match cells.iter().find(|(key, _)| key.as_ref() == name) {
            Some((_, cell)) => cell,
            // `record_index_field_value` falls back to a nested top-level
            // `metadata` object when the key is absent; only a parse can
            // reproduce that.
            None => {
                return cells
                    .iter()
                    .all(|(key, _)| key.as_ref() != "metadata")
                    .then_some(IndexValue::Null);
            }
        };
        Some(match cell {
            crate::record::CellRef::Null => IndexValue::Null,
            crate::record::CellRef::Bool(value) => IndexValue::Bool(*value),
            crate::record::CellRef::Int(value) => IndexValue::Int(*value),
            crate::record::CellRef::Float(value) => IndexValue::Float(ordered_f64(*value)),
            crate::record::CellRef::Str(text) => IndexValue::String(text.to_string()),
            crate::record::CellRef::Envelope { index_key, raw, .. } => match index_key {
                Some(hex) => {
                    if hex.is_empty()
                        || hex.len() % 2 != 0
                        || !hex
                            .bytes()
                            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
                    {
                        return None;
                    }
                    let mut label = String::with_capacity(13 + hex.len());
                    label.push_str("\0bicdb:typed:");
                    label.push_str(hex);
                    IndexValue::String(label)
                }
                // `json_to_index_value` stringifies an envelope without a
                // usable key; the raw text is exactly that serialization.
                None => IndexValue::String((*raw).to_string()),
            },
            // Nested objects/arrays: a typed envelope with a byte-array
            // index_key (pre-1.0.366 rows) or an object stringified by
            // `json_to_index_value` — only a parse reproduces those exactly.
            crate::record::CellRef::Raw(_) => return None,
        })
    }
    fn field_value(
        stored: &StoredRecord,
        cells: &crate::record::CellRow<'_>,
        field: &IndexField,
    ) -> Option<IndexValue> {
        Some(match field {
            IndexField::Id => IndexValue::String(stored.id.clone()),
            IndexField::Timestamp => stored
                .timestamp
                .map(IndexValue::Int)
                .unwrap_or(IndexValue::Null),
            IndexField::Geometry => stored
                .geometry
                .as_ref()
                .map(|geometry| IndexValue::String(geometry.to_wkt()))
                .unwrap_or(IndexValue::Null),
            IndexField::MetadataPath(path) => match path.as_slice() {
                [name] => cell_index_value(cells, name)?,
                _ => return None,
            },
            IndexField::Lower(inner) => match field_value(stored, cells, inner)? {
                IndexValue::Null => IndexValue::Null,
                value => IndexValue::String(index_value_text(&value).to_ascii_lowercase()),
            },
            IndexField::Trim(inner) => match field_value(stored, cells, inner)? {
                IndexValue::Null => IndexValue::Null,
                value => IndexValue::String(index_value_text(&value).trim().to_string()),
            },
        })
    }
    fields
        .iter()
        .map(|field| field_value(stored, &cells, field))
        .collect()
}

fn record_index_field_json(record: &Record, field: &IndexField) -> Value {
    match field {
        IndexField::Id => Value::String(record.id.clone()),
        IndexField::Timestamp => record.timestamp.map(Value::from).unwrap_or(Value::Null),
        IndexField::Geometry => record
            .geometry
            .as_ref()
            .map(|geometry| Value::String(geometry.to_wkt()))
            .unwrap_or(Value::Null),
        IndexField::MetadataPath(path) => json_path(&record.metadata, path)
            .or_else(|| {
                record
                    .metadata
                    .get("metadata")
                    .and_then(|metadata| json_path(metadata, path))
            })
            .cloned()
            .unwrap_or(Value::Null),
        IndexField::Lower(inner) => match record_index_field_json(record, inner) {
            Value::Null => Value::Null,
            value => Value::String(predicate_value_text(&value).to_ascii_lowercase()),
        },
        IndexField::Trim(inner) => match record_index_field_json(record, inner) {
            Value::Null => Value::Null,
            value => Value::String(predicate_value_text(&value).trim().to_string()),
        },
    }
}

fn predicate_value_text(value: &Value) -> String {
    match value {
        Value::Null => String::new(),
        Value::String(value) => value.clone(),
        other => other.to_string(),
    }
}

fn compare_predicate_values(
    left: &Value,
    right: &Value,
    value_type: IndexPredicateValueType,
) -> Option<Ordering> {
    if left.is_null() || right.is_null() {
        return None;
    }
    match value_type {
        IndexPredicateValueType::Int64 => left.as_i64()?.partial_cmp(&right.as_i64()?),
        IndexPredicateValueType::Float64 => left.as_f64()?.partial_cmp(&right.as_f64()?),
        IndexPredicateValueType::Decimal => {
            let left = left
                .as_str()
                .unwrap_or_else(|| left.as_number().map_or("", |number| number.as_str()));
            let right = right
                .as_str()
                .unwrap_or_else(|| right.as_number().map_or("", |number| number.as_str()));
            let (left_units, left_scale) = parse_repair_decimal(left)?;
            let (right_units, right_scale) = parse_repair_decimal(right)?;
            let scale = left_scale.max(right_scale);
            align_decimal_scale(left_units, left_scale, scale)?.partial_cmp(&align_decimal_scale(
                right_units,
                right_scale,
                scale,
            )?)
        }
        IndexPredicateValueType::Bool => left.as_bool()?.partial_cmp(&right.as_bool()?),
        IndexPredicateValueType::String
        | IndexPredicateValueType::Uuid
        | IndexPredicateValueType::Timestamp
        | IndexPredicateValueType::Date => left.as_str()?.partial_cmp(right.as_str()?),
        IndexPredicateValueType::Json => match (left, right) {
            (Value::Bool(left), Value::Bool(right)) => left.partial_cmp(right),
            (Value::Number(left), Value::Number(right)) => {
                left.as_f64()?.partial_cmp(&right.as_f64()?)
            }
            (Value::String(left), Value::String(right)) => left.partial_cmp(right),
            _ if left == right => Some(Ordering::Equal),
            _ => None,
        },
    }
}

fn evaluate_index_predicate(record: &Record, predicate: &IndexPredicate) -> Result<Value> {
    Ok(match predicate {
        IndexPredicate::Field { field } => record_index_field_json(record, field),
        IndexPredicate::Literal { value } => value.clone(),
        IndexPredicate::Unary {
            operator,
            value,
            value_type,
        } => {
            let value = evaluate_index_predicate(record, value)?;
            match operator {
                IndexPredicateUnaryOperator::Not => {
                    Value::Bool(!value.as_bool().ok_or_else(|| {
                        BicDbError::Index("partial index `not` operand is not boolean".to_string())
                    })?)
                }
                IndexPredicateUnaryOperator::Negate => match value_type {
                    IndexPredicateValueType::Int64 => {
                        Value::from(value.as_i64().and_then(i64::checked_neg).ok_or_else(|| {
                            BicDbError::Index(
                                "partial index integer negation overflowed".to_string(),
                            )
                        })?)
                    }
                    IndexPredicateValueType::Float64 => {
                        serde_json::Number::from_f64(-value.as_f64().ok_or_else(|| {
                            BicDbError::Index(
                                "partial index negate operand is not numeric".to_string(),
                            )
                        })?)
                        .map(Value::Number)
                        .ok_or_else(|| {
                            BicDbError::Index(
                                "partial index negate produced non-finite value".into(),
                            )
                        })?
                    }
                    _ => {
                        return Err(BicDbError::Index(
                            "partial index negate requires Int64 or Float64".to_string(),
                        ));
                    }
                },
            }
        }
        IndexPredicate::Binary {
            operator,
            left,
            right,
            value_type,
        } => {
            let left = evaluate_index_predicate(record, left)?;
            let right = evaluate_index_predicate(record, right)?;
            let boolean = match operator {
                IndexPredicateBinaryOperator::And => {
                    left.as_bool() == Some(true) && right.as_bool() == Some(true)
                }
                IndexPredicateBinaryOperator::Or => {
                    left.as_bool() == Some(true) || right.as_bool() == Some(true)
                }
                IndexPredicateBinaryOperator::Implies => {
                    left.as_bool() == Some(false) || right.as_bool() == Some(true)
                }
                IndexPredicateBinaryOperator::Contains => left
                    .as_str()
                    .zip(right.as_str())
                    .is_some_and(|(left, right)| left.contains(right)),
                IndexPredicateBinaryOperator::Equal => left == right,
                IndexPredicateBinaryOperator::NotEqual => left != right,
                IndexPredicateBinaryOperator::Greater => {
                    compare_predicate_values(&left, &right, *value_type)
                        .is_some_and(Ordering::is_gt)
                }
                IndexPredicateBinaryOperator::GreaterEqual => {
                    compare_predicate_values(&left, &right, *value_type)
                        .is_some_and(|ordering| !ordering.is_lt())
                }
                IndexPredicateBinaryOperator::Less => {
                    compare_predicate_values(&left, &right, *value_type)
                        .is_some_and(Ordering::is_lt)
                }
                IndexPredicateBinaryOperator::LessEqual => {
                    compare_predicate_values(&left, &right, *value_type)
                        .is_some_and(|ordering| !ordering.is_gt())
                }
            };
            Value::Bool(boolean)
        }
    })
}

fn record_matches_index_predicate(record: &Record, definition: &IndexDefinition) -> Result<bool> {
    record_matches_index_predicate_parts(record, &definition.name, definition.predicate.as_ref())
}

fn record_matches_index_predicate_parts(
    record: &Record,
    index_name: &str,
    predicate: Option<&IndexPredicate>,
) -> Result<bool> {
    let Some(predicate) = predicate else {
        return Ok(true);
    };
    evaluate_index_predicate(record, predicate)?
        .as_bool()
        .ok_or_else(|| {
            BicDbError::Index(format!(
                "partial index `{}` predicate did not return boolean",
                index_name
            ))
        })
}

fn record_exclusion_tuple(
    record: &Record,
    definition: &IndexDefinition,
) -> Result<Option<ExclusionTuple>> {
    let Some(exclusion) = &definition.exclusion else {
        return Ok(None);
    };
    let mut equal = Vec::new();
    let mut ranges = Vec::new();
    for element in &exclusion.elements {
        match element {
            IndexExclusionElement::Equal { field } => {
                let value = record_index_field_json(record, field);
                if value.is_null() {
                    return Ok(None);
                }
                equal.push(value);
            }
            IndexExclusionElement::Overlaps {
                start,
                end,
                value_type,
            } => {
                let start = record_index_field_json(record, start);
                let end = record_index_field_json(record, end);
                if start.is_null() || end.is_null() {
                    return Ok(None);
                }
                match compare_predicate_values(&start, &end, *value_type) {
                    Some(Ordering::Less) => ranges.push((start, end, *value_type)),
                    Some(Ordering::Equal) => return Ok(None),
                    Some(Ordering::Greater) => {
                        return Err(BicDbError::Index(format!(
                            "exclusion index `{}` range start exceeds its end",
                            definition.name
                        )));
                    }
                    None => {
                        return Err(BicDbError::Index(format!(
                            "exclusion index `{}` range values are not comparable",
                            definition.name
                        )));
                    }
                }
            }
        }
    }
    Ok(Some(ExclusionTuple { equal, ranges }))
}

fn exclusion_tuples_conflict(left: &ExclusionTuple, right: &ExclusionTuple) -> bool {
    left.equal == right.equal
        && left.ranges.len() == right.ranges.len()
        && left.ranges.iter().zip(&right.ranges).all(
            |((left_start, left_end, value_type), (right_start, right_end, right_type))| {
                value_type == right_type
                    && compare_predicate_values(left_start, right_end, *value_type)
                        .is_some_and(Ordering::is_lt)
                    && compare_predicate_values(right_start, left_end, *value_type)
                        .is_some_and(Ordering::is_lt)
            },
        )
}

/// Encodes a composite index key into an order-preserving, self-delimiting byte
/// string: bytewise (memcmp) comparison of two encodings yields the same
/// ordering as the structural `Vec<IndexValue>` comparison. This lets the index
/// BTreeMap compare flat byte slices (a single memcmp) instead of walking an
/// enum vector field by field (the dominant `lookup_index` / maintenance cost).
/// Each field's encoding is self-delimiting, so encoding a prefix of the fields
/// yields a byte-prefix of the full key — preserving prefix and range lookups.
fn encode_index_key(values: &[IndexValue]) -> Vec<u8> {
    let mut buf = Vec::new();
    for value in values {
        encode_index_value(&mut buf, value);
    }
    buf
}

fn encode_index_value(buf: &mut Vec<u8>, value: &IndexValue) {
    // Tag bytes preserve variant order: Null<Bool<Int<Float<String.
    match value {
        IndexValue::Null => buf.push(0),
        IndexValue::Bool(b) => {
            buf.push(1);
            buf.push(*b as u8);
        }
        IndexValue::Int(i) => {
            buf.push(2);
            // Flip the sign bit so two's-complement i64 sorts as big-endian u64.
            buf.extend_from_slice(&((*i as u64) ^ (1u64 << 63)).to_be_bytes());
        }
        IndexValue::Float(bits) => {
            buf.push(3);
            // IndexValue::Float orders by its raw u64 bits today; preserve that.
            buf.extend_from_slice(&bits.to_be_bytes());
        }
        IndexValue::String(s) => {
            buf.push(4);
            // Escape 0x00 as 0x00 0xFF and terminate with 0x00 0x00, keeping the
            // encoding order-preserving and self-delimiting in a composite key.
            for &b in s.as_bytes() {
                buf.push(b);
                if b == 0 {
                    buf.push(0xFF);
                }
            }
            buf.push(0);
            buf.push(0);
        }
    }
}

/// Decodes one [`encode_index_value`] field starting at `pos`, returning the
/// value and the position just past it.
fn decode_index_value_at(encoded: &[u8], mut pos: usize) -> (IndexValue, usize) {
    let tag = encoded[pos];
    pos += 1;
    match tag {
        0 => (IndexValue::Null, pos),
        1 => {
            let b = encoded[pos] != 0;
            (IndexValue::Bool(b), pos + 1)
        }
        2 => {
            let bytes: [u8; 8] = encoded[pos..pos + 8].try_into().expect("index int field");
            (
                IndexValue::Int((u64::from_be_bytes(bytes) ^ (1u64 << 63)) as i64),
                pos + 8,
            )
        }
        3 => {
            let bytes: [u8; 8] = encoded[pos..pos + 8].try_into().expect("index float field");
            (IndexValue::Float(u64::from_be_bytes(bytes)), pos + 8)
        }
        4 => {
            let mut text = Vec::new();
            loop {
                let b = encoded[pos];
                if b == 0 {
                    if encoded.get(pos + 1) == Some(&0xFF) {
                        text.push(0);
                        pos += 2;
                    } else {
                        pos += 2; // 0x00 0x00 terminator
                        break;
                    }
                } else {
                    text.push(b);
                    pos += 1;
                }
            }
            (
                IndexValue::String(String::from_utf8_lossy(&text).into_owned()),
                pos,
            )
        }
        other => unreachable!("invalid index key tag {other}"),
    }
}

/// Decodes a full [`encode_index_key`] byte string back to its composite
/// `Vec<IndexValue>`. Used on the cold ordered/range index-scan paths that need
/// the structured key.
fn decode_index_key(encoded: &[u8]) -> Vec<IndexValue> {
    let mut values = Vec::new();
    let mut pos = 0usize;
    while pos < encoded.len() {
        let (value, next) = decode_index_value_at(encoded, pos);
        values.push(value);
        pos = next;
    }
    values
}

/// Decodes just the `field_idx`-th field of an [`encode_index_key`] byte string.
fn decode_index_field(encoded: &[u8], field_idx: usize) -> IndexValue {
    let mut pos = 0usize;
    for _ in 0..field_idx {
        let (_, next) = decode_index_value_at(encoded, pos);
        pos = next;
    }
    decode_index_value_at(encoded, pos).0
}

fn record_index_field_value(record: &Record, field: &IndexField) -> IndexValue {
    match field {
        IndexField::Id => IndexValue::String(record.id.clone()),
        IndexField::Timestamp => record
            .timestamp
            .map(IndexValue::Int)
            .unwrap_or(IndexValue::Null),
        IndexField::Geometry => record
            .geometry
            .as_ref()
            .map(|geometry| IndexValue::String(geometry.to_wkt()))
            .unwrap_or(IndexValue::Null),
        IndexField::MetadataPath(path) => json_path(&record.metadata, path)
            .or_else(|| {
                record
                    .metadata
                    .get("metadata")
                    .and_then(|metadata| json_path(metadata, path))
            })
            .map(json_to_index_value)
            .unwrap_or(IndexValue::Null),
        IndexField::Lower(inner) => match record_index_field_value(record, inner) {
            IndexValue::Null => IndexValue::Null,
            value => IndexValue::String(index_value_text(&value).to_ascii_lowercase()),
        },
        IndexField::Trim(inner) => match record_index_field_value(record, inner) {
            IndexValue::Null => IndexValue::Null,
            value => IndexValue::String(index_value_text(&value).trim().to_string()),
        },
    }
}

/// Pack a pk-ordered (or impact-ordered) posting run into encoded blocks:
/// `(last_pk, block_bytes)` pairs, capped by doc count and byte target so a
/// block stays within a heap page's inline limit.
pub(crate) const FTS_BLOCK_DOC_CAP: usize = 128;
pub(crate) const FTS_BLOCK_BYTE_TARGET: usize = 960;

/// Split a posting run into block boundaries without encoding anything.
/// Shared by the fold (which always encodes every range) and the direct
/// backfill (which holds back the trailing partial range so the next chunk
/// can top it up before it is frozen into a block).
fn posting_block_ranges(
    postings: &[crate::paged_collection::BlockPosting],
    cap: usize,
    byte_target: usize,
) -> Vec<std::ops::Range<usize>> {
    let mut ranges = Vec::new();
    let mut start = 0usize;
    while start < postings.len() {
        let mut end = start;
        let mut bytes = 0usize;
        while end < postings.len() && end - start < cap {
            let posting = &postings[end];
            let posting_bytes = posting.pk.len() + posting.packed_positions.len() * 2 + 12;
            if end > start && bytes + posting_bytes > byte_target {
                break;
            }
            bytes += posting_bytes;
            end += 1;
        }
        ranges.push(start..end);
        start = end;
    }
    ranges
}

/// Encode one pk-contiguous posting run as a v3/v5 block: `(last_pk, bytes)`.
/// The header carries BOTH bounds the ranked scan prunes with: the impact
/// bucket (ordering + coarse termination) and the EXACT best single-term
/// rank (block-max skipping — the only bound that can retire a tie plateau).
fn encode_posting_run(run: &[crate::paged_collection::BlockPosting]) -> (String, Vec<u8>) {
    const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
    let mut max_impact = 0u16;
    let mut max_rank = f32::NEG_INFINITY;
    for posting in run {
        max_impact = max_impact.max(fts_impact_bucket(&posting.packed_positions));
        max_rank = max_rank.max(fts_rank_single_term(
            &posting.packed_positions,
            DEFAULT_WEIGHTS,
        ));
    }
    let last_pk = run.last().expect("non-empty run").pk.clone();
    (
        last_pk,
        crate::paged_collection::encode_posting_block(run, max_impact, max_rank),
    )
}

/// One posting's contribution to a term's impact-ordered sidecar: exactly
/// what the old impact-run records carried, minus the positions the sidecar
/// never stored. 24 bytes against the ~60 the full posting occupies.
#[derive(Clone, Copy)]
struct ImpactTriple {
    bucket: u16,
    rank: f32,
    document_id: u64,
    /// The same per-posting byte estimate the block-cut rule uses, so the
    /// single-pass cuts land exactly where the two-pass merge cut.
    estimated_bytes: u32,
}

/// Accumulates a term's impact triples across the pk-ordered merge and
/// replays them in (bucket desc, document id asc) order — the impact-run
/// comparator — cutting blocks with the block-cut rule. Bounded memory: past
/// the budget, sorted chunks spill to a scratch file and the finish is a
/// k-way merge, so a monster term on a 74M-document corpus cannot pin
/// gigabytes.
struct TermImpactAccumulator {
    triples: Vec<ImpactTriple>,
    budget_triples: usize,
    scratch_path: std::path::PathBuf,
    spill: Option<std::io::BufWriter<std::fs::File>>,
    chunks: Vec<(u64, u64)>,
    spilled_bytes: u64,
}

impl TermImpactAccumulator {
    const RECORD_BYTES: usize = 18;

    fn new(scratch_path: std::path::PathBuf, budget_bytes: usize) -> Self {
        Self {
            triples: Vec::new(),
            budget_triples: (budget_bytes / std::mem::size_of::<ImpactTriple>()).max(4_096),
            scratch_path,
            spill: None,
            chunks: Vec::new(),
            spilled_bytes: 0,
        }
    }

    fn push(&mut self, triple: ImpactTriple) -> Result<()> {
        self.triples.push(triple);
        if self.triples.len() >= self.budget_triples {
            self.spill_chunk()?;
        }
        Ok(())
    }

    fn sort(triples: &mut [ImpactTriple]) {
        triples.sort_unstable_by(|left, right| {
            right
                .bucket
                .cmp(&left.bucket)
                .then_with(|| left.document_id.cmp(&right.document_id))
        });
    }

    fn spill_chunk(&mut self) -> Result<()> {
        use std::io::Write as _;
        Self::sort(&mut self.triples);
        if self.spill.is_none() {
            let file = std::fs::File::create(&self.scratch_path).map_err(|error| {
                BicDbError::Index(format!("cannot create impact scratch: {error}"))
            })?;
            self.spill = Some(std::io::BufWriter::new(file));
        }
        let writer = self.spill.as_mut().expect("just created");
        let start = self.spilled_bytes;
        for triple in &self.triples {
            let mut record = [0u8; Self::RECORD_BYTES];
            record[0..2].copy_from_slice(&triple.bucket.to_le_bytes());
            record[2..6].copy_from_slice(&triple.rank.to_bits().to_le_bytes());
            record[6..14].copy_from_slice(&triple.document_id.to_le_bytes());
            record[14..18].copy_from_slice(&triple.estimated_bytes.to_le_bytes());
            writer.write_all(&record).map_err(|error| {
                BicDbError::Index(format!("impact scratch write failed: {error}"))
            })?;
        }
        self.spilled_bytes += (self.triples.len() * Self::RECORD_BYTES) as u64;
        self.chunks.push((start, self.spilled_bytes - start));
        self.triples.clear();
        Ok(())
    }

    /// Replay in sidecar order, cutting with the block rule and handing each
    /// block's (ids, max_impact, max_rank) to `emit`. Returns blocks emitted.
    fn finish(
        &mut self,
        cap: usize,
        byte_target: usize,
        mut emit: impl FnMut(&[u64], u16, f32) -> Result<()>,
    ) -> Result<usize> {
        let mut ids: Vec<u64> = Vec::with_capacity(cap);
        let mut block_bytes = 0usize;
        let mut max_impact = 0u16;
        let mut max_rank = f32::NEG_INFINITY;
        let mut blocks = 0usize;
        let mut consume = |triple: ImpactTriple,
                           ids: &mut Vec<u64>,
                           block_bytes: &mut usize,
                           max_impact: &mut u16,
                           max_rank: &mut f32,
                           blocks: &mut usize,
                           emit: &mut dyn FnMut(&[u64], u16, f32) -> Result<()>|
         -> Result<()> {
            let estimated = triple.estimated_bytes as usize;
            if !ids.is_empty()
                && (ids.len() >= cap || block_bytes.saturating_add(estimated) > byte_target)
            {
                emit(ids, *max_impact, *max_rank)?;
                *blocks += 1;
                ids.clear();
                *block_bytes = 0;
                *max_impact = 0;
                *max_rank = f32::NEG_INFINITY;
            }
            ids.push(triple.document_id);
            *block_bytes = block_bytes.saturating_add(estimated);
            *max_impact = (*max_impact).max(triple.bucket);
            *max_rank = max_rank.max(triple.rank);
            Ok(())
        };
        if self.chunks.is_empty() {
            Self::sort(&mut self.triples);
            for triple in std::mem::take(&mut self.triples) {
                consume(
                    triple,
                    &mut ids,
                    &mut block_bytes,
                    &mut max_impact,
                    &mut max_rank,
                    &mut blocks,
                    &mut emit,
                )?;
            }
        } else {
            use std::io::{Read as _, Seek as _, Write as _};
            if !self.triples.is_empty() {
                self.spill_chunk()?;
            }
            if let Some(mut writer) = self.spill.take() {
                writer.flush().map_err(|error| {
                    BicDbError::Index(format!("impact scratch flush failed: {error}"))
                })?;
            }
            struct ChunkCursor {
                reader: std::io::BufReader<std::fs::File>,
                remaining: u64,
                head: ImpactTriple,
            }
            fn read_triple(reader: &mut std::io::BufReader<std::fs::File>) -> Result<ImpactTriple> {
                let mut record = [0u8; TermImpactAccumulator::RECORD_BYTES];
                reader.read_exact(&mut record).map_err(|error| {
                    BicDbError::Index(format!("impact scratch read failed: {error}"))
                })?;
                Ok(ImpactTriple {
                    bucket: u16::from_le_bytes(record[0..2].try_into().expect("2")),
                    rank: f32::from_bits(u32::from_le_bytes(record[2..6].try_into().expect("4"))),
                    document_id: u64::from_le_bytes(record[6..14].try_into().expect("8")),
                    estimated_bytes: u32::from_le_bytes(record[14..18].try_into().expect("4")),
                })
            }
            let mut cursors = Vec::with_capacity(self.chunks.len());
            for (offset, length) in self.chunks.drain(..) {
                let mut file = std::fs::File::open(&self.scratch_path).map_err(|error| {
                    BicDbError::Index(format!("cannot open impact scratch: {error}"))
                })?;
                file.seek(std::io::SeekFrom::Start(offset))
                    .map_err(|error| {
                        BicDbError::Index(format!("impact scratch seek failed: {error}"))
                    })?;
                let mut reader = std::io::BufReader::new(file);
                let head = read_triple(&mut reader)?;
                cursors.push(ChunkCursor {
                    reader,
                    remaining: length / Self::RECORD_BYTES as u64 - 1,
                    head,
                });
            }
            // Small k (chunks = term bytes / budget); linear scan per pop is
            // simpler than a heap and k is single digits in practice.
            while !cursors.is_empty() {
                let mut best = 0usize;
                for index in 1..cursors.len() {
                    let candidate = &cursors[index].head;
                    let leader = &cursors[best].head;
                    if candidate
                        .bucket
                        .cmp(&leader.bucket)
                        .reverse()
                        .then_with(|| candidate.document_id.cmp(&leader.document_id))
                        .is_lt()
                    {
                        best = index;
                    }
                }
                let triple = cursors[best].head;
                if cursors[best].remaining == 0 {
                    cursors.swap_remove(best);
                } else {
                    cursors[best].remaining -= 1;
                    cursors[best].head = read_triple(&mut cursors[best].reader)?;
                }
                consume(
                    triple,
                    &mut ids,
                    &mut block_bytes,
                    &mut max_impact,
                    &mut max_rank,
                    &mut blocks,
                    &mut emit,
                )?;
            }
            let _ = std::fs::remove_file(&self.scratch_path);
            self.spilled_bytes = 0;
        }
        if !ids.is_empty() {
            emit(&ids, max_impact, max_rank)?;
            blocks += 1;
        }
        Ok(blocks)
    }
}

/// One worker of the parallel range merge: owns its part's segment writers
/// and replays the same per-term logic the sequential merge runs — block
/// cuts, sidecar generation, elision — over one term range. Segment mode
/// only: range workers never touch the paged store, which is what makes
/// them embarrassingly parallel. The byte-identity gate holds because every
/// decision here mirrors the sequential path exactly and parts concatenate
/// in term order.
struct SegmentRangeWorker {
    pk: crate::fts_segment::FtsSegmentWriter,
    impact: crate::fts_segment::FtsSegmentWriter,
    term_impacts: TermImpactAccumulator,
    current_term: Option<Vec<u8>>,
    block: Vec<crate::paged_collection::NumericBlockPosting>,
    block_bytes: usize,
    block_max_impact: u16,
    block_max_rank: f32,
    term_document_frequency: u64,
    term_collection_frequency: u64,
    term_maximum_contribution: f32,
    term_block_count: u32,
    term_first_document_id: Option<u64>,
    term_last_document_id: Option<u64>,
    terms_finished: u64,
}

impl SegmentRangeWorker {
    fn on_event(&mut self, event: crate::fts_build::TermStreamEvent) -> Result<()> {
        match event {
            crate::fts_build::TermStreamEvent::Term(term) => {
                if self.current_term.is_some() {
                    self.finish_term()?;
                }
                match self.current_term.as_mut() {
                    Some(buffer) => {
                        buffer.clear();
                        buffer.extend_from_slice(term);
                    }
                    None => self.current_term = Some(term.to_vec()),
                }
                Ok(())
            }
            crate::fts_build::TermStreamEvent::Posting {
                posting,
                impact_bucket,
                impact_rank,
            } => {
                let posting_bytes = 8 + posting.packed_positions.len() * 2 + 12;
                if !self.block.is_empty()
                    && (self.block.len() >= FTS_BLOCK_DOC_CAP
                        || self.block_bytes.saturating_add(posting_bytes) > FTS_BLOCK_BYTE_TARGET)
                {
                    self.flush_block()?;
                }
                self.term_document_frequency = self.term_document_frequency.saturating_add(1);
                self.term_collection_frequency = self
                    .term_collection_frequency
                    .saturating_add(posting.packed_positions.len() as u64);
                self.term_first_document_id = Some(
                    self.term_first_document_id
                        .map_or(posting.document_id, |first| first.min(posting.document_id)),
                );
                self.term_last_document_id = Some(
                    self.term_last_document_id
                        .map_or(posting.document_id, |last| last.max(posting.document_id)),
                );
                self.term_maximum_contribution = self.term_maximum_contribution.max(impact_rank);
                self.block_max_impact = self.block_max_impact.max(impact_bucket);
                self.block_max_rank = self.block_max_rank.max(impact_rank);
                self.block_bytes = self.block_bytes.saturating_add(posting_bytes);
                self.term_impacts.push(ImpactTriple {
                    bucket: impact_bucket,
                    rank: impact_rank,
                    document_id: posting.document_id,
                    // Same constant as the sequential path: the historical
                    // impact-run records carried no positions.
                    estimated_bytes: 8 + 12,
                })?;
                self.block.push(posting);
                Ok(())
            }
        }
    }

    fn flush_block(&mut self) -> Result<()> {
        if self.block.is_empty() {
            return Ok(());
        }
        let term = self.current_term.as_ref().expect("term exists");
        self.pk.append_pk_postings(
            term,
            &self.block,
            self.block_max_impact,
            self.block_max_rank,
        )?;
        self.term_block_count = self.term_block_count.saturating_add(1);
        self.block.clear();
        self.block_bytes = 0;
        self.block_max_impact = 0;
        self.block_max_rank = f32::NEG_INFINITY;
        Ok(())
    }

    fn finish_term(&mut self) -> Result<()> {
        self.flush_block()?;
        let term = self.current_term.clone().expect("term exists");
        let pk_blocks = self.term_block_count;
        let mut pending: Option<(Vec<u64>, u16, f32)> = None;
        let mut emitted = 0usize;
        self.term_impacts.finish(
            FTS_BLOCK_DOC_CAP,
            FTS_BLOCK_BYTE_TARGET,
            |ids, max_impact, max_rank| {
                emitted += 1;
                if emitted == 1 && pk_blocks == 1 {
                    pending = Some((ids.to_vec(), max_impact, max_rank));
                    return Ok(());
                }
                if let Some((held_ids, held_impact, held_rank)) = pending.take() {
                    self.impact
                        .append_impact_ids(&term, &held_ids, held_impact, held_rank)?;
                }
                self.impact
                    .append_impact_ids(&term, ids, max_impact, max_rank)?;
                Ok(())
            },
        )?;
        if pending.is_some() {
            self.impact.record_elided_impact_term(&term)?;
        } else {
            self.impact.end_impact_term(&term)?;
        }
        self.pk.end_pk_term(
            &term,
            &crate::fts_segment::PkTermStats {
                document_frequency: self.term_document_frequency,
                collection_frequency: self.term_collection_frequency,
                maximum_contribution: self.term_maximum_contribution,
                first_doc_id: self.term_first_document_id,
                last_doc_id: self.term_last_document_id,
            },
        )?;
        self.terms_finished += 1;
        self.term_document_frequency = 0;
        self.term_collection_frequency = 0;
        self.term_maximum_contribution = 0.0;
        self.term_block_count = 0;
        self.term_first_document_id = None;
        self.term_last_document_id = None;
        Ok(())
    }

    fn finish(mut self) -> Result<(Vec<u64>, Vec<u64>, u64)> {
        if self.current_term.is_some() {
            self.finish_term()?;
        }
        let terms = self.terms_finished;
        let pk_docs = self.pk.finish_part()?;
        let impact_docs = self.impact.finish_part()?;
        Ok((pk_docs, impact_docs, terms))
    }

    /// Full finish for a standalone (sub-)segment: docs.dat, state files —
    /// ready for `publish_segment`.
    fn finish_publish(mut self) -> Result<u64> {
        if self.current_term.is_some() {
            self.finish_term()?;
        }
        let terms = self.terms_finished;
        self.pk.finish_phase()?;
        self.impact.finish_phase()?;
        Ok(terms)
    }
}

/// The v1 block header fields as the encoder would compute them —
/// (max_rank, max_term_frequency, weight_mask) — for a decoded slim block
/// whose term directory carries no stored header (single-block terms).
pub(crate) fn numeric_run_metadata(
    run: &[crate::paged_collection::NumericBlockPosting],
) -> (f32, u32, u8) {
    const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
    let mut max_rank = f32::NEG_INFINITY;
    let mut max_term_frequency = 1usize;
    let mut weight_mask = 0u8;
    for posting in run {
        max_rank = max_rank.max(fts_rank_single_term(
            &posting.packed_positions,
            DEFAULT_WEIGHTS,
        ));
        max_term_frequency = max_term_frequency.max(posting.packed_positions.len().max(1));
        if posting.packed_positions.is_empty() {
            weight_mask |= 1;
        } else {
            for packed in &posting.packed_positions {
                weight_mask |= 1 << ((packed >> 14) & 0x3);
            }
        }
    }
    (max_rank, max_term_frequency as u32, weight_mask)
}

pub(crate) fn encode_numeric_posting_run(
    run: &[crate::paged_collection::NumericBlockPosting],
) -> (u64, Vec<u8>) {
    const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
    let mut max_impact = 0u16;
    let mut max_rank = f32::NEG_INFINITY;
    for posting in run {
        max_impact = max_impact.max(fts_impact_bucket(&posting.packed_positions));
        max_rank = max_rank.max(fts_rank_single_term(
            &posting.packed_positions,
            DEFAULT_WEIGHTS,
        ));
    }
    let last_document_id = run.last().expect("non-empty run").document_id;
    (
        last_document_id,
        crate::paged_collection::encode_numeric_posting_block(run, max_impact, max_rank),
    )
}

pub(crate) fn encode_compact_impact_run(
    run: &[crate::paged_collection::NumericBlockPosting],
) -> Vec<u8> {
    const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
    let mut max_impact = 0u16;
    let mut max_rank = f32::NEG_INFINITY;
    for posting in run {
        max_impact = max_impact.max(fts_impact_bucket(&posting.packed_positions));
        max_rank = max_rank.max(fts_rank_single_term(
            &posting.packed_positions,
            DEFAULT_WEIGHTS,
        ));
    }
    crate::paged_collection::encode_compact_impact_block(run, max_impact, max_rank)
}

/// Reproduce the impact-ordered sidecar block for a term whose postings all
/// fit in ONE pk block, byte-identically to what the build merge would have
/// stored: same total order (impact bucket descending, document id ascending
/// — the external-run comparator), same header accumulation, same encoder.
/// Packed segments elide exactly those sidecars and regenerate them here.
pub(crate) fn synthesize_impact_sidecar(
    postings: &mut [crate::paged_collection::NumericBlockPosting],
) -> Vec<u8> {
    postings.sort_by(|left, right| {
        fts_impact_bucket(&right.packed_positions)
            .cmp(&fts_impact_bucket(&left.packed_positions))
            .then_with(|| left.document_id.cmp(&right.document_id))
    });
    encode_compact_impact_run(postings)
}

fn build_posting_blocks(
    postings: &[crate::paged_collection::BlockPosting],
    cap: usize,
    byte_target: usize,
) -> Vec<(String, Vec<u8>)> {
    posting_block_ranges(postings, cap, byte_target)
        .into_iter()
        .map(|range| encode_posting_run(&postings[range]))
        .collect()
}

fn build_numeric_posting_blocks(
    postings: &[crate::paged_collection::NumericBlockPosting],
    cap: usize,
    byte_target: usize,
) -> Vec<(u64, Vec<u8>)> {
    let mut blocks = Vec::new();
    let mut start = 0usize;
    while start < postings.len() {
        let mut end = start;
        let mut bytes = 0usize;
        while end < postings.len() && end - start < cap {
            let estimate =
                20usize.saturating_add(postings[end].packed_positions.len().saturating_mul(2));
            if end > start && bytes.saturating_add(estimate) > byte_target {
                break;
            }
            bytes = bytes.saturating_add(estimate);
            end += 1;
        }
        blocks.push(encode_numeric_posting_run(&postings[start..end]));
        start = end;
    }
    blocks
}

fn build_compact_impact_blocks(
    postings: &[crate::paged_collection::NumericBlockPosting],
    cap: usize,
    byte_target: usize,
) -> Vec<(u64, Vec<u8>)> {
    let mut blocks = Vec::new();
    let mut start = 0usize;
    while start < postings.len() {
        // Impact sidecars hold only compressed ids, so a conservative ten
        // bytes per id bounds the temporary encoder even for irregular ids.
        let by_bytes = (byte_target / 10).max(1);
        let end = postings.len().min(start.saturating_add(cap.min(by_bytes)));
        blocks.push((
            postings[end - 1].document_id,
            encode_compact_impact_run(&postings[start..end]),
        ));
        start = end;
    }
    blocks
}

/// A secondary index whose entries are durably maintained in the page store,
/// in the same paged transaction as the rows they describe.
struct PagedDurableIndexDef {
    name: String,
    fields: Vec<IndexField>,
    kind: IndexKind,
    predicate: Option<IndexPredicate>,
    entry_format: crate::paged_collection::IndexEntryFormat,
    /// Unique constraint carried to the paged apply so the atomic
    /// check-and-insert probe (under the store write guard) knows which
    /// entries to guard. Enforcement authority today is still the pre-WAL
    /// validation plus per-key claims; the probe is the in-transaction
    /// backstop.
    unique: bool,
}

/// Whether the apply-time unique probe runs. Always in debug builds; release
/// builds opt in until the pre-WAL claims machinery is retired in favor of
/// in-transaction enforcement (the probe then becomes the authority).
fn paged_unique_apply_probe_enabled() -> bool {
    if cfg!(debug_assertions) {
        return true;
    }
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var("BICDB_PAGED_UNIQUE_APPLY_PROBE")
            .map(|value| matches!(value.as_str(), "1" | "on" | "true" | "yes"))
            .unwrap_or(false)
    })
}

pub(crate) fn full_text_term_entry_key(term: &str) -> Vec<u8> {
    debug_assert!(
        term.len() <= MAX_FULL_TEXT_TERM_BYTES,
        "oversized full-text term reached index-key encoding"
    );
    encode_index_key(std::slice::from_ref(&IndexValue::String(term.to_string())))
}

fn full_text_fields(def: &PagedDurableIndexDef) -> Result<&[IndexField]> {
    if def.fields.is_empty() {
        Err(BicDbError::Index(format!(
            "full-text index `{}` has no projection field",
            def.name
        )))
    } else {
        Ok(&def.fields)
    }
}

/// Maintain the durable entries of every index in `defs` for one upsert.
/// B-tree: replace the row's composite key. Full-text: diff the row's OLD and
/// NEW term sets and touch only the difference — an update that leaves a term
/// in place writes nothing for it, so unchanged terms cost zero WAL traffic.
fn apply_paged_index_upsert(
    paged: &crate::paged_collection::PagedRecords,
    xid: bicdb_page::Xid,
    collection: &str,
    defs: &[PagedDurableIndexDef],
    previous: Option<&Record>,
    record: &Record,
    // The record's chain-head locator plus that head's xmin — from `paged.put`
    // on the write path (xmin = this xid), or from a heads-scan on backfill
    // (xmin = the head's original writer). Ordered entries record the pair as
    // a TID hint; `None` writes hint-less entries, which read correctly
    // through the fallback descent.
    head: Option<(bicdb_page::TupleLocator, bicdb_page::Xid)>,
) -> Result<()> {
    let tid_hint =
        head.map(|(locator, xmin)| crate::paged_collection::encode_tid_hint(locator, xmin));
    for def in defs {
        match def.kind {
            IndexKind::FullText => {
                let fields = full_text_fields(def)?;
                let new_postings = record_full_text_postings(record, fields)?;
                let (old_postings, old_from_blob) = previous
                    .map(|previous| full_text_diff_postings(paged, &def.name, fields, previous))
                    .transpose()?
                    .unwrap_or_default();
                // Both sides are sorted and deduped by term, so set difference
                // is a binary search. A term present on both sides is
                // re-written ONLY when its payload changed: with positions in
                // the payload, an edit that reorders text keeps the term set
                // but must still update every posting it moved.
                for (term, old_payload) in old_postings.iter().filter(|(term, _)| {
                    new_postings
                        .binary_search_by(|(new_term, _)| new_term.cmp(term))
                        .is_err()
                }) {
                    let key = full_text_term_entry_key(term);
                    let was_in_tail = paged.delete_index_entry(xid, &def.name, &key, &record.id)?;
                    if let Some((_, _, packed)) = decode_fts_posting_payload(old_payload) {
                        paged.delete_index_entry_v2(
                            xid,
                            &def.name,
                            &key,
                            fts_impact_bucket(&packed),
                            &record.id,
                        )?;
                    }
                    // Folded posting (no tail entry to delete): the block
                    // still lists it — a tombstone hides it until the next
                    // fold rewrites the term.
                    if !was_in_tail {
                        paged.put_posting_tombstone(xid, &def.name, &key, &record.id)?;
                    }
                }
                for (term, payload) in &new_postings {
                    let key = full_text_term_entry_key(term);
                    let unchanged = old_postings
                        .binary_search_by(|(old_term, _)| old_term.cmp(term))
                        .map(|index| old_postings[index].1 == *payload)
                        .unwrap_or(false);
                    if unchanged {
                        continue;
                    }
                    // A payload change can move the impact bucket: drop the
                    // old v2 twin before writing the new one.
                    if let Ok(index) =
                        old_postings.binary_search_by(|(old_term, _)| old_term.cmp(term))
                    {
                        if let Some((_, _, old_packed)) =
                            decode_fts_posting_payload(&old_postings[index].1)
                        {
                            paged.delete_index_entry_v2(
                                xid,
                                &def.name,
                                &key,
                                fts_impact_bucket(&old_packed),
                                &record.id,
                            )?;
                        }
                    }
                    paged.put_index_entry(xid, &def.name, &key, &record.id, payload)?;
                    // A re-insert after a folded delete must clear the hide.
                    paged.delete_posting_tombstone(xid, &def.name, &key, &record.id)?;
                    // v2 twin CARRIES THE PAYLOAD: the impact scan must rank
                    // as it walks, and a per-posting point probe back into
                    // the v1 keyspace is a cold random read on a big corpus.
                    // Written even when the index predates v2 — harmless
                    // until a backfill plants the completeness sentinel.
                    if let Some((_, _, packed)) = decode_fts_posting_payload(payload) {
                        paged.put_index_entry_v2(
                            xid,
                            &def.name,
                            &key,
                            fts_impact_bucket(&packed),
                            &record.id,
                            payload,
                        )?;
                    }
                }
                // The rewrite makes the row's own state authoritative (its
                // projection, or its emptiness): a doc-terms blob left from
                // the bulk build is now stale — drop it.
                if old_from_blob {
                    paged.delete_doc_terms(xid, &def.name, &record.id)?;
                }
            }
            // Packed spatial (the only spatial kind in `defs`): one delta row
            // per touched pk. Any delta row masks the pk's packed entries;
            // an upsert additionally carries its current MBR/point so reopen
            // can rebuild the resident delta tree without touching the row.
            IndexKind::Spatial => {
                let field = def.fields.first().ok_or_else(|| {
                    BicDbError::Index(format!("spatial index `{}` has no field", def.name))
                })?;
                let payload = match record_spatial_geometry(record, field)? {
                    Some(geometry) => {
                        let entry = spatial_index_entry(record.id.clone(), &geometry)?;
                        spatial_packed::encode_delta_upsert(&packed_entry_from_index_entry(&entry))
                    }
                    None => {
                        // No geometry now: if it never had one there is no
                        // packed entry to mask and the tombstone is harmless;
                        // if geometry was removed, the mask is required.
                        spatial_packed::encode_delta_tombstone()
                    }
                };
                paged.put_spatial_delta(xid, &def.name, &record.id, &payload)?;
            }
            _ => {
                let new_matches = record_matches_index_predicate_parts(
                    record,
                    &def.name,
                    def.predicate.as_ref(),
                )?;
                let new_key =
                    new_matches.then(|| encode_index_key(&record_index_key(record, &def.fields)));
                let old_key = previous
                    .map(|previous| -> Result<Option<Vec<u8>>> {
                        Ok(record_matches_index_predicate_parts(
                            previous,
                            &def.name,
                            def.predicate.as_ref(),
                        )?
                        .then(|| encode_index_key(&record_index_key(previous, &def.fields))))
                    })
                    .transpose()?
                    .flatten();
                if let Some(old_key) = old_key
                    .as_ref()
                    .filter(|old| Some(*old) != new_key.as_ref())
                {
                    match def.entry_format {
                        crate::paged_collection::IndexEntryFormat::V2 => {
                            paged.delete_index_entry(xid, &def.name, old_key, &record.id)?;
                        }
                        crate::paged_collection::IndexEntryFormat::V3 => {
                            // The old entry was written under the row's
                            // current intern id (ids are stable for a pk's
                            // lifetime; deletes retire them).
                            let id = paged.intern_or_alloc(xid, collection, &record.id)?;
                            paged.delete_index_entry_intern(xid, &def.name, old_key, id)?;
                        }
                    }
                }
                if let Some(new_key) = new_key
                    .as_ref()
                    .filter(|new| Some(*new) != old_key.as_ref())
                {
                    // Atomic check-and-insert for unique indexes: this runs
                    // under the store write guard, and the own-writes
                    // snapshot sees committed state plus this batch's earlier
                    // writes, so no other committer can interleave between
                    // the probe and the put. Enforcement authority is still
                    // the pre-WAL validation plus per-key claims (an abort
                    // here happens after the core commit is sequenced); the
                    // probe is the in-transaction backstop that turns a
                    // bypassed validation into a loud error instead of a
                    // silently corrupt unique index. Always on in debug
                    // builds; release builds opt in via
                    // BICDB_PAGED_UNIQUE_APPLY_PROBE=1 until the claims
                    // machinery is retired.
                    if def.unique
                        && paged_unique_apply_probe_enabled()
                        && !index_key_contains_null(&decode_index_key(new_key))
                    {
                        let own_writes = bicdb_page::Snapshot {
                            xid,
                            xmax: xid + 1,
                            in_flight: empty_in_flight(),
                        };
                        let own_id = match def.entry_format {
                            crate::paged_collection::IndexEntryFormat::V2 => None,
                            crate::paged_collection::IndexEntryFormat::V3 => {
                                Some(paged.intern_or_alloc(xid, collection, &record.id)?)
                            }
                        };
                        for entry in paged.scan_index_exact_refs(&own_writes, &def.name, new_key)? {
                            let (entry_ref, _) = entry?;
                            let collides = match &entry_ref {
                                crate::paged_collection::IndexEntryRef::Pk(pk) => *pk != record.id,
                                crate::paged_collection::IndexEntryRef::Intern(id) => {
                                    own_id != Some(*id)
                                }
                            };
                            if collides {
                                return Err(BicDbError::Index(format!(
                                    "unique index `{}` has duplicate keys (apply-time probe: \
                                     `{}` collides with `{entry_ref:?}`)",
                                    def.name, record.id
                                )));
                            }
                        }
                    }
                    match def.entry_format {
                        crate::paged_collection::IndexEntryFormat::V2 => {
                            paged.put_index_entry(
                                xid,
                                &def.name,
                                new_key,
                                &record.id,
                                tid_hint.as_ref().map(|hint| &hint[..]).unwrap_or(&[]),
                            )?;
                        }
                        crate::paged_collection::IndexEntryFormat::V3 => {
                            let id = paged.intern_or_alloc(xid, collection, &record.id)?;
                            paged.put_index_entry_intern(
                                xid,
                                &def.name,
                                new_key,
                                id,
                                tid_hint.as_ref().map(|hint| &hint[..]).unwrap_or(&[]),
                            )?;
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

/// Remove the durable entries of every index in `defs` for one deleted row.
fn apply_paged_index_delete(
    paged: &crate::paged_collection::PagedRecords,
    xid: bicdb_page::Xid,
    collection: &str,
    defs: &[PagedDurableIndexDef],
    previous: &Record,
    record_id: &str,
) -> Result<()> {
    for def in defs {
        match def.kind {
            IndexKind::FullText => {
                let fields = full_text_fields(def)?;
                let (old_postings, old_from_blob) =
                    full_text_diff_postings(paged, &def.name, fields, previous)?;
                for (term, payload) in old_postings {
                    let key = full_text_term_entry_key(&term);
                    let was_in_tail = paged.delete_index_entry(xid, &def.name, &key, record_id)?;
                    if let Some((_, _, packed)) = decode_fts_posting_payload(&payload) {
                        paged.delete_index_entry_v2(
                            xid,
                            &def.name,
                            &key,
                            fts_impact_bucket(&packed),
                            record_id,
                        )?;
                    }
                    if !was_in_tail {
                        paged.put_posting_tombstone(xid, &def.name, &key, record_id)?;
                    }
                }
                if old_from_blob {
                    paged.delete_doc_terms(xid, &def.name, record_id)?;
                }
            }
            IndexKind::Spatial => {
                paged.put_spatial_delta(
                    xid,
                    &def.name,
                    record_id,
                    &spatial_packed::encode_delta_tombstone(),
                )?;
            }
            _ => {
                if record_matches_index_predicate_parts(
                    previous,
                    &def.name,
                    def.predicate.as_ref(),
                )? {
                    let old_key = encode_index_key(&record_index_key(previous, &def.fields));
                    match def.entry_format {
                        crate::paged_collection::IndexEntryFormat::V2 => {
                            paged.delete_index_entry(xid, &def.name, &old_key, record_id)?;
                        }
                        crate::paged_collection::IndexEntryFormat::V3 => {
                            if let Some(id) = paged.intern_id_for_pk(
                                &own_writes_snapshot(xid),
                                collection,
                                record_id,
                            )? {
                                paged.delete_index_entry_intern(xid, &def.name, &old_key, id)?;
                            }
                        }
                    }
                }
            }
        }
    }
    // The row is gone from every index: retire its intern id so a future
    // re-insert of the same pk allocates fresh (ids never span a delete).
    if defs
        .iter()
        .any(|def| def.entry_format == crate::paged_collection::IndexEntryFormat::V3)
    {
        paged.retire_intern(xid, collection, record_id)?;
    }
    Ok(())
}

/// The snapshot a paged apply uses to see committed state plus its own batch.
fn own_writes_snapshot(xid: bicdb_page::Xid) -> bicdb_page::Snapshot {
    bicdb_page::Snapshot {
        xid,
        xmax: xid + 1,
        in_flight: empty_in_flight(),
    }
}

fn record_full_text_terms(record: &Record, fields: &[IndexField]) -> Result<Vec<String>> {
    Ok(record_full_text_postings(record, fields)?
        .into_iter()
        .map(|(term, _)| term)
        .collect())
}

/// Version tag of the binary posting payload stored in durable FTS entry
/// values. Layout v1: `[1u8][len u32 LE][distinct u32 LE][count u16 LE]
/// [packed_position u16 LE]*count` — `len`/`distinct` are the document
/// scalars ts_rank normalization needs, positions are the projection's
/// packed `(position | weight<<14)` values in canonical order.
const FTS_POSTING_PAYLOAD_V1: u8 = 1;

/// Impact bucket of one posting: the quantized DEFAULT-WEIGHT single-operand
/// raw ts_rank contribution (sum of weights[w]/(i+1)^2 over canonical
/// positions), monotone in relevance for single-term default-weight
/// unnormalized queries — the shape the impact-ordered scan early-terminates.
/// Positionless postings score as one D-weight occurrence (rank parity).
pub fn fts_impact_bucket(packed_positions: &[u16]) -> u16 {
    // EXACTLY rank_or's per-lexeme term for a single unweighted operand
    // (same accumulation order over the canonical positions, same constant),
    // so the real rank of a remaining posting is strictly below its bucket's
    // upper edge. sqrt spreads the D-weight range (scores <= ~0.06) across
    // enough buckets to terminate on; the edge inverse is ((b+1)/255)^2.
    const DEFAULT_WEIGHTS: [f32; 4] = [0.1, 0.2, 0.4, 1.0];
    let mut sum = 0.0f32;
    let mut maximum = (-1.0f32, 0usize);
    if packed_positions.is_empty() {
        sum = DEFAULT_WEIGHTS[0];
        maximum = (DEFAULT_WEIGHTS[0], 0);
    } else {
        for (index, packed) in packed_positions.iter().enumerate() {
            let weight = DEFAULT_WEIGHTS[((packed >> 14) & 0x3) as usize];
            sum += weight / ((index + 1) * (index + 1)) as f32;
            if weight > maximum.0 {
                maximum = (weight, index);
            }
        }
    }
    let score =
        (maximum.0 + sum - maximum.0 / ((maximum.1 + 1) * (maximum.1 + 1)) as f32) / 1.644_934_1;
    (score.clamp(0.0, 1.0).sqrt() * 65_535.0).min(65_535.0) as u16
}

/// Upper edge (exclusive) of an impact bucket: no posting in bucket `b` can
/// rank at or above this under the single-term default-weight shape.
pub fn fts_impact_bucket_upper_edge(bucket: u16) -> f32 {
    let edge = (bucket as f32 + 1.0) / 65_535.0;
    edge * edge
}

/// Decode a v1 posting payload: `(doc_length, doc_distinct, packed positions)`.
/// `None` for empty (legacy, pre-position) or unrecognized payloads — the
/// caller must fall back to ranking from row text.
/// Inverse of [`decode_fts_posting_payload`] — used to hand block-resident
/// postings to callers in the same payload form the per-posting tail uses.
pub fn encode_fts_posting_payload(doc_length: u32, doc_distinct: u32, packed: &[u16]) -> Vec<u8> {
    let mut payload = Vec::with_capacity(11 + packed.len() * 2);
    payload.push(FTS_POSTING_PAYLOAD_V1);
    payload.extend_from_slice(&doc_length.to_le_bytes());
    payload.extend_from_slice(&doc_distinct.to_le_bytes());
    payload.extend_from_slice(&(packed.len() as u16).to_le_bytes());
    for value in packed {
        payload.extend_from_slice(&value.to_le_bytes());
    }
    payload
}

/// [`decode_fts_posting_payload`] into a caller-owned scratch buffer:
/// no allocation per posting on hot scans.
pub fn decode_fts_posting_payload_into(bytes: &[u8], packed: &mut Vec<u16>) -> Option<(u32, u32)> {
    if bytes.first() != Some(&FTS_POSTING_PAYLOAD_V1) || bytes.len() < 11 {
        return None;
    }
    let doc_len = u32::from_le_bytes(bytes[1..5].try_into().ok()?);
    let distinct = u32::from_le_bytes(bytes[5..9].try_into().ok()?);
    let count = u16::from_le_bytes(bytes[9..11].try_into().ok()?) as usize;
    packed.clear();
    let mut cursor = 11usize;
    for _ in 0..count {
        packed.push(u16::from_le_bytes(
            bytes.get(cursor..cursor + 2)?.try_into().ok()?,
        ));
        cursor += 2;
    }
    Some((doc_len, distinct))
}

/// EXACT `ts_rank` value of a single-operand tsquery against one posting's
/// packed positions, normalization 0 — the closed form of `rank_or` for one
/// matching lexeme (same accumulation order, same 1/zeta(2) constant, same
/// D-at-0 substitution for position-less postings). This is what lets the
/// ranked scan score straight off block bytes instead of building a sparse
/// tsvector and walking the query tree per posting. Must stay in lockstep
/// with `rank_or` in bicdb-sql/src/fts.rs and with [`fts_impact_bucket`].
/// Verdict of the ranked scan's per-block gate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BlockGate {
    /// Decode and score this block.
    Scan,
    /// This block cannot improve the top-k; the ordering does not prove the
    /// same for LATER blocks (exact maxima are not monotonic within an
    /// impact bucket) — skip it and keep walking.
    Skip,
    /// The bucket bound proves no remaining block can improve the top-k.
    Stop,
}

pub fn fts_rank_single_term(packed_positions: &[u16], weights: [f32; 4]) -> f32 {
    let mut sum = 0.0f32;
    let mut maximum = (-1.0f32, 0usize);
    if packed_positions.is_empty() {
        sum = weights[0];
        maximum = (weights[0], 0);
    } else {
        for (index, packed) in packed_positions.iter().enumerate() {
            let weight = weights[((packed >> 14) & 0x3) as usize];
            sum += weight / ((index + 1) * (index + 1)) as f32;
            if weight > maximum.0 {
                maximum = (weight, index);
            }
        }
    }
    (maximum.0 + sum - maximum.0 / ((maximum.1 + 1) * (maximum.1 + 1)) as f32) / 1.644_934_1
}

/// EXACT `ts_rank` of an And/Phrase tsquery over one document, computed from
/// packed position lists — the closed form of `rank_and` (bicdb-sql fts.rs).
///
/// `term_positions` holds one entry per DISTINCT operand, in sorted-by-text
/// order (rank_and's operand order after sort+dedup); `None` = the document
/// does not contain that term (the operand matches no lexeme and contributes
/// no pairs), `Some(&[])` = present without positions (rank_and substitutes
/// a D-weight position at MAX_POSITION-1). Pair iteration order, the
/// distance-decay constants, and the noisy-OR accumulation mirror `rank_and`
/// exactly — the lockstep property test pins the two bit-for-bit.
///
/// Valid ONLY for trees with no Not (ts_rank's operand collection includes
/// negated operands, which this signature cannot express) and ranks like
/// ts_rank at normalization 0.
pub fn fts_rank_conjunctive(term_positions: &[Option<&[u16]>], weights: [f32; 4]) -> f32 {
    const MAX_POSITION: u16 = 16_383;
    const SUBSTITUTE: &[u16] = &[MAX_POSITION - 1];
    // ts_rank short-circuits an EMPTY document to 0.0 before rank_and's
    // "no pairs" clamp to 1e-20 ever runs — mirror it.
    if term_positions.iter().all(Option::is_none) {
        return 0.0;
    }
    let mut result = -1.0f32;
    for index in 1..term_positions.len() {
        let Some(current) = term_positions[index] else {
            continue;
        };
        let current = if current.is_empty() {
            SUBSTITUTE
        } else {
            current
        };
        for previous in &term_positions[..index] {
            let Some(previous) = *previous else {
                continue;
            };
            let previous = if previous.is_empty() {
                SUBSTITUTE
            } else {
                previous
            };
            for left in previous {
                let left_position = left & MAX_POSITION;
                let left_weight = weights[((left >> 14) & 0x3) as usize];
                for right in current {
                    let right_position = right & MAX_POSITION;
                    let right_weight = weights[((right >> 14) & 0x3) as usize];
                    let mut distance = left_position.abs_diff(right_position);
                    if distance == 0 {
                        distance = MAX_POSITION;
                    }
                    let distance_weight = if distance > 100 {
                        1e-30
                    } else {
                        1.0 / (1.005 + 0.05 * ((distance as f32) / 1.5 - 2.0).exp())
                    };
                    let current_value = (left_weight * right_weight * distance_weight).sqrt();
                    result = if result < 0.0 {
                        current_value
                    } else {
                        1.0 - (1.0 - result) * (1.0 - current_value)
                    };
                }
            }
        }
    }
    if result < 0.0 {
        1e-20
    } else {
        result
    }
}

pub fn decode_fts_posting_payload(bytes: &[u8]) -> Option<(u32, u32, Vec<u16>)> {
    if bytes.first() != Some(&FTS_POSTING_PAYLOAD_V1) || bytes.len() < 11 {
        return None;
    }
    let doc_len = u32::from_le_bytes(bytes[1..5].try_into().ok()?);
    let distinct = u32::from_le_bytes(bytes[5..9].try_into().ok()?);
    let count = u16::from_le_bytes(bytes[9..11].try_into().ok()?) as usize;
    let mut packed = Vec::with_capacity(count);
    let mut cursor = 11usize;
    for _ in 0..count {
        packed.push(u16::from_le_bytes(
            bytes.get(cursor..cursor + 2)?.try_into().ok()?,
        ));
        cursor += 2;
    }
    Some((doc_len, distinct, packed))
}

/// `(term, posting payload)` pairs for a record's full-text projection,
/// sorted and deduplicated by term (callers binary-search the term list).
///
/// Two projection shapes exist: the legacy plain array of term strings
/// (payloads empty — rank-from-index falls back for such postings) and the
/// v1 object `{"v":1,"len":L,"distinct":D,"lex":{term:[packed…]}}` written
/// by 0.9.48+, whose positions become the payload.
/// Previous-state postings for an UPDATE/DELETE diff, derived from the row
/// itself: a projection object is parsed, a pre-tokenized array is taken as
/// given, and raw text goes through the same tokenizer the build used — so
/// the retraction is exactly what the build indexed. The doc-terms blob is
/// consulted only when the row yields nothing: legacy generations built
/// before 1.0.227 wrote one per row (and their rows may predate the
/// projection format), and direct-document ingestion still writes them
/// because those terms are caller-tokenized with no row to rederive from.
/// Returns `(postings, from_blob)`; the caller drops the blob once the
/// row's own state becomes authoritative again.
fn full_text_diff_postings(
    paged: &crate::paged_collection::PagedRecords,
    index: &str,
    fields: &[IndexField],
    record: &Record,
) -> Result<(Vec<(String, Vec<u8>)>, bool)> {
    let postings = record_full_text_postings(record, fields)?;
    if !postings.is_empty() {
        return Ok((postings, false));
    }
    let snapshot = paged.latest_snapshot();
    if let Some(blob) = paged.get_doc_terms(&snapshot, index, &record.id)? {
        let (doc_length, doc_distinct, terms) = crate::paged_collection::decode_doc_terms(&blob)?;
        let postings = terms
            .into_iter()
            .filter(|(term, _)| full_text_term_is_indexable(term))
            .map(|(term, positions)| {
                let payload = encode_fts_posting_payload(doc_length, doc_distinct, &positions);
                (term, payload)
            })
            .collect();
        return Ok((postings, true));
    }
    Ok((postings, false))
}

/// `BICDB_FTS_BUILD_TRACE=1` prints per-phase wall times of the external
/// full-text build to stderr — the knob the build A/B probes read.
/// Global budget of EXTRA scan threads shared by every parallel FTS
/// conjunction in the process. A solo query fans out to the full range
/// split; under concurrent load each query acquires only what remains and
/// degrades gracefully toward the sequential scan — without a budget, N
/// concurrent queries each spawning a full worker set oversubscribe the
/// host superlinearly (the recommend-then-measure trap of per-query
/// parallelism).
static FTS_SCAN_EXTRA_PERMITS: std::sync::OnceLock<std::sync::atomic::AtomicIsize> =
    std::sync::OnceLock::new();

fn fts_scan_permit_pool() -> &'static std::sync::atomic::AtomicIsize {
    FTS_SCAN_EXTRA_PERMITS.get_or_init(|| {
        let cores = std::thread::available_parallelism()
            .map(usize::from)
            .unwrap_or(1);
        std::sync::atomic::AtomicIsize::new(cores.saturating_sub(1) as isize)
    })
}

/// Take up to `wanted` extra-thread permits without blocking; returns what
/// was actually granted. The caller's own thread never needs a permit.
fn acquire_fts_scan_permits(wanted: usize) -> usize {
    if wanted == 0 {
        return 0;
    }
    let pool = fts_scan_permit_pool();
    let mut available = pool.load(AtomicOrdering::Relaxed);
    loop {
        if available <= 0 {
            return 0;
        }
        let granted = (available as usize).min(wanted);
        match pool.compare_exchange_weak(
            available,
            available - granted as isize,
            AtomicOrdering::AcqRel,
            AtomicOrdering::Relaxed,
        ) {
            Ok(_) => return granted,
            Err(current) => available = current,
        }
    }
}

struct FtsScanPermits(usize);

impl Drop for FtsScanPermits {
    fn drop(&mut self) {
        if self.0 > 0 {
            fts_scan_permit_pool().fetch_add(self.0 as isize, AtomicOrdering::AcqRel);
        }
    }
}

static FTS_BUILD_OPEN_NANOS: AtomicU64 = AtomicU64::new(0);
static FTS_BUILD_PUT_NANOS: AtomicU64 = AtomicU64::new(0);
static FTS_BUILD_APPEND_NANOS: AtomicU64 = AtomicU64::new(0);

fn fts_build_trace(index: &str, phase: &str, started: Instant) {
    if std::env::var("BICDB_FTS_BUILD_TRACE").as_deref() == Ok("1") {
        eprintln!("fts-build {index}: {phase} took {:?}", started.elapsed());
    }
}

/// Tokenize one scan batch into pk-ordered `(pk, doc-terms blob)` pairs,
/// fanned out across `workers` threads (chunked, joined in order, so the
/// output ordering is identical to the sequential loop). Tokenization is
/// pure per-record CPU — projection decode, term sort, blob encode — which
/// is exactly what was serializing the build scan against disk.
///
/// Returns `Ok(None)` when any record carries a legacy payload-less
/// projection: the caller abandons the block build and falls back to the
/// per-posting path, as before.
/// Whether a character ends a full-text token.
///
/// `is_alphanumeric()` alone is not enough. It uses the Unicode `Alphabetic`
/// property, which includes `Other_Alphabetic` and therefore already covers
/// Thai, Lao and Indic vowel signs — but NOT the Latin combining marks in
/// U+0300..U+036F. So `cafe` + U+0301 (the decomposed spelling of `café`,
/// which is what macOS-originated text and some HTML pipelines produce) split
/// into `cafe` plus a stray mark, and never matched the precomposed form.
///
/// Combining marks belong inside the word they modify. This also aligns the
/// core indexer with the SQL layer's `is_text_token_character`, which already
/// admitted marks — two tokenizers disagreeing about word boundaries is how a
/// document gets indexed under terms no query can produce.
fn full_text_is_token_boundary(character: char) -> bool {
    !(character.is_alphanumeric()
        || character == '_'
        || unicode_categories::UnicodeCategories::is_mark(character))
}

fn tokenize_full_text_batch(
    batch: &[Record],
    fields: &[IndexField],
    workers: usize,
) -> Result<Option<Vec<(String, Vec<u8>)>>> {
    fn tokenize_chunk(
        chunk: &[Record],
        fields: &[IndexField],
    ) -> Result<Option<Vec<(String, Vec<u8>)>>> {
        let mut blobs = Vec::with_capacity(chunk.len());
        for record in chunk {
            let postings = record_full_text_postings(record, fields)?;
            let mut terms = Vec::with_capacity(postings.len());
            let mut doc_length = 0u32;
            let mut doc_distinct = 0u32;
            for (term, payload) in postings {
                let Some((length, distinct, positions)) = decode_fts_posting_payload(&payload)
                else {
                    return Ok(None);
                };
                doc_length = length;
                doc_distinct = distinct;
                terms.push((term, positions));
            }
            terms.sort_by(|left, right| left.0.cmp(&right.0));
            blobs.push((
                record.id.clone(),
                BicDb::encode_fts_doc_terms(doc_length, doc_distinct, &terms),
            ));
        }
        Ok(Some(blobs))
    }

    let workers = workers.clamp(1, 64).min(batch.len().max(1));
    if workers == 1 || batch.len() < 128 {
        return tokenize_chunk(batch, fields);
    }
    let chunk_size = batch.len().div_ceil(workers);
    let results = std::thread::scope(|scope| {
        let handles: Vec<_> = batch
            .chunks(chunk_size)
            .map(|chunk| scope.spawn(move || tokenize_chunk(chunk, fields)))
            .collect();
        handles
            .into_iter()
            .map(|handle| {
                handle.join().map_err(|_| {
                    BicDbError::Index("full-text tokenize worker panicked".to_string())
                })?
            })
            .collect::<Result<Vec<_>>>()
    })?;
    let mut blobs = Vec::with_capacity(batch.len());
    for chunk in results {
        let Some(chunk) = chunk else { return Ok(None) };
        blobs.extend(chunk);
    }
    Ok(Some(blobs))
}

fn record_full_text_postings(
    record: &Record,
    fields: &[IndexField],
) -> Result<Vec<(String, Vec<u8>)>> {
    if fields.is_empty() {
        return Err(BicDbError::Index(
            "full-text index requires at least one projection field".to_string(),
        ));
    }
    if fields.len() > 1 {
        return record_raw_full_text_postings(record, fields);
    }
    let field = &fields[0];
    let IndexField::MetadataPath(path) = field else {
        return Err(BicDbError::Index(
            "full-text indexes require a metadata projection field".to_string(),
        ));
    };
    let Some(value) = json_path(&record.metadata, path) else {
        return Ok(Vec::new());
    };
    // PostgreSQL full-text indexes omit NULL source values. A typed resource
    // record preserves an explicit JSON null for a nullable field, so treat it
    // exactly like a missing projection instead of rejecting the transaction
    // at commit time.
    if value.is_null() {
        return Ok(Vec::new());
    }
    if let Some(values) = value.as_array() {
        let mut terms = values
            .iter()
            .map(|value| {
                value.as_str().map(str::to_string).ok_or_else(|| {
                    BicDbError::Index(
                        "full-text index projection contains a non-string term".to_string(),
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        terms.retain(|term| full_text_term_is_indexable(term));
        terms.sort();
        terms.dedup();
        return Ok(terms.into_iter().map(|term| (term, Vec::new())).collect());
    }
    if value.is_string() {
        return record_raw_full_text_postings(record, fields);
    }
    let Some(object) = value.as_object() else {
        return Err(BicDbError::Index(
            "full-text index projection must be a term array or projection object".to_string(),
        ));
    };
    let doc_len = object
        .get("len")
        .and_then(|value| value.as_u64())
        .unwrap_or(0) as u32;
    let distinct = object
        .get("distinct")
        .and_then(|value| value.as_u64())
        .unwrap_or(0) as u32;
    let Some(lex) = object.get("lex").and_then(|value| value.as_object()) else {
        return Err(BicDbError::Index(
            "full-text projection object is missing its lexeme map".to_string(),
        ));
    };
    // serde_json map iteration is key-ordered, so terms arrive sorted+unique.
    let mut postings = Vec::with_capacity(lex.len());
    for (term, positions) in lex {
        if !full_text_term_is_indexable(term) {
            continue;
        }
        let positions = positions.as_array().ok_or_else(|| {
            BicDbError::Index("full-text projection positions must be an array".to_string())
        })?;
        let mut payload = Vec::with_capacity(11 + positions.len() * 2);
        payload.push(FTS_POSTING_PAYLOAD_V1);
        payload.extend_from_slice(&doc_len.to_le_bytes());
        payload.extend_from_slice(&distinct.to_le_bytes());
        payload.extend_from_slice(&(positions.len() as u16).to_le_bytes());
        for packed in positions {
            let packed = packed.as_u64().ok_or_else(|| {
                BicDbError::Index("full-text projection position is not an integer".to_string())
            })? as u16;
            payload.extend_from_slice(&packed.to_le_bytes());
        }
        postings.push((term.clone(), payload));
    }
    Ok(postings)
}

/// Build the same position-carrying projection used by SQL GIN indexes from
/// explicitly declared raw text fields. This keeps tokenizer and term-boundary
/// policy inside BicDB while allowing typed application contracts to index
/// source fields without manufacturing a duplicate `search_text` column.
///
/// The first four fields map to tsvector weights A, B, C and D respectively;
/// additional fields share D. Positions are local to a field and bounded by
/// the 14-bit posting format.
fn record_raw_full_text_postings(
    record: &Record,
    fields: &[IndexField],
) -> Result<Vec<(String, Vec<u8>)>> {
    let mut terms = BTreeMap::<String, Vec<u16>>::new();
    let mut document_length = 0u32;
    for (field_index, field) in fields.iter().enumerate() {
        let IndexField::MetadataPath(path) = field else {
            return Err(BicDbError::Index(
                "raw full-text indexes require metadata projection fields".to_string(),
            ));
        };
        let Some(value) = json_path(&record.metadata, path) else {
            continue;
        };
        let texts = match value {
            serde_json::Value::String(text) => vec![text.as_str()],
            serde_json::Value::Array(values) => values
                .iter()
                .map(|value| {
                    value.as_str().ok_or_else(|| {
                        BicDbError::Index(
                            "raw full-text array contains a non-string value".to_string(),
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            serde_json::Value::Null => continue,
            _ => {
                return Err(BicDbError::Index(
                    "raw full-text projection must contain text or an array of text".to_string(),
                ));
            }
        };
        let weight = 3u16.saturating_sub(field_index.min(3) as u16);
        let mut position = 0u16;
        for text in texts {
            for token in text
                .split(full_text_is_token_boundary)
                .filter(|token| !token.is_empty())
                .map(str::to_lowercase)
            {
                if !full_text_term_is_indexable(&token) {
                    continue;
                }
                if position == 0x3fff {
                    break;
                }
                position += 1;
                document_length = document_length.saturating_add(1);
                terms
                    .entry(token)
                    .or_default()
                    .push((weight << 14) | position);
            }
        }
    }
    let distinct = u32::try_from(terms.len())
        .map_err(|_| BicDbError::Index("full-text document has too many terms".to_string()))?;
    Ok(terms
        .into_iter()
        .map(|(term, positions)| {
            let mut payload = Vec::with_capacity(11 + positions.len() * 2);
            payload.push(FTS_POSTING_PAYLOAD_V1);
            payload.extend_from_slice(&document_length.to_le_bytes());
            payload.extend_from_slice(&distinct.to_le_bytes());
            payload.extend_from_slice(&(positions.len() as u16).to_le_bytes());
            for packed in positions {
                payload.extend_from_slice(&packed.to_le_bytes());
            }
            (term, payload)
        })
        .collect())
}

fn index_key_contains_null(key: &[IndexValue]) -> bool {
    key.iter().any(|value| matches!(value, IndexValue::Null))
}

fn index_value_text(value: &IndexValue) -> String {
    match value {
        IndexValue::Null => String::new(),
        IndexValue::Bool(value) => value.to_string(),
        IndexValue::Int(value) => value.to_string(),
        IndexValue::Float(value) => value.to_string(),
        IndexValue::String(value) => value.clone(),
    }
}

/// Rows ANALYZE examines per table. PostgreSQL samples
/// `300 × default_statistics_target` = 30 000 rows; a table at or under the
/// limit is analyzed exactly. `BICDB_ANALYZE_SAMPLE_ROWS` overrides it
/// (0 = analyze every row). Before this bound ANALYZE materialized every row
/// of every table several times over: the 16-warehouse TPC-C seed (5.6 GB on
/// disk) took the loader from 13 GB to over 50 GB resident inside its final
/// ANALYZE and the kernel killed it.
pub fn analyze_sample_limit() -> usize {
    match std::env::var("BICDB_ANALYZE_SAMPLE_ROWS")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
    {
        Some(0) => usize::MAX,
        Some(limit) => limit,
        None => 30_000,
    }
}

/// Deterministic reservoir sampler (Algorithm R over a xorshift64* stream).
/// Every row of the scan is offered in turn; `offer` answers with the slot the
/// row should occupy in the sample, or `None` to skip it. Seeded from the
/// collection name so repeated ANALYZE runs over unchanged data produce the
/// same statistics and therefore the same plans.
pub struct AnalyzeSampler {
    limit: usize,
    seen: usize,
    state: u64,
}

impl AnalyzeSampler {
    pub fn new(limit: usize, seed: &str) -> Self {
        // FNV-1a; any non-zero seed works for xorshift.
        let mut state = 0xcbf2_9ce4_8422_2325u64;
        for byte in seed.bytes() {
            state ^= u64::from(byte);
            state = state.wrapping_mul(0x0000_0100_0000_01b3);
        }
        Self {
            limit,
            seen: 0,
            state: state | 1,
        }
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.state;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.state = x;
        x.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }

    /// Slot for the next offered row: `Some(index)` to store it at `index`
    /// (`index == current sample length` means append), `None` to skip.
    pub fn offer(&mut self) -> Option<usize> {
        let position = self.seen;
        self.seen += 1;
        if position < self.limit {
            return Some(position);
        }
        let slot = (self.next_u64() % (position as u64 + 1)) as usize;
        (slot < self.limit).then_some(slot)
    }

    /// Rows offered so far.
    pub fn seen(&self) -> usize {
        self.seen
    }
}

/// Scale a count observed over `sample_rows` rows up to `total_rows`.
pub fn scale_sample_count(count: usize, sample_rows: usize, total_rows: usize) -> usize {
    if sample_rows == 0 || sample_rows >= total_rows {
        return count;
    }
    let scaled = (count as f64 * total_rows as f64 / sample_rows as f64).round() as usize;
    scaled.min(total_rows)
}

/// Distinct-value estimate for a whole table from a sample, using the
/// Duj1 estimator PostgreSQL's ANALYZE uses (Haas & Stokes):
/// `D = n·d / (n − f1 + f1·n/N)` where `d` distinct values were seen in
/// `n` sampled rows, `f1` of them exactly once, out of `N` rows in total.
/// A sample that covers the table returns `distinct` unchanged.
pub fn estimate_distinct_from_sample(
    distinct: usize,
    singletons: usize,
    sample_rows: usize,
    total_rows: usize,
) -> usize {
    if sample_rows == 0 || sample_rows >= total_rows || distinct == 0 {
        return distinct;
    }
    let n = sample_rows as f64;
    let d = distinct as f64;
    let f1 = singletons.min(distinct) as f64;
    let total = total_rows as f64;
    let denominator = n - f1 + f1 * n / total;
    let estimate = if denominator <= 0.0 {
        total
    } else {
        (n * d / denominator).round()
    };
    (estimate as usize).clamp(distinct, total_rows)
}

fn collect_column_statistics(
    records: &RecordMap,
    field: IndexField,
    row_count: usize,
) -> ColumnStatistics {
    let mut null_count = 0;
    let mut frequencies = BTreeMap::<IndexValue, usize>::new();
    let mut min = None::<IndexValue>;
    let mut max = None::<IndexValue>;

    for entry in records.values() {
        let Ok(record) = entry.record.to_record() else {
            continue;
        };
        let value = record_index_key(&record, std::slice::from_ref(&field))
            .into_iter()
            .next()
            .unwrap_or(IndexValue::Null);
        if matches!(value, IndexValue::Null) {
            null_count += 1;
        } else {
            min = Some(match min {
                Some(current) => current.min(value.clone()),
                None => value.clone(),
            });
            max = Some(match max {
                Some(current) => current.max(value.clone()),
                None => value.clone(),
            });
        }
        *frequencies.entry(value).or_insert(0) += 1;
    }

    let mut most_common = frequencies
        .iter()
        .map(|(value, count)| ValueFrequency {
            value: value.clone(),
            count: *count,
        })
        .collect::<Vec<_>>();
    most_common.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then_with(|| left.value.cmp(&right.value))
    });
    most_common.truncate(16);

    // `records` may be a sample of a larger table: scale the absolute counts
    // the planner reads as row estimates up to `row_count`.
    let sample_rows = records.len();
    let distinct_count = estimate_distinct_from_sample(
        frequencies.len(),
        frequencies.values().filter(|count| **count == 1).count(),
        sample_rows,
        row_count,
    );
    let null_count = scale_sample_count(null_count, sample_rows, row_count);
    for common in &mut most_common {
        common.count = scale_sample_count(common.count, sample_rows, row_count);
    }

    ColumnStatistics {
        field,
        row_count,
        null_count,
        distinct_count,
        min,
        max,
        most_common,
        range: None,
        network: None,
        typed: None,
    }
}

fn index_field_stats_name(field: &IndexField) -> String {
    match field {
        IndexField::Id => "id".to_string(),
        IndexField::Timestamp => "timestamp".to_string(),
        IndexField::Geometry => "geometry".to_string(),
        IndexField::MetadataPath(path) => path.join("."),
        IndexField::Lower(inner) => format!("lower({})", index_field_stats_name(inner)),
        IndexField::Trim(inner) => format!("trim({})", index_field_stats_name(inner)),
    }
}

fn record_spatial_geometry(record: &Record, field: &IndexField) -> Result<Option<Geometry>> {
    match field {
        IndexField::Geometry => Ok(record.geometry.clone()),
        IndexField::MetadataPath(path) => {
            let Some(value) = json_path(&record.metadata, path).or_else(|| {
                record
                    .metadata
                    .get("metadata")
                    .and_then(|metadata| json_path(metadata, path))
            }) else {
                return Ok(None);
            };
            geometry_from_json_value(value).map(Some).map_err(|error| {
                BicDbError::Index(format!("invalid spatial index geometry: {error}"))
            })
        }
        other => Err(BicDbError::Index(format!(
            "spatial index field {:?} is not a geometry field",
            other
        ))),
    }
}

fn spatial_record_point(record: &Record, field: &IndexField) -> Result<Option<[f64; 2]>> {
    let Some(geometry) = record_spatial_geometry(record, field)? else {
        return Ok(None);
    };
    match geometry {
        Geometry::Point(point) => Ok(Some([point.x(), point.y()])),
        other => Err(BicDbError::Index(format!(
            "spatial nearest and radius queries support only point geometries, got {}",
            spatial_geometry_name(&other)
        ))),
    }
}

fn spatial_field_from_name(field: &str) -> Result<IndexField> {
    let trimmed = field.trim();
    if trimmed.is_empty() {
        return Err(BicDbError::Index(
            "spatial field name cannot be empty".to_string(),
        ));
    }
    if trimmed.eq_ignore_ascii_case("geometry") {
        return Ok(IndexField::Geometry);
    }
    let path = trimmed
        .split('.')
        .map(str::trim)
        .map(str::to_string)
        .collect::<Vec<_>>();
    if path.iter().any(String::is_empty) {
        return Err(BicDbError::Index(format!(
            "spatial field `{field}` contains an empty metadata path segment"
        )));
    }
    Ok(IndexField::MetadataPath(path))
}

fn spatial_index_name(collection: &str, field: &str) -> String {
    let sanitized_field = field
        .trim()
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect::<String>();
    let sanitized_field = sanitized_field.trim_matches('_');
    let field = if sanitized_field.is_empty() {
        "geometry"
    } else {
        sanitized_field
    };
    format!("idx_{collection}_{field}_spatial")
}

#[derive(Clone, Copy, Debug)]
enum RouteAlgorithm {
    Dijkstra,
    AStar,
}

#[derive(Debug)]
struct RouteDistanceMatrix {
    distance_mode: String,
    distances: Vec<Vec<f64>>,
}

#[derive(Debug)]
struct RoadGraph {
    name: String,
    graph: DiGraph<RoadNode, RoadEdge>,
}

#[cfg(feature = "osm-import")]
#[derive(Clone, Debug)]
struct OsmNode {
    id: String,
    osm_id: i64,
    lon: f64,
    lat: f64,
}

#[cfg(feature = "osm-import")]
#[derive(Clone, Debug)]
struct OsmWay {
    id: i64,
    highway: String,
    name: Option<String>,
    oneway: OsmOneway,
    nodes: Vec<String>,
}

#[cfg(feature = "osm-import")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OsmOneway {
    Forward,
    Reverse,
    Both,
}

#[cfg(feature = "osm-import")]
#[derive(Clone, Debug)]
struct OsmEdge {
    id: String,
    from: String,
    to: String,
    distance_m: f64,
    duration_s: f64,
    road_class: String,
    osm_way_id: i64,
    name: Option<String>,
}

#[derive(Clone, Copy, Debug)]
struct RoadSnap {
    index: NodeIndex,
    snap_distance_m: f64,
}

impl RoadSnap {
    fn into_public(self, graph: &RoadGraph) -> SnappedRoadNode {
        let node = &graph.graph[self.index];
        SnappedRoadNode {
            id: node.id.clone(),
            lon: node.lon,
            lat: node.lat,
            snap_distance_m: self.snap_distance_m,
        }
    }
}

impl RoadGraph {
    fn build(name: &str, node_records: Vec<Record>, edge_records: Vec<Record>) -> Result<Self> {
        let mut graph = DiGraph::new();
        let mut nodes_by_id = HashMap::new();

        for record in node_records {
            let node = road_node_from_record(record)?;
            if nodes_by_id.contains_key(&node.id) {
                return Err(BicDbError::Routing(format!(
                    "road graph `{name}` contains duplicate node `{}`",
                    node.id
                )));
            }
            let id = node.id.clone();
            let index = graph.add_node(node);
            nodes_by_id.insert(id, index);
        }

        if nodes_by_id.is_empty() {
            return Err(BicDbError::Routing(format!(
                "road graph `{name}` has no nodes in `{name}_nodes`"
            )));
        }

        for record in edge_records {
            let edge = road_edge_from_record(record)?;
            let from = *nodes_by_id.get(&edge.from).ok_or_else(|| {
                BicDbError::Routing(format!(
                    "road graph `{name}` edge references missing from node `{}`",
                    edge.from
                ))
            })?;
            let to = *nodes_by_id.get(&edge.to).ok_or_else(|| {
                BicDbError::Routing(format!(
                    "road graph `{name}` edge references missing to node `{}`",
                    edge.to
                ))
            })?;
            graph.add_edge(from, to, edge);
        }

        Ok(Self {
            name: name.to_string(),
            graph,
        })
    }

    fn nearest_node(&self, lon: f64, lat: f64, label: &str) -> Result<RoadSnap> {
        self.graph
            .node_indices()
            .map(|index| {
                let node = &self.graph[index];
                (
                    haversine_meters(lon, lat, node.lon, node.lat),
                    node.id.as_str(),
                    index,
                )
            })
            .min_by(|left, right| left.0.total_cmp(&right.0).then_with(|| left.1.cmp(right.1)))
            .map(|(snap_distance_m, _, index)| RoadSnap {
                index,
                snap_distance_m,
            })
            .ok_or_else(|| {
                BicDbError::Routing(format!(
                    "road graph `{}` cannot snap {label}: no nodes available",
                    self.name
                ))
            })
    }

    fn dijkstra_path(&self, start: NodeIndex, end: NodeIndex) -> Result<(f64, Vec<NodeIndex>)> {
        let distances = dijkstra(&self.graph, start, Some(end), |edge| {
            edge.weight().distance_m
        });
        let distance = distances.get(&end).copied().ok_or_else(|| {
            BicDbError::Routing(format!(
                "no route in road graph `{}` between snapped nodes `{}` and `{}`",
                self.name, self.graph[start].id, self.graph[end].id
            ))
        })?;

        let mut path = vec![end];
        let mut current = end;
        while current != start {
            let current_distance = distances[&current];
            let mut predecessors = self
                .graph
                .edges_directed(current, petgraph::Direction::Incoming)
                .filter_map(|edge| {
                    let previous = edge.source();
                    let previous_distance = *distances.get(&previous)?;
                    let expected = previous_distance + edge.weight().distance_m;
                    if (expected - current_distance).abs() <= 1e-9 {
                        Some((self.graph[previous].id.as_str(), previous))
                    } else {
                        None
                    }
                })
                .collect::<Vec<_>>();
            predecessors.sort_by(|left, right| left.0.cmp(right.0));
            let Some((_, previous)) = predecessors.into_iter().next() else {
                return Err(BicDbError::Routing(format!(
                    "could not reconstruct route in road graph `{}`",
                    self.name
                )));
            };
            current = previous;
            path.push(current);
        }
        path.reverse();
        Ok((distance, path))
    }

    fn astar_path(&self, start: NodeIndex, end: NodeIndex) -> Result<(f64, Vec<NodeIndex>)> {
        astar(
            &self.graph,
            start,
            |node| node == end,
            |edge| edge.weight().distance_m,
            |node| {
                let left = &self.graph[node];
                let right = &self.graph[end];
                haversine_meters(left.lon, left.lat, right.lon, right.lat)
            },
        )
        .ok_or_else(|| {
            BicDbError::Routing(format!(
                "no route in road graph `{}` between snapped nodes `{}` and `{}`",
                self.name, self.graph[start].id, self.graph[end].id
            ))
        })
    }
}

// Only the gated import path reads these; the types stay public API.
#[cfg_attr(not(feature = "osm-import"), allow(dead_code))]
impl OsmImportBbox {
    fn validate(self) -> Result<()> {
        if [self.min_lon, self.min_lat, self.max_lon, self.max_lat]
            .iter()
            .any(|value| !value.is_finite())
        {
            return Err(BicDbError::Routing(
                "OSM import bbox values must be finite".to_string(),
            ));
        }
        if self.min_lon > self.max_lon || self.min_lat > self.max_lat {
            return Err(BicDbError::Routing(
                "OSM import bbox min values must not exceed max values".to_string(),
            ));
        }
        if self.min_lon < -180.0
            || self.max_lon > 180.0
            || self.min_lat < -90.0
            || self.max_lat > 90.0
        {
            return Err(BicDbError::Routing(
                "OSM import bbox must be within lon [-180,180] and lat [-90,90]".to_string(),
            ));
        }
        Ok(())
    }

    fn contains(self, lon: f64, lat: f64) -> bool {
        lon >= self.min_lon && lon <= self.max_lon && lat >= self.min_lat && lat <= self.max_lat
    }
}

#[cfg(feature = "osm-import")]
impl OsmNode {
    fn to_record(&self) -> Record {
        Record::new(self.id.clone())
            .with_geometry(Geometry::point(self.lon, self.lat).expect("validated OSM coordinate"))
            .with_metadata(json!({
                "osm_id": self.osm_id,
                "lon": self.lon,
                "lat": self.lat,
            }))
    }
}

#[cfg(feature = "osm-import")]
impl OsmEdge {
    fn into_record(self) -> Record {
        let mut metadata = json!({
            "from": self.from,
            "to": self.to,
            "distance_m": self.distance_m,
            "duration_s": self.duration_s,
            "road_class": self.road_class,
            "metadata": {
                "source": "osm",
                "osm_way_id": self.osm_way_id,
            }
        });
        if let Some(name) = self.name {
            metadata["metadata"]["name"] = json!(name);
        }
        Record::new(self.id).with_metadata(metadata)
    }
}

#[cfg(feature = "osm-import")]
fn osm_nodes_in_bbox(path: &Path, bbox: OsmImportBbox) -> Result<HashMap<String, OsmNode>> {
    let file = File::open(path)?;
    let mut pbf = osmpbfreader::OsmPbfReader::new(BufReader::new(file));
    let mut nodes = HashMap::new();
    for obj in pbf.iter() {
        let obj = obj.map_err(osm_import_error)?;
        let osmpbfreader::OsmObj::Node(node) = obj else {
            continue;
        };
        let lon = node.lon();
        let lat = node.lat();
        if bbox.contains(lon, lat) {
            let id = osm_node_record_id(node.id.0);
            nodes.insert(
                id.clone(),
                OsmNode {
                    id,
                    osm_id: node.id.0,
                    lon,
                    lat,
                },
            );
        }
    }
    Ok(nodes)
}

#[cfg(feature = "osm-import")]
fn osm_road_ways_in_bbox(path: &Path, nodes: &HashMap<String, OsmNode>) -> Result<Vec<OsmWay>> {
    let file = File::open(path)?;
    let mut pbf = osmpbfreader::OsmPbfReader::new(BufReader::new(file));
    let mut ways = Vec::new();
    for obj in pbf.iter() {
        let obj = obj.map_err(osm_import_error)?;
        let osmpbfreader::OsmObj::Way(way) = obj else {
            continue;
        };
        let Some(highway) = way.tags.get("highway").map(|value| value.to_string()) else {
            continue;
        };
        if !osm_highway_is_routable(&highway) {
            continue;
        }
        let node_ids = way
            .nodes
            .iter()
            .map(|node_id| osm_node_record_id(node_id.0))
            .collect::<Vec<_>>();
        if !node_ids.iter().any(|node_id| nodes.contains_key(node_id)) {
            continue;
        }
        ways.push(OsmWay {
            id: way.id.0,
            highway,
            name: way.tags.get("name").map(|value| value.to_string()),
            oneway: osm_oneway(&way.tags),
            nodes: node_ids,
        });
    }
    ways.sort_by_key(|way| way.id);
    Ok(ways)
}

#[cfg(feature = "osm-import")]
fn osm_way_edges(way: &OsmWay, nodes: &HashMap<String, OsmNode>) -> Vec<OsmEdge> {
    let mut edges = Vec::new();
    for (index, pair) in way.nodes.windows(2).enumerate() {
        let Some(from) = nodes.get(&pair[0]) else {
            continue;
        };
        let Some(to) = nodes.get(&pair[1]) else {
            continue;
        };
        if from.id == to.id {
            continue;
        }
        let distance_m = haversine_meters(from.lon, from.lat, to.lon, to.lat);
        if !distance_m.is_finite() || distance_m <= 0.0 {
            continue;
        }
        let duration_s = distance_m / osm_speed_mps(&way.highway);
        match way.oneway {
            OsmOneway::Forward => {
                edges.push(osm_edge(way, index, from, to, distance_m, duration_s))
            }
            OsmOneway::Reverse => {
                edges.push(osm_edge(way, index, to, from, distance_m, duration_s))
            }
            OsmOneway::Both => {
                edges.push(osm_edge(way, index, from, to, distance_m, duration_s));
                edges.push(osm_edge(way, index, to, from, distance_m, duration_s));
            }
        }
    }
    edges
}

#[cfg(feature = "osm-import")]
fn osm_edge(
    way: &OsmWay,
    index: usize,
    from: &OsmNode,
    to: &OsmNode,
    distance_m: f64,
    duration_s: f64,
) -> OsmEdge {
    OsmEdge {
        id: format!("osm-way-{}-{index}-{}-{}", way.id, from.osm_id, to.osm_id),
        from: from.id.clone(),
        to: to.id.clone(),
        distance_m,
        duration_s,
        road_class: way.highway.clone(),
        osm_way_id: way.id,
        name: way.name.clone(),
    }
}

#[cfg(feature = "osm-import")]
fn osm_node_record_id(osm_id: i64) -> String {
    format!("osm-node-{osm_id}")
}

#[cfg(feature = "osm-import")]
fn osm_highway_is_routable(highway: &str) -> bool {
    matches!(
        highway,
        "motorway"
            | "trunk"
            | "primary"
            | "secondary"
            | "tertiary"
            | "unclassified"
            | "residential"
            | "living_street"
            | "service"
            | "track"
            | "road"
            | "motorway_link"
            | "trunk_link"
            | "primary_link"
            | "secondary_link"
            | "tertiary_link"
    )
}

#[cfg(feature = "osm-import")]
fn osm_oneway(tags: &osmpbfreader::Tags) -> OsmOneway {
    match tags.get("oneway").map(|value| value.as_str()) {
        Some("-1") => OsmOneway::Reverse,
        Some("yes" | "true" | "1") => OsmOneway::Forward,
        _ => OsmOneway::Both,
    }
}

#[cfg(feature = "osm-import")]
fn osm_speed_mps(highway: &str) -> f64 {
    let kmh = match highway {
        "motorway" | "motorway_link" => 100.0,
        "trunk" | "trunk_link" => 80.0,
        "primary" | "primary_link" => 65.0,
        "secondary" | "secondary_link" => 55.0,
        "tertiary" | "tertiary_link" => 45.0,
        "residential" | "living_street" | "service" => 30.0,
        "track" => 20.0,
        _ => 40.0,
    };
    kmh * 1000.0 / 3600.0
}

#[cfg(feature = "osm-import")]
fn osm_import_error(error: osmpbfreader::Error) -> BicDbError {
    BicDbError::Routing(format!("OSM PBF import failed: {error}"))
}

/// Ray-cast point-in-polygon honoring interior rings (holes).
fn polygon_contains_point(
    polygon: &geo_types::Polygon<f64>,
    point: &geo_types::Point<f64>,
) -> bool {
    fn ring_contains(ring: &geo_types::LineString<f64>, point: &geo_types::Point<f64>) -> bool {
        let mut inside = false;
        let coords = &ring.0;
        let mut previous = match coords.last() {
            Some(last) => *last,
            None => return false,
        };
        for coord in coords {
            if (coord.y > point.y()) != (previous.y > point.y()) {
                let intersect_x = (previous.x - coord.x) * (point.y() - coord.y)
                    / (previous.y - coord.y)
                    + coord.x;
                if point.x() < intersect_x {
                    inside = !inside;
                }
            }
            previous = *coord;
        }
        inside
    }
    ring_contains(polygon.exterior(), point)
        && !polygon
            .interiors()
            .iter()
            .any(|hole| ring_contains(hole, point))
}

/// Andrew's monotone chain: deterministic convex hull, closed CCW ring.
fn convex_hull_ring(mut points: Vec<geo_types::Coord<f64>>) -> Vec<geo_types::Coord<f64>> {
    points.sort_by(|a, b| a.x.total_cmp(&b.x).then(a.y.total_cmp(&b.y)));
    points.dedup_by(|a, b| a.x == b.x && a.y == b.y);
    if points.len() < 3 {
        return points;
    }
    let cross = |o: geo_types::Coord<f64>, a: geo_types::Coord<f64>, b: geo_types::Coord<f64>| {
        (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x)
    };
    let mut lower: Vec<geo_types::Coord<f64>> = Vec::new();
    for point in &points {
        while lower.len() >= 2
            && cross(lower[lower.len() - 2], lower[lower.len() - 1], *point) <= 0.0
        {
            lower.pop();
        }
        lower.push(*point);
    }
    let mut upper: Vec<geo_types::Coord<f64>> = Vec::new();
    for point in points.iter().rev() {
        while upper.len() >= 2
            && cross(upper[upper.len() - 2], upper[upper.len() - 1], *point) <= 0.0
        {
            upper.pop();
        }
        upper.push(*point);
    }
    lower.pop();
    upper.pop();
    lower.extend(upper);
    if let Some(first) = lower.first().copied() {
        lower.push(first);
    }
    lower
}

fn road_node_from_record(record: Record) -> Result<RoadNode> {
    let (lon, lat) = match record.geometry {
        Some(Geometry::Point(point)) => (point.x(), point.y()),
        Some(other) => {
            return Err(BicDbError::Routing(format!(
                "road node `{}` must use POINT geometry, got {}",
                record.id,
                spatial_geometry_name(&other)
            )));
        }
        None => (
            route_metadata_number(&record.metadata, "lon", &record.id)?,
            route_metadata_number(&record.metadata, "lat", &record.id)?,
        ),
    };
    if !lon.is_finite() || !lat.is_finite() {
        return Err(BicDbError::Routing(format!(
            "road node `{}` requires finite lon/lat",
            record.id
        )));
    }
    Ok(RoadNode {
        id: record.id,
        lon,
        lat,
    })
}

fn road_edge_from_record(record: Record) -> Result<RoadEdge> {
    let from = route_metadata_string(&record.metadata, "from", &record.id)?;
    let to = route_metadata_string(&record.metadata, "to", &record.id)?;
    let distance_m = route_metadata_number(&record.metadata, "distance_m", &record.id)?;
    let duration_s = route_metadata_number(&record.metadata, "duration_s", &record.id)?;
    if distance_m < 0.0 || !distance_m.is_finite() {
        return Err(BicDbError::Routing(format!(
            "road edge `{}` requires non-negative finite distance_m",
            record.id
        )));
    }
    if duration_s < 0.0 || !duration_s.is_finite() {
        return Err(BicDbError::Routing(format!(
            "road edge `{}` requires non-negative finite duration_s",
            record.id
        )));
    }
    Ok(RoadEdge {
        from,
        to,
        distance_m,
        duration_s,
        road_class: route_metadata_string(&record.metadata, "road_class", &record.id)?,
        metadata: record
            .metadata
            .get("metadata")
            .cloned()
            .unwrap_or(serde_json::Value::Null),
    })
}

fn routing_point(label: &str, geometry: &Geometry) -> Result<(f64, f64)> {
    match geometry {
        Geometry::Point(point) => Ok((point.x(), point.y())),
        other => Err(BicDbError::Routing(format!(
            "route {label} must be a POINT, got {}",
            spatial_geometry_name(other)
        ))),
    }
}

fn nearest_neighbor_order(distances: &[Vec<f64>]) -> Vec<usize> {
    let mut order = vec![0];
    let mut remaining = (1..distances.len()).collect::<BTreeSet<_>>();
    while let Some(&current) = order.last() {
        let Some(next) = remaining.iter().copied().min_by(|left, right| {
            distances[current][*left]
                .total_cmp(&distances[current][*right])
                .then_with(|| left.cmp(right))
        }) else {
            break;
        };
        remaining.remove(&next);
        order.push(next);
    }
    order
}

fn two_opt_order(mut order: Vec<usize>, distances: &[Vec<f64>]) -> Vec<usize> {
    if order.len() < 4 {
        return order;
    }

    let mut improved = true;
    while improved {
        improved = false;
        let current_distance = route_order_distance(&order, distances);
        for left in 1..(order.len() - 2) {
            for right in (left + 1)..(order.len() - 1) {
                let mut candidate = order.clone();
                candidate[left..=right].reverse();
                if route_order_distance(&candidate, distances) + 1e-9 < current_distance {
                    order = candidate;
                    improved = true;
                    break;
                }
            }
            if improved {
                break;
            }
        }
    }
    order
}

fn route_order_distance(order: &[usize], distances: &[Vec<f64>]) -> f64 {
    order
        .windows(2)
        .map(|pair| distances[pair[0]][pair[1]])
        .sum()
}

fn route_optimization_result(
    graph: &str,
    distance_mode: &str,
    heuristic: &str,
    stops: &[Geometry],
    order: Vec<usize>,
    distances: &[Vec<f64>],
) -> OptimizedRoute {
    let estimated_distance_m = route_order_distance(&order, distances);
    let ordered_stops = order
        .into_iter()
        .map(|input_index| OptimizedRouteStop {
            input_index,
            geometry: stops[input_index].clone(),
        })
        .collect();
    OptimizedRoute {
        graph: graph.to_string(),
        distance_mode: distance_mode.to_string(),
        heuristic: heuristic.to_string(),
        ordered_stops,
        estimated_distance_m,
    }
}

fn route_metadata_number(metadata: &serde_json::Value, key: &str, record_id: &str) -> Result<f64> {
    metadata
        .get(key)
        .and_then(serde_json::Value::as_f64)
        .ok_or_else(|| {
            BicDbError::Routing(format!(
                "road record `{record_id}` requires numeric metadata field `{key}`"
            ))
        })
}

fn route_metadata_string(
    metadata: &serde_json::Value,
    key: &str,
    record_id: &str,
) -> Result<String> {
    metadata
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .ok_or_else(|| {
            BicDbError::Routing(format!(
                "road record `{record_id}` requires string metadata field `{key}`"
            ))
        })
}

fn spatial_field_name(field: &IndexField) -> String {
    match field {
        IndexField::Geometry => "geometry".to_string(),
        IndexField::MetadataPath(path) => path.join("."),
        IndexField::Id => "id".to_string(),
        IndexField::Timestamp => "timestamp".to_string(),
        IndexField::Lower(inner) => format!("lower({})", spatial_field_name(inner)),
        IndexField::Trim(inner) => format!("trim({})", spatial_field_name(inner)),
    }
}

fn spatial_geometry_name(geometry: &Geometry) -> &'static str {
    match geometry {
        Geometry::Point(_) => "POINT",
        Geometry::LineString(_) => "LINESTRING",
        Geometry::Polygon(_) => "POLYGON",
        Geometry::Envelope(_) => "ENVELOPE",
        Geometry::MultiPoint(_) => "MULTIPOINT",
        Geometry::MultiLineString(_) => "MULTILINESTRING",
        Geometry::MultiPolygon(_) => "MULTIPOLYGON",
        Geometry::GeometryCollection(_) => "GEOMETRYCOLLECTION",
    }
}

fn geometry_from_json_value(value: &serde_json::Value) -> Result<Geometry> {
    match value {
        serde_json::Value::String(value) => {
            let trimmed = value.trim_start();
            if trimmed.starts_with('{') {
                Geometry::from_geojson_str(value)
            } else {
                Geometry::from_wkt(value)
            }
        }
        serde_json::Value::Object(_) => Geometry::from_geojson_value(value.clone()),
        other => Err(BicDbError::Index(format!(
            "spatial index value must be WKT text or GeoJSON object, got {other}"
        ))),
    }
}

fn spatial_index_entry(record_id: String, geometry: &Geometry) -> Result<SpatialIndexEntry> {
    let (min, max, point) = match geometry {
        Geometry::Point(point) => {
            let xy = [point.x(), point.y()];
            (xy, xy, Some(xy))
        }
        Geometry::Envelope(rect) => (
            [rect.min().x, rect.min().y],
            [rect.max().x, rect.max().y],
            None,
        ),
        Geometry::LineString(line) => {
            let mut points = line.points();
            let Some(first) = points.next() else {
                return Err(BicDbError::Index(
                    "spatial index cannot index empty linestring".to_string(),
                ));
            };
            let mut min = [first.x(), first.y()];
            let mut max = min;
            for point in points {
                min[0] = min[0].min(point.x());
                min[1] = min[1].min(point.y());
                max[0] = max[0].max(point.x());
                max[1] = max[1].max(point.y());
            }
            (min, max, None)
        }
        Geometry::MultiPoint(_)
        | Geometry::MultiLineString(_)
        | Geometry::MultiPolygon(_)
        | Geometry::GeometryCollection(_) => {
            let Some((min, max)) = geometry.coordinate_bounds() else {
                return Err(BicDbError::Index(
                    "spatial index cannot index empty geometry".to_string(),
                ));
            };
            (min, max, None)
        }
        Geometry::Polygon(polygon) => {
            let mut points = polygon
                .exterior()
                .points()
                .chain(polygon.interiors().iter().flat_map(|ring| ring.points()));
            let Some(first) = points.next() else {
                return Err(BicDbError::Index(
                    "spatial index cannot index empty polygon".to_string(),
                ));
            };
            let mut min = [first.x(), first.y()];
            let mut max = min;
            for point in points {
                min[0] = min[0].min(point.x());
                min[1] = min[1].min(point.y());
                max[0] = max[0].max(point.x());
                max[1] = max[1].max(point.y());
            }
            (min, max, None)
        }
    };
    Ok(SpatialIndexEntry {
        record_id,
        envelope: AABB::from_corners(min, max),
        point,
    })
}

fn packed_entry_from_index_entry(entry: &SpatialIndexEntry) -> PackedSpatialEntry {
    PackedSpatialEntry {
        record_id: entry.record_id.clone(),
        min: entry.envelope.lower(),
        max: entry.envelope.upper(),
        point: entry.point,
    }
}

fn index_entry_from_packed(entry: PackedSpatialEntry) -> SpatialIndexEntry {
    SpatialIndexEntry {
        record_id: entry.record_id,
        envelope: AABB::from_corners(entry.min, entry.max),
        point: entry.point,
    }
}

const EARTH_RADIUS_METERS: f64 = 6_371_000.0;

/// A lon/lat AABB guaranteed to COVER the haversine ball of `meters` around
/// the query point. Latitude span is the exact meridian arc (a great circle
/// always covers at least its latitude difference); longitude span comes from
/// `hav σ >= cos φ1 · cos φ2 · hav Δλ` evaluated at the highest-|latitude|
/// the ball can reach, where parallels are shortest. Callers re-check exact
/// distances against candidates, so the envelope only ever rounds outward.
/// (The flat-earth constants this replaces clipped points near the boundary
/// — 111,320 m/deg overstates the meridian degree — and under-spanned
/// longitude whenever the ball reached latitudes above the query's.)
fn lon_lat_radius_envelope(lon: f64, lat: f64, meters: f64) -> AABB<[f64; 2]> {
    let half_angle = meters / (2.0 * EARTH_RADIUS_METERS);
    if half_angle >= std::f64::consts::FRAC_PI_2 {
        // The ball covers a hemisphere or more: no useful bound exists.
        return AABB::from_corners([lon - 360.0, -90.0], [lon + 360.0, 90.0]);
    }
    let lat_delta = (meters / EARTH_RADIUS_METERS).to_degrees();
    let reach = (lat.abs() + lat_delta).min(90.0);
    let cos_reach = reach.to_radians().cos();
    let sin_half = half_angle.sin();
    let lon_delta = if sin_half >= cos_reach {
        // The ball wraps a pole (or nearly): every longitude qualifies.
        360.0
    } else {
        2.0 * (sin_half / cos_reach).asin().to_degrees()
    };
    AABB::from_corners(
        [lon - lon_delta, lat - lat_delta],
        [lon + lon_delta, lat + lat_delta],
    )
}

/// Squared PLANAR distance from the query to the farthest corner of the
/// envelope covering the `meters` haversine ball. Sound stop radius for
/// consuming a planar-ordered nearest iterator while ranking by haversine:
/// any point closer than `meters` lies inside the envelope, hence planar-
/// nearer than its far corner. When the envelope crosses the ±180°
/// antimeridian that guarantee breaks — a wrapped neighbor is planar-FAR in
/// raw coordinates — so the stop disables itself (`INFINITY`, full
/// consumption) rather than risk dropping a true neighbor.
fn haversine_stop_planar_d2(lon: f64, lat: f64, meters: f64) -> f64 {
    let envelope = lon_lat_radius_envelope(lon, lat, meters);
    if envelope.lower()[0] < -180.0 || envelope.upper()[0] > 180.0 {
        return f64::INFINITY;
    }
    let dx = (lon - envelope.lower()[0]).max(envelope.upper()[0] - lon);
    let dy = (lat - envelope.lower()[1]).max(envelope.upper()[1] - lat);
    dx * dx + dy * dy
}

/// Exact minimum great-circle distance from a query point to any point of a
/// lon/lat rectangle — the admissible lower bound the geographic best-first
/// descent prunes with (for a degenerate point rect it IS the haversine
/// distance).
///
/// Great-circle distance grows with the wrapped longitude difference at any
/// fixed latitude pair (`cos φ1 · cos φ2 >= 0`), so the nearest rectangle
/// longitude minimizes `|Δλ|` independently of latitude: zero if some
/// longitude congruent to the query's lies in the span, else the nearer span
/// edge. Along that fixed `Δλ`, distance over the rectangle's latitude has a
/// single interior minimum at the cross-track foot `φ = atan2(sin φ1,
/// cos φ1 · cos Δλ)`, so the true minimum is at that foot clamped into the
/// span, or at a span edge.
fn haversine_rect_min_meters(lon: f64, lat: f64, min: [f64; 2], max: [f64; 2]) -> f64 {
    let wrapped = |delta: f64| {
        let delta = delta.abs() % 360.0;
        delta.min(360.0 - delta)
    };
    let congruent_steps = ((min[0] - lon) / 360.0).ceil();
    let delta_lon_deg = if lon + 360.0 * congruent_steps <= max[0] {
        0.0
    } else {
        wrapped(lon - min[0]).min(wrapped(lon - max[0]))
    };
    if delta_lon_deg == 0.0 && lat >= min[1] && lat <= max[1] {
        return 0.0;
    }
    let lat_rad = lat.to_radians();
    let foot = lat_rad
        .sin()
        .atan2(lat_rad.cos() * delta_lon_deg.to_radians().cos())
        .to_degrees();
    let mut best = f64::INFINITY;
    for rect_lat in [min[1], max[1], foot.clamp(min[1], max[1])] {
        best = best.min(haversine_meters(0.0, lat, delta_lon_deg, rect_lat));
    }
    best
}

/// Max-heap of the `limit` smallest distances seen so far — the pruning
/// threshold bounded nearest scans lower as they fill. `kth()` stays `None`
/// (no pruning) until `limit` distances have arrived.
struct NearestThreshold {
    limit: usize,
    heap: BinaryHeap<NearestThresholdDistance>,
}

struct NearestThresholdDistance(f64);

impl PartialEq for NearestThresholdDistance {
    fn eq(&self, other: &Self) -> bool {
        self.0.total_cmp(&other.0) == Ordering::Equal
    }
}

impl Eq for NearestThresholdDistance {}

impl PartialOrd for NearestThresholdDistance {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.0.total_cmp(&other.0))
    }
}

impl Ord for NearestThresholdDistance {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0.total_cmp(&other.0)
    }
}

impl NearestThreshold {
    fn new(limit: usize) -> Self {
        Self {
            limit,
            heap: BinaryHeap::with_capacity(limit.min(65_536).saturating_add(1)),
        }
    }

    fn offer(&mut self, distance: f64) {
        if self.heap.len() < self.limit {
            self.heap.push(NearestThresholdDistance(distance));
        } else if self.heap.peek().is_some_and(|worst| distance < worst.0) {
            self.heap.pop();
            self.heap.push(NearestThresholdDistance(distance));
        }
    }

    fn kth(&self) -> Option<f64> {
        (self.heap.len() >= self.limit)
            .then(|| self.heap.peek().map(|worst| worst.0))
            .flatten()
    }
}

fn haversine_meters(left_lon: f64, left_lat: f64, right_lon: f64, right_lat: f64) -> f64 {
    let radius_meters = 6_371_000.0_f64;
    let d_lat = (right_lat - left_lat).to_radians();
    let d_lon = (right_lon - left_lon).to_radians();
    let left_lat = left_lat.to_radians();
    let right_lat = right_lat.to_radians();
    let a = (d_lat / 2.0).sin().powi(2)
        + left_lat.cos() * right_lat.cos() * (d_lon / 2.0).sin().powi(2);
    2.0 * radius_meters * a.sqrt().asin()
}

fn json_path<'a>(value: &'a serde_json::Value, path: &[String]) -> Option<&'a serde_json::Value> {
    let mut current = value;
    for part in path {
        current = current.get(part)?;
    }
    Some(current)
}

fn json_to_index_value(value: &serde_json::Value) -> IndexValue {
    if let Some(index_key) = typed_storage_index_label(value) {
        return IndexValue::String(index_key);
    }
    match value {
        serde_json::Value::Null => IndexValue::Null,
        serde_json::Value::Bool(value) => IndexValue::Bool(*value),
        serde_json::Value::Number(value) => value
            .as_i64()
            .map(IndexValue::Int)
            .or_else(|| {
                value
                    .as_f64()
                    .map(|value| IndexValue::Float(ordered_f64(value)))
            })
            .unwrap_or(IndexValue::Null),
        serde_json::Value::String(value) => IndexValue::String(value.clone()),
        serde_json::Value::Array(_) | serde_json::Value::Object(_) => {
            IndexValue::String(value.to_string())
        }
    }
}

fn typed_storage_index_label(value: &serde_json::Value) -> Option<String> {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let key = value.get("$bicdb_typed")?.get("index_key")?;
    // Since 1.0.366 the key is persisted as lowercase hex; older records carry
    // an array of byte values. Both produce the same label.
    if let Some(hex) = key.as_str() {
        if hex.is_empty()
            || hex.len() % 2 != 0
            || !hex
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return None;
        }
        let mut label = String::with_capacity(13 + hex.len());
        label.push_str("\0bicdb:typed:");
        label.push_str(hex);
        return Some(label);
    }
    let bytes = key
        .as_array()?
        .iter()
        .map(|value| value.as_u64().and_then(|value| u8::try_from(value).ok()))
        .collect::<Option<Vec<_>>>()?;
    if bytes.is_empty() {
        return None;
    }
    let mut label = String::with_capacity(13 + bytes.len() * 2);
    label.push_str("\0bicdb:typed:");
    for byte in bytes {
        label.push(HEX[(byte >> 4) as usize] as char);
        label.push(HEX[(byte & 0x0f) as usize] as char);
    }
    Some(label)
}

fn ordered_f64(value: f64) -> u64 {
    let bits = value.to_bits();
    if bits & (1 << 63) == 0 {
        bits ^ (1 << 63)
    } else {
        !bits
    }
}

fn decode_record_frame(payload: &[u8]) -> Result<RecordFrame> {
    match serde_json::from_slice::<RecordFrame>(payload) {
        Ok(frame) => Ok(frame),
        Err(_) => {
            let record: Record = serde_json::from_slice(payload)?;
            Ok(RecordFrame::Upsert { record })
        }
    }
}

/// Like [`decode_record_frame`] but decodes straight into the compact
/// [`StoredRecord`] form (metadata kept as raw JSON), skipping the `Value`
/// materialize + re-serialize round trip. Used on the open/recovery hot path.
///
/// Two-step: capture the frame with the record sub-object as `RawValue` (native
/// deserializer), then deserialize that raw record into `StoredRecord` directly.
/// Neither step builds the metadata `Value`. The `record` raw bytes are the exact
/// on-disk JSON, which `StoredRecord` stores verbatim — byte-identical to the old
/// `Record` -> `to_raw_value` path (the on-disk metadata is already that canonical
/// serialization), so `content_hash`/equality are unchanged.
fn decode_stored_record_frame(payload: &[u8]) -> Result<StoredRecordFrame> {
    let missing = |what: &str| BicDbError::Corruption {
        path: PathBuf::new(),
        message: format!("record frame missing {what}"),
    };
    match serde_json::from_slice::<RecordFrameWire>(payload) {
        Ok(wire) => {
            let frame = match wire.op {
                RecordFrameOp::Upsert => {
                    let raw = wire.record.ok_or_else(|| missing("record"))?;
                    StoredRecordFrame::Upsert(serde_json::from_str(raw.get())?)
                }
                RecordFrameOp::Delete => {
                    StoredRecordFrame::Delete(wire.id.ok_or_else(|| missing("id"))?)
                }
                RecordFrameOp::TxUpsert => {
                    let raw = wire.record.ok_or_else(|| missing("record"))?;
                    let tx_id = wire.tx_id.ok_or_else(|| missing("tx_id"))?;
                    StoredRecordFrame::TxUpsert(tx_id, serde_json::from_str(raw.get())?)
                }
                RecordFrameOp::TxDelete => {
                    let tx_id = wire.tx_id.ok_or_else(|| missing("tx_id"))?;
                    StoredRecordFrame::TxDelete(tx_id, wire.id.ok_or_else(|| missing("id"))?)
                }
            };
            Ok(frame)
        }
        Err(_) => {
            // Legacy untagged bare-record frame.
            let record: StoredRecord = serde_json::from_slice(payload)?;
            Ok(StoredRecordFrame::Upsert(record))
        }
    }
}

fn record_upsert_audit_event(
    collection: &str,
    collection_mode: &CollectionMode,
    record: &Record,
    op_type: OpType,
    write_context: Option<&SyncVector>,
    write_clock: Option<&serde_json::Value>,
) -> Result<Event> {
    let event_type = match op_type {
        OpType::Insert => "RecordCreated",
        OpType::Update => "RecordUpdated",
        OpType::Delete => "RecordDeleted",
    };
    let mut payload = json!({
        "collection": collection,
        "collection_mode": collection_mode,
        "record_id": record.id,
        "record": record,
    });
    attach_write_context(&mut payload, write_context)?;
    attach_write_clock(&mut payload, write_clock);
    Ok(Event::new(RECORD_AUDIT_STREAM, event_type, payload))
}

fn record_deleted_event(
    collection: &str,
    collection_mode: &CollectionMode,
    record: &Record,
    write_context: Option<&SyncVector>,
    write_clock: Option<&serde_json::Value>,
) -> Result<Event> {
    let mut payload = json!({
        "collection": collection,
        "collection_mode": collection_mode,
        "record_id": record.id,
        "record": record,
    });
    attach_write_context(&mut payload, write_context)?;
    attach_write_clock(&mut payload, write_clock);
    Ok(Event::new(RECORD_AUDIT_STREAM, "RecordDeleted", payload))
}

fn mesh_coverage_signing_message(
    protocol: u32,
    signer: &NodeId,
    peer: &NodeId,
    initiator_nonce: &str,
    responder_nonce: &str,
    vector: &SyncVector,
) -> Result<Vec<u8>> {
    if uuid::Uuid::parse_str(initiator_nonce).is_err()
        || uuid::Uuid::parse_str(responder_nonce).is_err()
    {
        return Err(BicDbError::SyncBundle(
            "mesh hello nonce is invalid".to_string(),
        ));
    }
    serde_json::to_vec(&(
        "bicdb.mesh.coverage-proof.v1",
        protocol,
        signer,
        peer,
        initiator_nonce,
        responder_nonce,
        vector,
    ))
    .map_err(Into::into)
}

const MESH_SIGNING_KEY_FILE: &str = "mesh_signing_key.json";
const MESH_SIGNING_KEY_AAD: &[u8] = b"bicdb.mesh.signing-key.v2";
const MAX_MESH_SIGNING_KEY_FILE_BYTES: u64 = 16 * 1024;

/// Loads or generates this node's ed25519 mesh signing key. The secret is
/// wrapped by the database encryption runtime when at-rest encryption is on.
/// The key file is created as 0600 before any secret bytes are written.
fn load_or_create_mesh_signing_key(
    path: &Path,
    fsync: bool,
    encryption: &EncryptionRuntime,
) -> Result<ed25519_dalek::SigningKey> {
    let key_path = path.join(MESH_SIGNING_KEY_FILE);
    if key_path.exists() {
        let value: serde_json::Value =
            serde_json::from_slice(&read_mesh_signing_key_file(&key_path)?)?;
        let format = value
            .get("format")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(1);
        let secret = match format {
            1 => {
                let secret_hex = value
                    .get("secret_hex")
                    .and_then(serde_json::Value::as_str)
                    .ok_or_else(|| {
                        BicDbError::SyncBundle(
                            "mesh signing key file is missing secret_hex".to_string(),
                        )
                    })?;
                hex::decode(secret_hex)
                    .map_err(|error| BicDbError::SyncBundle(error.to_string()))?
            }
            2 => {
                let ciphertext = value
                    .get("ciphertext_hex")
                    .and_then(serde_json::Value::as_str)
                    .ok_or_else(|| {
                        BicDbError::SyncBundle(
                            "encrypted mesh signing key is missing ciphertext_hex".to_string(),
                        )
                    })?;
                let ciphertext = hex::decode(ciphertext)
                    .map_err(|error| BicDbError::SyncBundle(error.to_string()))?;
                encryption.decrypt_for(
                    crate::encryption::EncryptionObjectPurpose::IdentitySecret,
                    &key_path,
                    &ciphertext,
                    MESH_SIGNING_KEY_AAD,
                )?
            }
            other => {
                return Err(BicDbError::SyncBundle(format!(
                    "unsupported mesh signing key format {other}"
                )));
            }
        };
        let bytes: [u8; 32] = secret
            .try_into()
            .map_err(|_| BicDbError::SyncBundle("mesh signing key must be 32 bytes".to_string()))?;
        if format == 1 && encryption.is_enabled() {
            persist_mesh_signing_key(&key_path, &bytes, fsync, encryption)?;
        }
        return Ok(ed25519_dalek::SigningKey::from_bytes(&bytes));
    }
    let mut secret = [0_u8; 32];
    chacha20poly1305::aead::rand_core::RngCore::fill_bytes(
        &mut chacha20poly1305::aead::OsRng,
        &mut secret,
    );
    let key = ed25519_dalek::SigningKey::from_bytes(&secret);
    persist_mesh_signing_key(&key_path, &secret, fsync, encryption)?;
    Ok(key)
}

fn persist_mesh_signing_key(
    key_path: &Path,
    secret: &[u8; 32],
    fsync: bool,
    encryption: &EncryptionRuntime,
) -> Result<()> {
    let value = if encryption.is_enabled() {
        let ciphertext = encryption.encrypt_for(
            crate::encryption::EncryptionObjectPurpose::IdentitySecret,
            key_path,
            secret,
            MESH_SIGNING_KEY_AAD,
        )?;
        json!({
            "format": 2,
            "algorithm": "ed25519",
            "protection": "database_encryption",
            "ciphertext_hex": hex::encode(ciphertext),
        })
    } else {
        json!({
            "format": 1,
            "algorithm": "ed25519",
            "secret_hex": hex::encode(secret),
        })
    };
    secure_write_secret_atomic(key_path, &serde_json::to_vec_pretty(&value)?, fsync)
}

fn read_mesh_signing_key_file(key_path: &Path) -> Result<Vec<u8>> {
    let metadata = fs::symlink_metadata(key_path)?;
    if metadata.file_type().is_symlink()
        || !metadata.is_file()
        || metadata.len() > MAX_MESH_SIGNING_KEY_FILE_BYTES
    {
        return Err(BicDbError::SyncBundle(
            "mesh signing key path is unsafe or exceeds its size bound".to_string(),
        ));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
        let mut file = fs::OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(key_path)?;
        let opened_metadata = file.metadata()?;
        if !opened_metadata.is_file() || opened_metadata.len() > MAX_MESH_SIGNING_KEY_FILE_BYTES {
            return Err(BicDbError::SyncBundle(
                "mesh signing key path is unsafe or exceeds its size bound".to_string(),
            ));
        }
        file.set_permissions(fs::Permissions::from_mode(0o600))?;
        let mut bytes = Vec::with_capacity(opened_metadata.len() as usize);
        file.take(MAX_MESH_SIGNING_KEY_FILE_BYTES.saturating_add(1))
            .read_to_end(&mut bytes)?;
        if bytes.len() as u64 != opened_metadata.len() {
            return Err(BicDbError::SyncBundle(
                "mesh signing key changed while it was read".to_string(),
            ));
        }
        return Ok(bytes);
    }
    #[cfg(not(unix))]
    {
        let bytes = fs::read(key_path)?;
        if bytes.len() as u64 > MAX_MESH_SIGNING_KEY_FILE_BYTES {
            return Err(BicDbError::SyncBundle(
                "mesh signing key exceeds its size bound".to_string(),
            ));
        }
        Ok(bytes)
    }
}

fn secure_write_secret_atomic(path: &Path, bytes: &[u8], fsync: bool) -> Result<()> {
    let parent = path.parent().ok_or_else(|| {
        BicDbError::SyncBundle("mesh signing key has no parent directory".to_string())
    })?;
    let temporary = parent.join(format!(
        ".{}.{}.tmp",
        MESH_SIGNING_KEY_FILE,
        Uuid::new_v4().simple()
    ));
    let write_result = (|| -> Result<()> {
        let mut options = fs::OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600);
        }
        let mut file = options.open(&temporary)?;
        file.write_all(bytes)?;
        if fsync {
            file.sync_all()?;
        }
        drop(file);
        fs::rename(&temporary, path)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(path, fs::Permissions::from_mode(0o600))?;
            if fsync {
                File::open(parent)?.sync_all()?;
            }
        }
        Ok(())
    })();
    if write_result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    write_result
}

/// Monotonic timing evidence: within one runtime session, `monotonic_ms`
/// never jumps even when the wall clock does; a changed session id is the
/// signal that comparability was lost. Evidence for forensics and future
/// resolvers — never consulted by the current one.
fn attach_write_clock(payload: &mut serde_json::Value, write_clock: Option<&serde_json::Value>) {
    let (Some(clock), serde_json::Value::Object(fields)) = (write_clock, payload) else {
        return;
    };
    fields.insert("write_clock".to_string(), clock.clone());
}

/// Stamps the writer's per-origin coverage at write time into the audit
/// payload. This is what lets the conflict resolver prove causal dominance —
/// "this write had already seen that one" — instead of trusting device
/// clocks. Inside the payload it is covered by the envelope payload hash, so
/// relays cannot rewrite causality without detection.
fn attach_write_context(
    payload: &mut serde_json::Value,
    write_context: Option<&SyncVector>,
) -> Result<()> {
    let Some(context) = write_context else {
        return Ok(());
    };
    let serde_json::Value::Object(fields) = payload else {
        return Ok(());
    };
    fields.insert("write_context".to_string(), serde_json::to_value(context)?);
    Ok(())
}

fn spatial_record_inserted_event(
    collection: &str,
    collection_mode: &CollectionMode,
    mutation: &PreparedMutation,
    indexes: &FxHashMap<String, RwLock<IndexState>>,
) -> Result<Option<Event>> {
    let mut fields = BTreeSet::new();
    if mutation.record.geometry.is_some() {
        fields.insert("geometry".to_string());
    }
    for index in indexes.values() {
        let index = index.read();
        if !(index.definition.kind == IndexKind::Spatial
            && index.definition.collection == collection)
        {
            continue;
        }
        let field = index
            .definition
            .fields
            .first()
            .expect("validated spatial field");
        if record_spatial_geometry(&mutation.record, field)?.is_some() {
            fields.insert(spatial_field_name(field));
        }
    }
    if fields.is_empty() {
        return Ok(None);
    }
    Ok(Some(Event::new(
        SPATIAL_AUDIT_STREAM,
        "SpatialRecordInserted",
        json!({
            "collection": collection,
            "collection_mode": collection_mode,
            "record_id": mutation.record.id,
            "op": op_type_name(mutation.op_type),
            "spatial_fields": fields.into_iter().collect::<Vec<_>>(),
        }),
    )))
}

fn spatial_index_updated_event(
    definition: &IndexDefinition,
    operation: &str,
    indexed_records: usize,
) -> Result<Event> {
    Ok(Event::new(
        SPATIAL_AUDIT_STREAM,
        "SpatialIndexUpdated",
        json!({
            "index": definition.name,
            "collection": definition.collection,
            "fields": definition.fields.iter().map(spatial_field_name).collect::<Vec<_>>(),
            "operation": operation,
            "indexed_records": indexed_records,
        }),
    ))
}

