    #[test]
    fn paged_btree_publish_checkpoint_crash_reconciles_and_cannot_discard() {
        let temp = tempfile::tempdir().unwrap();
        let config = DbConfig::default()
            .with_fsync(false)
            .with_storage_mode(StorageMode::ServerPaged)
            .with_btree_build_batch_limits(1, 64 * 1024);
        let definition = IndexDefinition {
            name: "idx_items_id".to_string(),
            collection: "items".to_string(),
            fields: vec![IndexField::Id],
            unique: true,
            kind: IndexKind::BTree,
            predicate: None,
            exclusion: None,
        };
        let limits = PagedBTreeBuildLimits {
            max_batch_rows: 1,
            max_batch_bytes: 64 * 1024,
            max_state_bytes: 1024 * 1024,
        };
        let demand = ResourceDemand {
            memory_bytes: limits.max_batch_bytes as u64,
            io_bytes: limits.max_batch_bytes as u64,
            cpu_slots: 1,
            io_charge_bytes: 1,
        };
        {
            let mut db = BicDb::open_with_config(temp.path(), config.clone()).unwrap();
            db.create_collection("items").unwrap();
            db.insert("items", Record::new("one")).unwrap();
            db.begin_paged_btree_build(definition.clone(), limits, 100)
                .unwrap();
            let governor =
                ResourceGovernor::new(crate::ResourceGovernorConfig::default(), 100).unwrap();
            let mut now = 101;
            loop {
                let advance = db
                    .advance_paged_btree_build_governed(
                        &definition.name,
                        limits,
                        &governor,
                        demand,
                        now,
                    )
                    .unwrap();
                let state = match advance {
                    PagedBTreeBuildAdvance::Progress(state) => state,
                    PagedBTreeBuildAdvance::Complete(_) => panic!("published unexpectedly"),
                };
                if state.phase == PagedBTreeBuildPhase::Publishing {
                    db.publish_full_text_generation(&definition.name, &state.physical_name)
                        .unwrap();
                    db.indexes.insert(
                        definition.name.clone(),
                        RwLock::new(IndexState {
                            definition: definition.clone(),
                            store: new_index_store(),
                            spatial: None,
                            packed_spatial: None,
                            spatial_tombstones: FxHashSet::default(),
                            spatial_delta_durable: false,
                            paged_read_through: true,
                            full_text_build_incomplete: false,
                        }),
                    );
                    db.persist_index_catalog().unwrap();
                    break;
                }
                now += 1;
            }
        }

        let mut reopened = BicDb::open_with_config(temp.path(), config).unwrap();
        assert!(reopened
            .discard_paged_btree_build(&definition.name, limits)
            .unwrap_err()
            .to_string()
            .contains("published catalog"));
        let report = reopened.create_index_online(definition.clone()).unwrap();
        assert!(report.interrupted_previous);
        assert_eq!(
            reopened
                .load_paged_btree_build(&definition.name, limits)
                .unwrap()
                .phase,
            PagedBTreeBuildPhase::Complete
        );
        assert_eq!(
            reopened
                .lookup_index(&definition.name, &[IndexValue::from("one")])
                .unwrap(),
            vec!["one".to_string()]
        );
    }

    #[test]
    fn partial_btree_indexes_track_membership_and_survive_restart() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("partial-index");
        let mut db = persistent_test_db(&path);
        db.create_collection("reservations").unwrap();
        db.insert(
            "reservations",
            Record::new("active").with_metadata(json!({
                "tenant": "tenant-a",
                "starts_on": "2026-08-01",
                "cancelled_at": null
            })),
        )
        .unwrap();
        db.insert(
            "reservations",
            Record::new("cancelled").with_metadata(json!({
                "tenant": "tenant-a",
                "starts_on": "2026-08-02",
                "cancelled_at": "2026-07-01T00:00:00Z"
            })),
        )
        .unwrap();
        db.create_index(IndexDefinition {
            name: "active_reservations".into(),
            collection: "reservations".into(),
            fields: vec![
                IndexField::MetadataPath(vec!["tenant".into()]),
                IndexField::MetadataPath(vec!["starts_on".into()]),
            ],
            unique: false,
            kind: IndexKind::BTree,
            predicate: Some(IndexPredicate::Binary {
                operator: IndexPredicateBinaryOperator::Equal,
                left: Box::new(IndexPredicate::Field {
                    field: IndexField::MetadataPath(vec!["cancelled_at".into()]),
                }),
                right: Box::new(IndexPredicate::Literal { value: Value::Null }),
                value_type: IndexPredicateValueType::Timestamp,
            }),
            exclusion: None,
        })
        .unwrap();

        assert_eq!(
            db.lookup_index("active_reservations", &[IndexValue::from("tenant-a")])
                .unwrap(),
            vec!["active"]
        );
        db.insert(
            "reservations",
            Record::new("active").with_metadata(json!({
                "tenant": "tenant-a",
                "starts_on": "2026-08-01",
                "cancelled_at": "2026-07-02T00:00:00Z"
            })),
        )
        .unwrap();
        assert!(db
            .lookup_index("active_reservations", &[IndexValue::from("tenant-a")])
            .unwrap()
            .is_empty());
        drop(db);

        let reopened = persistent_test_db(&path);
        assert!(reopened
            .lookup_index("active_reservations", &[IndexValue::from("tenant-a")])
            .unwrap()
            .is_empty());
        assert!(reopened.index_definitions()[0].predicate.is_some());
    }

    #[test]
    fn exclusion_indexes_reject_overlaps_and_survive_restart() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("exclusion-index");
        let mut db = persistent_test_db(&path);
        db.create_collection("reservations").unwrap();
        let tenant = IndexField::MetadataPath(vec!["tenant".into()]);
        let starts_on = IndexField::MetadataPath(vec!["starts_on".into()]);
        let ends_on = IndexField::MetadataPath(vec!["ends_on".into()]);
        db.create_index(IndexDefinition {
            name: "reservations_no_overlap".into(),
            collection: "reservations".into(),
            fields: vec![tenant.clone(), starts_on.clone(), ends_on.clone()],
            unique: false,
            kind: IndexKind::BTree,
            predicate: None,
            exclusion: Some(IndexExclusion {
                elements: vec![
                    IndexExclusionElement::Equal { field: tenant },
                    IndexExclusionElement::Overlaps {
                        start: starts_on,
                        end: ends_on,
                        value_type: IndexPredicateValueType::Date,
                    },
                ],
            }),
        })
        .unwrap();
        let reservation = |id: &str, tenant: &str, start: &str, end: &str| {
            Record::new(id).with_metadata(json!({
                "tenant": tenant,
                "starts_on": start,
                "ends_on": end
            }))
        };
        db.insert(
            "reservations",
            reservation("first", "tenant-a", "2026-08-01", "2026-08-10"),
        )
        .unwrap();
        let overlap = db
            .insert(
                "reservations",
                reservation("overlap", "tenant-a", "2026-08-09", "2026-08-12"),
            )
            .expect_err("overlap must fail");
        assert!(overlap.to_string().contains("exclusion constraint"));
        db.insert(
            "reservations",
            reservation("adjacent", "tenant-a", "2026-08-10", "2026-08-12"),
        )
        .unwrap();
        db.insert(
            "reservations",
            reservation("other-tenant", "tenant-b", "2026-08-09", "2026-08-12"),
        )
        .unwrap();
        drop(db);

        let mut reopened = persistent_test_db(&path);
        let overlap = reopened
            .insert(
                "reservations",
                reservation("restart-overlap", "tenant-a", "2026-08-02", "2026-08-03"),
            )
            .expect_err("restart preserves exclusion");
        assert!(overlap.to_string().contains("exclusion constraint"));
    }

    #[test]
    fn record_frame_ref_serializes_byte_identical_to_record_frame() {
        // The checkpoint writes segment frames through the borrowed
        // `RecordFrameRef` (raw-metadata passthrough). Recovery decodes them as
        // `RecordFrame`/`RecordFrameWire`, so the bytes must match exactly what
        // the owned `RecordFrame` would have produced for the same record —
        // including a record exercising every optional field.
        let record = Record {
            id: "rec-1".into(),
            vector: Some(vec![1.5, -2.25]),
            metadata: serde_json::json!({
                "w_id": 3,
                "name": "widget \"quoted\" ✓",
                "nested": {"a": [1, 2, 3], "b": null},
                "amount": 12.34,
            }),
            geometry: None,
            timestamp: Some(1_700_000_000),
            payload: Some(vec![0, 1, 254, 255]),
        };
        let stored = StoredRecord::from_record(&record).expect("stored form");
        let owned = serde_json::to_vec(&RecordFrame::Upsert {
            record: stored.to_record().expect("round trip"),
        })
        .expect("owned frame");
        let borrowed = serde_json::to_vec(&RecordFrameRef::Upsert { record: &stored })
            .expect("borrowed frame");
        assert_eq!(
            String::from_utf8_lossy(&owned),
            String::from_utf8_lossy(&borrowed),
            "RecordFrameRef::Upsert must serialize byte-identically"
        );

        let owned_delete =
            serde_json::to_vec(&RecordFrame::Delete { id: "rec-1".into() }).expect("owned delete");
        let borrowed_delete =
            serde_json::to_vec(&RecordFrameRef::Delete { id: "rec-1" }).expect("borrowed delete");
        assert_eq!(owned_delete, borrowed_delete);

        // And the frame decodes back into the same record via the recovery path.
        let wire: RecordFrameWire = serde_json::from_slice(&borrowed).expect("wire decode");
        assert!(matches!(wire.op, RecordFrameOp::Upsert));
    }

    #[test]
    fn shadow_index_store_mirrors_writes_and_reads_agree() {
        // Drives the shadow wrapper through a write/read workload and asserts the
        // candidate and reference stay structurally identical -- the rollout
        // validation mechanism for a new index implementation. Here both sides
        // are BTreeIndexStore (so they trivially agree), which exercises the
        // wrapper's forwarding + verify(); a real candidate slots into `candidate`.
        let mut shadow = ShadowIndexStore::new(
            Box::new(BTreeIndexStore::default()),
            Box::new(BTreeIndexStore::default()),
        );
        // Insert a spread of keys, some sharing a key (multimap), some unique.
        for i in 0..200u32 {
            let key = encode_index_key(&[IndexValue::Int((i % 40) as i64)]);
            assert!(shadow.insert(&key, rid(i as u64)));
        }
        assert_eq!(shadow.verify(), 0, "candidate and reference must agree");
        // Remove a chunk and re-verify.
        for i in 0..50u32 {
            let key = encode_index_key(&[IndexValue::Int((i % 40) as i64)]);
            shadow.remove(&key, rid(i as u64));
        }
        assert_eq!(shadow.verify(), 0, "agreement holds after removals");
        // Reads come from the candidate and must be correct.
        // Key 5 was inserted by i in {5,45,85,125,165}; removals (i<50) dropped
        // rec-5 and rec-45, leaving rec-85/rec-125/rec-165.
        let key = encode_index_key(&[IndexValue::Int(5)]);
        let mut ids = Vec::new();
        shadow.collect_exact(&key, &mut ids);
        assert!(ids.contains(&rid(85)));
        assert!(!ids.contains(&rid(5)), "rec-5 was removed");
        assert!(!ids.contains(&rid(45)), "rec-45 was removed");
        // A clone preserves both sides.
        assert_eq!(shadow.clone_box().total_entries(), shadow.total_entries());
    }

    #[test]
    fn sharded_index_store_matches_reference_under_workload() {
        // Drive identical insert/remove workloads through the sharded store and
        // the reference BTreeMap store; their per-op results, content, point
        // reads, AND ordered-scan sequences (the cross-shard k-way merge -- the
        // novel, risky part) must match exactly.
        let mut sharded = ShardedBTreeIndexStore::with_shards(16);
        let mut reference = BTreeIndexStore::default();
        // Deterministic LCG so the test is reproducible without an RNG dependency.
        let mut rng: u64 = 0x9e3779b97f4a7c15;
        let mut next = || {
            rng = rng.wrapping_mul(6364136223846793005).wrapping_add(1);
            rng >> 33
        };
        for _ in 0..5000 {
            let key = encode_index_key(&[IndexValue::Int((next() % 200) as i64)]);
            let id = rid(next() % 50);
            if next() % 3 == 0 {
                assert_eq!(
                    sharded.remove(&key, id),
                    reference.remove(&key, id),
                    "remove result divergence"
                );
            } else {
                assert_eq!(
                    sharded.insert(&key, id),
                    reference.insert(&key, id),
                    "insert result divergence"
                );
            }
        }
        assert_eq!(sharded.total_entries(), reference.total_entries());
        assert_eq!(sharded.key_count(), reference.key_count());

        let collect = |s: &dyn OrderedIndexStore, rev: bool| {
            let mut out: Vec<(Vec<u8>, Vec<RowId>)> = Vec::new();
            let mut visit = |k: &[u8], ids: &mut dyn Iterator<Item = RowId>| {
                out.push((k.to_vec(), ids.collect()));
                true
            };
            if rev {
                s.scan_rev(&mut visit);
            } else {
                s.scan_from(&[], &mut visit);
            }
            out
        };
        let sharded_dyn: &dyn OrderedIndexStore = &sharded;
        let reference_dyn: &dyn OrderedIndexStore = &reference;
        assert_eq!(
            collect(sharded_dyn, false),
            collect(reference_dyn, false),
            "ascending scan order/content must match the reference"
        );
        let mut ascending_reversed = collect(sharded_dyn, false);
        ascending_reversed.reverse();
        assert_eq!(
            collect(sharded_dyn, true),
            ascending_reversed,
            "descending scan must be the reverse of ascending"
        );

        for k in 0..200i64 {
            let key = encode_index_key(&[IndexValue::Int(k)]);
            assert_eq!(
                sharded.ids_at(&key),
                reference.ids_at(&key),
                "ids_at divergence"
            );
            assert_eq!(
                sharded.has_other_id(&key, rid(0)),
                reference.has_other_id(&key, rid(0)),
                "has_other_id divergence"
            );
        }
    }

    fn tpcc_like_sharded_store(shards: usize) -> ShardedBTreeIndexStore {
        // Transactional composite key (w, d, o): w in 1..=16 partitions,
        // d in 1..=10 districts, o the growing order id.
        let mut s = ShardedBTreeIndexStore::with_shards(shards);
        for w in 1..=16i64 {
            for d in 1..=10i64 {
                for o in 1..=2000i64 {
                    let key = encode_index_key(&[
                        IndexValue::Int(w),
                        IndexValue::Int(d),
                        IndexValue::Int(o),
                    ]);
                    s.insert(&key, rid((w * 100_000 + d * 10_000 + o) as u64));
                }
            }
        }
        s
    }

    #[test]
    fn keystone_value_sharding_distributes_tpcc_int_keys() {
        // KEYSTONE claim 1: value-based (leading-field) sharding DISTRIBUTES
        // Clustered integer composite keys -- where order-preserving
        // byte-prefix sharding collapsed them into 1 shard (hollow). 16 warehouse
        // values hash across 64 shards: expect ~14 occupied (birthday), each shard
        // carrying 1-2 warehouses => disjoint warehouses commit to disjoint shards.
        let store = tpcc_like_sharded_store(64);
        let occupied = store.shards.iter().filter(|m| !m.read().is_empty()).count();
        let max_frac = store
            .shards
            .iter()
            .map(|m| m.read().len())
            .max()
            .unwrap_or(0) as f64
            / store.key_count().max(1) as f64;
        eprintln!(
            "KEYSTONE occupancy (value-sharded, 16 warehouses / 64 shards): {occupied}/64 shards \
             used, max shard = {:.1}% of keys (order-preserving gave 1 shard / 100%)",
            max_frac * 100.0
        );
        assert!(
            occupied >= 12 && max_frac <= 0.15,
            "value-based sharding under-distributed ({occupied}/64 shards, max {:.1}%) -- keystone weak",
            max_frac * 100.0
        );
    }

    #[test]
    fn keystone_prefix_scan_is_single_shard_and_correct() {
        // KEYSTONE claim 2: a prefix scan that fixes the leading field touches a
        // SINGLE shard (no k-way merge => no -30% regression) AND returns exactly
        // the reference result in order.
        let sharded = tpcc_like_sharded_store(16);
        let mut reference = BTreeIndexStore::default();
        for w in 1..=16i64 {
            for d in 1..=10i64 {
                for o in 1..=2000i64 {
                    let key = encode_index_key(&[
                        IndexValue::Int(w),
                        IndexValue::Int(d),
                        IndexValue::Int(o),
                    ]);
                    reference.insert(&key, rid((w * 100_000 + d * 10_000 + o) as u64));
                }
            }
        }

        let collect_prefix = |s: &dyn OrderedIndexStore, prefix: &[u8]| {
            let mut out: Vec<(Vec<u8>, Vec<RowId>)> = Vec::new();
            s.scan_prefix(prefix, &mut |k, ids| {
                out.push((k.to_vec(), ids.collect()));
                true
            });
            out
        };

        for w in 1..=16i64 {
            // A (w) prefix and a (w,d) prefix -- common transactional access shapes.
            for prefix in [
                encode_index_key(&[IndexValue::Int(w)]),
                encode_index_key(&[IndexValue::Int(w), IndexValue::Int(5)]),
            ] {
                // Locality: every matching key lives in exactly ONE shard.
                let shards_touched = sharded
                    .shards
                    .iter()
                    .filter(|m| {
                        m.read()
                            .range::<[u8], _>((
                                Bound::Included(prefix.as_slice()),
                                Bound::Unbounded,
                            ))
                            .next()
                            .is_some_and(|(k, _)| k.starts_with(&prefix))
                    })
                    .count();
                assert_eq!(
                    shards_touched, 1,
                    "prefix scan for w={w} spans {shards_touched} shards, not 1 -- no locality"
                );
                // Correctness: routed single-shard scan == reference prefix scan.
                assert_eq!(
                    collect_prefix(&sharded, &prefix),
                    collect_prefix(&reference, &prefix),
                    "prefix scan result diverges from reference for w={w}"
                );
            }
        }
        eprintln!("KEYSTONE prefix-scan: single-shard routing + correct for all 16 warehouses");
    }

    #[test]
    fn scan_prefix_rev_matches_reversed_forward_scan_and_stops_early() {
        // scan_prefix_rev must visit exactly the prefix matches in DESCENDING key
        // order, for the sharded store, the reference BTree store, AND the trait
        // default (exercised via ShadowIndexStore). It is the engine of the
        // greatest-extreme (MAX / ORDER BY DESC LIMIT 1) fast path.
        let sharded = tpcc_like_sharded_store(16);
        let mut reference = BTreeIndexStore::default();
        let mut shadow_inner_a = BTreeIndexStore::default();
        let mut shadow_inner_b = BTreeIndexStore::default();
        for w in 1..=16i64 {
            for d in 1..=10i64 {
                for o in 1..=2000i64 {
                    let key = encode_index_key(&[
                        IndexValue::Int(w),
                        IndexValue::Int(d),
                        IndexValue::Int(o),
                    ]);
                    let id = rid((w * 100_000 + d * 10_000 + o) as u64);
                    reference.insert(&key, id);
                    shadow_inner_a.insert(&key, id);
                    shadow_inner_b.insert(&key, id);
                }
            }
        }
        // ShadowIndexStore overrides scan_prefix; its scan_prefix_rev therefore
        // uses the trait DEFAULT (collect-forward-then-reverse) — covered here.
        let shadow = ShadowIndexStore::new(Box::new(shadow_inner_a), Box::new(shadow_inner_b));

        let forward = |s: &dyn OrderedIndexStore, prefix: &[u8]| {
            let mut out: Vec<(Vec<u8>, Vec<RowId>)> = Vec::new();
            s.scan_prefix(prefix, &mut |k, ids| {
                out.push((k.to_vec(), ids.collect()));
                true
            });
            out
        };
        let reverse = |s: &dyn OrderedIndexStore, prefix: &[u8]| {
            let mut out: Vec<(Vec<u8>, Vec<RowId>)> = Vec::new();
            s.scan_prefix_rev(prefix, &mut |k, ids| {
                out.push((k.to_vec(), ids.collect()));
                true
            });
            out
        };

        for w in 1..=16i64 {
            for prefix in [
                encode_index_key(&[IndexValue::Int(w)]),
                encode_index_key(&[IndexValue::Int(w), IndexValue::Int(5)]),
            ] {
                let mut expected = forward(&sharded, &prefix);
                expected.reverse();
                assert_eq!(reverse(&sharded, &prefix), expected, "sharded rev mismatch");
                assert_eq!(
                    reverse(&reference, &prefix),
                    expected,
                    "reference rev mismatch"
                );
                assert_eq!(
                    reverse(&shadow, &prefix),
                    expected,
                    "shadow(default) rev mismatch"
                );

                // Early stop: the FIRST visited key is the greatest in the prefix.
                let mut first = None;
                sharded.scan_prefix_rev(&prefix, &mut |k, _| {
                    first = Some(k.to_vec());
                    false
                });
                assert_eq!(first.as_ref(), expected.first().map(|(k, _)| k));
            }
        }
    }

    #[test]
    fn update_naming_its_changed_keys_skips_untouched_indexes_at_commit() {
        // A stored-form update that names the keys it changed lets commit skip
        // every index reading none of them: no key derivation, no cell scan
        // of the new row (the unique claim, validation and apply all consult
        // the hint first). Indexes reading a changed key still update.
        let dir = tempfile::tempdir().unwrap();
        let mut db =
            BicDb::open_with_config(dir.path(), DbConfig::default().with_fsync(false)).unwrap();
        db.create_collection("stock").unwrap();
        for (name, fields, unique) in [
            ("stock_pk", vec!["w", "i"], true),
            ("stock_data", vec!["d"], false),
        ] {
            db.create_index(IndexDefinition {
                name: name.to_string(),
                collection: "stock".to_string(),
                fields: fields
                    .into_iter()
                    .map(|f| IndexField::MetadataPath(vec![f.to_string()]))
                    .collect(),
                unique,
                kind: IndexKind::BTree,
                predicate: None,
                exclusion: None,
            })
            .unwrap();
        }
        let mut tx = db.begin_transaction().unwrap();
        tx.insert(
            "stock",
            // Splicing requires ascending keys under either serde map mode.
            Record::new("s1").with_metadata(json!({"d": "x", "i": 7, "q": 10, "w": 1})),
        )
        .unwrap();
        tx.commit().unwrap();
        let stored_row = |db: &BicDb| match db.get_stored("stock", "s1").unwrap() {
            Some(VisibleRow::Stored(stored)) => stored,
            other => panic!("resident stored row expected, got {other:?}"),
        };
        let spliced = |stored: &StoredRecord, key: &str, json: &str| {
            let text =
                crate::record::splice_json_object_text(stored.metadata.get(), &[(key, Some(json))])
                    .expect("compact row splices");
            Arc::new(stored.with_metadata_text_spliced(text).unwrap())
        };
        let scans = || IMAGE_CELL_SCANS.with(|scans| scans.get());

        // Only `q` changes, and no index reads `q`: zero cell scans at commit.
        let before = scans();
        let stored = stored_row(&db);
        let mut tx = db.begin_transaction().unwrap();
        tx.write_stored_upserts_with_changes(
            "stock",
            [(
                spliced(&stored, "q", "20"),
                0,
                None,
                Some(Arc::from([Box::<str>::from("q")])),
            )],
        )
        .unwrap();
        tx.commit().unwrap();
        assert_eq!(scans() - before, 0, "untouched indexes derive no keys");
        let row = stored_row(&db);
        assert!(
            row.metadata.get().contains("\"q\":20"),
            "{}",
            row.metadata.get()
        );
        assert_eq!(
            db.lookup_index("stock_pk", &[IndexValue::Int(1), IndexValue::Int(7)])
                .unwrap(),
            vec!["s1".to_string()]
        );
        assert_eq!(
            db.lookup_index("stock_data", &[IndexValue::String("x".into())])
                .unwrap(),
            vec!["s1".to_string()]
        );

        // `d` changes: the index on `d` moves the entry, the pk index stays.
        let stored = stored_row(&db);
        let mut tx = db.begin_transaction().unwrap();
        tx.write_stored_upserts_with_changes(
            "stock",
            [(
                spliced(&stored, "d", "\"y\""),
                0,
                None,
                Some(Arc::from([Box::<str>::from("d")])),
            )],
        )
        .unwrap();
        tx.commit().unwrap();
        assert!(db
            .lookup_index("stock_data", &[IndexValue::String("x".into())])
            .unwrap()
            .is_empty());
        assert_eq!(
            db.lookup_index("stock_data", &[IndexValue::String("y".into())])
                .unwrap(),
            vec!["s1".to_string()]
        );
        assert_eq!(
            db.lookup_index("stock_pk", &[IndexValue::Int(1), IndexValue::Int(7)])
                .unwrap(),
            vec!["s1".to_string()]
        );

        // A unique key move with the hint: the claim, validation and apply
        // all run for the pk index (it reads `i`), and the old key is gone.
        let stored = stored_row(&db);
        let mut tx = db.begin_transaction().unwrap();
        tx.write_stored_upserts_with_changes(
            "stock",
            [(
                spliced(&stored, "i", "8"),
                0,
                None,
                Some(Arc::from([Box::<str>::from("i")])),
            )],
        )
        .unwrap();
        tx.commit().unwrap();
        assert!(db
            .lookup_index("stock_pk", &[IndexValue::Int(1), IndexValue::Int(7)])
            .unwrap()
            .is_empty());
        assert_eq!(
            db.lookup_index("stock_pk", &[IndexValue::Int(1), IndexValue::Int(8)])
                .unwrap(),
            vec!["s1".to_string()]
        );
        // Without a hint every index is diffed as before (the new row scans).
        let before = scans();
        let stored = stored_row(&db);
        let mut tx = db.begin_transaction().unwrap();
        tx.write_stored_upserts_with_repairs("stock", [(spliced(&stored, "q", "30"), 0, None)])
            .unwrap();
        tx.commit().unwrap();
        assert!(scans() > before, "an unhinted update derives its keys");
    }

    #[test]
    fn dead_version_sweeper_reclaims_what_the_write_path_cannot() {
        // A write prunes only its own row's chain, and the version it
        // supersedes is always newer than that write's watermark, so rows
        // written once keep one dead version forever; the sweeper reclaims
        // them under the current watermark, respects an older open snapshot,
        // and empties fully deleted rows out of the registry.
        let dir = tempfile::tempdir().unwrap();
        let mut db =
            BicDb::open_with_config(dir.path(), DbConfig::default().with_fsync(false)).unwrap();
        db.create_collection("stock").unwrap();
        let rows = 200i64;
        for i in 0..rows {
            let mut tx = db.begin_transaction().unwrap();
            tx.insert(
                "stock",
                Record::new(format!("s-{i}")).with_metadata(json!({"i": i, "q": 10})),
            )
            .unwrap();
            tx.commit().unwrap();
        }
        for i in 0..rows {
            let mut tx = db.begin_transaction().unwrap();
            tx.update(
                "stock",
                Record::new(format!("s-{i}")).with_metadata(json!({"i": i, "q": 20})),
            )
            .unwrap();
            tx.commit().unwrap();
        }
        let stats = db.mvcc_debug_stats();
        assert_eq!(stats.total_records as i64, rows);
        assert_eq!(
            stats.total_versions as i64,
            rows * 2,
            "every write left its superseded version behind"
        );

        // A snapshot opened now pins nothing older than itself: the 200 dead
        // versions were deleted before it and are reclaimable, while a
        // version deleted after it (s-0's next update) must survive.
        let pinned = db.begin_transaction().unwrap();
        {
            let mut tx = db.begin_transaction().unwrap();
            tx.update(
                "stock",
                Record::new("s-0").with_metadata(json!({"i": 0, "q": 30})),
            )
            .unwrap();
            tx.commit().unwrap();
        }
        let freed_while_pinned = db.sweep_dead_versions(usize::MAX);
        // s-0 was rewritten above, and that write pruned its older dead
        // version itself, so the sweeper finds one fewer.
        assert_eq!(
            freed_while_pinned as i64,
            rows - 1,
            "dead before the snapshot: reclaimable"
        );
        assert_eq!(
            db.mvcc_debug_stats().total_versions as i64,
            rows + 1,
            "the version deleted after the open snapshot stays"
        );
        drop(pinned);

        let freed = db.sweep_dead_versions(usize::MAX);
        assert_eq!(
            freed, 1,
            "released snapshot: the re-queued row is reclaimed"
        );
        let stats = db.mvcc_debug_stats();
        assert_eq!(
            stats.total_versions as i64, rows,
            "one live version per row after the sweep"
        );
        assert_eq!(stats.max_chain, 1);
        // Every row still reads its latest value.
        let latest = db.get("stock", "s-0").unwrap().unwrap();
        assert_eq!(latest.metadata["q"], 30);
        let other = db.get("stock", "s-7").unwrap().unwrap();
        assert_eq!(other.metadata["q"], 20);

        // Deleted rows age out entirely and can be re-inserted afterwards.
        for i in 0..10 {
            let mut tx = db.begin_transaction().unwrap();
            tx.delete("stock", &format!("s-{i}")).unwrap();
            tx.commit().unwrap();
        }
        let _ = db.sweep_dead_versions(usize::MAX);
        assert!(db.get("stock", "s-3").unwrap().is_none());
        let stats = db.mvcc_debug_stats();
        assert_eq!(stats.total_versions as i64, rows - 10);
        let mut tx = db.begin_transaction().unwrap();
        tx.insert(
            "stock",
            Record::new("s-3").with_metadata(json!({"i": 3, "q": 99})),
        )
        .unwrap();
        tx.commit().unwrap();
        assert_eq!(db.get("stock", "s-3").unwrap().unwrap().metadata["q"], 99);
        // A budget bounds one sweep and the remainder stays queued.
        for i in 20..60 {
            let mut tx = db.begin_transaction().unwrap();
            tx.update(
                "stock",
                Record::new(format!("s-{i}")).with_metadata(json!({"i": i, "q": 40})),
            )
            .unwrap();
            tx.commit().unwrap();
        }
        let first = db.sweep_dead_versions(10);
        assert_eq!(first, 10);
        let rest = db.sweep_dead_versions(usize::MAX);
        assert_eq!(rest, 30);
    }

    #[test]
    fn lookup_index_extreme_greatest_returns_max_without_full_scan() {
        // End-to-end: greatest extreme over a growing per-prefix key set returns the
        // maximum (the ORDER BY DESC LIMIT 1 path), for both store backends.
        for store in ["btree", "sharded"] {
            // SAFETY: single-threaded test setup of process env for store selection.
            unsafe {
                std::env::set_var("BICDB_INDEX_STORE", store);
                std::env::set_var("BICDB_INDEX_SHARDS", "16");
            }
            let dir = tempfile::tempdir().unwrap();
            let mut db =
                BicDb::open_with_config(dir.path(), DbConfig::default().with_fsync(false)).unwrap();
            db.create_collection("orders").unwrap();
            db.create_index(IndexDefinition {
                name: "orders_cust".to_string(),
                collection: "orders".to_string(),
                fields: vec![
                    IndexField::MetadataPath(vec!["w".to_string()]),
                    IndexField::MetadataPath(vec!["c".to_string()]),
                    IndexField::MetadataPath(vec!["o".to_string()]),
                ],
                unique: false,
                kind: IndexKind::BTree,
                predicate: None,
                exclusion: None,
            })
            .unwrap();
            for o in 1..=50i64 {
                let mut tx = db.begin_transaction().unwrap();
                tx.insert(
                    "orders",
                    Record::new(format!("o-{o}")).with_metadata(json!({"w": 1, "c": 7, "o": o})),
                )
                .unwrap();
                tx.commit().unwrap();
            }
            let greatest = db
                .lookup_index_extreme(
                    "orders_cust",
                    &[IndexValue::Int(1), IndexValue::Int(7)],
                    true,
                )
                .unwrap()
                .expect("a max exists");
            assert_eq!(
                greatest.0,
                vec![IndexValue::Int(1), IndexValue::Int(7), IndexValue::Int(50)],
                "greatest must be the max o for ({store})"
            );
            let least = db
                .lookup_index_extreme(
                    "orders_cust",
                    &[IndexValue::Int(1), IndexValue::Int(7)],
                    false,
                )
                .unwrap()
                .expect("a min exists");
            assert_eq!(
                least.0,
                vec![IndexValue::Int(1), IndexValue::Int(7), IndexValue::Int(1)],
                "least must be the min o for ({store})"
            );
        }
        unsafe {
            std::env::remove_var("BICDB_INDEX_STORE");
            std::env::remove_var("BICDB_INDEX_SHARDS");
        }
    }

    #[test]
    fn index_key_encoding_is_order_preserving_and_roundtrips() {
        // memcmp over the encodings must match the structural Vec<IndexValue> Ord,
        // and decoding must recover the original (the index correctness invariant).
        let samples: Vec<Vec<IndexValue>> = vec![
            vec![],
            vec![IndexValue::Null],
            vec![IndexValue::Bool(false)],
            vec![IndexValue::Bool(true)],
            vec![IndexValue::Int(i64::MIN)],
            vec![IndexValue::Int(-1)],
            vec![IndexValue::Int(0)],
            vec![IndexValue::Int(1)],
            vec![IndexValue::Int(i64::MAX)],
            vec![IndexValue::Float(0)],
            vec![IndexValue::Float(u64::MAX)],
            vec![IndexValue::String(String::new())],
            vec![IndexValue::String("a".into())],
            vec![IndexValue::String("a\0b".into())],
            vec![IndexValue::String("ab".into())],
            vec![IndexValue::String("b".into())],
            vec![IndexValue::Int(5), IndexValue::String("a".into())],
            vec![IndexValue::Int(5), IndexValue::String("ab".into())],
            vec![IndexValue::Int(5), IndexValue::Int(3)],
            vec![
                IndexValue::String("a".into()),
                IndexValue::String("b".into()),
            ],
            vec![
                IndexValue::String("ab".into()),
                IndexValue::String("".into()),
            ],
        ];
        for a in &samples {
            // Round-trip: decode(encode(a)) == a.
            assert_eq!(
                &decode_index_key(&encode_index_key(a)),
                a,
                "roundtrip {a:?}"
            );
            for b in &samples {
                let ea = encode_index_key(a);
                let eb = encode_index_key(b);
                assert_eq!(
                    ea.cmp(&eb),
                    a.cmp(b),
                    "encoded order must match structural order for {a:?} vs {b:?}"
                );
            }
        }
        // Prefix: encoding a prefix is a byte-prefix of the full key.
        let full = encode_index_key(&[IndexValue::Int(5), IndexValue::String("x".into())]);
        let pref = encode_index_key(&[IndexValue::Int(5)]);
        assert!(
            full.starts_with(&pref),
            "prefix encoding must be a byte prefix"
        );
        // Field decode at a position.
        assert_eq!(decode_index_field(&full, 1), IndexValue::String("x".into()));
    }

    #[test]
    fn stored_index_key_matches_record_index_key_or_declines() {
        // Every cell shape the resident row can carry, keyed the way the SQL
        // layer stores them; the cells twin must agree with the parsed twin
        // wherever it answers, and decline (None) where only a parse is exact.
        let record = Record::new("row-1")
            .with_metadata(json!({
                "i": 42,
                "neg": -7,
                "f": 2.5,
                "b": true,
                "n": null,
                "s": "plain",
                "q": "a \"q\" b",
                "amount": {"$bicdb_typed": {"version": 1, "pg_type": "numeric", "text": "12.50", "index_key": "0a0b"}},
                "seen": {"$bicdb_typed": {"version": 1, "pg_type": "timestamp", "text": "2026-09-02 05:28:05"}},
                "shape": {"$bicdb_typed": {"version": 1, "pg_type": "point", "text": "(1,2)", "type_oid": 600}},
                "nested": {"k": [1, 2]},
                "up": "MiXeD  ",
            }))
            .with_timestamp(77);
        let stored = StoredRecord::from_record(&record).unwrap();
        let path = |name: &str| IndexField::MetadataPath(vec![name.to_string()]);
        for fields in [
            vec![path("i")],
            vec![path("neg"), path("f")],
            vec![path("b"), path("n"), path("s")],
            vec![path("q")],
            vec![path("amount")],
            vec![path("seen")],
            vec![path("missing")],
            vec![IndexField::Id, IndexField::Timestamp, path("i")],
            vec![IndexField::Lower(Box::new(path("up")))],
            vec![IndexField::Trim(Box::new(path("up")))],
            vec![path("i"), path("amount"), path("s")],
        ] {
            assert_eq!(
                stored_index_key(&stored, &fields),
                Some(record_index_key(&record, &fields)),
                "{fields:?}"
            );
        }
        // Declines: structured/user-type envelope (stringified by the parse
        // path), nested objects, multi-segment paths.
        for fields in [
            vec![path("shape")],
            vec![path("nested")],
            vec![IndexField::MetadataPath(vec![
                "nested".to_string(),
                "k".to_string(),
            ])],
            vec![path("i"), path("nested")],
        ] {
            assert_eq!(stored_index_key(&stored, &fields), None, "{fields:?}");
        }
        // A top-level `metadata` object stands in for missing keys on the parse
        // path; the cells twin declines rather than guess.
        let legacy = StoredRecord::from_record(
            &Record::new("row-2").with_metadata(json!({"metadata": {"i": 1}, "j": 2})),
        )
        .unwrap();
        assert_eq!(stored_index_key(&legacy, &[path("i")]), None);
        assert_eq!(
            stored_index_key(&legacy, &[path("j")]),
            Some(vec![IndexValue::Int(2)])
        );
        // Non-object metadata: no cells at all.
        let scalar =
            StoredRecord::from_record(&Record::new("row-3").with_metadata(json!(5))).unwrap();
        assert_eq!(stored_index_key(&scalar, &[path("i")]), None);
    }

    #[test]
    fn owned_cell_keys_equal_the_borrowed_cell_keys() {
        // The once-parsed owned cells must yield exactly what the streaming
        // derivation yields, including its declines.
        let rows = [
            r#"{"i": 5, "s": "x", "b": true, "n": null, "f": 2.5, "neg": -0}"#,
            r#"{"num": {"$bicdb_typed": {"version": 1, "pg_type": "numeric", "text": "1.50", "index_key": "0a0b"}}}"#,
            r#"{"ts": {"$bicdb_typed": {"version": 1, "pg_type": "timestamptz", "text": "2026-09-03 00:00:00+00"}}}"#,
            r#"{"bad": {"$bicdb_typed": {"version": 1, "pg_type": "numeric", "text": "1", "index_key": "zz"}}}"#,
            r#"{"o": {"a": 1}, "arr": [1, 2]}"#,
            r#"{"metadata": {"i": 1}}"#,
        ];
        let path = |name: &str| IndexField::MetadataPath(vec![name.to_string()]);
        for text in rows {
            let stored = StoredRecord {
                id: "r".to_string(),
                vector: None,
                metadata: serde_json::value::RawValue::from_string(text.to_string()).unwrap(),
                geometry: None,
                timestamp: Some(7),
                payload: None,
                typed: std::sync::OnceLock::new(),
                evicted: None,
            };
            let cells = ImageCells::scan(&stored).unwrap();
            let image = OldImage::from_stored(Arc::new(stored.clone()));
            for fields in [
                vec![path("i")],
                vec![path("s"), path("b")],
                vec![path("num")],
                vec![path("ts")],
                vec![path("bad")],
                vec![path("o")],
                vec![path("missing")],
                vec![IndexField::Id, IndexField::Timestamp],
                vec![IndexField::Lower(Box::new(path("s")))],
                vec![IndexField::Trim(Box::new(path("s")))],
                vec![path("neg"), path("f")],
            ] {
                assert_eq!(
                    image_cells_index_key(&stored, &cells, &fields),
                    stored_index_key(&stored, &fields),
                    "{text} {fields:?}"
                );
                // The memoized image answers the same key on every ask (the
                // first from cells, the rest from the memo) and the record
                // path agrees wherever the cell path declines.
                let expected = stored_index_key(&stored, &fields)
                    .unwrap_or_else(|| record_index_key(&stored.to_record().unwrap(), &fields));
                let first = image.index_key(&fields).unwrap().unwrap();
                let second = image.index_key(&fields).unwrap().unwrap();
                assert_eq!(*first, expected, "{text} {fields:?}");
                assert!(
                    Arc::ptr_eq(&first, &second),
                    "{text} {fields:?} not memoized"
                );
            }
        }
    }

    #[test]
    fn image_cells_keep_escaped_strings_and_span_text() {
        let stored = StoredRecord {
            id: "r".to_string(),
            vector: None,
            metadata: serde_json::value::RawValue::from_string(
                r#"{"plain": "abc", "esc\"aped": "line\nbreak", "quote": "say \"hi\""}"#
                    .to_string(),
            )
            .unwrap(),
            geometry: None,
            timestamp: None,
            payload: None,
            typed: std::sync::OnceLock::new(),
            evicted: None,
        };
        let cells = ImageCells::scan(&stored).unwrap();
        let path = |name: &str| vec![IndexField::MetadataPath(vec![name.to_string()])];
        assert_eq!(
            image_cells_index_key(&stored, &cells, &path("plain")),
            Some(vec![IndexValue::String("abc".to_string())])
        );
        assert_eq!(
            image_cells_index_key(&stored, &cells, &path("esc\"aped")),
            Some(vec![IndexValue::String("line\nbreak".to_string())])
        );
        assert_eq!(
            image_cells_index_key(&stored, &cells, &path("quote")),
            Some(vec![IndexValue::String("say \"hi\"".to_string())])
        );
        assert_eq!(
            image_cells_index_key(&stored, &cells, &path("missing")),
            Some(vec![IndexValue::Null])
        );
    }

    #[test]
    fn tx_frame_stored_ref_matches_owned_serialization() {
        // `prepare_wal_payloads` compacts the record once and serializes the
        // frame from the StoredRecord; the bytes must equal the owned frame the
        // recovery path decodes, for every field Record serializes.
        let tx_id = TransactionId(9);
        let record = Record::new("w-2")
            .with_metadata(json!({
                "name": "a \"quoted\" name",
                "amount": {"$bicdb_typed": {"version": 1, "pg_type": "numeric", "text": "12.50"}},
                "tags": ["x", "y"],
                "nested": {"k": null, "f": 1.5, "i": -3},
            }))
            .with_vector(vec![0.25, -1.0])
            .with_payload(vec![1, 2, 3]);
        let write = TxWrite {
            collection: "widgets".to_string(),
            op: TxWriteOp::Upsert,
            record_id: "w-2".to_string(),
            record: OnceLock::from(Some(Arc::new(record.clone()))),
            timestamp: 4321,
            statement_snapshot: 5,
            repair: None,
            stored: None,
            previous: None,
            previous_stored: None,
            changed: None,
        };
        let stored = StoredRecord::from_record(&record).unwrap();
        let owned = TxFrame::Write {
            tx_id,
            write: Box::new(write.clone()),
        };
        let compacted = TxFrameRef::WriteStored {
            tx_id,
            write: TxWriteStoredRef {
                collection: &write.collection,
                op: write.op,
                record_id: &write.record_id,
                record: Some(&stored),
                timestamp: write.timestamp,
                statement_snapshot: write.statement_snapshot,
            },
        };
        assert_eq!(
            serde_json::to_vec(&owned).unwrap(),
            serde_json::to_vec(&compacted).unwrap(),
            "compacted tx_write frame must serialize identically to the owned frame"
        );
    }

    #[test]
    fn fresh_stored_repair_finalizes_a_narrow_wal_patch() {
        let dir = tempfile::tempdir().unwrap();
        let mut db = BicDb::open_with_config(
            dir.path(),
            DbConfig::default()
                .with_fsync(false)
                .with_storage_mode(StorageMode::EmbeddedMemory),
        )
        .unwrap();
        db.create_collection("widgets").unwrap();
        let base = Record::new("row").with_metadata(json!({
            "counter":100, "description":"a long field that is unchanged by this narrow counter increment"
        }));
        db.insert("widgets", base.clone()).unwrap();
        let previous = Arc::new(StoredRecord::from_record(&base).unwrap());
        let pending = Arc::new(
            previous
                .with_metadata_text(
                    crate::record::splice_json_object_text(
                        previous.metadata.get(),
                        &[("counter", Some("105"))],
                    )
                    .unwrap(),
                )
                .unwrap(),
        );
        let mut tx = db.begin_transaction().unwrap();
        tx.write_stored_updates_with_changes(
            "widgets",
            [(
                Some(previous),
                pending,
                0,
                Some(RepairPlan {
                    deltas: vec![("counter".into(), RepairDelta::Int(5))],
                }),
                Some(Arc::from(vec![Box::<str>::from("counter")])),
            )],
        )
        .unwrap();
        db.repair_conflicting_delta_writes(&mut tx).unwrap();
        assert!(tx.writes[0].repair.is_none());
        let (before, after) = compact_wal_patch(&tx.writes[0]).unwrap();
        assert_eq!(before.get(), "{\"counter\":100}");
        assert_eq!(after.get(), "{\"counter\":105}");
        if compact_update_wal_enabled() {
            let prepared: Value = serde_json::from_slice(tx.prepared_wal.first_payload()).unwrap();
            assert_eq!(prepared["type"], "tx_patch");
        }
        tx.commit().unwrap();
        assert_eq!(
            db.get("widgets", "row").unwrap().unwrap().metadata["counter"],
            105
        );
    }

    #[test]
    fn prepared_wal_does_not_reuse_replaced_savepoint_writes() {
        for with_lock_mark in [false, true] {
            let dir = tempfile::tempdir().unwrap();
            let config = DbConfig::default()
                .with_fsync(false)
                .with_storage_mode(StorageMode::EmbeddedMemory);
            let mut db = BicDb::open_with_config(dir.path(), config.clone()).unwrap();
            db.create_collection("widgets").unwrap();
            let mut tx = db.begin_transaction().unwrap();
            tx.insert(
                "widgets",
                Record::new("discarded").with_metadata(json!({"value":1})),
            )
            .unwrap();
            tx.prepare_wal_payloads();
            assert_eq!(tx.prepared_wal.len(), 1);
            if with_lock_mark {
                tx.truncate_writes_and_locks(0, 0).unwrap();
            } else {
                tx.truncate_writes(0).unwrap();
            }
            tx.insert(
                "widgets",
                Record::new("replacement").with_metadata(json!({"value":2})),
            )
            .unwrap();
            tx.prepare_wal_payloads();
            let prepared: Value = serde_json::from_slice(tx.prepared_wal.first_payload()).unwrap();
            assert_eq!(
                prepared["write"]["record_id"], "replacement",
                "matching frame counts do not prove that cached WAL still describes these writes"
            );
            tx.commit().unwrap();
            assert!(db.get("widgets", "discarded").unwrap().is_none());
            drop(db);
            let reopened = BicDb::open_with_config(dir.path(), config).unwrap();
            assert!(reopened.get("widgets", "discarded").unwrap().is_none());
            assert_eq!(
                reopened
                    .get("widgets", "replacement")
                    .unwrap()
                    .unwrap()
                    .metadata["value"],
                2
            );
        }
    }

    #[test]
    fn stored_delta_repair_matches_full_record_arithmetic() {
        let values = [
            json!(41),
            json!(i64::MAX),
            json!(1.25),
            json!("123.50"),
            json!(null),
            json!({"$bicdb_typed":{"version":1,"pg_type":"numeric","text":"12.50","index_key":"old"}}),
            json!({"$bicdb_typed":{"version":1,"pg_type":"numeric","value":{
                "kind":"finite","coefficient":"1250","display_scale":2,"negative":true},"index_key":"old"}}),
        ];
        for value in values {
            for delta in [
                RepairDelta::Int(5),
                RepairDelta::Float(1.5),
                RepairDelta::Decimal {
                    units: -75,
                    scale: 2,
                },
            ] {
                let record = Record::new("row")
                    .with_metadata(json!({
                        "counter":value, "unchanged":{"nested":[1,2,3],"text":"héllo\\\""}
                    }))
                    .with_timestamp(42);
                let stored = StoredRecord::from_record(&record).unwrap();
                let plan = RepairPlan {
                    deltas: vec![("counter".into(), delta)],
                };
                let expected = apply_repair_deltas(record, &plan);
                let actual =
                    apply_stored_repair_deltas(&stored, &plan).map(|row| row.to_record().unwrap());
                assert_eq!(actual, expected, "value={value} delta={delta:?}");
            }
        }
        let noncompact =
            StoredRecord::from_parts("row".into(), "{ \"counter\": 41 }".into()).unwrap();
        let plan = RepairPlan {
            deltas: vec![("counter".into(), RepairDelta::Int(1))],
        };
        assert!(apply_stored_repair_deltas(&noncompact, &plan).is_none());
    }

