    #[test]
    // Pinned to embedded_memory: asserts Write-frame redo in the core log,
    // which is that mode's durability contract. Paged mode deliberately logs
    // only a CommitMaterialized marker (the page WAL carries the rows) —
    // covered by tests/paged_concurrency.rs.
    fn transaction_commit_uses_wal_redo_until_checkpoint_materialization() {
        let temp = tempfile::tempdir().unwrap();
        let tx_id;
        {
            let mut db = BicDb::open_with_config(
                temp.path(),
                DbConfig::default()
                    .with_storage_mode(StorageMode::EmbeddedMemory)
                    .with_fsync(false),
            )
            .unwrap();
            db.create_collection("ledger_entries").unwrap();

            let mut tx = db.begin_transaction().unwrap();
            tx_id = tx.id();
            tx.insert("ledger_entries", Record::new("kept-1")).unwrap();
            tx.insert("ledger_entries", Record::new("kept-2")).unwrap();
            let before_rolled_back = tx.write_len();
            tx.insert("ledger_entries", Record::new("rolled-back"))
                .unwrap();
            tx.truncate_writes(before_rolled_back).unwrap();

            let pending_recovery = recover_transaction_log(
                &db.tx_log_path(),
                SegmentReadMode::Buffered,
                &db.encryption,
            )
            .unwrap();
            assert!(!pending_recovery.writes.contains_key(&tx_id.0));
            assert!(!pending_recovery.is_committed(tx_id));

            tx.commit().unwrap();

            let committed_recovery = recover_transaction_log(
                &db.tx_log_path(),
                SegmentReadMode::Buffered,
                &db.encryption,
            )
            .unwrap();
            assert!(committed_recovery.is_committed(tx_id));
            assert!(!committed_recovery.is_materialized(tx_id));
            let committed_writes = committed_recovery.writes.get(&tx_id.0).unwrap();
            assert_eq!(committed_writes.len(), 2);
            assert_eq!(committed_writes[0].collection(), "ledger_entries");
            assert_eq!(committed_writes[0].record_id(), "kept-1");
            assert_eq!(committed_writes[1].record_id(), "kept-2");
        }

        let db = BicDb::open_with_config(
            temp.path(),
            DbConfig::default()
                .with_storage_mode(StorageMode::EmbeddedMemory)
                .with_fsync(false),
        )
        .unwrap();
        assert!(db.get("ledger_entries", "kept-1").unwrap().is_some());
        assert!(db.get("ledger_entries", "kept-2").unwrap().is_some());
        assert!(db.get("ledger_entries", "rolled-back").unwrap().is_none());
    }

    #[test]
    fn committed_record_audit_outbox_recovers_before_projection_consumers_open() {
        for storage_mode in [StorageMode::EmbeddedMemory, StorageMode::ServerPaged] {
            let temp = tempfile::tempdir().unwrap();
            {
                let mut db = BicDb::open_with_config(
                    temp.path(),
                    DbConfig::default()
                        .with_fsync(false)
                        .with_audit_events(true)
                        .with_storage_mode(storage_mode.clone()),
                )
                .unwrap();
                db.create_collection("widgets").unwrap();

                let mut tx = db.begin_transaction().unwrap();
                tx.insert(
                    "widgets",
                    Record::new("w-1").with_metadata(json!({"score": 7})),
                )
                .unwrap();
                let commit_seq = db.commit_buffered_transaction(&mut tx).unwrap();
                db.tx_log_handle().write_durable(commit_seq).unwrap();

                // Model process death in the narrow window after commit WAL
                // durability but before the caller publishes the audit outbox.
                assert!(db.events().read(RECORD_AUDIT_STREAM).is_empty());
                drop(tx);
            }

            let db = BicDb::open_with_config(
                temp.path(),
                DbConfig::default()
                    .with_fsync(false)
                    .with_audit_events(true)
                    .with_storage_mode(storage_mode),
            )
            .unwrap();
            assert_eq!(
                db.get("widgets", "w-1").unwrap().unwrap().metadata["score"],
                7
            );
            let audit = db.events().read(RECORD_AUDIT_STREAM);
            assert_eq!(audit.len(), 1);
            assert_eq!(audit[0].event.payload["record_id"], "w-1");
        }
    }

    #[test]
    // Pinned to embedded_memory: asserts segment/dirty-set/residency mechanics
    // that do not exist in paged mode (segments carry no rows there). The paged
    // sweep (BICDB_STORAGE_MODE=server_paged) covers that engine's own contract.
    fn transaction_log_replay_rebuilds_vector_store_once_per_touched_collection() {
        let temp = tempfile::tempdir().unwrap();
        {
            let mut db = BicDb::open_with_config(
                temp.path(),
                DbConfig::default()
                    .with_storage_mode(StorageMode::EmbeddedMemory)
                    .with_fsync(false),
            )
            .unwrap();
            db.create_collection("arbitrary_events").unwrap();

            let mut tx = db.begin_transaction().unwrap();
            for idx in 0..4 {
                tx.insert(
                    "arbitrary_events",
                    Record::new(format!("event-{idx}"))
                        .with_metadata(json!({"source": "wal-replay", "position": idx})),
                )
                .unwrap();
            }
            tx.commit().unwrap();
        }

        let db = BicDb::open_with_config(
            temp.path(),
            DbConfig::default()
                .with_storage_mode(StorageMode::EmbeddedMemory)
                .with_fsync(false),
        )
        .unwrap();
        let state = db.collections.get("arbitrary_events").unwrap().read();
        assert_eq!(state.record_count(), 4);
        assert_eq!(
            state.vector_store.read().rebuild_count,
            2,
            "open should rebuild once for segment state and once after replaying all pending tx-log writes"
        );
        assert_eq!(
            state.generation(),
            4,
            "replay should still advance generation for each applied write"
        );
    }

    #[test]
    fn buffered_transaction_log_drains_without_sync_calls() {
        let temp = tempfile::tempdir().unwrap();
        {
            let mut db =
                BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false))
                    .unwrap();
            db.create_collection("buffered_probe").unwrap();
            let mut tx = db.begin_transaction().unwrap();
            tx.insert("buffered_probe", Record::new("entry-1")).unwrap();
            tx.commit().unwrap();

            let stats = db.tx_log_handle().stats();
            assert_eq!(stats.write_calls, 1);
            assert_eq!(stats.sync_calls, 0);
            assert_eq!(stats.commits_written, 1);
            assert!(stats.bytes_written > 0);
        }

        let db =
            BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false)).unwrap();
        assert!(db.get("buffered_probe", "entry-1").unwrap().is_some());
    }

    #[test]
    fn transaction_commit_is_durable_across_reopen_with_fsync() {
        // Commits with fsync go through the cached O_DSYNC transaction-log
        // handle; the durability guarantee is verified by recovery rather than
        // by introspecting a process-global sync-mode counter (which races with
        // other parallel tests). Several commits exercise the cached handle
        // across more than one append.
        let temp = tempfile::tempdir().unwrap();
        {
            let mut db =
                BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(true)).unwrap();
            db.create_collection("durability_probe").unwrap();
            for i in 0..3 {
                let mut tx = db.begin_transaction().unwrap();
                tx.insert("durability_probe", Record::new(format!("entry-{i}")))
                    .unwrap();
                tx.commit().unwrap();
            }
            assert!(db.get("durability_probe", "entry-2").unwrap().is_some());
            let stats = db.tx_log_handle().stats();
            assert_eq!(stats.write_calls, 3);
            assert_eq!(stats.sync_calls, 3);
            assert_eq!(stats.commits_written, 3);
        }
        // Reopen: every committed record must survive recovery.
        let db = BicDb::open(temp.path()).unwrap();
        for i in 0..3 {
            assert!(
                db.get("durability_probe", &format!("entry-{i}"))
                    .unwrap()
                    .is_some(),
                "committed record entry-{i} must be durable across reopen"
            );
        }
    }

