    #[test]
    fn transaction_mixed_repeated_writes_commit_final_index_state() {
        let temp = tempfile::tempdir().unwrap();
        {
            let mut db =
                BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false))
                    .unwrap();
            db.create_collection("jobs").unwrap();
            db.create_index(IndexDefinition {
                name: "idx_jobs_bucket".to_string(),
                collection: "jobs".to_string(),
                fields: vec![IndexField::MetadataPath(vec!["bucket".to_string()])],
                unique: false,
                kind: IndexKind::BTree,
                predicate: None,
                exclusion: None,
            })
            .unwrap();
            db.batch_insert(
                "jobs",
                [
                    Record::new("job-a").with_metadata(json!({"bucket": 0, "position": 1})),
                    Record::new("job-b").with_metadata(json!({"bucket": 1, "position": 2})),
                ],
            )
            .unwrap();

            let mut tx = db.begin_transaction().unwrap();
            tx.update(
                "jobs",
                Record::new("job-a").with_metadata(json!({"bucket": 1, "position": 3})),
            )
            .unwrap();
            tx.update(
                "jobs",
                Record::new("job-a").with_metadata(json!({"bucket": 2, "position": 4})),
            )
            .unwrap();
            tx.delete("jobs", "job-b").unwrap();
            tx.insert(
                "jobs",
                Record::new("job-c").with_metadata(json!({"bucket": 2, "position": 5})),
            )
            .unwrap();
            tx.commit().unwrap();

            assert_eq!(db.scan_collection("jobs").unwrap().len(), 2);
            assert!(db.verify_index("idx_jobs_bucket").unwrap().valid);
            assert!(db
                .lookup_index("idx_jobs_bucket", &[IndexValue::from(0)])
                .unwrap()
                .is_empty());
            assert!(db
                .lookup_index("idx_jobs_bucket", &[IndexValue::from(1)])
                .unwrap()
                .is_empty());
            assert_eq!(
                db.lookup_index("idx_jobs_bucket", &[IndexValue::from(2)])
                    .unwrap(),
                vec!["job-a".to_string(), "job-c".to_string()]
            );
        }

        let db =
            BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false)).unwrap();
        assert_eq!(db.scan_collection("jobs").unwrap().len(), 2);
        assert!(db.verify_index("idx_jobs_bucket").unwrap().valid);
    }

