    #[test]
    fn verify_index_detects_missing_stale_and_wrong_entries() {
        let temp = tempfile::tempdir().unwrap();
        let mut db =
            BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false)).unwrap();
        db.create_collection("patients").unwrap();
        db.insert(
            "patients",
            Record::new("p-1").with_metadata(json!({"clinic": "east"})),
        )
        .unwrap();
        db.insert(
            "patients",
            Record::new("p-2").with_metadata(json!({"clinic": "west"})),
        )
        .unwrap();
        db.create_index(IndexDefinition {
            name: "idx_patients_clinic".to_string(),
            collection: "patients".to_string(),
            fields: vec![IndexField::MetadataPath(vec!["clinic".to_string()])],
            unique: false,
            kind: IndexKind::BTree,
            predicate: None,
            exclusion: None,
        })
        .unwrap();

        // Resolve the physical locators the index actually stores, so the
        // corruption (drop a real entry, add a wrong one) hits the right rowids.
        let p1 = db
            .collection_state("patients")
            .unwrap()
            .shard("p-1")
            .read()
            .rowid_of("p-1")
            .unwrap();
        let p2 = db
            .collection_state("patients")
            .unwrap()
            .shard("p-2")
            .read()
            .rowid_of("p-2")
            .unwrap();
        let state = db.indexes.get_mut("idx_patients_clinic").unwrap().get_mut();
        state
            .store
            .remove(&encode_index_key(&[IndexValue::from("east")]), p1);
        state
            .store
            .insert(&encode_index_key(&[IndexValue::from("wrong")]), p2);

        let report = db.verify_index("idx_patients_clinic").unwrap();
        assert!(!report.valid);
        assert_eq!(report.missing_entries, 1);
        assert_eq!(report.stale_entries, 1);
        assert_eq!(report.wrong_entries, 1);
    }

