    #[test]
    fn record_mutations_maintain_indexes_without_rebuilding_unrelated_records() {
        let temp = tempfile::tempdir().unwrap();
        let mut db =
            BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false)).unwrap();
        db.create_collection("items").unwrap();
        db.insert(
            "items",
            Record::new("item-1")
                .with_metadata(json!({"bucket": "open", "position": "POINT(0 0)"})),
        )
        .unwrap();
        db.insert(
            "items",
            Record::new("item-2")
                .with_metadata(json!({"bucket": "open", "position": "POINT(1 1)"})),
        )
        .unwrap();
        db.create_index(IndexDefinition {
            name: "idx_items_bucket".to_string(),
            collection: "items".to_string(),
            fields: vec![IndexField::MetadataPath(vec!["bucket".to_string()])],
            unique: false,
            kind: IndexKind::BTree,
            predicate: None,
            exclusion: None,
        })
        .unwrap();
        db.create_spatial_index("items", "position").unwrap();

        let entry = db
            .collections
            .get_mut("items")
            .unwrap()
            .get_mut()
            .shard_mut("item-2")
            .get_record_mut("item-2")
            .unwrap();
        let stored = Arc::make_mut(&mut entry.record);
        let mut record = stored.to_record().unwrap();
        record.metadata["position"] = json!(7);
        *stored = StoredRecord::from_record(&record).unwrap();

        db.insert(
            "items",
            Record::new("item-1")
                .with_metadata(json!({"bucket": "closed", "position": "POINT(0 0)"})),
        )
        .unwrap();

        assert_eq!(
            db.lookup_index("idx_items_bucket", &[IndexValue::from("open")])
                .unwrap(),
            vec!["item-2".to_string()]
        );
        assert_eq!(
            db.lookup_index("idx_items_bucket", &[IndexValue::from("closed")])
                .unwrap(),
            vec!["item-1".to_string()]
        );
        assert!(db.verify_index("idx_items_bucket").unwrap().valid);

        assert!(db.delete("items", "item-1").unwrap());
        assert!(db
            .lookup_index("idx_items_bucket", &[IndexValue::from("closed")])
            .unwrap()
            .is_empty());
        assert!(db.verify_index("idx_items_bucket").unwrap().valid);
    }

