    #[test]
    fn lookup_index_extreme_returns_first_and_last_key_for_prefix() {
        let temp = tempfile::tempdir().unwrap();
        let mut db =
            BicDb::open_with_config(temp.path(), DbConfig::default().with_fsync(false)).unwrap();
        db.create_collection("events").unwrap();
        db.create_index(IndexDefinition {
            name: "idx_events_bucket_position".to_string(),
            collection: "events".to_string(),
            fields: vec![
                IndexField::MetadataPath(vec!["bucket".to_string()]),
                IndexField::MetadataPath(vec!["position".to_string()]),
            ],
            unique: false,
            kind: IndexKind::BTree,
            predicate: None,
            exclusion: None,
        })
        .unwrap();
        db.batch_insert(
            "events",
            vec![
                Record::new("outside-low").with_metadata(json!({"bucket": 1, "position": 1})),
                Record::new("event-3").with_metadata(json!({"bucket": 7, "position": 3})),
                Record::new("event-5").with_metadata(json!({"bucket": 7, "position": 5})),
                Record::new("event-9").with_metadata(json!({"bucket": 7, "position": 9})),
                Record::new("outside-high").with_metadata(json!({"bucket": 9, "position": 1})),
            ],
        )
        .unwrap();

        let first = db
            .lookup_index_extreme("idx_events_bucket_position", &[IndexValue::from(7)], false)
            .unwrap()
            .unwrap();
        assert_eq!(first.0, vec![IndexValue::from(7), IndexValue::from(3)]);
        assert_eq!(first.1, vec!["event-3".to_string()]);

        let last = db
            .lookup_index_extreme("idx_events_bucket_position", &[IndexValue::from(7)], true)
            .unwrap()
            .unwrap();
        assert_eq!(last.0, vec![IndexValue::from(7), IndexValue::from(9)]);
        assert_eq!(last.1, vec!["event-9".to_string()]);

        let filtered = db
            .lookup_index_extreme_with_filters(
                "idx_events_bucket_position",
                &[IndexValue::from(7)],
                false,
                &[(1, IndexValue::from(5))],
            )
            .unwrap()
            .unwrap();
        assert_eq!(filtered.0, vec![IndexValue::from(7), IndexValue::from(5)]);
        assert_eq!(filtered.1, vec!["event-5".to_string()]);

        assert!(db
            .lookup_index_extreme("idx_events_bucket_position", &[IndexValue::from(8)], false)
            .unwrap()
            .is_none());
    }

